// GENERATED from src/data/cheat-sheets.json by scripts/build-cheat-sheets-data-module.js.
// Do not hand-edit: regenerate with `npm run build:cheat-sheets-data`.
export const CHEAT_SHEETS_DATA = {"version":1,"generatedFrom":"workups/admission/*.workup.json (prerounding_workup_v1)","sheets":[{"id":"dyspnea","title":"Shortness of breath / dyspnea","aliases":["shortness of breath","breathlessness"],"history":[{"id":"history-01","system":"respiratory","question":"Did your shortness of breath come on gradually over days, or suddenly over minutes to hours?","listenFor":["Gradual, over days to weeks","Abrupt, over minutes to hours","Episodic, recurring in discrete attacks"],"why":null,"whySource":null,"meaning":"Gradual onset over days to weeks favors heart failure, COPD exacerbation, anemia, or pleural effusion, while abrupt onset over minutes to hours points to pulmonary embolism, pneumothorax, anaphylaxis, or acute pulmonary edema — sudden dyspnea with pleuritic pain or syncope is an emergency workup. Episodic discrete attacks with full recovery between them favor asthma or panic attacks; get the exact time course before anchoring.","meaningSource":"ai-draft"},{"id":"history-02","system":"cardiovascular","question":"Do you need to prop yourself up on extra pillows to breathe comfortably at night?","listenFor":["No orthopnea","Needs one extra pillow to breathe comfortably","Cannot lie flat at all"],"why":"Needing extra pillows to breathe comfortably (orthopnea) suggests elevated left-sided filling pressures, as seen in left heart failure.","whySource":"curated","meaning":"Needing extra pillows to breathe comfortably (orthopnea) suggests elevated left-sided filling pressures, as seen in left heart failure.","meaningSource":"curated"},{"id":"history-03","system":"cardiovascular","question":"Have you ever woken up suddenly gasping for air that got better after you sat up?","listenFor":["No nocturnal awakening with breathlessness","Wakes gasping for air, relieved by sitting up"],"why":"Waking up gasping for air, relieved by sitting up (paroxysmal nocturnal dyspnea), reflects pulmonary edema from elevated left-sided filling pressures, as in left heart failure.","whySource":"curated","meaning":"Waking up gasping for air, relieved by sitting up (paroxysmal nocturnal dyspnea), reflects pulmonary edema from elevated left-sided filling pressures, as in left heart failure.","meaningSource":"curated"},{"id":"history-04","system":"cardiovascular","question":"Do you have any chest discomfort along with the shortness of breath, and if so, what does it feel like?","listenFor":["No chest discomfort","Exertional pressure or tightness relieved by rest","Pleuritic pain, sharp and worse with inspiration","Sudden tearing pain radiating to the back"],"why":"Sudden tearing chest pain radiating to the back is the classic presentation of aortic dissection.","whySource":"curated","meaning":"Sudden tearing chest pain radiating to the back is the classic presentation of aortic dissection.","meaningSource":"curated"},{"id":"history-05","system":"respiratory","question":"Have you had a cough?","listenFor":["No cough","Dry, nonproductive cough","Productive cough"],"why":null,"whySource":null,"meaning":"A cough accompanying dyspnea points to an airway or parenchymal trigger — productive cough suggests pneumonia, COPD exacerbation, or bronchiectasis, while a dry cough fits asthma, pulmonary edema, pulmonary embolism, or interstitial disease. Absent cough pushes toward cardiac, pulmonary-vascular, anemic, or anxiety-related causes; ask about sputum character and fever.","meaningSource":"ai-draft"},{"id":"history-06","system":"respiratory","question":"Are you coughing anything up, and if so, what does it look like?","listenFor":["No sputum production","Clear or white sputum","Purulent or discolored sputum","Pink, frothy sputum","Blood-streaked sputum or hemoptysis"],"why":"Pink, frothy sputum suggests acute pulmonary edema; purulent sputum suggests bacterial infection.","whySource":"curated","meaning":"Pink, frothy sputum suggests acute pulmonary edema; purulent sputum suggests bacterial infection.","meaningSource":"curated"},{"id":"history-07","system":"respiratory","question":"Have you noticed any wheezing?","listenFor":["No wheeze","Wheeze consistent with prior diagnosed asthma or COPD","New wheeze with no prior reactive-airway history"],"why":null,"whySource":null,"meaning":"Wheezing signals airflow limitation: in known asthma or COPD it supports an exacerbation, while new wheeze without reactive-airway history should prompt consideration of anaphylaxis, foreign body, heart failure ('cardiac asthma'), or upper-airway obstruction. New wheeze in a first-time presentation warrants a careful allergen and medication history.","meaningSource":"ai-draft"},{"id":"history-08","system":"infectious","question":"Have you had a fever?","listenFor":["No fever","Subjective fever without chills","Fever with shaking chills or rigors"],"why":"Fever with shaking chills (rigors) suggests bacteremia.","whySource":"curated","meaning":"Fever with shaking chills (rigors) suggests bacteremia.","meaningSource":"curated"},{"id":"history-09","system":"cardiovascular","question":"Have you been told you have heart failure, and does this episode feel like a previous flare-up?","listenFor":["No known heart failure","Known heart failure, this episode feels different from baseline","Known heart failure, this episode resembles a prior decompensation"],"why":null,"whySource":null,"meaning":"Known heart failure makes acute decompensation the leading consideration, especially when the episode feels like a prior flare — look for triggers such as dietary salt load, missed diuretics, or new atrial fibrillation. An episode that feels different from baseline, or no known heart failure at all, argues against decompensation and toward pneumonia, pulmonary embolism, or a new cardiac event.","meaningSource":"ai-draft"},{"id":"history-10","system":"skin","question":"Have you broken out in hives, or noticed swelling of your lips, tongue, or throat after being exposed to something new?","listenFor":["No urticaria, angioedema, or exposure","Hives after a new exposure, no airway symptoms","Lip, tongue, or throat swelling after a new exposure"],"why":"Hives with facial swelling or throat tightness after an exposure suggests anaphylaxis, which can rapidly obstruct the airway.","whySource":"curated","meaning":"Hives with facial swelling or throat tightness after an exposure suggests anaphylaxis, which can rapidly obstruct the airway.","meaningSource":"curated"},{"id":"history-11","system":"gastrointestinal","question":"Did you choke or aspirate on food or liquid right before this started?","listenFor":["No witnessed choking or aspiration","Witnessed choking or aspiration event"],"why":null,"whySource":null,"meaning":"A witnessed choking or aspiration event just before sudden dyspnea points to foreign-body aspiration or aspiration pneumonitis, particularly in the elderly or intoxicated patient. New unilateral wheeze or unilateral decreased breath sounds after aspiration favors a retained foreign body and should prompt imaging.","meaningSource":"ai-draft"},{"id":"history-12","system":"cardiovascular","question":"Have you noticed any swelling in one leg?","listenFor":["No leg swelling","Unilateral leg swelling"],"why":"New unilateral leg swelling suggests deep vein thrombosis.","whySource":"curated","meaning":"New unilateral leg swelling suggests deep vein thrombosis.","meaningSource":"curated"},{"id":"history-13","system":"functional","question":"Have you traveled recently, had surgery, been hospitalized, or do you have cancer or a history of blood clots?","listenFor":["No provoking risk factor","Air travel over four hours in the past month","Surgery or hospitalization in the past month","Active malignancy or prior venous thromboembolism"],"why":"Recent travel, surgery, hospitalization, cancer, or prior clots are provoking risk factors for venous thromboembolism.","whySource":"curated","meaning":"Recent travel, surgery, hospitalization, cancer, or prior clots are provoking risk factors for venous thromboembolism.","meaningSource":"curated"},{"id":"history-14","system":"psychiatric","question":"Does this feel like a panic attack, with tingling around your mouth or hands that gets better once you calm down?","listenFor":["No situational trigger or panic history","Situational trigger with paresthesias, resolves with reassurance","Known panic disorder with similar prior episodes"],"why":null,"whySource":null,"meaning":"Perioral or hand paresthesias that accompany situational dyspnea and resolve with calming fit hyperventilation-related panic — but this is a diagnosis of exclusion. Pulmonary embolism, pulmonary edema, and pneumothorax must be clinically excluded first, since their presentations overlap with panic.","meaningSource":"ai-draft"},{"id":"history-15","system":"hematologic","question":"Have you been told you have anemia, and has your breathlessness been gradually getting worse with activity?","listenFor":["No known anemia","Known anemia with gradually worsening exertional dyspnea"],"why":null,"whySource":null,"meaning":"Gradually worsening exertional dyspnea in a known anemic patient is expected, but in a patient without known anemia it raises suspicion for slow blood loss or a marrow problem — check for melena, menorrhagia, fatigue, and pallor, and review the hemoglobin trend. Dyspnea out of proportion to the anemia should prompt a search for a cardiopulmonary cause.","meaningSource":"ai-draft"},{"id":"history-16","system":"hematologic","question":"Have you noticed black, tarry stools, red blood in your stool, or vomited blood?","listenFor":["No signs of gastrointestinal bleeding","Melena or hematochezia","Hematemesis"],"why":"Black, tarry stools (melena), hematochezia, or hematemesis indicate gastrointestinal bleeding; melena points to an upper source.","whySource":"curated","meaning":"Black, tarry stools (melena), hematochezia, or hematemesis indicate gastrointestinal bleeding; melena points to an upper source.","meaningSource":"curated"}],"exam":[{"id":"exam-01","system":"respiratory","maneuver":"Assess respiratory rate and work of breathing.","findings":["Normal rate, no accessory muscle use","Tachypneic with accessory muscle use","Severe distress with paradoxical or fatiguing respiratory pattern"],"how":null,"why":null,"whySource":null,"meaning":"Respiratory rate and accessory muscle use gauge severity: tachypnea with accessory-muscle recruitment, or a paradoxical or fatiguing pattern, signals impending respiratory failure and the need for escalation. A normal rate does not exclude serious causes such as pulmonary embolism, so pair it with the rest of the vitals and exam.","meaningSource":"ai-draft"},{"id":"exam-02","system":"respiratory","maneuver":"Assess oxygen saturation and response to supplemental oxygen.","findings":["Normal saturation on room air","Hypoxemic, corrected with low-flow supplemental oxygen","Hypoxemic despite high-flow oxygen or a non-rebreather mask"],"how":null,"why":null,"whySource":null,"meaning":"Hypoxemia correcting on low-flow oxygen supports a ventilation–perfusion mismatch from a reversible process such as COPD or heart failure, while hypoxemia persisting on high-flow oxygen or a non-rebreather implies significant shunt — severe pneumonia, pulmonary edema, or ARDS — and mandates ICU-level care. Recheck saturation after any oxygen change rather than assuming the first reading.","meaningSource":"ai-draft"},{"id":"exam-03","system":"ent","maneuver":"Auscultate for stridor.","findings":["No stridor","Inspiratory stridor"],"how":null,"why":"Stridor indicates upper airway obstruction and is an airway emergency.","whySource":"curated","meaning":"Stridor indicates upper airway obstruction and is an airway emergency.","meaningSource":"curated"},{"id":"exam-04","system":"respiratory","maneuver":"Auscultate the lungs for focal versus diffuse findings.","findings":["Clear bilaterally","Focal crackles or dullness in one region","Diffuse bilateral crackles","Diffuse wheeze or prolonged expiration"],"how":null,"why":"Diffuse bilateral crackles suggest pulmonary edema from left heart failure.","whySource":"curated","meaning":"Diffuse bilateral crackles suggest pulmonary edema from left heart failure.","meaningSource":"curated"},{"id":"exam-05","system":"cardiovascular","maneuver":"Assess jugular venous pressure.","findings":["Normal jugular venous pressure","Elevated jugular venous pressure","Elevated jugular venous pressure with prominent v waves"],"how":"With the patient reclined at 30 to 45 degrees, identify the highest point of internal jugular venous pulsation and measure its vertical distance above the sternal angle.","why":"Elevated jugular venous pressure reflects elevated right-sided filling pressures, seen in right heart failure, volume overload, or tamponade.","whySource":"curated","meaning":"Elevated jugular venous pressure reflects elevated right-sided filling pressures, seen in right heart failure, volume overload, or tamponade.","meaningSource":"curated"},{"id":"exam-06","system":"cardiovascular","maneuver":"Auscultate heart sounds for a gallop.","findings":["Normal S1 and S2, no extra sounds","S3 gallop present"],"how":null,"why":"An S3 gallop reflects rapid early ventricular filling and suggests left ventricular systolic dysfunction or volume overload, as in heart failure.","whySource":"curated","meaning":"An S3 gallop reflects rapid early ventricular filling and suggests left ventricular systolic dysfunction or volume overload, as in heart failure.","meaningSource":"curated"},{"id":"exam-07","system":"cardiovascular","maneuver":"Auscultate the heart for a new murmur.","findings":["No murmur","New murmur"],"how":null,"why":"A new murmur suggests acute valvular pathology, as in endocarditis or aortic dissection.","whySource":"curated","meaning":"A new murmur suggests acute valvular pathology, as in endocarditis or aortic dissection.","meaningSource":"curated"},{"id":"exam-08","system":"cardiovascular","maneuver":"Assess for pulsus paradoxus and Beck triad findings suggesting tamponade.","findings":["No pulsus paradoxus, heart sounds normal","Pulsus paradoxus greater than 10 mmHg","Hypotension with elevated jugular venous pressure and muffled heart sounds"],"how":"With the patient reclined at 30 to 45 degrees, identify the highest point of internal jugular venous pulsation and measure its vertical distance above the sternal angle.","why":"Pulsus paradoxus over 10 mmHg with hypotension, elevated jugular venous pressure, and muffled heart sounds (Beck triad) suggests cardiac tamponade.","whySource":"curated","meaning":"Pulsus paradoxus over 10 mmHg with hypotension, elevated jugular venous pressure, and muffled heart sounds (Beck triad) suggests cardiac tamponade.","meaningSource":"curated"},{"id":"exam-09","system":"respiratory","maneuver":"Assess tracheal position and breath sounds for asymmetry.","findings":["Midline trachea, symmetric breath sounds","Unilateral decreased or absent breath sounds","Tracheal deviation with hyperresonance to percussion"],"how":null,"why":"Tracheal deviation with hyperresonance and absent breath sounds suggests tension pneumothorax, which needs immediate decompression.","whySource":"curated","meaning":"Tracheal deviation with hyperresonance and absent breath sounds suggests tension pneumothorax, which needs immediate decompression.","meaningSource":"curated"},{"id":"exam-10","system":"skin","maneuver":"Inspect the face and skin for urticaria or angioedema.","findings":["No hives or swelling","Urticaria without facial involvement","Facial, lip, or tongue angioedema"],"how":null,"why":null,"whySource":null,"meaning":"Urticaria or angioedema of the lips, face, or tongue identifies anaphylaxis as the cause of dyspnea — give epinephrine immediately rather than waiting for wheeze or stridor. Isolated urticaria without airway involvement suggests a milder allergic reaction but still warrants treatment and observation.","meaningSource":"ai-draft"},{"id":"exam-11","system":"neurologic","maneuver":"Assess mental status.","findings":["Alert and appropriate","Confused or somnolent"],"how":null,"why":null,"whySource":null,"meaning":"Confusion or somnolence in a dyspneic patient signals cerebral hypoxia, hypercapnic CO2 retention, or a toxic-metabolic cause and changes management — hypercapnia in particular argues against uncontrolled high-flow oxygen in a known CO2 retainer. Alert and appropriate status makes a catastrophic cause less likely but does not rule out severe dyspnea.","meaningSource":"ai-draft"},{"id":"exam-12","system":"skin","maneuver":"Assess lips and nail beds for central cyanosis.","findings":["Normal color","Central cyanosis"],"how":null,"why":"Central cyanosis of the lips, tongue, and nail beds reflects arterial hypoxemia.","whySource":"curated","meaning":"Central cyanosis of the lips, tongue, and nail beds reflects arterial hypoxemia.","meaningSource":"curated"},{"id":"exam-13","system":"cardiovascular","maneuver":"Inspect and palpate the calves for asymmetric swelling or a palpable cord.","findings":["Symmetric, no swelling or cord","Unilateral swelling","Unilateral swelling with tenderness or a palpable cord"],"how":null,"why":"Unilateral calf swelling, tenderness, or a palpable cord suggests deep vein thrombosis.","whySource":"curated","meaning":"Unilateral calf swelling, tenderness, or a palpable cord suggests deep vein thrombosis.","meaningSource":"curated"},{"id":"exam-14","system":"hematologic","maneuver":"Inspect the conjunctiva and nail beds for pallor.","findings":["Normal color","Conjunctival or nail-bed pallor"],"how":null,"why":"Pallor of the conjunctivae, nail beds, or palmar creases suggests anemia.","whySource":"curated","meaning":"Pallor of the conjunctivae, nail beds, or palmar creases suggests anemia.","meaningSource":"curated"}],"reviewNeeded":{"whyMissing":11,"howMissing":12}},{"id":"chest-pain","title":"Chest pain","aliases":["chest discomfort","angina"],"history":[{"id":"history-01","system":"cardiovascular","question":"What does the pain feel like, and does it spread anywhere?","listenFor":["Pressure or squeezing radiating to the arm, jaw, or neck","Sharp, positional, pleuritic pain","Sudden tearing pain radiating to the back","Burning, retrosternal pain"],"why":"Sudden tearing chest pain radiating to the back is the classic presentation of aortic dissection.","whySource":"curated","meaning":"Sudden tearing chest pain radiating to the back is the classic presentation of aortic dissection.","meaningSource":"curated"},{"id":"history-02","system":"cardiovascular","question":"Does the pain come on with activity and go away with rest, or is it there all the time?","listenFor":["Worse with exertion, relieved by rest","Present at rest, unrelated to exertion","Reproducible with chest wall movement or palpation"],"why":"Chest pressure brought on by exertion and relieved by rest is the classic pattern of angina from myocardial ischemia.","whySource":"curated","meaning":"Chest pressure brought on by exertion and relieved by rest is the classic pattern of angina from myocardial ischemia.","meaningSource":"curated"},{"id":"history-03","system":"cardiovascular","question":"Have you been sweating along with the pain?","listenFor":["No diaphoresis","Diaphoresis accompanying the pain"],"why":null,"whySource":null,"meaning":"Diaphoresis with chest pain reflects autonomic activation and raises the pretest probability of a dangerous cause — most classically acute coronary syndrome, but also pulmonary embolism and aortic dissection. Treat it as a high-risk feature and proceed with ECG and serial troponins rather than reassurance.","meaningSource":"ai-draft"},{"id":"history-04","system":"gastrointestinal","question":"Have you felt nauseated along with the pain?","listenFor":["No nausea","Nausea accompanying the pain"],"why":null,"whySource":null,"meaning":"Nausea with chest pain is a common autonomic accompaniment of acute coronary syndrome, especially inferior ischemia with vagal activation. Its absence does not exclude ACS, and new nausea in a chest-pain patient keeps cardiac causes high on the differential.","meaningSource":"ai-draft"},{"id":"history-05","system":"neurologic","question":"Have you felt like you were going to pass out, or did you actually pass out?","listenFor":["No syncope or presyncope","Lightheadedness or presyncope","Frank syncope"],"why":null,"whySource":null,"meaning":"Syncope or presyncope during chest pain suggests a hemodynamically significant or arrhythmic event — massive pulmonary embolism, aortic dissection, malignant arrhythmia, tamponade, or severe ischemia. These patients need continuous monitoring and urgent evaluation, not a routine rule-out pathway.","meaningSource":"ai-draft"},{"id":"history-06","system":"cardiovascular","question":"Do you have high blood pressure, diabetes, high cholesterol, or a family history of heart disease, or have you had a heart attack or stent before?","listenFor":["No known coronary risk factors","Multiple risk factors: hypertension, diabetes, hyperlipidemia, smoking, or family history","Known coronary artery disease, prior infarction, or revascularization"],"why":null,"whySource":null,"meaning":"Hypertension, diabetes, hyperlipidemia, smoking, family history, and especially known coronary disease or a prior stent raise the pretest probability that chest pain is ischemic — a prior stent specifically raises concern for stent thrombosis or restenosis. More risk factors mean a lower threshold to admit and work up; absence of risk factors lowers but never eliminates that probability.","meaningSource":"ai-draft"},{"id":"history-07","system":"cardiovascular","question":"Do you have a known aneurysm, a connective tissue condition like Marfan syndrome, or have you used cocaine recently?","listenFor":["No known dissection risk factor","Uncontrolled hypertension","Known aortic aneurysm, Marfan syndrome, or bicuspid aortic valve","Recent cocaine or stimulant use"],"why":null,"whySource":null,"meaning":"A known aortic aneurysm, Marfan syndrome, bicuspid aortic valve, or recent cocaine use markedly raises the pretest probability of aortic dissection or coronary vasospasm. Tearing or severe pain in these patients should redirect the workup to emergent aortic imaging (CT angiography) rather than a routine cardiac rule-out.","meaningSource":"ai-draft"},{"id":"history-08","system":"functional","question":"Have you traveled recently, had surgery, been hospitalized, or do you have cancer or a history of blood clots?","listenFor":["No provoking risk factor","Air travel over four hours, surgery, or hospitalization in the past month","Active malignancy or prior venous thromboembolism"],"why":"Active cancer and prior venous thromboembolism are strong risk factors for recurrent clots.","whySource":"curated","meaning":"Active cancer and prior venous thromboembolism are strong risk factors for recurrent clots.","meaningSource":"curated"},{"id":"history-09","system":"cardiovascular","question":"Is the pain worse when you lie flat and better when you lean forward?","listenFor":["No positional change","Worse lying flat, improved leaning forward"],"why":"Chest pain worse lying flat and better leaning forward suggests pericarditis.","whySource":"curated","meaning":"Chest pain worse lying flat and better leaning forward suggests pericarditis.","meaningSource":"curated"},{"id":"history-10","system":"infectious","question":"Were you sick with a cold or virus in the past week or two?","listenFor":["No preceding viral illness","Preceded by a viral illness"],"why":null,"whySource":null,"meaning":"A cold or viral illness in the preceding one to two weeks before pleuritic or positional chest pain points toward viral pericarditis or myocarditis. Ask about fever and positional relief with leaning forward, and listen for a pericardial friction rub.","meaningSource":"ai-draft"},{"id":"history-11","system":"musculoskeletal","question":"Did you do any heavy lifting, start a new exercise, or hurt your chest before this started?","listenFor":["No preceding trauma or unusual exertion","Recent heavy lifting, new exercise, or repetitive strain","Recent direct chest trauma"],"why":null,"whySource":null,"meaning":"A clear history of heavy lifting, new exercise, or chest trauma before onset points toward a musculoskeletal source such as costochondritis or strain, or toward traumatic injury like rib fracture. Reproducible focal tenderness supports this — but do not anchor on it until red flags such as hypoxia, asymmetric pulses, or concerning vitals are excluded.","meaningSource":"ai-draft"},{"id":"history-12","system":"skin","question":"Is the pain in a band on just one side, and have you noticed a rash there?","listenFor":["No dermatomal pain","Unilateral band-like pain without a visible rash","Unilateral band-like pain with a vesicular rash"],"why":"Band-like pain in a single dermatome with a vesicular rash suggests herpes zoster (shingles).","whySource":"curated","meaning":"Band-like pain in a single dermatome with a vesicular rash suggests herpes zoster (shingles).","meaningSource":"curated"},{"id":"history-13","system":"gastrointestinal","question":"Is it a burning pain that's worse after eating or lying down, and does it get better with antacids?","listenFor":["No relationship to meals or antacids","Burning worse after meals or lying down, relieved by antacids"],"why":"Burning retrosternal pain worse after meals or lying down and relieved by antacids suggests gastroesophageal reflux.","whySource":"curated","meaning":"Burning retrosternal pain worse after meals or lying down and relieved by antacids suggests gastroesophageal reflux.","meaningSource":"curated"},{"id":"history-14","system":"gastrointestinal","question":"Did you have severe vomiting or retching right before the pain started?","listenFor":["No preceding vomiting or retching","Severe vomiting or retching immediately preceding the pain"],"why":"Forceful retching before chest pain raises concern for esophageal rupture (Boerhaave syndrome).","whySource":"curated","meaning":"Forceful retching before chest pain raises concern for esophageal rupture (Boerhaave syndrome).","meaningSource":"curated"},{"id":"history-15","system":"gastrointestinal","question":"Do you have pain in your right upper belly that spreads to your shoulder or back?","listenFor":["No right upper quadrant or shoulder-radiating pain","Right upper quadrant pain after fatty food","Right upper quadrant pain with fever or chills"],"why":"Right upper quadrant pain after fatty foods suggests biliary colic or cholecystitis.","whySource":"curated","meaning":"Right upper quadrant pain after fatty foods suggests biliary colic or cholecystitis.","meaningSource":"curated"},{"id":"history-16","system":"psychiatric","question":"Does this feel like a panic attack, with tingling around your mouth or hands?","listenFor":["No situational trigger or panic history","Situational trigger with paresthesias, resolves with reassurance","Known panic disorder with similar prior episodes"],"why":null,"whySource":null,"meaning":"Perioral and hand tingling with a situational trigger fits a panic attack with hyperventilation — but panic is a diagnosis of exclusion. Only accept it after ACS, pulmonary embolism, and other dangerous causes have been ruled out, especially on a first episode.","meaningSource":"ai-draft"},{"id":"history-17","system":"medication","question":"Have you used cocaine, amphetamines, or other stimulants recently?","listenFor":["No stimulant use","Stimulant use more than 24 hours before onset","Stimulant use within 24 hours of onset"],"why":null,"whySource":null,"meaning":"Stimulant use within 24 hours of onset raises the risk of cocaine-associated MI, coronary vasospasm, aortic dissection, and arrhythmia. These patients need the same full ACS workup, and the timing of use guides whether vasospasm is likely still active.","meaningSource":"ai-draft"}],"exam":[{"id":"exam-01","system":"cardiovascular","maneuver":"Measure blood pressure in both arms.","findings":["Symmetric blood pressure between arms","Hypertensive on both sides without asymmetry","Blood pressure differential greater than 20 mmHg between arms"],"how":null,"why":"A systolic blood pressure difference greater than 20 mmHg between arms suggests aortic dissection.","whySource":"curated","meaning":"A systolic blood pressure difference greater than 20 mmHg between arms suggests aortic dissection.","meaningSource":"curated"},{"id":"exam-02","system":"cardiovascular","maneuver":"Palpate peripheral pulses for symmetry.","findings":["Symmetric pulses throughout","Diminished or absent pulse in one limb"],"how":null,"why":null,"whySource":null,"meaning":"Diminished or absent pulses in one limb — or a blood pressure difference between arms — suggests aortic dissection with branch-vessel involvement. Check pulses and bilateral arm pressures in every chest-pain patient, because a deficit shifts the workup to emergent aortic imaging.","meaningSource":"ai-draft"},{"id":"exam-03","system":"cardiovascular","maneuver":"Auscultate for a new diastolic murmur.","findings":["No murmur","New diastolic murmur of aortic regurgitation"],"how":null,"why":"A new diastolic murmur of aortic regurgitation suggests acute aortic valve disruption, as in aortic dissection or endocarditis.","whySource":"curated","meaning":"A new diastolic murmur of aortic regurgitation suggests acute aortic valve disruption, as in aortic dissection or endocarditis.","meaningSource":"curated"},{"id":"exam-04","system":"cardiovascular","maneuver":"Auscultate for a pericardial friction rub.","findings":["No friction rub","Pericardial friction rub present"],"how":null,"why":"A pericardial friction rub suggests acute pericarditis.","whySource":"curated","meaning":"A pericardial friction rub suggests acute pericarditis.","meaningSource":"curated"},{"id":"exam-05","system":"cardiovascular","maneuver":"Assess jugular venous pressure and heart sounds for tamponade physiology.","findings":["Normal jugular venous pressure, normal heart sounds","Elevated jugular venous pressure with muffled heart sounds and hypotension"],"how":"With the patient reclined at 30 to 45 degrees, identify the highest point of internal jugular venous pulsation and measure its vertical distance above the sternal angle.","why":"Elevated jugular venous pressure reflects elevated right-sided filling pressures, seen in right heart failure, volume overload, or tamponade.","whySource":"curated","meaning":"Elevated jugular venous pressure reflects elevated right-sided filling pressures, seen in right heart failure, volume overload, or tamponade.","meaningSource":"curated"},{"id":"exam-06","system":"respiratory","maneuver":"Auscultate the lungs for asymmetry or focal findings.","findings":["Clear and symmetric bilaterally","Unilateral absent breath sounds with hyperresonance","Focal crackles or dullness","Diminished breath sounds with subcutaneous crepitus or a mediastinal crunch"],"how":null,"why":"Subcutaneous crepitus indicates air in the soft tissues, as in pneumomediastinum, pneumothorax, or esophageal rupture.","whySource":"curated","meaning":"Subcutaneous crepitus indicates air in the soft tissues, as in pneumomediastinum, pneumothorax, or esophageal rupture.","meaningSource":"curated"},{"id":"exam-07","system":"musculoskeletal","maneuver":"Palpate the chest wall for reproducible tenderness.","findings":["Nontender, pain not reproduced","Focal chest wall tenderness reproducing the pain","Palpable crepitus or step-off"],"how":null,"why":null,"whySource":null,"meaning":"Pain exactly reproduced by palpating one spot favors a musculoskeletal source like costochondritis or strain. But reproducible tenderness does not rule out ACS, so treat it as a low-risk modifier only when the rest of the picture is otherwise low risk — and a palpable step-off or crepitus points to fracture.","meaningSource":"ai-draft"},{"id":"exam-08","system":"skin","maneuver":"Inspect the skin over the painful dermatome for a vesicular rash.","findings":["No rash","Vesicular rash in a dermatomal distribution"],"how":null,"why":null,"whySource":null,"meaning":"A vesicular rash confined to a single dermatome identifies herpes zoster (shingles) as the cause of the pain — look for it especially when pain precedes any visible rash, and consider antivirals if lesions are fresh.","meaningSource":"ai-draft"},{"id":"exam-09","system":"gastrointestinal","maneuver":"Palpate the right upper quadrant for a Murphy sign.","findings":["Nontender, negative Murphy sign","Right upper quadrant tenderness with a positive Murphy sign"],"how":"Hook your fingers under the right costal margin at the midclavicular line and ask the patient to inhale deeply; abrupt inspiratory arrest from pain is a positive Murphy sign.","why":"A positive Murphy sign (inspiratory arrest on palpation of the right upper quadrant) suggests acute cholecystitis.","whySource":"curated","meaning":"A positive Murphy sign (inspiratory arrest on palpation of the right upper quadrant) suggests acute cholecystitis.","meaningSource":"curated"},{"id":"exam-10","system":"neurologic","maneuver":"Assess mental status and perfusion.","findings":["Alert with normal color and perfusion","Diaphoretic, pale, or poorly perfused","Altered mental status with hypotension"],"how":null,"why":null,"whySource":null,"meaning":"A diaphoretic, pale, or poorly perfused chest-pain patient is in or approaching shock — obstructive (pulmonary embolism, tamponade), cardiogenic, or hemorrhagic — and altered mentation with hypotension is late and ominous. Get vitals, continuous monitoring, and resuscitation going alongside the cardiac workup.","meaningSource":"ai-draft"},{"id":"exam-11","system":"cardiovascular","maneuver":"Inspect and palpate the calves for asymmetric swelling or a palpable cord.","findings":["Symmetric, no tenderness or swelling","Unilateral swelling, tenderness, or palpable cord"],"how":null,"why":"Unilateral calf swelling, tenderness, or a palpable cord suggests deep vein thrombosis.","whySource":"curated","meaning":"Unilateral calf swelling, tenderness, or a palpable cord suggests deep vein thrombosis.","meaningSource":"curated"}],"reviewNeeded":{"whyMissing":13,"howMissing":9}},{"id":"abdominal-pain","title":"Abdominal pain","aliases":["acute abdomen","stomach pain"],"history":[{"id":"history-01","system":"gastrointestinal","question":"Where did the pain start, and has it moved anywhere?","listenFor":["Periumbilical pain migrating to the right lower quadrant","Right upper quadrant pain, worse after fatty food","Epigastric pain radiating to the back","Diffuse pain without clear localization"],"why":"Periumbilical pain migrating to the right lower quadrant is the classic presentation of acute appendicitis.","whySource":"curated","meaning":"Periumbilical pain migrating to the right lower quadrant is the classic presentation of acute appendicitis.","meaningSource":"curated"},{"id":"history-02","system":"gastrointestinal","question":"How suddenly did the pain start, and how bad is it compared to any pain you've had before?","listenFor":["Gradual onset, mild to moderate severity","Sudden onset, worst pain of the patient's life","Pain out of proportion to the physical findings"],"why":"Pain out of proportion to the physical findings is a red flag for necrotizing soft tissue infection or mesenteric ischemia.","whySource":"curated","meaning":"Pain out of proportion to the physical findings is a red flag for necrotizing soft tissue infection or mesenteric ischemia.","meaningSource":"curated"},{"id":"history-03","system":"gastrointestinal","question":"Did you vomit before the pain started, or after?","listenFor":["No vomiting","Vomiting preceded the pain","Vomiting began after the pain started"],"why":"Vomiting after pain onset fits a surgical abdomen such as appendicitis or cholecystitis; vomiting before pain suggests gastroenteritis or obstruction.","whySource":"curated","meaning":"Vomiting after pain onset fits a surgical abdomen such as appendicitis or cholecystitis; vomiting before pain suggests gastroenteritis or obstruction.","meaningSource":"curated"},{"id":"history-04","system":"gastrointestinal","question":"Are you able to pass gas or have a bowel movement?","listenFor":["Passing flatus and stool normally","Obstipation with abdominal distention"],"why":"Inability to pass gas or stool (obstipation) with distention suggests complete bowel obstruction.","whySource":"curated","meaning":"Inability to pass gas or stool (obstipation) with distention suggests complete bowel obstruction.","meaningSource":"curated"},{"id":"history-05","system":"hematologic","question":"Have you noticed black, tarry stools, red blood in your stool, or vomited blood?","listenFor":["No signs of gastrointestinal bleeding","Melena or hematochezia","Hematemesis"],"why":"Black, tarry stools (melena), hematochezia, or hematemesis indicate gastrointestinal bleeding; melena points to an upper source.","whySource":"curated","meaning":"Black, tarry stools (melena), hematochezia, or hematemesis indicate gastrointestinal bleeding; melena points to an upper source.","meaningSource":"curated"},{"id":"history-06","system":"cardiovascular","question":"Do you have an irregular heartbeat, a clotting disorder, or a known aneurysm in your belly?","listenFor":["No known risk factor","Known atrial fibrillation or hypercoagulable state","Known abdominal aortic aneurysm"],"why":"Atrial fibrillation or a hypercoagulable state with acute abdominal pain raises concern for mesenteric ischemia.","whySource":"curated","meaning":"Atrial fibrillation or a hypercoagulable state with acute abdominal pain raises concern for mesenteric ischemia.","meaningSource":"curated"},{"id":"history-07","system":"gastrointestinal","question":"Do you drink heavily, have gallstones, or have high triglycerides?","listenFor":["No known risk factor","Heavy or binge alcohol use preceding symptom onset","Known gallstones or biliary colic","Known hypertriglyceridemia"],"why":"Severe hypertriglyceridemia (typically over 1000 mg/dL) can precipitate pancreatitis.","whySource":"curated","meaning":"Severe hypertriglyceridemia (typically over 1000 mg/dL) can precipitate pancreatitis.","meaningSource":"curated"},{"id":"history-08","system":"reproductive","question":"Is there any chance you could be pregnant, and have you had any vaginal bleeding or sudden one-sided pelvic pain?","listenFor":["Not applicable or none of these","Possible pregnancy with vaginal bleeding","Sudden severe unilateral pelvic pain with nausea"],"why":"Vaginal bleeding with possible pregnancy raises concern for ectopic pregnancy or miscarriage.","whySource":"curated","meaning":"Vaginal bleeding with possible pregnancy raises concern for ectopic pregnancy or miscarriage.","meaningSource":"curated"},{"id":"history-09","system":"genitourinary","question":"Do you have any burning with urination, or pain in your side that spreads toward your groin?","listenFor":["No urinary symptoms","Dysuria and frequency with fever","Colicky flank pain radiating to the groin with hematuria"],"why":"Colicky flank pain radiating to the groin with hematuria suggests an obstructing ureteral stone.","whySource":"curated","meaning":"Colicky flank pain radiating to the groin with hematuria suggests an obstructing ureteral stone.","meaningSource":"curated"},{"id":"history-10","system":"gastrointestinal","question":"Do you have a hernia that has become painful, bulging, or that you can't push back in?","listenFor":["No known hernia","Known hernia now painful, bulging, or irreducible"],"why":null,"whySource":null,"meaning":"A hernia that is newly painful, bulging, or irreducible raises concern for incarceration or strangulation — a surgical emergency — especially with vomiting or obstipation suggesting obstruction. Do not attempt forceful reduction; involve surgery promptly.","meaningSource":"ai-draft"},{"id":"history-11","system":"gastrointestinal","question":"Have you had abdominal surgery in the past?","listenFor":["No prior abdominal surgery","Prior abdominal surgery"],"why":null,"whySource":null,"meaning":"Prior abdominal surgery predisposes to adhesive small bowel obstruction, so pain with vomiting and obstipation in these patients should be evaluated for obstruction. Prior operative anatomy also changes what the surgeon needs to know before any intervention.","meaningSource":"ai-draft"},{"id":"history-12","system":"reproductive","question":"Did you have sudden pain in one testicle along with nausea or vomiting?","listenFor":["Not applicable or none","Sudden unilateral testicular pain with nausea or vomiting"],"why":"Sudden unilateral testicular pain with nausea or vomiting suggests testicular torsion, a surgical emergency.","whySource":"curated","meaning":"Sudden unilateral testicular pain with nausea or vomiting suggests testicular torsion, a surgical emergency.","meaningSource":"curated"},{"id":"history-13","system":"gastrointestinal","question":"Do you have inflammatory bowel disease, and does this feel like a prior flare, or have you had bloody diarrhea?","listenFor":["No known inflammatory bowel disease or bloody diarrhea","Known inflammatory bowel disease, pain resembles a prior flare","Bloody diarrhea accompanying the pain"],"why":null,"whySource":null,"meaning":"Known inflammatory bowel disease makes a flare the leading consideration when the pain matches prior episodes. But bloody diarrhea or a pain pattern that differs from prior flares warrants evaluation for complications such as toxic megacolon, abscess, or obstruction — and IBD patients remain at risk for ordinary surgical emergencies like appendicitis.","meaningSource":"ai-draft"},{"id":"history-14","system":"endocrine","question":"Do you have diabetes, and have you noticed excessive thirst, urination, or a fruity breath smell?","listenFor":["No known diabetes","Known diabetes with polyuria or polydipsia","Known diabetes with fruity breath odor or rapid, deep breathing"],"why":"Fruity breath with rapid, deep breathing suggests diabetic ketoacidosis.","whySource":"curated","meaning":"Fruity breath with rapid, deep breathing suggests diabetic ketoacidosis.","meaningSource":"curated"},{"id":"history-15","system":"medication","question":"Do you regularly take NSAIDs like ibuprofen, or a blood thinner?","listenFor":["Neither","Chronic NSAID use","Anticoagulant use"],"why":"Chronic NSAID use raises the risk of peptic ulcer disease and gastrointestinal bleeding.","whySource":"curated","meaning":"Chronic NSAID use raises the risk of peptic ulcer disease and gastrointestinal bleeding.","meaningSource":"curated"},{"id":"history-16","system":"cardiovascular","question":"Do you get a squeezing pain in your upper belly with exertion, or have you been diagnosed with heart disease?","listenFor":["No known coronary disease or exertional discomfort","Known coronary artery disease without exertional epigastric symptoms","Exertional epigastric discomfort"],"why":"Exertional epigastric discomfort can be an anginal equivalent of myocardial ischemia.","whySource":"curated","meaning":"Exertional epigastric discomfort can be an anginal equivalent of myocardial ischemia.","meaningSource":"curated"}],"exam":[{"id":"exam-01","system":"general","maneuver":"Assess general appearance and vital signs.","findings":["Well-appearing, normotensive","Ill-appearing, tachycardic","Hypotensive or in shock"],"how":null,"why":null,"whySource":null,"meaning":"General appearance and vitals are the first triage step: an ill-appearing or tachycardic patient may be septic, bleeding, or hypovolemic, and hypotension or shock mandates immediate resuscitation and a search for a catastrophic cause before any leisurely workup.","meaningSource":"ai-draft"},{"id":"exam-02","system":"gastrointestinal","maneuver":"Palpate the abdomen for tenderness, guarding, and rebound.","findings":["Soft, nontender","Focal tenderness without guarding","Guarding, rebound, or rigidity"],"how":null,"why":"Guarding, rebound, or rigidity on palpation suggests peritonitis.","whySource":"curated","meaning":"Guarding, rebound, or rigidity on palpation suggests peritonitis.","meaningSource":"curated"},{"id":"exam-03","system":"gastrointestinal","maneuver":"Assess McBurney point tenderness and Rovsing, psoas, or obturator signs.","findings":["All negative","Positive McBurney point tenderness","Positive Rovsing, psoas, or obturator sign"],"how":"Palpate one-third of the distance from the anterior superior iliac spine to the umbilicus; that point is McBurney point.","why":"McBurney point tenderness with Rovsing, psoas, or obturator signs suggests acute appendicitis.","whySource":"curated","meaning":"McBurney point tenderness with Rovsing, psoas, or obturator signs suggests acute appendicitis.","meaningSource":"curated"},{"id":"exam-04","system":"gastrointestinal","maneuver":"Assess the right upper quadrant for a Murphy sign or palpable mass.","findings":["Negative Murphy sign, no mass","Positive Murphy sign","Palpable gallbladder mass"],"how":"Hook your fingers under the right costal margin at the midclavicular line and ask the patient to inhale deeply; abrupt inspiratory arrest from pain is a positive Murphy sign.","why":"A positive Murphy sign (inspiratory arrest on palpation of the right upper quadrant) suggests acute cholecystitis.","whySource":"curated","meaning":"A positive Murphy sign (inspiratory arrest on palpation of the right upper quadrant) suggests acute cholecystitis.","meaningSource":"curated"},{"id":"exam-05","system":"gastrointestinal","maneuver":"Inspect for distention and auscultate bowel sounds.","findings":["Normal bowel sounds, no distention","Distended with high-pitched or hyperactive bowel sounds","Distended and silent"],"how":null,"why":"High-pitched, hyperactive bowel sounds suggest early mechanical obstruction; absent bowel sounds suggest ileus or late obstruction.","whySource":"curated","meaning":"High-pitched, hyperactive bowel sounds suggest early mechanical obstruction; absent bowel sounds suggest ileus or late obstruction.","meaningSource":"curated"},{"id":"exam-06","system":"cardiovascular","maneuver":"Palpate the abdomen for a pulsatile mass.","findings":["No pulsatile mass","Palpable pulsatile mass, hemodynamically stable","Pulsatile mass with hypotension"],"how":null,"why":"A pulsatile abdominal mass with hypotension suggests ruptured abdominal aortic aneurysm, a surgical emergency.","whySource":"curated","meaning":"A pulsatile abdominal mass with hypotension suggests ruptured abdominal aortic aneurysm, a surgical emergency.","meaningSource":"curated"},{"id":"exam-07","system":"genitourinary","maneuver":"Assess for costovertebral-angle tenderness.","findings":["None","Unilateral costovertebral-angle tenderness","Bilateral costovertebral-angle tenderness"],"how":null,"why":"Costovertebral angle tenderness suggests pyelonephritis.","whySource":"curated","meaning":"Costovertebral angle tenderness suggests pyelonephritis.","meaningSource":"curated"},{"id":"exam-08","system":"gastrointestinal","maneuver":"Examine hernia sites for a bulge and reducibility.","findings":["No hernia identified","Reducible hernia","Tender, irreducible or incarcerated hernia"],"how":null,"why":"A tender, irreducible hernia suggests incarceration or strangulation, which needs urgent surgical evaluation.","whySource":"curated","meaning":"A tender, irreducible hernia suggests incarceration or strangulation, which needs urgent surgical evaluation.","meaningSource":"curated"},{"id":"exam-09","system":"reproductive","maneuver":"Perform a pelvic or testicular examination when clinically indicated.","findings":["Normal or deferred as not indicated","Cervical motion tenderness or adnexal mass or tenderness","High-riding, tender testicle with absent cremasteric reflex"],"how":null,"why":"A high-riding, tender testicle with absent cremasteric reflex suggests testicular torsion, a surgical emergency.","whySource":"curated","meaning":"A high-riding, tender testicle with absent cremasteric reflex suggests testicular torsion, a surgical emergency.","meaningSource":"curated"},{"id":"exam-10","system":"gastrointestinal","maneuver":"Perform a rectal examination when clinically indicated.","findings":["Normal, guaiac negative, or deferred as not indicated","Gross blood or melena on examination","Palpable mass on examination"],"how":null,"why":"Melena (black, tarry stools) indicates upper gastrointestinal bleeding.","whySource":"curated","meaning":"Melena (black, tarry stools) indicates upper gastrointestinal bleeding.","meaningSource":"curated"},{"id":"exam-11","system":"skin","maneuver":"Inspect skin and sclerae for jaundice or flank/periumbilical ecchymosis.","findings":["Normal color, no ecchymosis","Jaundice or scleral icterus","Flank (Grey Turner) or periumbilical (Cullen) ecchymosis"],"how":null,"why":"Flank ecchymosis (Grey Turner sign) or periumbilical ecchymosis (Cullen sign) suggests retroperitoneal hemorrhage, as in severe pancreatitis.","whySource":"curated","meaning":"Flank ecchymosis (Grey Turner sign) or periumbilical ecchymosis (Cullen sign) suggests retroperitoneal hemorrhage, as in severe pancreatitis.","meaningSource":"curated"}],"reviewNeeded":{"whyMissing":4,"howMissing":9}},{"id":"fever-suspected-infection","title":"Fever / suspected infection","aliases":["fever","infection"],"history":[{"id":"history-01","system":"infectious","question":"Has your fever been low-grade and coming and going, or high with shaking chills?","listenFor":["Low-grade, intermittent fever","High fever with shaking rigors","Subjective coldness or measured hypothermia instead of fever"],"why":"Fever with shaking chills (rigors) suggests bacteremia.","whySource":"curated","meaning":"Fever with shaking chills (rigors) suggests bacteremia.","meaningSource":"curated"},{"id":"history-02","system":"respiratory","question":"Have you had a cough?","listenFor":["No cough","Cough"],"why":null,"whySource":null,"meaning":"Cough localizes the source to the respiratory tract and raises pneumonia in the differential; its character and associated sputum help distinguish viral from bacterial causes.","meaningSource":"ai-draft"},{"id":"history-03","system":"respiratory","question":"Do you have any sharp chest pain that's worse when you breathe in?","listenFor":["No pleuritic chest pain","Pleuritic chest pain"],"why":"Pleuritic chest pain with sudden dyspnea suggests pulmonary embolism.","whySource":"curated","meaning":"Pleuritic chest pain with sudden dyspnea suggests pulmonary embolism.","meaningSource":"curated"},{"id":"history-04","system":"genitourinary","question":"Do you have any burning with urination, going more often than usual, or pain in your side?","listenFor":["No urinary symptoms","Dysuria or urinary frequency","Flank pain"],"why":null,"whySource":null,"meaning":"Burning with urination, frequency, or flank pain points to a urinary source — cystitis versus pyelonephritis — which determines whether outpatient treatment or admission is needed.","meaningSource":"ai-draft"},{"id":"history-05","system":"gastrointestinal","question":"Do you have belly pain, or has your skin or eyes turned yellow along with chills?","listenFor":["No abdominal pain or jaundice","Localized abdominal pain","Jaundice with right upper quadrant pain and rigors"],"why":"Fever with shaking chills (rigors) suggests bacteremia.","whySource":"curated","meaning":"Fever with shaking chills (rigors) suggests bacteremia.","meaningSource":"curated"},{"id":"history-06","system":"skin","question":"Do you have any redness on your skin, and does it hurt a lot more than it looks like it should?","listenFor":["No skin redness or disproportionate pain","Localized erythema and warmth","Rapidly spreading pain out of proportion to exam, with blistering or dark discoloration"],"why":"Pain out of proportion to the physical findings is a red flag for necrotizing soft tissue infection or mesenteric ischemia.","whySource":"curated","meaning":"Pain out of proportion to the physical findings is a red flag for necrotizing soft tissue infection or mesenteric ischemia.","meaningSource":"curated"},{"id":"history-07","system":"musculoskeletal","question":"Do you have a new swollen, painful joint that's hard to move?","listenFor":["No new joint symptoms","New joint swelling or pain with restricted motion"],"why":"A new hot, swollen joint with restricted motion raises concern for septic arthritis.","whySource":"curated","meaning":"A new hot, swollen joint with restricted motion raises concern for septic arthritis.","meaningSource":"curated"},{"id":"history-08","system":"neurologic","question":"Do you have a stiff neck, or has any light been bothering your eyes?","listenFor":["No neck stiffness or photophobia","Neck stiffness","Photophobia"],"why":"Neck stiffness with fever and headache suggests meningitis.","whySource":"curated","meaning":"Neck stiffness with fever and headache suggests meningitis.","meaningSource":"curated"},{"id":"history-09","system":"medication","question":"Are you on chemotherapy, a transplant medication, a biologic, or long-term steroids?","listenFor":["No chronic immunosuppression","Chronic steroid or biologic therapy","Transplant history, chemotherapy, or known neutropenia"],"why":null,"whySource":null,"meaning":"Chemotherapy, transplant drugs, biologics, and long-term steroids blunt the immune response and widen the differential to opportunistic infections; these patients need a lower threshold for workup and admission, and neutropenic fever is an emergency.","meaningSource":"ai-draft"},{"id":"history-10","system":"infectious","question":"Has anyone around you been sick with similar symptoms?","listenFor":["No known sick contacts","Sick contacts with similar symptoms"],"why":null,"whySource":null,"meaning":"Sick contacts suggest a contagious or outbreak etiology such as influenza or COVID-19, which guides testing, isolation precautions, and empiric therapy choices.","meaningSource":"ai-draft"},{"id":"history-11","system":"infectious","question":"Have you traveled anywhere recently, especially outside the country?","listenFor":["No recent travel to an endemic area","Recent travel to an area with endemic infectious disease"],"why":null,"whySource":null,"meaning":"Recent travel, especially international, brings travel-associated infections such as malaria, dengue, and typhoid into the differential; the destination and timing determine which specific tests to order.","meaningSource":"ai-draft"},{"id":"history-12","system":"infectious","question":"Have you been bitten by a tick or handled any animals recently?","listenFor":["No tick or animal exposure","Tick or animal exposure"],"why":null,"whySource":null,"meaning":"Tick bites and animal exposures point to zoonotic infections such as Lyme disease, ehrlichiosis, or tularemia; identifying the exposure narrows testing and empiric treatment.","meaningSource":"ai-draft"},{"id":"history-13","system":"medication","question":"Did you start a new antibiotic, seizure medication, or gout medication before the fever began?","listenFor":["No new drug-fever risk medication","New antibiotic started","New antiepileptic or allopurinol started"],"why":"Antiepileptics and allopurinol can cause drug fever or DRESS syndrome.","whySource":"curated","meaning":"Antiepileptics and allopurinol can cause drug fever or DRESS syndrome.","meaningSource":"curated"},{"id":"history-14","system":"medication","question":"Did you start a new antidepressant or antipsychotic medication before the fever began?","listenFor":["No new serotonergic agent or antipsychotic","New serotonergic agent started","New antipsychotic started"],"why":"New serotonergic agents can precipitate serotonin syndrome.","whySource":"curated","meaning":"New serotonergic agents can precipitate serotonin syndrome.","meaningSource":"curated"},{"id":"history-15","system":"endocrine","question":"Do you have an overactive thyroid, and have you been taking your thyroid medication as prescribed?","listenFor":["No known hyperthyroidism","Known hyperthyroidism, adherent to therapy","Known hyperthyroidism with missed thionamide doses"],"why":"Missed thionamide doses in hyperthyroidism can precipitate thyroid storm.","whySource":"curated","meaning":"Missed thionamide doses in hyperthyroidism can precipitate thyroid storm.","meaningSource":"curated"},{"id":"history-16","system":"cardiovascular","question":"Have you had a recent dental or vascular procedure, do you have a known heart valve problem, or do you inject drugs?","listenFor":["No known risk factor","Recent dental or vascular procedure","Known valvular disease","Intravenous drug use"],"why":"Recent dental or vascular procedures can seed bacteremia and endocarditis.","whySource":"curated","meaning":"Recent dental or vascular procedures can seed bacteremia and endocarditis.","meaningSource":"curated"},{"id":"history-17","system":"medication","question":"Do you have a catheter, port, or other implanted device, and is there any pain, redness, or drainage where it is?","listenFor":["No indwelling device","Indwelling device without local symptoms","Indwelling device with local pain, redness, or drainage"],"why":"Pain, redness, or drainage at a device site suggests device-related infection.","whySource":"curated","meaning":"Pain, redness, or drainage at a device site suggests device-related infection.","meaningSource":"curated"},{"id":"history-18","system":"infectious","question":"Have you been in the hospital or had surgery in the past month?","listenFor":["No recent hospitalization or surgery","Recent hospitalization or surgery within the preceding month"],"why":"Recent hospitalization or surgery raises risk for healthcare-associated and resistant infections.","whySource":"curated","meaning":"Recent hospitalization or surgery raises risk for healthcare-associated and resistant infections.","meaningSource":"curated"}],"exam":[{"id":"exam-01","system":"general","maneuver":"Assess general appearance and hemodynamic stability.","findings":["Well-appearing, stable vital signs","Toxic-appearing, tachycardic","Hypotensive or in shock"],"how":null,"why":"A toxic appearance with abnormal vital signs suggests severe systemic illness or sepsis.","whySource":"curated","meaning":"A toxic appearance with abnormal vital signs suggests severe systemic illness or sepsis.","meaningSource":"curated"},{"id":"exam-02","system":"skin","maneuver":"Inspect the skin for localized infection versus necrotizing changes.","findings":["Normal skin","Localized erythema and warmth consistent with cellulitis","Pain out of proportion with bullae, crepitus, or skin necrosis"],"how":null,"why":"Pain out of proportion to the physical findings is a red flag for necrotizing soft tissue infection or mesenteric ischemia.","whySource":"curated","meaning":"Pain out of proportion to the physical findings is a red flag for necrotizing soft tissue infection or mesenteric ischemia.","meaningSource":"curated"},{"id":"exam-03","system":"infectious","maneuver":"Inspect any wound, line, or device site.","findings":["Normal, no device or wound present","Purulent drainage or erythema at a wound or device site"],"how":null,"why":null,"whySource":null,"meaning":"Wounds, lines, and device sites are common occult sources of fever; purulent drainage or erythema at a site identifies a device or wound infection that may require removal or drainage in addition to antibiotics.","meaningSource":"ai-draft"},{"id":"exam-04","system":"respiratory","maneuver":"Auscultate the lungs for focal or diffuse findings.","findings":["Clear bilaterally","Focal crackles or dullness","Diffuse bilateral findings"],"how":null,"why":null,"whySource":null,"meaning":"Focal crackles or dullness suggests pneumonia and localizes the source, while diffuse bilateral findings point toward a viral process or widespread pulmonary involvement — the pattern directs imaging and therapy.","meaningSource":"ai-draft"},{"id":"exam-05","system":"gastrointestinal","maneuver":"Palpate the abdomen for focal tenderness or peritoneal signs.","findings":["Soft, nontender","Right upper quadrant tenderness","Diffuse tenderness with guarding or rebound"],"how":null,"why":"Guarding, rebound, or rigidity on palpation suggests peritonitis.","whySource":"curated","meaning":"Guarding, rebound, or rigidity on palpation suggests peritonitis.","meaningSource":"curated"},{"id":"exam-06","system":"genitourinary","maneuver":"Assess for costovertebral-angle tenderness.","findings":["None","Unilateral costovertebral-angle tenderness","Bilateral costovertebral-angle tenderness"],"how":null,"why":"Costovertebral angle tenderness suggests pyelonephritis.","whySource":"curated","meaning":"Costovertebral angle tenderness suggests pyelonephritis.","meaningSource":"curated"},{"id":"exam-07","system":"musculoskeletal","maneuver":"Examine any symptomatic joint for effusion, warmth, and range of motion.","findings":["Normal range of motion, no effusion","Warm, swollen joint with restricted motion","Overlying erythema with inability to bear weight or move the joint"],"how":null,"why":null,"whySource":null,"meaning":"A warm, swollen joint with restricted motion is a red flag for septic arthritis, which needs urgent arthrocentesis; inability to bear weight or move the joint further raises concern for a joint emergency rather than simple inflammation.","meaningSource":"ai-draft"},{"id":"exam-08","system":"neurologic","maneuver":"Assess for nuchal rigidity and mental status change.","findings":["No nuchal rigidity, normal mental status","Nuchal rigidity","Altered mental status with a focal neurologic deficit"],"how":null,"why":"Nuchal rigidity suggests meningeal irritation, as in meningitis or subarachnoid hemorrhage.","whySource":"curated","meaning":"Nuchal rigidity suggests meningeal irritation, as in meningitis or subarachnoid hemorrhage.","meaningSource":"curated"},{"id":"exam-09","system":"cardiovascular","maneuver":"Auscultate for a new heart murmur.","findings":["No murmur","New murmur"],"how":null,"why":"A new murmur suggests acute valvular pathology, as in endocarditis or aortic dissection.","whySource":"curated","meaning":"A new murmur suggests acute valvular pathology, as in endocarditis or aortic dissection.","meaningSource":"curated"},{"id":"exam-10","system":"skin","maneuver":"Inspect the extremities and nail beds for embolic or immunologic stigmata of endocarditis.","findings":["No stigmata present","Janeway lesions or Osler nodes","Splinter hemorrhages"],"how":null,"why":"Janeway lesions, Osler nodes, splinter hemorrhages, and Roth spots are embolic or immunologic stigmata of infective endocarditis.","whySource":"curated","meaning":"Janeway lesions, Osler nodes, splinter hemorrhages, and Roth spots are embolic or immunologic stigmata of infective endocarditis.","meaningSource":"curated"},{"id":"exam-11","system":"ent","maneuver":"Inspect the oropharynx, teeth, and neck for a focal source.","findings":["Normal oropharynx and neck","Focal cervical lymphadenopathy","Oropharyngeal exudate","Dental abscess"],"how":null,"why":"A dental abscess can seed bacteremia and endocarditis.","whySource":"curated","meaning":"A dental abscess can seed bacteremia and endocarditis.","meaningSource":"curated"}],"reviewNeeded":{"whyMissing":9,"howMissing":11}},{"id":"generalized-weakness","title":"Generalized weakness / non-specific decline","aliases":["weakness","decline"],"history":[{"id":"history-01","system":"neurologic","question":"Did the weakness come on gradually over days, suddenly on one side, or is it spreading upward from your legs?","listenFor":["Gradual, diffuse weakness over days to weeks","Sudden, asymmetric weakness of one side","Symmetric, ascending weakness starting in the legs"],"why":"Symmetric ascending weakness suggests Guillain-Barre syndrome.","whySource":"curated","meaning":"Symmetric ascending weakness suggests Guillain-Barre syndrome.","meaningSource":"curated"},{"id":"history-02","system":"infectious","question":"Have you had a fever?","listenFor":["No fever","Subjective fever","Documented fever with rigors"],"why":"Fever with shaking chills (rigors) suggests bacteremia.","whySource":"curated","meaning":"Fever with shaking chills (rigors) suggests bacteremia.","meaningSource":"curated"},{"id":"history-03","system":"medication","question":"Have you started a new medication or had a dose change in the past few days?","listenFor":["No recent medication change","New sedative or opioid started","New antihypertensive started","Dose change to an existing chronic medication"],"why":null,"whySource":null,"meaning":"New or changed medications are a common reversible cause of generalized weakness in older adults — sedatives, opioids, and new antihypertensives can all produce weakness, while a recent antihypertensive start or dose increase suggests orthostatic hypotension or medication-induced fatigue; reviewing the timeline points to a medication adjustment or holding as the next step.","meaningSource":"ai-draft"},{"id":"history-04","system":"cardiovascular","question":"Have you felt like you were going to pass out, or did you actually pass out?","listenFor":["No syncope or near-syncope","Near-syncope or presyncope","Frank syncope"],"why":null,"whySource":null,"meaning":"Near-syncope or frank syncope suggests the weakness is cardiac or neurovascular rather than muscular — transient loss of perfusion from arrhythmia, orthostatic hypotension, or valvular disease; any syncope warrants an orthostatic and cardiac workup, and frank syncope is a red flag for an acute event rather than simple deconditioning.","meaningSource":"ai-draft"},{"id":"history-05","system":"gastrointestinal","question":"Have you been eating and drinking normally the past few days?","listenFor":["Normal oral intake","Poor oral intake","Vomiting or diarrhea limiting intake"],"why":null,"whySource":null,"meaning":"Poor intake, vomiting, or diarrhea suggests the weakness is driven by volume depletion, electrolyte disturbance, or hypoglycemia rather than a primary neuromuscular problem; normal intake points away from dehydration and toward medication, neurologic, or systemic causes.","meaningSource":"ai-draft"},{"id":"history-06","system":"endocrine","question":"Have you felt unusually cold, gained weight, or become more constipated than usual?","listenFor":["No hypothyroid symptoms","Cold intolerance","Weight gain and constipation"],"why":"Cold intolerance with weight gain and constipation suggests hypothyroidism.","whySource":"curated","meaning":"Cold intolerance with weight gain and constipation suggests hypothyroidism.","meaningSource":"curated"},{"id":"history-07","system":"endocrine","question":"Have you lost weight without trying, or noticed new darkening of your skin?","listenFor":["No adrenal insufficiency symptoms","Fatigue and unintentional weight loss","New skin darkening or hyperpigmentation"],"why":"New hyperpigmentation of skin creases and scars suggests primary adrenal insufficiency.","whySource":"curated","meaning":"New hyperpigmentation of skin creases and scars suggests primary adrenal insufficiency.","meaningSource":"curated"},{"id":"history-08","system":"neurologic","question":"Have you noticed one side of your face drooping?","listenFor":["No facial droop","New facial droop"],"why":"New facial droop suggests stroke.","whySource":"curated","meaning":"New facial droop suggests stroke.","meaningSource":"curated"},{"id":"history-09","system":"neurologic","question":"Has your speech changed or become slurred?","listenFor":["No speech change","New speech change"],"why":null,"whySource":null,"meaning":"New slurred or changed speech is a focal neurologic red flag that re-frames \"weakness\" as a possible stroke, transient ischemic attack, or other central process rather than systemic decline; any positive answer warrants an urgent neurologic examination and consideration of stroke workup.","meaningSource":"ai-draft"},{"id":"history-10","system":"neurologic","question":"Have you noticed numbness or tingling on both sides along with the weakness?","listenFor":["No numbness or paresthesias","Symmetric numbness or paresthesias"],"why":null,"whySource":null,"meaning":"Symmetric numbness or tingling alongside weakness suggests a length-dependent process such as polyneuropathy, vitamin B12 deficiency, or a toxic-metabolic state rather than focal weakness; isolated weakness without sensory change points more toward deconditioning, medication effect, or a central cause.","meaningSource":"ai-draft"},{"id":"history-11","system":"psychiatric","question":"Have you been feeling down or lost interest in things you usually enjoy over the past several weeks?","listenFor":["No low mood or anhedonia","Low mood or anhedonia over several weeks"],"why":null,"whySource":null,"meaning":"Sustained low mood and anhedonia suggest depression is contributing to the functional decline, since psychomotor slowing and loss of initiative can mimic medical weakness; screening separates a treatable mood component from purely medical causes.","meaningSource":"ai-draft"},{"id":"history-12","system":"neurologic","question":"Have family or caregivers noticed your attention or thinking coming and going over the past day or two?","listenFor":["No acute inattention or confusion","Acute inattention or confusion, fluctuating over hours to days"],"why":null,"whySource":null,"meaning":"Acute, fluctuating inattention or confusion over hours to days is the hallmark of delirium, which frequently presents as new weakness or functional decline in older adults; delirium signals an underlying medical trigger (infection, medication, electrolyte disturbance) that must be found and treated rather than the weakness itself.","meaningSource":"ai-draft"},{"id":"history-13","system":"functional","question":"Who do you have helping you at home, and are you able to get the care and supplies you need?","listenFor":["Adequate supports, safe home environment","Living alone with limited supports","Signs of self-neglect or suspected abuse or neglect by a caregiver"],"why":null,"whySource":null,"meaning":"Understanding supports at home determines whether weakness is worsened by self-neglect — missed medications, poor nutrition, or inability to get supplies — and whether the home environment is safe; limited supports or signs of neglect or abuse trigger a social-work referral and discharge-planning needs, not just a medical workup.","meaningSource":"ai-draft"},{"id":"history-14","system":"musculoskeletal","question":"Have you fallen recently?","listenFor":["No recent fall","Recent fall without injury","Recent fall with injury or head strike"],"why":null,"whySource":null,"meaning":"A recent fall may be the cause of the decline (head injury, occult hip fracture, bleeding) or its consequence (orthostasis, weakness); a fall with head strike or injury is a red flag requiring targeted imaging and bleeding assessment, not just reassurance.","meaningSource":"ai-draft"},{"id":"history-15","system":"endocrine","question":"Do you have diabetes, and have you felt shaky, sweaty, or hungry along with the weakness?","listenFor":["No known diabetes","Known diabetes without hypoglycemic symptoms","Known diabetes with tremor, diaphoresis, or hunger"],"why":"Hypoglycemia causes neuroglycopenic symptoms such as confusion, diaphoresis, and tremor, and needs urgent correction.","whySource":"curated","meaning":"Hypoglycemia causes neuroglycopenic symptoms such as confusion, diaphoresis, and tremor, and needs urgent correction.","meaningSource":"curated"},{"id":"history-16","system":"hematologic","question":"Have you had a poor diet, heavy alcohol use, weight-loss surgery, or been told you're low in B12?","listenFor":["None of these","Poor diet, alcohol use, or bariatric surgery history","Known B12 deficiency with paresthesias or gait imbalance"],"why":"B12 deficiency causes paresthesias and gait imbalance from subacute combined degeneration.","whySource":"curated","meaning":"B12 deficiency causes paresthesias and gait imbalance from subacute combined degeneration.","meaningSource":"curated"},{"id":"history-17","system":"hematologic","question":"Have you lost weight without trying, or do you have a history of cancer with new symptoms?","listenFor":["No unintentional weight loss or known malignancy","Unintentional weight loss","Known malignancy with new or worsening symptoms"],"why":null,"whySource":null,"meaning":"Unintentional weight loss or a known cancer with new symptoms suggests the weakness is part of a systemic process such as malignancy, hypercalcemia, or progressive disease rather than benign decline; it warrants a malignancy-focused review of systems and workup.","meaningSource":"ai-draft"}],"exam":[{"id":"exam-01","system":"general","maneuver":"Assess vital signs and orthostatic change when safe.","findings":["Normal vital signs, no orthostatic change","Tachycardic or hypotensive at rest","Positive orthostatic hypotension"],"how":"Measure blood pressure and heart rate after 5 minutes supine, then at 1 and 3 minutes after standing; a sustained drop of 20 mmHg systolic or 10 mmHg diastolic within 3 minutes is positive.","why":null,"whySource":null,"meaning":"Orthostatic vitals distinguish volume depletion and autonomic failure from other causes of weakness: a sustained blood-pressure drop within 3 minutes of standing with inadequate heart-rate rise suggests dehydration, bleeding, or autonomic dysfunction, while orthostatic symptoms without a vital-sign change push the workup toward neurologic or medication causes.","meaningSource":"ai-draft"},{"id":"exam-02","system":"neurologic","maneuver":"Assess attention and level of consciousness.","findings":["Alert and fully oriented","Inattentive or fluctuating alertness","Lethargic or obtunded"],"how":null,"why":"Inattention with fluctuating alertness is the hallmark of delirium.","whySource":"curated","meaning":"Inattention with fluctuating alertness is the hallmark of delirium.","meaningSource":"curated"},{"id":"exam-03","system":"neurologic","maneuver":"Assess motor strength for symmetry.","findings":["Symmetric strength throughout","Unilateral weakness or facial droop","Symmetric distal weakness with diminished reflexes"],"how":null,"why":"New facial droop suggests stroke.","whySource":"curated","meaning":"New facial droop suggests stroke.","meaningSource":"curated"},{"id":"exam-04","system":"cardiovascular","maneuver":"Auscultate the heart for rate, rhythm, and murmurs.","findings":["Normal rate and regular rhythm, no murmur","Irregular rhythm","Murmur or gallop"],"how":null,"why":null,"whySource":null,"meaning":"Listening for rate, rhythm, and murmurs screens for cardiac drivers of weakness — an irregular rhythm suggests arrhythmia with poor perfusion, while a new murmur or gallop raises concern for valvular disease or heart failure; a normal exam moves attention away from the heart.","meaningSource":"ai-draft"},{"id":"exam-05","system":"general","maneuver":"Assess mucous membranes and skin turgor for dehydration.","findings":["Moist mucous membranes, normal turgor","Dry mucous membranes or poor skin turgor"],"how":null,"why":null,"whySource":null,"meaning":"Dry mucous membranes and poor skin turgor support dehydration or volume depletion as the driver of weakness, which is often reversible with fluids and electrolyte correction; moist membranes with normal turgor make dehydration less likely, though the signs are insensitive in older adults.","meaningSource":"ai-draft"},{"id":"exam-06","system":"skin","maneuver":"Inspect the skin for hyperpigmentation.","findings":["Normal skin color","Skin hyperpigmentation"],"how":null,"why":"New hyperpigmentation of skin creases and scars suggests primary adrenal insufficiency.","whySource":"curated","meaning":"New hyperpigmentation of skin creases and scars suggests primary adrenal insufficiency.","meaningSource":"curated"},{"id":"exam-07","system":"endocrine","maneuver":"Assess the thyroid and for other signs of thyroid dysfunction.","findings":["Normal thyroid exam","Goiter, dry skin, or delayed reflex relaxation","Exophthalmos or fine tremor"],"how":null,"why":"Goiter with dry skin and delayed reflex relaxation suggests hypothyroidism.","whySource":"curated","meaning":"Goiter with dry skin and delayed reflex relaxation suggests hypothyroidism.","meaningSource":"curated"},{"id":"exam-08","system":"musculoskeletal","maneuver":"Assess proximal muscle strength and safety of gait.","findings":["Normal gait and proximal strength","Proximal muscle weakness","Unable to ambulate safely"],"how":null,"why":"Proximal muscle weakness suggests myopathy.","whySource":"curated","meaning":"Proximal muscle weakness suggests myopathy.","meaningSource":"curated"},{"id":"exam-09","system":"skin","maneuver":"Inspect skin and hygiene for evidence of neglect.","findings":["Skin intact, hygiene appropriate","Poor hygiene","Pressure ulcers or bruising in varying stages of healing"],"how":null,"why":"Pressure ulcers or bruises in varying stages of healing raise concern for neglect or abuse.","whySource":"curated","meaning":"Pressure ulcers or bruises in varying stages of healing raise concern for neglect or abuse.","meaningSource":"curated"},{"id":"exam-10","system":"gastrointestinal","maneuver":"Perform a rectal examination when indicated.","findings":["Normal, guaiac negative, or deferred as not indicated","Melena on rectal examination"],"how":null,"why":"Melena (black, tarry stools) indicates upper gastrointestinal bleeding.","whySource":"curated","meaning":"Melena (black, tarry stools) indicates upper gastrointestinal bleeding.","meaningSource":"curated"},{"id":"exam-11","system":"neurologic","maneuver":"Assess deep tendon reflexes and sensation.","findings":["Normal reflexes and sensation","Diminished or absent reflexes","Sensory level or stocking-glove sensory loss"],"how":null,"why":"Stocking-glove sensory loss suggests a length-dependent peripheral neuropathy.","whySource":"curated","meaning":"Stocking-glove sensory loss suggests a length-dependent peripheral neuropathy.","meaningSource":"curated"}],"reviewNeeded":{"whyMissing":13,"howMissing":10}},{"id":"sepsis-septic-shock","title":"Sepsis / septic shock","aliases":["sepsis","septic shock"],"history":[{"id":"history-01","system":"respiratory","question":"Have you had a cough, shortness of breath, or coughed up blood?","listenFor":["No respiratory symptoms","Cough","Dyspnea","Hemoptysis"],"why":"Hemoptysis with pleuritic pain and dyspnea suggests pulmonary infarction from embolism.","whySource":"curated","meaning":"Hemoptysis with pleuritic pain and dyspnea suggests pulmonary infarction from embolism.","meaningSource":"curated"},{"id":"history-02","system":"genitourinary","question":"Do you have any burning with urination or pain in your side?","listenFor":["No urinary symptoms","Dysuria","Flank pain"],"why":null,"whySource":null,"meaning":"Dysuria points to a urinary source, and flank pain with costovertebral-angle tenderness suggests pyelonephritis or an obstructed infected stone, which needs urgent imaging and urologic drainage consideration. Absence of urinary symptoms does not exclude a urinary source, especially in the elderly, where presentations are often atypical.","meaningSource":"ai-draft"},{"id":"history-03","system":"gastrointestinal","question":"Do you have belly pain?","listenFor":["No abdominal pain","Localized abdominal pain","Diffuse abdominal pain"],"why":null,"whySource":null,"meaning":"Localized abdominal pain narrows the source — right upper quadrant for cholangitis or cholecystitis, right lower quadrant for appendicitis, diffuse pain with peritoneal signs for perforation — and a surgical abdomen needs evaluation without delaying antibiotics. Diffuse pain without localization can also reflect mesenteric hypoperfusion in shock.","meaningSource":"ai-draft"},{"id":"history-04","system":"skin","question":"Do you have any redness on your skin, and is it spreading or blistering?","listenFor":["No skin findings","Localized erythema and warmth","Rapidly spreading pain with blistering or dark discoloration"],"why":null,"whySource":null,"meaning":"Localized erythema and warmth suggest cellulitis, but rapidly spreading pain with blistering or dark discoloration signals necrotizing soft-tissue infection, a surgical emergency. Pain out of proportion to visible skin findings is the classic early clue — do not wait for frank necrosis to call surgery.","meaningSource":"ai-draft"},{"id":"history-05","system":"medication","question":"Do you have a catheter, port, or other implanted device, and is there any pain, redness, or drainage where it is?","listenFor":["No indwelling device","Indwelling device without local symptoms","Indwelling device with local pain, redness, or drainage"],"why":"Pain, redness, or drainage at a device site suggests device-related infection.","whySource":"curated","meaning":"Pain, redness, or drainage at a device site suggests device-related infection.","meaningSource":"curated"},{"id":"history-06","system":"neurologic","question":"Have you or your family noticed any change in your thinking or alertness since this started?","listenFor":["No mental status change","Subtle new confusion","Marked altered mental status or unresponsiveness"],"why":"New confusion marks severity of systemic illness and suggests acute organ dysfunction, as in severe infection, sepsis, or metabolic derangement.","whySource":"curated","meaning":"New confusion marks severity of systemic illness and suggests acute organ dysfunction, as in severe infection, sepsis, or metabolic derangement.","meaningSource":"curated"},{"id":"history-07","system":"genitourinary","question":"Have you noticed a change in how much you're urinating?","listenFor":["Normal urine output","Decreased urine output","No urine output in the preceding several hours"],"why":"Anuria suggests severe acute kidney injury or obstructive uropathy.","whySource":"curated","meaning":"Anuria suggests severe acute kidney injury or obstructive uropathy.","meaningSource":"curated"},{"id":"history-08","system":"medication","question":"Are you on chemotherapy, a transplant medication, a biologic, or long-term steroids?","listenFor":["No chronic immunosuppression","Chronic steroid or biologic therapy","Transplant history, chemotherapy, or known neutropenia"],"why":null,"whySource":null,"meaning":"Chronic immunosuppression widens the differential to opportunistic and fungal pathogens and blunts the fever response, so absence of fever cannot exclude infection. Known neutropenia is an emergency (febrile neutropenia) requiring immediate antipseudomonal coverage — check the ANC and start broad-spectrum antibiotics without delay.","meaningSource":"ai-draft"},{"id":"history-09","system":"infectious","question":"Did you get sick gradually over days, or did this hit you suddenly with shaking chills?","listenFor":["Gradual worsening over several days","Abrupt onset with rigors","Rapid deterioration over hours"],"why":"Fever with shaking chills (rigors) suggests bacteremia.","whySource":"curated","meaning":"Fever with shaking chills (rigors) suggests bacteremia.","meaningSource":"curated"},{"id":"history-10","system":"skin","question":"Did you break out in hives or have facial swelling after being exposed to something new, like a food or medication?","listenFor":["No new exposure or allergic symptoms","Hives after a new exposure, no airway symptoms","Throat tightness or facial swelling after a new exposure"],"why":"Hives with facial swelling or throat tightness after an exposure suggests anaphylaxis, which can rapidly obstruct the airway.","whySource":"curated","meaning":"Hives with facial swelling or throat tightness after an exposure suggests anaphylaxis, which can rapidly obstruct the airway.","meaningSource":"curated"},{"id":"history-11","system":"cardiovascular","question":"Did you have chest pain before your blood pressure dropped, or do you have heart failure that's recently gotten worse?","listenFor":["Neither","Chest pain preceding the hypotension","Known heart failure with recent decompensation"],"why":"Chest pain before hypotension suggests a cardiac cause of shock rather than sepsis.","whySource":"curated","meaning":"Chest pain before hypotension suggests a cardiac cause of shock rather than sepsis.","meaningSource":"curated"},{"id":"history-12","system":"hematologic","question":"Have you had severe vomiting, diarrhea, or been unable to eat or drink for several days?","listenFor":["None of these","Severe vomiting or diarrhea","Poor oral intake over several days"],"why":null,"whySource":null,"meaning":"Prolonged vomiting, diarrhea, or poor intake flags hypovolemia and electrolyte derangement as contributors to shock that may not be purely distributive, and argues for aggressive fluid resuscitation and electrolyte repletion alongside the sepsis workup. It can also point to a gastrointestinal infectious source.","meaningSource":"ai-draft"},{"id":"history-13","system":"hematologic","question":"Have you had any bleeding, or a recent injury?","listenFor":["Neither","Gastrointestinal bleeding","Recent trauma"],"why":null,"whySource":null,"meaning":"Active bleeding or recent trauma identifies hemorrhagic shock, which coexists with or mimics sepsis but demands blood products and hemorrhage control rather than fluids and pressors alone. In a septic patient, GI bleeding should also prompt review for stress ulceration and coagulopathy.","meaningSource":"ai-draft"},{"id":"history-14","system":"medication","question":"Have you taken antibiotics recently, or been told you carry a resistant bacteria?","listenFor":["Neither","Recent antibiotic course","Known multidrug-resistant organism colonization"],"why":"Known colonization with a resistant organism guides empiric antibiotic choice in sepsis.","whySource":"curated","meaning":"Known colonization with a resistant organism guides empiric antibiotic choice in sepsis.","meaningSource":"curated"}],"exam":[{"id":"exam-01","system":"general","maneuver":"Assess peripheral perfusion.","findings":["Warm, well-perfused extremities with brisk capillary refill","Cool, clammy extremities with delayed capillary refill","Mottled skin"],"how":"Press the nail bed firmly for 5 seconds, release, and count the seconds until color returns; return after more than 2 to 3 seconds is delayed.","why":"Cool, clammy extremities with delayed capillary refill or mottling indicate poor peripheral perfusion in shock.","whySource":"curated","meaning":"Cool, clammy extremities with delayed capillary refill or mottling indicate poor peripheral perfusion in shock.","meaningSource":"curated"},{"id":"exam-02","system":"neurologic","maneuver":"Assess mental status.","findings":["Alert and fully oriented","New confusion","Unresponsive or minimally responsive"],"how":null,"why":"New confusion marks severity of systemic illness and suggests acute organ dysfunction, as in severe infection, sepsis, or metabolic derangement.","whySource":"curated","meaning":"New confusion marks severity of systemic illness and suggests acute organ dysfunction, as in severe infection, sepsis, or metabolic derangement.","meaningSource":"curated"},{"id":"exam-03","system":"general","maneuver":"Assess blood pressure and response to initial fluid resuscitation.","findings":["Normotensive","Tachycardic with narrowed pulse pressure","Hypotensive despite fluid resuscitation"],"how":null,"why":"Persistent hypotension despite fluid resuscitation defines septic shock.","whySource":"curated","meaning":"Persistent hypotension despite fluid resuscitation defines septic shock.","meaningSource":"curated"},{"id":"exam-04","system":"skin","maneuver":"Inspect the skin for a source or for necrotizing changes.","findings":["Normal skin","Localized cellulitis","Bullae, crepitus, or skin necrosis"],"how":null,"why":null,"whySource":null,"meaning":"Cellulitis found on exam localizes the source and guides coverage, while bullae, crepitus, or necrosis identifies necrotizing soft-tissue infection requiring immediate surgical debridement. Normal skin simply moves the search to the lungs, urine, abdomen, and lines.","meaningSource":"ai-draft"},{"id":"exam-05","system":"infectious","maneuver":"Inspect any line, catheter, or device site.","findings":["Normal, no device present","Erythema or purulence at a device site"],"how":null,"why":null,"whySource":null,"meaning":"Erythema or purulence at a line, catheter, or device site identifies a catheter-related bloodstream infection source — draw cultures from the line and peripherally and plan for removal. A clean device site does not rule out line infection but keeps other sources higher on the list.","meaningSource":"ai-draft"},{"id":"exam-06","system":"respiratory","maneuver":"Auscultate the lungs for focal or diffuse findings.","findings":["Clear bilaterally","Focal crackles or dullness","Diffuse findings with respiratory distress"],"how":null,"why":null,"whySource":null,"meaning":"Focal crackles or dullness localizes a pneumonia source, while diffuse findings with respiratory distress suggest ARDS or aspiration. Clear lungs make pneumonia less likely but do not exclude it — the elderly and ventilated patient may have minimal findings, so imaging still matters.","meaningSource":"ai-draft"},{"id":"exam-07","system":"gastrointestinal","maneuver":"Palpate the abdomen for a source of infection.","findings":["Soft, nontender","Focal tenderness","Diffuse tenderness with guarding or rebound"],"how":null,"why":"Guarding, rebound, or rigidity on palpation suggests peritonitis.","whySource":"curated","meaning":"Guarding, rebound, or rigidity on palpation suggests peritonitis.","meaningSource":"curated"},{"id":"exam-08","system":"genitourinary","maneuver":"Assess for costovertebral-angle tenderness.","findings":["None","Unilateral costovertebral-angle tenderness","Bilateral costovertebral-angle tenderness"],"how":null,"why":"Costovertebral angle tenderness suggests pyelonephritis.","whySource":"curated","meaning":"Costovertebral angle tenderness suggests pyelonephritis.","meaningSource":"curated"},{"id":"exam-09","system":"cardiovascular","maneuver":"Assess jugular venous pressure and heart sounds to distinguish distributive from cardiogenic shock.","findings":["Flat neck veins, normal heart sounds","Elevated jugular venous pressure with a gallop"],"how":"With the patient reclined at 30 to 45 degrees, identify the highest point of internal jugular venous pulsation and measure its vertical distance above the sternal angle.","why":"Hypotension with cool extremities and pulmonary edema suggests cardiogenic shock from pump failure.","whySource":"curated","meaning":"Hypotension with cool extremities and pulmonary edema suggests cardiogenic shock from pump failure.","meaningSource":"curated"},{"id":"exam-10","system":"genitourinary","maneuver":"Assess urine output, by catheter if placed.","findings":["Adequate urine output","Oliguric","Anuric"],"how":null,"why":null,"whySource":null,"meaning":"Urine output is the bedside marker of end-organ perfusion in sepsis: oliguria signals developing acute kidney injury and inadequate resuscitation, while anuria suggests established severe AKI or obstructive uropathy. Sustained oliguria should prompt reassessment of fluids, perfusion, and a possible urinary source such as an obstructed infected stone.","meaningSource":"ai-draft"}],"reviewNeeded":{"whyMissing":10,"howMissing":8}},{"id":"pneumonia","title":"Pneumonia (community- or hospital-acquired)","aliases":["pneumonia","lower respiratory infection"],"history":[{"id":"history-01","system":"respiratory","question":"Did your cough come on gradually, and what color is what you're coughing up?","listenFor":["Gradual onset with mucoid sputum","Abrupt onset with rust-colored or purulent sputum","Chronic cough with weight loss or night sweats"],"why":"Rust-colored or purulent sputum suggests bacterial pneumonia.","whySource":"curated","meaning":"Rust-colored or purulent sputum suggests bacterial pneumonia.","meaningSource":"curated"},{"id":"history-02","system":"respiratory","question":"Do you have any sharp chest pain that's worse when you breathe in, and has your fever kept coming back despite antibiotics?","listenFor":["No pleuritic pain","Pleuritic pain worse with breathing","Pleuritic pain with fever persisting despite antibiotics"],"why":null,"whySource":null,"meaning":"Pleuritic chest pain suggests pleural involvement or a parapneumonic effusion, and fever persisting despite antibiotics signals treatment failure or a complication such as empyema — both findings should prompt repeat imaging and escalation of care.","meaningSource":"ai-draft"},{"id":"history-03","system":"respiratory","question":"How short of breath are you — only with activity, at rest, or so bad you can barely breathe?","listenFor":["Mild dyspnea with exertion","Dyspnea at rest","Severe respiratory distress"],"why":null,"whySource":null,"meaning":"The degree of dyspnea grades severity: exertional symptoms fit mild disease, while breathlessness at rest signals severe pneumonia and pushes toward admission or higher-level care.","meaningSource":"ai-draft"},{"id":"history-04","system":"gastrointestinal","question":"Do you have trouble swallowing or reflux, or did you choke or aspirate before this started?","listenFor":["None of these","Chronic dysphagia or reflux","Witnessed aspiration event or impaired consciousness at symptom onset"],"why":"A witnessed aspiration event predisposes to aspiration pneumonia or pneumonitis.","whySource":"curated","meaning":"A witnessed aspiration event predisposes to aspiration pneumonia or pneumonitis.","meaningSource":"curated"},{"id":"history-05","system":"medication","question":"Have you been in the hospital in the past three months, or are you currently admitted and on a ventilator?","listenFor":["No recent hospitalization","Hospitalized within the preceding 90 days","Currently hospitalized more than 48 hours or mechanically ventilated"],"why":"Recent hospitalization raises concern for drug-resistant organisms in pneumonia.","whySource":"curated","meaning":"Recent hospitalization raises concern for drug-resistant organisms in pneumonia.","meaningSource":"curated"},{"id":"history-06","system":"medication","question":"Are you on chronic steroids, do you have HIV, a transplant, or are you on chemotherapy?","listenFor":["None of these","Chronic steroid therapy or COPD","HIV, transplant history, or chemotherapy"],"why":null,"whySource":null,"meaning":"Chronic steroids, HIV, transplant, or chemotherapy widen the pathogen differential to opportunistic organisms such as Pneumocystis or fungi, which need different testing and treatment than typical bacterial pneumonia.","meaningSource":"ai-draft"},{"id":"history-07","system":"infectious","question":"Have you been incarcerated, experienced homelessness, traveled somewhere with high rates of tuberculosis, or been around someone with TB?","listenFor":["None of these","Incarceration, homelessness, or travel to a tuberculosis-endemic area","Known tuberculosis contact"],"why":null,"whySource":null,"meaning":"Incarceration, homelessness, high-TB travel, or TB contacts raise tuberculosis in the differential; a positive risk history should prompt airborne isolation and specific TB testing rather than routine community-acquired pneumonia management alone.","meaningSource":"ai-draft"},{"id":"history-08","system":"respiratory","question":"Do you smoke, have COPD, or have a lung condition like bronchiectasis?","listenFor":["None of these","Active smoking or known COPD","Known bronchiectasis or other structural lung disease"],"why":null,"whySource":null,"meaning":"Smoking, COPD, and bronchiectasis are major risk factors for pneumonia and for worse outcomes; underlying lung disease also changes severity assessment and empiric antibiotic choices.","meaningSource":"ai-draft"},{"id":"history-09","system":"functional","question":"Are you able to manage your daily activities on your own, or do you need help?","listenFor":["Independent with activities of daily living","Needs assistance with activities of daily living","Bedbound or nursing home resident"],"why":null,"whySource":null,"meaning":"Functional status and frailty heavily influence disposition: a patient who cannot manage daily activities independently is a poor candidate for outpatient care even with otherwise moderate pneumonia.","meaningSource":"ai-draft"},{"id":"history-10","system":"cardiovascular","question":"Do you have heart failure, and have you needed extra pillows or woken up gasping for air?","listenFor":["No known heart failure","Known heart failure without acute decompensation symptoms","Known heart failure with orthopnea or paroxysmal nocturnal dyspnea"],"why":"Waking up gasping for air, relieved by sitting up (paroxysmal nocturnal dyspnea), reflects pulmonary edema from elevated left-sided filling pressures, as in left heart failure.","whySource":"curated","meaning":"Waking up gasping for air, relieved by sitting up (paroxysmal nocturnal dyspnea), reflects pulmonary edema from elevated left-sided filling pressures, as in left heart failure.","meaningSource":"curated"},{"id":"history-11","system":"cardiovascular","question":"Have you traveled recently, had surgery, or do you have cancer or a history of blood clots?","listenFor":["None of these","Recent immobilization or surgery","Active malignancy or prior venous thromboembolism"],"why":"Active cancer and prior venous thromboembolism are strong risk factors for recurrent clots.","whySource":"curated","meaning":"Active cancer and prior venous thromboembolism are strong risk factors for recurrent clots.","meaningSource":"curated"},{"id":"history-12","system":"neurologic","question":"Have you or your family noticed any new confusion?","listenFor":["No new confusion","Mild new confusion","Marked new confusion or disorientation"],"why":"New confusion marks severity of systemic illness and suggests acute organ dysfunction, as in severe infection, sepsis, or metabolic derangement.","whySource":"curated","meaning":"New confusion marks severity of systemic illness and suggests acute organ dysfunction, as in severe infection, sepsis, or metabolic derangement.","meaningSource":"curated"}],"exam":[{"id":"exam-01","system":"general","maneuver":"Assess overall severity from vital signs.","findings":["Hemodynamically stable, normal oxygenation","Tachypneic or hypoxic","Hemodynamically unstable"],"how":null,"why":null,"whySource":null,"meaning":"Vital signs triage severity at a glance — tachypnea or hypoxia signals moderate-to-severe disease needing admission, while hemodynamic instability suggests severe pneumonia or sepsis requiring ICU-level care.","meaningSource":"ai-draft"},{"id":"exam-02","system":"respiratory","maneuver":"Auscultate the lungs for focal versus diffuse findings.","findings":["Clear bilaterally","Focal crackles, bronchial breath sounds, or egophony","Diffuse bilateral findings"],"how":null,"why":"Focal crackles with bronchial breath sounds or egophony suggests lobar consolidation from pneumonia.","whySource":"curated","meaning":"Focal crackles with bronchial breath sounds or egophony suggests lobar consolidation from pneumonia.","meaningSource":"curated"},{"id":"exam-03","system":"respiratory","maneuver":"Percuss the chest for dullness suggesting consolidation or effusion.","findings":["Resonant throughout","Focal dullness to percussion","Dullness with absent breath sounds suggesting a large effusion"],"how":null,"why":"Dullness to percussion with absent breath sounds suggests a pleural effusion.","whySource":"curated","meaning":"Dullness to percussion with absent breath sounds suggests a pleural effusion.","meaningSource":"curated"},{"id":"exam-04","system":"respiratory","maneuver":"Assess work of breathing and ability to speak in full sentences.","findings":["Normal work of breathing, speaks in full sentences","Accessory muscle use","Unable to speak in full sentences"],"how":null,"why":"Inability to speak in full sentences marks severe respiratory distress or fatigue.","whySource":"curated","meaning":"Inability to speak in full sentences marks severe respiratory distress or fatigue.","meaningSource":"curated"},{"id":"exam-05","system":"neurologic","maneuver":"Assess mental status.","findings":["Alert and oriented","New confusion"],"how":null,"why":"New confusion marks severity of systemic illness and suggests acute organ dysfunction, as in severe infection, sepsis, or metabolic derangement.","whySource":"curated","meaning":"New confusion marks severity of systemic illness and suggests acute organ dysfunction, as in severe infection, sepsis, or metabolic derangement.","meaningSource":"curated"},{"id":"exam-06","system":"ent","maneuver":"Assess swallowing safety, dentition, and pooling of secretions when aspiration is a concern.","findings":["Normal swallow and gag, good dentition","Poor dentition or pooled oral secretions","Overt aspiration observed"],"how":null,"why":"Poor dentition and pooled oral secretions raise aspiration risk.","whySource":"curated","meaning":"Poor dentition and pooled oral secretions raise aspiration risk.","meaningSource":"curated"},{"id":"exam-07","system":"cardiovascular","maneuver":"Assess for jugular venous distension, an S3 gallop, or peripheral edema suggesting a cardiac contributor.","findings":["None of these","Jugular venous distension or S3 gallop","Peripheral edema with jugular venous distension"],"how":null,"why":"An S3 gallop reflects rapid early ventricular filling and suggests left ventricular systolic dysfunction or volume overload, as in heart failure.","whySource":"curated","meaning":"An S3 gallop reflects rapid early ventricular filling and suggests left ventricular systolic dysfunction or volume overload, as in heart failure.","meaningSource":"curated"},{"id":"exam-08","system":"skin","maneuver":"Assess skin and lip color for cyanosis.","findings":["Normal color","Cyanosis"],"how":null,"why":null,"whySource":null,"meaning":"Cyanosis of the skin or lips indicates severe hypoxemia that pulse oximetry may understate; it is a red flag demanding immediate oxygen and escalation of care.","meaningSource":"ai-draft"},{"id":"exam-09","system":"respiratory","maneuver":"Assess chest wall expansion for symmetry and tracheal position.","findings":["Symmetric expansion, midline trachea","Asymmetric expansion or tracheal shift"],"how":null,"why":null,"whySource":null,"meaning":"Asymmetric chest expansion or tracheal shift points to a pleural effusion, pneumothorax, or atelectasis complicating the pneumonia; a tension physiology picture is an emergency requiring immediate decompression.","meaningSource":"ai-draft"},{"id":"exam-10","system":"general","maneuver":"Assess body habitus and nutritional status.","findings":["Normal body habitus","Cachectic appearance"],"how":null,"why":"A cachectic appearance suggests chronic disease, malignancy, or prolonged malnutrition.","whySource":"curated","meaning":"A cachectic appearance suggests chronic disease, malignancy, or prolonged malnutrition.","meaningSource":"curated"}],"reviewNeeded":{"whyMissing":9,"howMissing":10}},{"id":"acute-decompensated-heart-failure","title":"Congestive heart failure exacerbation (ADHF)","aliases":["heart failure","ADHF","fluid overload"],"history":[{"id":"history-01","system":"cardiovascular","question":"Do you need extra pillows to breathe comfortably while lying down, or can you not lie flat at all?","listenFor":["No orthopnea","Needs one extra pillow to breathe comfortably","Cannot lie flat at all"],"why":"Needing extra pillows to breathe comfortably (orthopnea) suggests elevated left-sided filling pressures, as seen in left heart failure.","whySource":"curated","meaning":"Needing extra pillows to breathe comfortably (orthopnea) suggests elevated left-sided filling pressures, as seen in left heart failure.","meaningSource":"curated"},{"id":"history-02","system":"cardiovascular","question":"Have you woken up gasping for air and needed to sit up to catch your breath?","listenFor":["No nocturnal awakening with breathlessness","Wakes gasping for air, relieved by sitting up"],"why":"Waking up gasping for air, relieved by sitting up (paroxysmal nocturnal dyspnea), reflects pulmonary edema from elevated left-sided filling pressures, as in left heart failure.","whySource":"curated","meaning":"Waking up gasping for air, relieved by sitting up (paroxysmal nocturnal dyspnea), reflects pulmonary edema from elevated left-sided filling pressures, as in left heart failure.","meaningSource":"curated"},{"id":"history-03","system":"cardiovascular","question":"Have you noticed new or worsening swelling in your legs or belly?","listenFor":["No swelling","New or worsening leg swelling","New abdominal distention or early satiety"],"why":null,"whySource":null,"meaning":"Leg swelling signals dependent edema from systemic venous congestion, while abdominal distention or early satiety suggests ascites or hepatic congestion from elevated right-sided pressures — both point toward a volume-overloaded state. Absence doesn't exclude ADHF, since pulmonary congestion can dominate; compare against the patient's dry weight and assess diuretic need.","meaningSource":"ai-draft"},{"id":"history-04","system":"general","question":"Have you gained several pounds in less than a week?","listenFor":["No rapid weight gain","Weight gain of several pounds over less than a week"],"why":"Weight gain of several pounds over days reflects fluid retention in heart failure.","whySource":"curated","meaning":"Weight gain of several pounds over days reflects fluid retention in heart failure.","meaningSource":"curated"},{"id":"history-05","system":"medication","question":"Have you missed any doses of your water pill or other heart failure medications?","listenFor":["No missed doses","Missed one or more diuretic or heart failure medication doses"],"why":"Missed diuretic or heart failure medication doses are a common precipitant of decompensation.","whySource":"curated","meaning":"Missed diuretic or heart failure medication doses are a common precipitant of decompensation.","meaningSource":"curated"},{"id":"history-06","system":"gastrointestinal","question":"Have you eaten anything unusually salty recently, like takeout or processed food?","listenFor":["No dietary indiscretion","Recent high-sodium meal or dietary indiscretion"],"why":"A high-sodium meal can precipitate heart failure decompensation.","whySource":"curated","meaning":"A high-sodium meal can precipitate heart failure decompensation.","meaningSource":"curated"},{"id":"history-07","system":"cardiovascular","question":"Have you been told you have heart failure before, and if so, was your heart pumping normally or weakly?","listenFor":["No known heart failure diagnosis","Known heart failure with preserved ejection fraction","Known heart failure with reduced ejection fraction"],"why":null,"whySource":null,"meaning":"Knowing whether the patient has reduced or preserved ejection fraction changes acute management: HFpEF exacerbations are often hypertensive pulmonary edema responsive to vasodilation and diuresis, while HFrEF patients are more prone to low-output states needing inotropic support. A de novo presentation should prompt a search for the underlying cause rather than assuming a familiar exacerbation.","meaningSource":"ai-draft"},{"id":"history-08","system":"cardiovascular","question":"Have you had any chest pressure with exertion along with the breathing trouble?","listenFor":["No chest pressure","Exertional chest pressure"],"why":null,"whySource":null,"meaning":"Exertional chest pressure alongside new dyspnea raises concern for myocardial ischemia as the precipitant of decompensation — acute coronary syndrome can directly cause ADHF. A positive answer should prompt an urgent ECG and troponins, since revascularization may be the definitive treatment.","meaningSource":"ai-draft"},{"id":"history-09","system":"cardiovascular","question":"Have you felt your heart racing or fluttering, or do you have a known history of atrial fibrillation?","listenFor":["No palpitations or known atrial fibrillation","New palpitations","Known atrial fibrillation, possibly with a fast rate"],"why":null,"whySource":null,"meaning":"A rapid atrial arrhythmia like atrial fibrillation shortens diastolic filling time and is a classic precipitant of decompensation; new palpitations may reveal new-onset AF or another tachyarrhythmia. A positive answer should prompt an ECG and rate control, and raises the question of anticoagulation.","meaningSource":"ai-draft"},{"id":"history-10","system":"infectious","question":"Have you had a fever or a new or worsening cough?","listenFor":["No fever or cough","Fever","New or worsening cough"],"why":null,"whySource":null,"meaning":"Infection is a common precipitant of ADHF, and a new cough or fever helps separate pulmonary edema from pneumonia — edema alone rarely causes fever. A positive answer should trigger a search for an infectious source (chest imaging, labs), since treating the precipitant matters as much as diuresis.","meaningSource":"ai-draft"},{"id":"history-11","system":"medication","question":"Have you taken any ibuprofen, naproxen, or other NSAID pain relievers recently?","listenFor":["No recent NSAID use","Recent NSAID use"],"why":"NSAIDs reduce renal perfusion and promote sodium and water retention, worsening kidney function, heart failure, and potassium excretion.","whySource":"curated","meaning":"NSAIDs reduce renal perfusion and promote sodium and water retention, worsening kidney function, heart failure, and potassium excretion.","meaningSource":"curated"},{"id":"history-12","system":"genitourinary","question":"Have you noticed you're urinating less than usual?","listenFor":["No change in urine output","Decreased urine output"],"why":"Decreased urine output suggests volume depletion or acute kidney injury.","whySource":"curated","meaning":"Decreased urine output suggests volume depletion or acute kidney injury.","meaningSource":"curated"},{"id":"history-13","system":"neurologic","question":"Have you felt lightheaded or actually passed out along with this?","listenFor":["No lightheadedness or syncope","Lightheadedness","Syncope"],"why":null,"whySource":null,"meaning":"Lightheadedness or syncope during decompensation points to low cardiac output, arrhythmia, or hypotension from over-diuresis — all higher-risk features than breathlessness alone. Positive answers call for rhythm monitoring, orthostatics, and review of blood-pressure-lowering medications.","meaningSource":"ai-draft"},{"id":"history-14","system":"cardiovascular","question":"Have you been hospitalized for heart failure before, and if so, does this feel similar or worse than those times?","listenFor":["First presentation of heart failure","Prior admissions, this episode feels similar","Prior admissions, this episode is more severe than usual"],"why":null,"whySource":null,"meaning":"Comparing to prior admissions gauges whether this is a routine exacerbation or a worse-than-usual event — a more severe episode than baseline suggests a new precipitant or declining cardiac reserve and lowers the threshold for escalation. It also tells you what regimen worked last time, such as the effective diuretic dose.","meaningSource":"ai-draft"}],"exam":[{"id":"exam-01","system":"cardiovascular","maneuver":"Assess jugular venous pressure.","findings":["Normal jugular venous pressure","Elevated jugular venous pressure","Elevated jugular venous pressure with prominent v waves"],"how":"With the patient reclined at 30 to 45 degrees, identify the highest point of internal jugular venous pulsation and measure its vertical distance above the sternal angle.","why":"Elevated jugular venous pressure reflects elevated right-sided filling pressures, seen in right heart failure, volume overload, or tamponade.","whySource":"curated","meaning":"Elevated jugular venous pressure reflects elevated right-sided filling pressures, seen in right heart failure, volume overload, or tamponade.","meaningSource":"curated"},{"id":"exam-02","system":"cardiovascular","maneuver":"Assess hepatojugular reflux.","findings":["Negative hepatojugular reflux","Positive hepatojugular reflux"],"how":"Apply firm, sustained pressure over the right upper quadrant for 30 to 60 seconds and watch for a sustained rise in the jugular venous pressure.","why":"A positive hepatojugular reflux (sustained jugular venous pressure rise with abdominal pressure) suggests elevated right-sided filling pressures.","whySource":"curated","meaning":"A positive hepatojugular reflux (sustained jugular venous pressure rise with abdominal pressure) suggests elevated right-sided filling pressures.","meaningSource":"curated"},{"id":"exam-03","system":"respiratory","maneuver":"Auscultate the lungs for crackles.","findings":["Clear bilaterally","Bibasilar crackles","Crackles throughout both lung fields"],"how":null,"why":"Bibasilar crackles suggest pulmonary edema from left heart failure; focal crackles suggest pneumonia.","whySource":"curated","meaning":"Bibasilar crackles suggest pulmonary edema from left heart failure; focal crackles suggest pneumonia.","meaningSource":"curated"},{"id":"exam-04","system":"respiratory","maneuver":"Assess work of breathing.","findings":["Normal work of breathing","Tachypneic with accessory muscle use","Severe respiratory distress"],"how":null,"why":null,"whySource":null,"meaning":"Accessory muscle use and marked tachypnea signal respiratory muscle fatigue and impending failure — these patients need escalation (noninvasive ventilation, ICU-level care) rather than ward-level diuresis alone. Normal work of breathing with reported dyspnea suggests a milder episode but doesn't rule out significant congestion.","meaningSource":"ai-draft"},{"id":"exam-05","system":"cardiovascular","maneuver":"Auscultate for an S3 gallop.","findings":["No S3 gallop","S3 gallop present"],"how":null,"why":"An S3 gallop reflects rapid early ventricular filling and suggests left ventricular systolic dysfunction or volume overload, as in heart failure.","whySource":"curated","meaning":"An S3 gallop reflects rapid early ventricular filling and suggests left ventricular systolic dysfunction or volume overload, as in heart failure.","meaningSource":"curated"},{"id":"exam-06","system":"cardiovascular","maneuver":"Auscultate for a new or changed murmur.","findings":["No murmur","New or changed murmur"],"how":null,"why":null,"whySource":null,"meaning":"A new murmur points to acute valvular pathology — such as acute mitral regurgitation from papillary muscle dysfunction after ischemia — as the precipitant rather than simple fluid overload. A new murmur should prompt an urgent echocardiogram.","meaningSource":"ai-draft"},{"id":"exam-07","system":"cardiovascular","maneuver":"Assess heart rate and rhythm regularity.","findings":["Regular rate and rhythm","Irregularly irregular rhythm","Regular tachycardia"],"how":null,"why":"An irregularly irregular pulse suggests atrial fibrillation.","whySource":"curated","meaning":"An irregularly irregular pulse suggests atrial fibrillation.","meaningSource":"curated"},{"id":"exam-08","system":"cardiovascular","maneuver":"Inspect and palpate the lower extremities for edema.","findings":["No peripheral edema","Mild pitting edema to the ankles","Marked pitting edema extending above the knees","Anasarca including sacral edema"],"how":null,"why":"Anasarca reflects severe generalized volume overload.","whySource":"curated","meaning":"Anasarca reflects severe generalized volume overload.","meaningSource":"curated"},{"id":"exam-09","system":"gastrointestinal","maneuver":"Assess the abdomen for ascites or hepatomegaly.","findings":["No ascites or hepatomegaly","Hepatomegaly","Ascites with a fluid wave"],"how":null,"why":"Shifting dullness and a fluid wave suggest ascites.","whySource":"curated","meaning":"Shifting dullness and a fluid wave suggest ascites.","meaningSource":"curated"},{"id":"exam-10","system":"cardiovascular","maneuver":"Assess extremity warmth and capillary refill for perfusion status.","findings":["Warm extremities, brisk capillary refill","Cool extremities with delayed capillary refill","Cool, mottled extremities with thready pulses"],"how":"Press the nail bed firmly for 5 seconds, release, and count the seconds until color returns; return after more than 2 to 3 seconds is delayed.","why":"Mottled skin indicates poor peripheral perfusion in shock.","whySource":"curated","meaning":"Mottled skin indicates poor peripheral perfusion in shock.","meaningSource":"curated"},{"id":"exam-11","system":"general","maneuver":"Measure and compare weight to the documented dry weight.","findings":["At or near documented dry weight","Above documented dry weight","No dry weight on record"],"how":null,"why":null,"whySource":null,"meaning":"Weight above the documented dry weight quantifies retained volume (roughly 1 kg per liter) and confirms a volume-overloaded state; returning to dry weight is the clinical endpoint of diuresis. Without a recorded dry weight, use exam findings and response to diuretics instead.","meaningSource":"ai-draft"},{"id":"exam-12","system":"general","maneuver":"Assess blood pressure for hypertensive or hypotensive decompensation.","findings":["Normotensive","Hypertensive","Hypotensive"],"how":null,"why":null,"whySource":null,"meaning":"Blood pressure phenotyping determines therapy: hypertensive decompensation (flash pulmonary edema) responds to vasodilation plus diuresis, while hypotension signals low output or cardiogenic shock — where vasodilators are dangerous and inotropes may be needed. Recheck frequently, since diuresis itself can drop pressure.","meaningSource":"ai-draft"}],"reviewNeeded":{"whyMissing":11,"howMissing":9}},{"id":"copd-exacerbation","title":"COPD exacerbation","aliases":["COPD flare","emphysema exacerbation"],"history":[{"id":"history-01","system":"respiratory","question":"Compared to how you normally breathe, is your shortness of breath a little worse or severe even at rest?","listenFor":["No change from baseline","Mild increase from baseline","Severe increase, dyspnea at rest"],"why":null,"whySource":null,"meaning":"Establishing the baseline distinguishes a true exacerbation from chronic dyspnea or another cause — severe worsening or dyspnea at rest signals a severe exacerbation needing emergency care, while mild worsening may be managed in clinic. No change from baseline should redirect the workup away from COPD.","meaningSource":"ai-draft"},{"id":"history-02","system":"respiratory","question":"Are you coughing up more phlegm than usual?","listenFor":["No change in sputum volume","Increased sputum volume"],"why":null,"whySource":null,"meaning":"Increased sputum volume suggests airway inflammation and possible bacterial infection; together with increased purulence it defines the subset most likely to benefit from antibiotics (Anthonisen criteria). Unchanged sputum volume argues against a bacterial trigger and toward viral or irritant causes.","meaningSource":"ai-draft"},{"id":"history-03","system":"respiratory","question":"Has the color of what you're coughing up changed, like turning yellow or green?","listenFor":["No change in sputum color","New purulent or discolored sputum"],"why":"New purulent sputum with increased dyspnea and sputum volume suggests a bacterial trigger for COPD exacerbation.","whySource":"curated","meaning":"New purulent sputum with increased dyspnea and sputum volume suggests a bacterial trigger for COPD exacerbation.","meaningSource":"curated"},{"id":"history-04","system":"respiratory","question":"Is your wheezing worse than it usually is?","listenFor":["No change in wheeze","Increased wheeze"],"why":null,"whySource":null,"meaning":"Increased wheeze reflects worsening airflow obstruction consistent with an exacerbation and supports bronchodilator therapy. Absent change in wheeze — or no wheeze at all — should prompt consideration of mimics such as heart failure, pulmonary embolism, or pneumothorax.","meaningSource":"ai-draft"},{"id":"history-05","system":"infectious","question":"Have you had a fever?","listenFor":["No fever","Fever"],"why":null,"whySource":null,"meaning":"Fever suggests infection as the exacerbation trigger and raises concern for pneumonia; afebrile exacerbations are common and do not exclude infection, but fever plus focal findings warrants a chest film to distinguish pneumonia from exacerbation alone.","meaningSource":"ai-draft"},{"id":"history-06","system":"respiratory","question":"Did you have a sudden sharp chest pain that's worse when you breathe in?","listenFor":["No sudden pleuritic chest pain","Sudden pleuritic chest pain"],"why":"Pleuritic chest pain with sudden dyspnea suggests pulmonary embolism.","whySource":"curated","meaning":"Pleuritic chest pain with sudden dyspnea suggests pulmonary embolism.","meaningSource":"curated"},{"id":"history-07","system":"respiratory","question":"Do you use oxygen at home, and if so, have you needed to turn it up higher than usual?","listenFor":["No home oxygen use","Uses home oxygen at the usual baseline rate","Recently increased home oxygen requirement"],"why":null,"whySource":null,"meaning":"A new or increased home-oxygen requirement signals worsening hypoxemia and a more severe exacerbation, and the baseline setting matters for oxygen titration in a chronic CO2 retainer. No home oxygen use puts the patient at a lower baseline severity tier.","meaningSource":"ai-draft"},{"id":"history-08","system":"respiratory","question":"Have you ever been admitted to the ICU or put on a breathing machine for a COPD flare before?","listenFor":["No prior hospitalization for COPD","Prior hospitalization without ICU admission","Prior ICU admission or intubation for COPD"],"why":null,"whySource":null,"meaning":"Prior ICU admission or intubation for a COPD flare is the strongest predictor of needing ventilatory support again and lowers the threshold for ICU admission and early noninvasive ventilation. No prior hospitalization suggests a lower-risk course but does not guarantee it.","meaningSource":"ai-draft"},{"id":"history-09","system":"medication","question":"Have you been using your daily inhalers as prescribed?","listenFor":["Adherent to maintenance inhalers","Missed inhaler doses","Unable to afford or access inhalers"],"why":null,"whySource":null,"meaning":"Missed maintenance inhaler doses are a common, fixable trigger of exacerbations and point to an adherence or access problem rather than disease progression. Confirm adherence before escalating therapy, and address affordability directly — it is a discharge-planning issue.","meaningSource":"ai-draft"},{"id":"history-10","system":"medication","question":"Are you still smoking, or were you recently exposed to smoke, fumes, or other lung irritants?","listenFor":["No smoking or irritant exposure","Ongoing active smoking","New occupational or environmental irritant exposure"],"why":null,"whySource":null,"meaning":"Ongoing smoking or new irritant exposure identifies a trigger that must stop, and continued smoking markedly raises exacerbation and hospitalization risk. Absence of exposure makes viral infection or nonadherence more likely triggers — and every encounter is a cessation-counseling opportunity.","meaningSource":"ai-draft"},{"id":"history-11","system":"neurologic","question":"Have you had morning headaches or felt unusually sleepy during the day?","listenFor":["Neither","Morning headache","Daytime somnolence or new confusion"],"why":"Morning headache with daytime somnolence suggests nocturnal hypercapnia (carbon dioxide retention).","whySource":"curated","meaning":"Morning headache with daytime somnolence suggests nocturnal hypercapnia (carbon dioxide retention).","meaningSource":"curated"},{"id":"history-12","system":"cardiovascular","question":"Have you noticed leg swelling, or do you need extra pillows to breathe comfortably at night?","listenFor":["Neither","Leg swelling","Orthopnea"],"why":"Needing extra pillows to breathe comfortably (orthopnea) suggests elevated left-sided filling pressures, as seen in left heart failure.","whySource":"curated","meaning":"Needing extra pillows to breathe comfortably (orthopnea) suggests elevated left-sided filling pressures, as seen in left heart failure.","meaningSource":"curated"},{"id":"history-13","system":"functional","question":"Have you been immobilized, had recent surgery, or do you have cancer or a history of blood clots?","listenFor":["No provoking risk factor","Recent immobilization or surgery","Active malignancy or prior venous thromboembolism"],"why":"Active cancer and prior venous thromboembolism are strong risk factors for recurrent clots.","whySource":"curated","meaning":"Active cancer and prior venous thromboembolism are strong risk factors for recurrent clots.","meaningSource":"curated"}],"exam":[{"id":"exam-01","system":"respiratory","maneuver":"Assess work of breathing and ability to speak in full sentences.","findings":["Normal work of breathing, speaks in full sentences","Accessory muscle use","Tripod posture, unable to speak in full sentences"],"how":null,"why":"Tripod posture with inability to speak in full sentences marks severe respiratory distress.","whySource":"curated","meaning":"Tripod posture with inability to speak in full sentences marks severe respiratory distress.","meaningSource":"curated"},{"id":"exam-02","system":"respiratory","maneuver":"Auscultate for wheeze and air movement.","findings":["Normal air entry, no wheeze","Wheeze with adequate air movement","Minimal air movement, silent chest"],"how":null,"why":"A silent chest with minimal air movement signals severe airflow obstruction and impending respiratory failure.","whySource":"curated","meaning":"A silent chest with minimal air movement signals severe airflow obstruction and impending respiratory failure.","meaningSource":"curated"},{"id":"exam-03","system":"respiratory","maneuver":"Assess for pursed-lip breathing.","findings":["Absent","Present"],"how":null,"why":null,"whySource":null,"meaning":"Pursed-lip breathing is a compensatory maneuver COPD patients use to splint small airways open during exhalation; its presence confirms significant airflow obstruction and distress. Its absence neither confirms nor excludes COPD severity — many patients do not spontaneously adopt it.","meaningSource":"ai-draft"},{"id":"exam-04","system":"respiratory","maneuver":"Percuss the chest for hyperresonance and assess diaphragmatic excursion.","findings":["Normal resonance and excursion","Hyperresonant with reduced diaphragmatic excursion"],"how":null,"why":"Hyperresonance with reduced diaphragmatic excursion reflects hyperinflation and air trapping in COPD.","whySource":"curated","meaning":"Hyperresonance with reduced diaphragmatic excursion reflects hyperinflation and air trapping in COPD.","meaningSource":"curated"},{"id":"exam-05","system":"respiratory","maneuver":"Assess breath sounds for asymmetry suggesting pneumothorax.","findings":["Symmetric breath sounds","Unilateral decreased or absent breath sounds"],"how":null,"why":null,"whySource":null,"meaning":"Unilateral decreased or absent breath sounds in a COPD exacerbation raises concern for pneumothorax, which bullous disease and coughing can precipitate, and requires urgent imaging with possible chest-tube placement. Symmetric breath sounds do not exclude a small pneumothorax, so clinical suspicion still warrants a film.","meaningSource":"ai-draft"},{"id":"exam-06","system":"respiratory","maneuver":"Assess oxygenation.","findings":["Normal saturation on room air","Hypoxemic, requiring supplemental oxygen","Central cyanosis"],"how":null,"why":"Central cyanosis of the lips, tongue, and nail beds reflects arterial hypoxemia.","whySource":"curated","meaning":"Central cyanosis of the lips, tongue, and nail beds reflects arterial hypoxemia.","meaningSource":"curated"},{"id":"exam-07","system":"neurologic","maneuver":"Assess mental status and asterixis for hypercapnic respiratory failure.","findings":["Alert, no asterixis","Somnolent or confused","Asterixis present"],"how":"Have the patient extend both arms with wrists dorsiflexed and fingers spread; observe for 15 to 30 seconds for the flapping tremor.","why":"Asterixis (flapping tremor of the outstretched hands) suggests a metabolic encephalopathy, classically hepatic encephalopathy.","whySource":"curated","meaning":"Asterixis (flapping tremor of the outstretched hands) suggests a metabolic encephalopathy, classically hepatic encephalopathy.","meaningSource":"curated"},{"id":"exam-08","system":"cardiovascular","maneuver":"Assess jugular venous pressure and peripheral edema for right-sided congestion.","findings":["Normal jugular venous pressure, no edema","Elevated jugular venous pressure","Elevated jugular venous pressure with peripheral edema"],"how":"With the patient reclined at 30 to 45 degrees, identify the highest point of internal jugular venous pulsation and measure its vertical distance above the sternal angle.","why":"Elevated jugular venous pressure reflects elevated right-sided filling pressures, seen in right heart failure, volume overload, or tamponade.","whySource":"curated","meaning":"Elevated jugular venous pressure reflects elevated right-sided filling pressures, seen in right heart failure, volume overload, or tamponade.","meaningSource":"curated"},{"id":"exam-09","system":"cardiovascular","maneuver":"Assess cardiac rhythm regularity.","findings":["Regular rhythm","Irregular rhythm"],"how":null,"why":null,"whySource":null,"meaning":"An irregular rhythm in a COPD exacerbation suggests new atrial fibrillation, a common precipitant and consequence of hypoxia and sympathomimetic bronchodilator use, which changes management. A regular rhythm keeps the focus on the airway, but beta-agonist therapy still warrants monitoring for tachycardia and ischemia.","meaningSource":"ai-draft"},{"id":"exam-10","system":"cardiovascular","maneuver":"Inspect and palpate the calves for asymmetric swelling or tenderness.","findings":["Symmetric, no swelling or tenderness","Unilateral swelling or tenderness"],"how":null,"why":null,"whySource":null,"meaning":"Unilateral calf swelling or tenderness raises suspicion for deep vein thrombosis, and pulmonary embolism frequently mimics a COPD exacerbation. When dyspnea, tachycardia, or hypoxemia seem out of proportion to the wheeze, pursue PE workup rather than attributing everything to COPD.","meaningSource":"ai-draft"}],"reviewNeeded":{"whyMissing":12,"howMissing":8}},{"id":"urinary-tract-infection","title":"Urinary tract infection","aliases":["UTI","pyelonephritis"],"history":[{"id":"history-01","system":"genitourinary","question":"Do you have any burning or pain when you urinate?","listenFor":["No dysuria","Dysuria"],"why":null,"whySource":null,"meaning":"Dysuria is the hallmark symptom of cystitis; its absence makes uncomplicated bladder infection less likely, though older adults may present without it.","meaningSource":"ai-draft"},{"id":"history-02","system":"genitourinary","question":"Are you urinating more often than usual, or feeling like you have to go urgently?","listenFor":["Neither","Increased frequency","Urgency"],"why":null,"whySource":null,"meaning":"Urinary frequency and urgency are classic lower urinary tract symptoms localizing infection to the bladder; their absence points away from cystitis toward another source.","meaningSource":"ai-draft"},{"id":"history-03","system":"genitourinary","question":"Do you have any pain just above your pubic bone?","listenFor":["No suprapubic pain","Suprapubic pain"],"why":null,"whySource":null,"meaning":"Suprapubic pain localizes the infection to the bladder, supporting cystitis over urethritis or asymptomatic bacteriuria.","meaningSource":"ai-draft"},{"id":"history-04","system":"genitourinary","question":"Have you seen blood in your urine?","listenFor":["No visible hematuria","Visible hematuria"],"why":"Visible hematuria localizes bleeding to the urinary tract.","whySource":"curated","meaning":"Visible hematuria localizes bleeding to the urinary tract.","meaningSource":"curated"},{"id":"history-05","system":"genitourinary","question":"Do you have pain in one side of your back or flank?","listenFor":["No flank pain","Unilateral flank pain"],"why":null,"whySource":null,"meaning":"Unilateral flank pain suggests upper-tract involvement — pyelonephritis or an obstructed, infected kidney — which needs more urgent evaluation and different management than simple cystitis.","meaningSource":"ai-draft"},{"id":"history-06","system":"infectious","question":"Have you had a fever with shaking chills?","listenFor":["No fever","Subjective fever","Fever with rigors"],"why":"Fever with shaking chills (rigors) suggests bacteremia.","whySource":"curated","meaning":"Fever with shaking chills (rigors) suggests bacteremia.","meaningSource":"curated"},{"id":"history-07","system":"gastrointestinal","question":"Have you had nausea or vomiting along with the urinary symptoms?","listenFor":["Neither","Nausea","Vomiting"],"why":null,"whySource":null,"meaning":"Nausea or vomiting with urinary symptoms suggests pyelonephritis rather than simple cystitis and signals the patient may not tolerate oral antibiotics, favoring parenteral treatment.","meaningSource":"ai-draft"},{"id":"history-08","system":"genitourinary","question":"Do you currently have a urinary catheter in place?","listenFor":["No catheter","Indwelling catheter present"],"why":"An indwelling urinary catheter is a major risk factor for urinary tract infection.","whySource":"curated","meaning":"An indwelling urinary catheter is a major risk factor for urinary tract infection.","meaningSource":"curated"},{"id":"history-09","system":"genitourinary","question":"Have you had trouble starting your stream or noticed it's weaker than usual, or do you have a history of urinary blockage or stones?","listenFor":["No voiding difficulty","Difficulty voiding or weak stream","Known obstruction or urinary stones"],"why":"Difficulty voiding or a weak stream suggests obstructive uropathy.","whySource":"curated","meaning":"Difficulty voiding or a weak stream suggests obstructive uropathy.","meaningSource":"curated"},{"id":"history-10","system":"reproductive","question":"Is there any chance you could be pregnant?","listenFor":["Not pregnant or not applicable","Pregnant"],"why":"Pregnancy status changes the differential diagnosis, medication safety, and imaging choices.","whySource":"curated","meaning":"Pregnancy status changes the differential diagnosis, medication safety, and imaging choices.","meaningSource":"curated"},{"id":"history-11","system":"reproductive","question":"Have you noticed any vaginal discharge or irritation?","listenFor":["No vaginal discharge or irritation","Vaginal discharge or irritation"],"why":"Vaginal discharge or irritation suggests vaginitis or sexually transmitted infection rather than urinary infection.","whySource":"curated","meaning":"Vaginal discharge or irritation suggests vaginitis or sexually transmitted infection rather than urinary infection.","meaningSource":"curated"},{"id":"history-12","system":"reproductive","question":"Do you have any pain in the area between your genitals and rectum, or any known prostate problems?","listenFor":["Not applicable or none","Perineal pain or prostate symptoms"],"why":null,"whySource":null,"meaning":"Perineal pain or prostate symptoms in a man point toward prostatitis or urinary retention rather than simple cystitis — changing antibiotic choice, duration, and the need for a prostate and retention evaluation.","meaningSource":"ai-draft"},{"id":"history-13","system":"medication","question":"Do you get urinary tract infections often, or were you told a prior infection was resistant to certain antibiotics?","listenFor":["No recurrent infections or known resistant organism","Recurrent urinary tract infections","Known resistant organism on prior culture"],"why":"A prior resistant organism guides empiric antibiotic choice.","whySource":"curated","meaning":"A prior resistant organism guides empiric antibiotic choice.","meaningSource":"curated"},{"id":"history-14","system":"genitourinary","question":"Do you have a bladder condition affecting how it empties, or have you had a recent procedure involving your bladder or urethra?","listenFor":["Neither","Known neurogenic bladder","Recent urologic instrumentation"],"why":"Neurogenic bladder and urinary retention predispose to urinary tract infection.","whySource":"curated","meaning":"Neurogenic bladder and urinary retention predispose to urinary tract infection.","meaningSource":"curated"}],"exam":[{"id":"exam-01","system":"genitourinary","maneuver":"Palpate the suprapubic region for tenderness.","findings":["No suprapubic tenderness","Suprapubic tenderness"],"how":null,"why":null,"whySource":null,"meaning":"Suprapubic tenderness confirms bladder inflammation, supporting cystitis; marked tenderness with a distended bladder instead suggests urinary retention.","meaningSource":"ai-draft"},{"id":"exam-02","system":"genitourinary","maneuver":"Assess for bladder distention.","findings":["No bladder distention","Palpable, distended bladder"],"how":null,"why":null,"whySource":null,"meaning":"A palpable, distended bladder indicates urinary retention, which predisposes to infection and requires bladder drainage; retention also explains frequency and urgency.","meaningSource":"ai-draft"},{"id":"exam-03","system":"genitourinary","maneuver":"Assess for costovertebral-angle tenderness.","findings":["None","Unilateral costovertebral-angle tenderness","Bilateral costovertebral-angle tenderness"],"how":null,"why":"Costovertebral angle tenderness suggests pyelonephritis.","whySource":"curated","meaning":"Costovertebral angle tenderness suggests pyelonephritis.","meaningSource":"curated"},{"id":"exam-04","system":"general","maneuver":"Assess general appearance and hemodynamic stability.","findings":["Well-appearing, normal vital signs","Ill-appearing, tachycardic","Hypotensive or septic-appearing"],"how":null,"why":null,"whySource":null,"meaning":"An ill-appearing, tachycardic, or hypotensive patient suggests urosepsis — an emergency requiring prompt broad-spectrum antibiotics, fluids, and source control rather than routine outpatient treatment.","meaningSource":"ai-draft"},{"id":"exam-05","system":"neurologic","maneuver":"Assess mental status, since urinary infection can present atypically as delirium in older adults.","findings":["No mental status change","New confusion"],"how":null,"why":"New confusion marks severity of systemic illness and suggests acute organ dysfunction, as in severe infection, sepsis, or metabolic derangement.","whySource":"curated","meaning":"New confusion marks severity of systemic illness and suggests acute organ dysfunction, as in severe infection, sepsis, or metabolic derangement.","meaningSource":"curated"},{"id":"exam-06","system":"genitourinary","maneuver":"Inspect the urine appearance, by catheter bag if present.","findings":["Clear, pale urine","Cloudy or foul-smelling urine","Grossly bloody urine"],"how":null,"why":"Cloudy or foul-smelling urine suggests urinary tract infection.","whySource":"curated","meaning":"Cloudy or foul-smelling urine suggests urinary tract infection.","meaningSource":"curated"},{"id":"exam-07","system":"reproductive","maneuver":"Perform a pelvic examination when clinically indicated.","findings":["Normal or deferred as not indicated","Cervical motion tenderness or vaginal discharge"],"how":null,"why":"Cervical motion tenderness suggests pelvic inflammatory disease.","whySource":"curated","meaning":"Cervical motion tenderness suggests pelvic inflammatory disease.","meaningSource":"curated"},{"id":"exam-08","system":"reproductive","maneuver":"Perform a prostate examination when clinically indicated.","findings":["Normal or deferred as not indicated","Tender, boggy prostate"],"how":null,"why":"A tender, boggy prostate suggests acute bacterial prostatitis.","whySource":"curated","meaning":"A tender, boggy prostate suggests acute bacterial prostatitis.","meaningSource":"curated"},{"id":"exam-09","system":"skin","maneuver":"Inspect the catheter insertion site or perineal skin when a catheter is present.","findings":["Normal skin, no catheter or skin intact","Catheter site irritation or skin breakdown"],"how":null,"why":null,"whySource":null,"meaning":"Irritation at a catheter insertion site suggests a catheter-associated urinary tract infection, where the catheter itself is the source and usually needs removal or exchange; surrounding skin breakdown raises further infection risk.","meaningSource":"ai-draft"},{"id":"exam-10","system":"general","maneuver":"Assess mucous membranes and skin turgor for dehydration.","findings":["Moist mucous membranes, normal turgor","Dry mucous membranes or poor skin turgor"],"how":null,"why":null,"whySource":null,"meaning":"Dry mucous membranes and poor skin turgor indicate dehydration, which worsens acute kidney injury risk and impairs recovery — supporting IV fluids alongside antibiotics.","meaningSource":"ai-draft"}],"reviewNeeded":{"whyMissing":11,"howMissing":10}},{"id":"altered-mental-status-delirium","title":"Altered mental status / delirium","aliases":["confusion","delirium"],"history":[{"id":"history-01","system":"neurologic","question":"Has the confusion been a stable long-standing pattern, did it come on suddenly over hours, or does it come and go throughout the day?","listenFor":["Chronic, stable baseline confusion","Acute onset over hours","Fluctuating course over the day"],"why":"A fluctuating course with inattention is characteristic of delirium rather than dementia.","whySource":"curated","meaning":"A fluctuating course with inattention is characteristic of delirium rather than dementia.","meaningSource":"curated"},{"id":"history-02","system":"neurologic","question":"Before the confusion started, did you or your family notice any weakness on one side, facial drooping, or trouble speaking?","listenFor":["None","Unilateral weakness or facial droop","Speech change"],"why":"New facial droop suggests stroke.","whySource":"curated","meaning":"New facial droop suggests stroke.","meaningSource":"curated"},{"id":"history-03","system":"musculoskeletal","question":"Have you had a recent fall or hit your head?","listenFor":["No recent fall or head trauma","Recent fall or head trauma"],"why":null,"whySource":null,"meaning":"A recent fall or head trauma points to subdural hematoma, contusion, or post-concussive injury — subdurals can present days after a minor fall, especially on anticoagulation. No trauma history keeps the focus on metabolic, infectious, and toxic causes.","meaningSource":"ai-draft"},{"id":"history-04","system":"infectious","question":"Did you have a fever before the confusion started?","listenFor":["No fever","Fever"],"why":null,"whySource":null,"meaning":"Fever preceding confusion suggests infection — urinary tract infection, pneumonia, meningitis, or bacteremia — as the delirium precipitant and should drive a fever workup. Afebrile delirium does not exclude infection, since the elderly may not mount a fever, so leukocytosis and tachycardia still matter.","meaningSource":"ai-draft"},{"id":"history-05","system":"medication","question":"Have you started any new sleep, anxiety, allergy, or pain medications recently?","listenFor":["No new sedating medication","New sedative or anticholinergic medication","New or increased opioid dose"],"why":"Sedatives and anticholinergics are common precipitants of delirium in older adults.","whySource":"curated","meaning":"Sedatives and anticholinergics are common precipitants of delirium in older adults.","meaningSource":"curated"},{"id":"history-06","system":"medication","question":"Do you drink alcohol regularly, and when was your last drink?","listenFor":["No regular alcohol use","Regular alcohol use, last drink more than 48 hours ago","Regular alcohol use, last drink within 48 hours"],"why":"Alcohol withdrawal peaks 48 to 96 hours after the last drink.","whySource":"curated","meaning":"Alcohol withdrawal peaks 48 to 96 hours after the last drink.","meaningSource":"curated"},{"id":"history-07","system":"endocrine","question":"Do you have diabetes, and has your insulin or diabetes pill dose changed recently?","listenFor":["No known diabetes","Known diabetes without recent medication change","Known diabetes with a recent insulin or sulfonylurea dose change"],"why":"Insulin and sulfonylureas can cause hypoglycemia with neuroglycopenic confusion.","whySource":"curated","meaning":"Insulin and sulfonylureas can cause hypoglycemia with neuroglycopenic confusion.","meaningSource":"curated"},{"id":"history-08","system":"gastrointestinal","question":"Do you have cirrhosis or liver disease, and have you been constipated, had a stomach bleed, or felt sick recently?","listenFor":["No known cirrhosis","Known cirrhosis without a clear trigger","Known cirrhosis with recent constipation, gastrointestinal bleeding, or infection"],"why":"Constipation, gastrointestinal bleeding, and infection precipitate hepatic encephalopathy.","whySource":"curated","meaning":"Constipation, gastrointestinal bleeding, and infection precipitate hepatic encephalopathy.","meaningSource":"curated"},{"id":"history-09","system":"genitourinary","question":"Do you have kidney disease, and if you're on dialysis, have you missed a session?","listenFor":["No known chronic kidney disease","Known chronic kidney disease, no missed dialysis","Known dialysis dependence with a missed session"],"why":"A missed dialysis session can cause uremia, hyperkalemia, and volume overload.","whySource":"curated","meaning":"A missed dialysis session can cause uremia, hyperkalemia, and volume overload.","meaningSource":"curated"},{"id":"history-10","system":"genitourinary","question":"Do you have a history of being unable to empty your bladder?","listenFor":["No known urinary retention","Known urinary retention"],"why":"Urinary retention is a reversible precipitant of delirium in older adults.","whySource":"curated","meaning":"Urinary retention is a reversible precipitant of delirium in older adults.","meaningSource":"curated"},{"id":"history-11","system":"gastrointestinal","question":"Have you been severely constipated or had trouble having a bowel movement recently?","listenFor":["No known severe constipation","Known severe constipation or fecal impaction"],"why":"Fecal impaction is a reversible precipitant of delirium in older adults.","whySource":"curated","meaning":"Fecal impaction is a reversible precipitant of delirium in older adults.","meaningSource":"curated"},{"id":"history-12","system":"general","question":"Are you in significant pain that hasn't been controlled?","listenFor":["No uncontrolled pain","Uncontrolled pain"],"why":null,"whySource":null,"meaning":"Uncontrolled pain is a common, reversible precipitant of delirium, especially in the elderly — treating the pain often clarifies the mentation. Persistent confusion after adequate analgesia points to another cause, and delirium itself can mask the pain history.","meaningSource":"ai-draft"},{"id":"history-13","system":"neurologic","question":"Did anyone witness you having a seizure before the confusion started?","listenFor":["No witnessed seizure","Witnessed seizure activity"],"why":null,"whySource":null,"meaning":"A witnessed seizure before confusion suggests a postictal state, which typically resolves within about an hour. Prolonged or worsening confusion beyond that window, or recurrent seizures, raises concern for status epilepticus, intracranial pathology, or a metabolic trigger — get an EEG when the course is atypical.","meaningSource":"ai-draft"},{"id":"history-14","system":"neurologic","question":"Before this episode, did you or your family notice any memory or thinking problems as your normal baseline?","listenFor":["No known baseline cognitive impairment","Known mild baseline dementia","Known moderate to severe baseline dementia"],"why":null,"whySource":null,"meaning":"Establishing baseline cognition is essential: acute worsening on known dementia defines delirium superimposed on dementia, and the family is the best source for the baseline. Over-attributing changes to 'just dementia' is a classic way to miss delirium.","meaningSource":"ai-draft"},{"id":"history-15","system":"hematologic","question":"Have you been eating poorly or drinking heavily for an extended period?","listenFor":["No poor nutrition or alcohol use disorder","Poor nutrition or alcohol use disorder"],"why":"Chronic poor nutrition or alcohol use raises concern for thiamine deficiency and Wernicke encephalopathy.","whySource":"curated","meaning":"Chronic poor nutrition or alcohol use raises concern for thiamine deficiency and Wernicke encephalopathy.","meaningSource":"curated"}],"exam":[{"id":"exam-01","system":"neurologic","maneuver":"Assess the level of arousal.","findings":["Alert","Hypoactive or lethargic","Hyperactive or agitated"],"how":null,"why":null,"whySource":null,"meaning":"Arousal level maps the encephalopathy: hypoactive lethargy is the most commonly missed delirium subtype, while hyperactive agitation raises fall and safety risk and may need different management. Fluctuating arousal is a hallmark of delirium versus the fixed course of dementia.","meaningSource":"ai-draft"},{"id":"exam-02","system":"neurologic","maneuver":"Assess attention.","findings":["Normal attention","Inattentive"],"how":null,"why":"Inattention with fluctuating alertness is the hallmark of delirium.","whySource":"curated","meaning":"Inattention with fluctuating alertness is the hallmark of delirium.","meaningSource":"curated"},{"id":"exam-03","system":"neurologic","maneuver":"Assess for focal motor weakness or facial asymmetry.","findings":["Symmetric, no focal weakness","Focal weakness or facial asymmetry"],"how":null,"why":null,"whySource":null,"meaning":"Focal weakness or facial asymmetry identifies a focal neurologic lesion — stroke, mass, or postictal Todd's paresis — as the cause of altered mentation rather than a metabolic delirium, and is an emergency. Symmetric findings keep a toxic-metabolic cause at the top but do not fully exclude a lesion.","meaningSource":"ai-draft"},{"id":"exam-04","system":"neurologic","maneuver":"Assess pupil size and reactivity.","findings":["Normal, reactive pupils","Pinpoint pupils","Dilated or sluggish pupils"],"how":null,"why":"Pinpoint pupils suggest opioid intoxication; dilated or sluggish pupils suggest sympathomimetic, anticholinergic, or withdrawal states.","whySource":"curated","meaning":"Pinpoint pupils suggest opioid intoxication; dilated or sluggish pupils suggest sympathomimetic, anticholinergic, or withdrawal states.","meaningSource":"curated"},{"id":"exam-05","system":"endocrine","maneuver":"Check fingerstick glucose.","findings":["Normal glucose","Hypoglycemic","Markedly hyperglycemic"],"how":"Prick the side of the fingertip rather than the pad, and apply the blood drop to the test strip.","why":"Hypoglycemia causes neuroglycopenic symptoms such as confusion, diaphoresis, and tremor, and needs urgent correction.","whySource":"curated","meaning":"Hypoglycemia causes neuroglycopenic symptoms such as confusion, diaphoresis, and tremor, and needs urgent correction.","meaningSource":"curated"},{"id":"exam-06","system":"general","maneuver":"Assess vital signs for fever or hemodynamic instability.","findings":["Normal vital signs","Febrile or tachycardic","Hypotensive"],"how":null,"why":null,"whySource":null,"meaning":"Fever with tachycardia points to infection as the delirium driver and should trigger a source workup, while hypotension suggests sepsis or cardiogenic shock causing cerebral hypoperfusion. Normal vitals do not exclude serious causes such as hypoglycemia, hyponatremia, or drug effect.","meaningSource":"ai-draft"},{"id":"exam-07","system":"gastrointestinal","maneuver":"Assess for asterixis.","findings":["Absent","Present"],"how":"Have the patient extend both arms with wrists dorsiflexed and fingers spread; observe for 15 to 30 seconds for the flapping tremor.","why":"Asterixis (flapping tremor of the outstretched hands) suggests a metabolic encephalopathy, classically hepatic encephalopathy.","whySource":"curated","meaning":"Asterixis (flapping tremor of the outstretched hands) suggests a metabolic encephalopathy, classically hepatic encephalopathy.","meaningSource":"curated"},{"id":"exam-08","system":"neurologic","maneuver":"Assess for nuchal rigidity.","findings":["Absent","Present"],"how":null,"why":"Nuchal rigidity suggests meningeal irritation, as in meningitis or subarachnoid hemorrhage.","whySource":"curated","meaning":"Nuchal rigidity suggests meningeal irritation, as in meningitis or subarachnoid hemorrhage.","meaningSource":"curated"},{"id":"exam-09","system":"genitourinary","maneuver":"Assess for a distended, palpable bladder.","findings":["Nondistended","Distended, palpable bladder"],"how":null,"why":"A distended, palpable bladder indicates urinary retention.","whySource":"curated","meaning":"A distended, palpable bladder indicates urinary retention.","meaningSource":"curated"},{"id":"exam-10","system":"gastrointestinal","maneuver":"Perform a rectal examination for fecal impaction when indicated.","findings":["Normal or deferred as not indicated","Fecal impaction present"],"how":null,"why":"Fecal impaction is a reversible precipitant of delirium in older adults.","whySource":"curated","meaning":"Fecal impaction is a reversible precipitant of delirium in older adults.","meaningSource":"curated"},{"id":"exam-11","system":"skin","maneuver":"Inspect the skin for signs of trauma or intravenous drug use.","findings":["Normal skin","Bruising or signs of trauma","Needle track marks"],"how":null,"why":"Intravenous drug use raises risk for bacteremia, endocarditis, and soft tissue infection.","whySource":"curated","meaning":"Intravenous drug use raises risk for bacteremia, endocarditis, and soft tissue infection.","meaningSource":"curated"},{"id":"exam-12","system":"neurologic","maneuver":"Assess for tremor suggesting alcohol or sedative withdrawal.","findings":["Absent","Present"],"how":null,"why":null,"whySource":null,"meaning":"A tremor in an altered patient raises alcohol or sedative withdrawal, which can progress to seizures and delirium tremens — a medical emergency. Absent tremor lowers but does not eliminate withdrawal concern, so the last-drink history still matters; give thiamine and use symptom-triggered benzodiazepines.","meaningSource":"ai-draft"}],"reviewNeeded":{"whyMissing":9,"howMissing":10}},{"id":"syncope-presyncope","title":"Syncope or presyncope","aliases":["fainting","passing out"],"history":[{"id":"history-01","system":"neurologic","question":"Did you have any warning, like nausea, sweating, or tunnel vision, before you passed out, or did it happen with no warning at all?","listenFor":["Warning prodrome with nausea, diaphoresis, or tunnel vision","No prodrome, sudden loss of consciousness","Preceded by palpitations"],"why":"A prodrome of nausea, diaphoresis, and tunnel vision suggests vasovagal (neurocardiogenic) syncope.","whySource":"curated","meaning":"A prodrome of nausea, diaphoresis, and tunnel vision suggests vasovagal (neurocardiogenic) syncope.","meaningSource":"curated"},{"id":"history-02","system":"neurologic","question":"Were you standing for a long time, in the heat, in pain, or scared right before it happened, or was it triggered by coughing, urinating, or having a bowel movement?","listenFor":["No situational trigger","Prolonged standing, heat, pain, or fear","Cough, micturition, or defecation"],"why":"Syncope triggered by cough, micturition, or defecation suggests situational (reflex) syncope.","whySource":"curated","meaning":"Syncope triggered by cough, micturition, or defecation suggests situational (reflex) syncope.","meaningSource":"curated"},{"id":"history-03","system":"cardiovascular","question":"Were you lying down, sitting, standing up, or exercising when it happened?","listenFor":["Supine or seated","On standing","During exertion"],"why":"Syncope during exertion suggests a cardiac cause such as outflow obstruction or arrhythmia.","whySource":"curated","meaning":"Syncope during exertion suggests a cardiac cause such as outflow obstruction or arrhythmia.","meaningSource":"curated"},{"id":"history-04","system":"neurologic","question":"How long were you out, and did you feel back to normal right away or stay confused afterward?","listenFor":["Brief, under one minute, with rapid full recovery","Prolonged unconsciousness","Prolonged postictal confusion after regaining consciousness"],"why":"Postictal confusion or drowsiness lasting minutes to hours supports a true seizure rather than syncope.","whySource":"curated","meaning":"Postictal confusion or drowsiness lasting minutes to hours supports a true seizure rather than syncope.","meaningSource":"curated"},{"id":"history-05","system":"neurologic","question":"Did anyone see you jerk or shake, bite your tongue, or lose control of your bladder during the episode?","listenFor":["None of these","Brief myoclonic jerks (convulsive syncope)","Tongue biting or urinary incontinence"],"why":"Brief myoclonic jerks can occur with convulsive syncope and do not by themselves indicate epilepsy.","whySource":"curated","meaning":"Brief myoclonic jerks can occur with convulsive syncope and do not by themselves indicate epilepsy.","meaningSource":"curated"},{"id":"history-06","system":"cardiovascular","question":"Did you feel your heart racing or pounding right before you passed out?","listenFor":["No palpitations","Palpitations preceding the event"],"why":null,"whySource":null,"meaning":"Palpitations immediately before syncope suggest a tachyarrhythmia — such as supraventricular tachycardia, ventricular tachycardia, or rapid atrial fibrillation — rather than benign vasovagal or orthostatic causes. A positive answer is a cardiac red flag that warrants cardiac monitoring and arrhythmia workup.","meaningSource":"ai-draft"},{"id":"history-07","system":"cardiovascular","question":"Did you have chest pain right before you passed out?","listenFor":["No chest pain","Chest pain preceding the event"],"why":null,"whySource":null,"meaning":"Chest pain preceding syncope points to a cardiopulmonary emergency — myocardial ischemia, massive pulmonary embolism, or aortic dissection — as the cause. A positive answer should trigger an urgent ECG, troponin, and consideration of PE or aortic imaging rather than routine syncope workup.","meaningSource":"ai-draft"},{"id":"history-08","system":"cardiovascular","question":"Have you been told you have a heart valve problem, a thickened heart muscle, or a weak heart?","listenFor":["No known structural heart disease","Known valvular disease or hypertrophic cardiomyopathy","Known reduced ejection fraction or implanted defibrillator"],"why":null,"whySource":null,"meaning":"Known valvular disease, hypertrophic cardiomyopathy, or reduced ejection fraction makes syncope far more dangerous — exertional syncope in severe aortic stenosis or HCM and ventricular arrhythmias in weak hearts can be fatal. A positive history lowers the threshold for admission, telemetry, and urgent echocardiography.","meaningSource":"ai-draft"},{"id":"history-09","system":"cardiovascular","question":"Has anyone in your family died suddenly from a heart problem before age 50?","listenFor":["No known family history","Family history of sudden cardiac death before age 50"],"why":"Family history of sudden cardiac death before age 50 raises concern for an inherited arrhythmia or cardiomyopathy.","whySource":"curated","meaning":"Family history of sudden cardiac death before age 50 raises concern for an inherited arrhythmia or cardiomyopathy.","meaningSource":"curated"},{"id":"history-10","system":"medication","question":"Have you started a new blood pressure pill, water pill, or heart rhythm medication recently?","listenFor":["No relevant new medication","New antihypertensive or diuretic","New QT-prolonging medication"],"why":"QT-prolonging medications raise the risk of torsades de pointes.","whySource":"curated","meaning":"QT-prolonging medications raise the risk of torsades de pointes.","meaningSource":"curated"},{"id":"history-11","system":"hematologic","question":"Have you noticed black, tarry stools, red blood in your stool, or vomited blood?","listenFor":["No signs of gastrointestinal bleeding","Melena or hematochezia","Hematemesis"],"why":"Black, tarry stools (melena), hematochezia, or hematemesis indicate gastrointestinal bleeding; melena points to an upper source.","whySource":"curated","meaning":"Black, tarry stools (melena), hematochezia, or hematemesis indicate gastrointestinal bleeding; melena points to an upper source.","meaningSource":"curated"},{"id":"history-12","system":"musculoskeletal","question":"Did you hit your head when you fell?","listenFor":["No head strike","Head strike during the fall"],"why":null,"whySource":null,"meaning":"A head strike during the fall shifts attention to traumatic brain injury — anticoagulated patients, prolonged loss of consciousness, or visible injury warrant head imaging. It also helps reconstruct the event: a collapse without prodrome versus one preceded by warning symptoms.","meaningSource":"ai-draft"},{"id":"history-13","system":"endocrine","question":"Do you have diabetes, and did you feel shaky, sweaty, or hungry right before this happened?","listenFor":["No known diabetes","Known diabetes without hypoglycemic symptoms","Known diabetes with hypoglycemic symptoms preceding the event"],"why":"Hypoglycemia causes neuroglycopenic symptoms such as confusion, diaphoresis, and tremor, and needs urgent correction.","whySource":"curated","meaning":"Hypoglycemia causes neuroglycopenic symptoms such as confusion, diaphoresis, and tremor, and needs urgent correction.","meaningSource":"curated"},{"id":"history-14","system":"functional","question":"Have you been immobilized, had recent surgery or travel, or do you have cancer or a history of blood clots?","listenFor":["No provoking risk factor","Recent immobilization, surgery, or travel","Active malignancy or prior venous thromboembolism"],"why":"Active cancer and prior venous thromboembolism are strong risk factors for recurrent clots.","whySource":"curated","meaning":"Active cancer and prior venous thromboembolism are strong risk factors for recurrent clots.","meaningSource":"curated"}],"exam":[{"id":"exam-01","system":"cardiovascular","maneuver":"Assess orthostatic vital signs when safe.","findings":["Negative orthostatics","Positive orthostatic hypotension","Unable to safely assess"],"how":"Measure blood pressure and heart rate after 5 minutes supine, then at 1 and 3 minutes after standing; a sustained drop of 20 mmHg systolic or 10 mmHg diastolic within 3 minutes is positive.","why":null,"whySource":null,"meaning":"A sustained drop of 20 mmHg systolic or 10 mmHg diastolic within 3 minutes of standing identifies orthostatic hypotension — commonly from volume depletion, antihypertensives, or autonomic dysfunction — pointing to medication review and volume repletion rather than cardiac workup. Negative orthostatics make a cardiac or neurologic cause more likely.","meaningSource":"ai-draft"},{"id":"exam-02","system":"cardiovascular","maneuver":"Auscultate the heart for a murmur.","findings":["No murmur","Systolic murmur","Diastolic murmur"],"how":null,"why":null,"whySource":null,"meaning":"A systolic murmur — especially a harsh crescendo–decrescendo murmur of aortic stenosis or the dynamic murmur of hypertrophic cardiomyopathy — flags structural heart disease that makes syncope potentially lethal. Any murmur in this context should prompt echocardiography.","meaningSource":"ai-draft"},{"id":"exam-03","system":"cardiovascular","maneuver":"Assess heart rate and rhythm.","findings":["Regular rate and rhythm","Irregular rhythm","Bradycardic"],"how":null,"why":null,"whySource":null,"meaning":"An irregular rhythm suggests atrial fibrillation — whose pauses or rapid rates can cause syncope — while bradycardia points to sinus node dysfunction or heart block. Either finding should prompt an ECG and rhythm monitoring, since conduction disease may need pacing.","meaningSource":"ai-draft"},{"id":"exam-04","system":"cardiovascular","maneuver":"Auscultate for a carotid bruit.","findings":["Absent","Present"],"how":null,"why":null,"whySource":null,"meaning":"A carotid bruit indicates carotid atherosclerosis and matters mainly for safety: carotid sinus massage is contraindicated when a bruit is present. A bruit alone rarely explains syncope, so don't let it distract from cardiac and orthostatic causes.","meaningSource":"ai-draft"},{"id":"exam-05","system":"neurologic","maneuver":"Assess for a focal neurologic deficit.","findings":["No focal deficit","Focal deficit present"],"how":null,"why":null,"whySource":null,"meaning":"A focal deficit means the event was likely a stroke, TIA, or postictal state rather than true syncope — redirecting the workup to urgent neuroimaging. Its absence supports syncope and keeps the focus on cardiac, orthostatic, and reflex causes.","meaningSource":"ai-draft"},{"id":"exam-06","system":"ent","maneuver":"Inspect the tongue for a lateral laceration suggesting seizure.","findings":["No tongue laceration","Lateral tongue laceration"],"how":null,"why":"A lateral tongue bite favors a generalized tonic-clonic seizure over syncope.","whySource":"curated","meaning":"A lateral tongue bite favors a generalized tonic-clonic seizure over syncope.","meaningSource":"curated"},{"id":"exam-07","system":"musculoskeletal","maneuver":"Inspect for injury sustained during the fall.","findings":["No injury identified","Injury identified from the fall"],"how":null,"why":null,"whySource":null,"meaning":"Documenting fall injuries (lacerations, fractures, head trauma) determines what needs treatment now — elderly patients may have occult hip fractures — and an injury without any prodrome suggests abrupt, high-risk syncope. The fall, not the syncope, may be the immediate threat.","meaningSource":"ai-draft"},{"id":"exam-08","system":"gastrointestinal","maneuver":"Perform a rectal examination when gastrointestinal bleeding is suspected.","findings":["Normal or deferred as not indicated","Melena on examination"],"how":null,"why":"Melena (black, tarry stools) indicates upper gastrointestinal bleeding.","whySource":"curated","meaning":"Melena (black, tarry stools) indicates upper gastrointestinal bleeding.","meaningSource":"curated"},{"id":"exam-09","system":"hematologic","maneuver":"Inspect conjunctiva and nail beds for pallor.","findings":["Normal color","Conjunctival or nail-bed pallor"],"how":null,"why":"Pallor of the conjunctivae, nail beds, or palmar creases suggests anemia.","whySource":"curated","meaning":"Pallor of the conjunctivae, nail beds, or palmar creases suggests anemia.","meaningSource":"curated"},{"id":"exam-10","system":"skin","maneuver":"Assess skin for diaphoresis or pallor at the time of evaluation.","findings":["Normal, dry skin","Diaphoretic or pale"],"how":null,"why":"Pallor of the conjunctivae, nail beds, or palmar creases suggests anemia.","whySource":"curated","meaning":"Pallor of the conjunctivae, nail beds, or palmar creases suggests anemia.","meaningSource":"curated"}],"reviewNeeded":{"whyMissing":10,"howMissing":9}},{"id":"atrial-fibrillation-rvr","title":"Atrial fibrillation with rapid ventricular rate","aliases":["afib with RVR","rapid atrial fibrillation"],"history":[{"id":"history-01","system":"cardiovascular","question":"Have you been diagnosed with atrial fibrillation before, and if so, does this feel like your usual episodes or is it your first time?","listenFor":["Known paroxysmal atrial fibrillation, similar to prior episodes","Known persistent or permanent atrial fibrillation","First-time, new-onset atrial fibrillation"],"why":null,"whySource":null,"meaning":"Known AF with a typical episode points toward rate control and checking anticoagulation status, while a first-ever episode needs a full new-diagnosis workup for precipitants and a decision about anticoagulation and cardioversion timing.","meaningSource":"ai-draft"},{"id":"history-02","system":"cardiovascular","question":"Do you have any chest pain along with the palpitations?","listenFor":["No chest pain","Chest pain"],"why":null,"whySource":null,"meaning":"Chest pain with rapid AF raises concern for demand ischemia or underlying coronary disease; obtain an EKG and troponin, since a rapid rate can unmask ischemia even without plaque rupture.","meaningSource":"ai-draft"},{"id":"history-03","system":"respiratory","question":"Are you short of breath along with the palpitations?","listenFor":["No dyspnea","Dyspnea"],"why":null,"whySource":null,"meaning":"Shortness of breath suggests the rapid rate is causing pulmonary congestion or heart failure, which raises the urgency of rate control and may require diuresis alongside it.","meaningSource":"ai-draft"},{"id":"history-04","system":"neurologic","question":"Have you felt like you were going to pass out, or did you actually pass out?","listenFor":["Neither","Presyncope","Syncope"],"why":null,"whySource":null,"meaning":"Syncope or presyncope with rapid AF signals hemodynamic compromise — an unstable patient needs emergent synchronized cardioversion rather than medications alone.","meaningSource":"ai-draft"},{"id":"history-05","system":"infectious","question":"Have you had a fever or felt sick before this started?","listenFor":["No fever or infectious symptoms","Fever or infectious symptoms"],"why":null,"whySource":null,"meaning":"Fever or a preceding illness points to infection or sepsis as the precipitant; the AF often resolves with treatment of the underlying cause, though rate control is still needed in the meantime.","meaningSource":"ai-draft"},{"id":"history-06","system":"medication","question":"Did you binge drink alcohol recently?","listenFor":["No recent binge alcohol intake","Recent binge alcohol intake"],"why":"Binge alcohol intake can precipitate atrial fibrillation (holiday heart).","whySource":"curated","meaning":"Binge alcohol intake can precipitate atrial fibrillation (holiday heart).","meaningSource":"curated"},{"id":"history-07","system":"endocrine","question":"Have you noticed heat intolerance, tremor, or unexplained weight loss, or do you have a known thyroid problem?","listenFor":["No hyperthyroid symptoms","Known hyperthyroidism, stable","New heat intolerance, tremor, or unintentional weight loss"],"why":"Heat intolerance, tremor, and weight loss suggest hyperthyroidism, a reversible trigger of atrial fibrillation.","whySource":"curated","meaning":"Heat intolerance, tremor, and weight loss suggest hyperthyroidism, a reversible trigger of atrial fibrillation.","meaningSource":"curated"},{"id":"history-08","system":"medication","question":"Are you on a blood thinner for your heart rhythm, and have you been taking it exactly as prescribed?","listenFor":["Therapeutic and adherent on anticoagulation","Subtherapeutic or missed anticoagulant doses","Not currently anticoagulated"],"why":"Missed or subtherapeutic anticoagulation raises stroke risk in atrial fibrillation.","whySource":"curated","meaning":"Missed or subtherapeutic anticoagulation raises stroke risk in atrial fibrillation.","meaningSource":"curated"},{"id":"history-09","system":"hematologic","question":"Have you had any unusual bruising or bleeding while on your blood thinner?","listenFor":["No bleeding symptoms","Bleeding symptoms while anticoagulated"],"why":"Blood thinner use increases bleeding risk and severity, and affects reversal decisions.","whySource":"curated","meaning":"Blood thinner use increases bleeding risk and severity, and affects reversal decisions.","meaningSource":"curated"},{"id":"history-10","system":"cardiovascular","question":"Do you have high blood pressure, diabetes, known blood vessel disease, or have you had a stroke or mini-stroke before?","listenFor":["None of these","Hypertension, diabetes, or known vascular disease","Prior stroke or transient ischemic attack"],"why":null,"whySource":null,"meaning":"Hypertension, diabetes, vascular disease, and prior stroke or TIA are the core components of the CHA2DS2-VASc score; eliciting them determines whether long-term anticoagulation is indicated.","meaningSource":"ai-draft"},{"id":"history-11","system":"medication","question":"Have you had surgery recently or been sick with another acute illness?","listenFor":["Neither","Recent surgery","Recent acute illness or infection"],"why":null,"whySource":null,"meaning":"Recent surgery or acute illness is a common reversible precipitant of AF, especially postoperatively; identifying it focuses management on the trigger and informs whether long-term anticoagulation will be needed.","meaningSource":"ai-draft"},{"id":"history-12","system":"cardiovascular","question":"Have you been diagnosed with Wolff-Parkinson-White syndrome or another abnormal heart electrical pathway?","listenFor":["No known pre-excitation syndrome","Known Wolff-Parkinson-White or pre-excitation syndrome"],"why":"Atrial fibrillation with Wolff-Parkinson-White syndrome risks rapid conduction down the accessory pathway into ventricular fibrillation; avoid AV nodal blockers.","whySource":"curated","meaning":"Atrial fibrillation with Wolff-Parkinson-White syndrome risks rapid conduction down the accessory pathway into ventricular fibrillation; avoid AV nodal blockers.","meaningSource":"curated"},{"id":"history-13","system":"medication","question":"Have you used any stimulant drugs or had a lot more caffeine than usual recently?","listenFor":["No recent stimulant or excess caffeine intake","Recent stimulant use or excess caffeine intake"],"why":null,"whySource":null,"meaning":"Stimulant drugs and excess caffeine are reversible triggers of AF with rapid rates; identifying them guides counseling and may avoid committing the patient to long-term therapy for a one-time precipitant.","meaningSource":"ai-draft"},{"id":"history-14","system":"cardiovascular","question":"Do you need extra pillows to breathe at night, wake up gasping for air, or have new leg swelling?","listenFor":["None of these","Orthopnea or paroxysmal nocturnal dyspnea","Leg swelling"],"why":"Waking up gasping for air, relieved by sitting up (paroxysmal nocturnal dyspnea), reflects pulmonary edema from elevated left-sided filling pressures, as in left heart failure.","whySource":"curated","meaning":"Waking up gasping for air, relieved by sitting up (paroxysmal nocturnal dyspnea), reflects pulmonary edema from elevated left-sided filling pressures, as in left heart failure.","meaningSource":"curated"}],"exam":[{"id":"exam-01","system":"cardiovascular","maneuver":"Assess heart rate and rhythm regularity.","findings":["Regular rhythm","Irregularly irregular rhythm"],"how":null,"why":"An irregularly irregular pulse suggests atrial fibrillation.","whySource":"curated","meaning":"An irregularly irregular pulse suggests atrial fibrillation.","meaningSource":"curated"},{"id":"exam-02","system":"general","maneuver":"Assess hemodynamic stability.","findings":["Normotensive and stable","Hypotensive or hemodynamically unstable"],"how":null,"why":null,"whySource":null,"meaning":"Hemodynamic stability is the pivotal branch point: an unstable patient (hypotensive, altered, ischemic chest pain, pulmonary edema) needs emergent synchronized cardioversion, while a stable patient is managed with rate control.","meaningSource":"ai-draft"},{"id":"exam-03","system":"cardiovascular","maneuver":"Assess jugular venous pressure and peripheral edema.","findings":["Normal jugular venous pressure, no edema","Elevated jugular venous pressure or peripheral edema"],"how":"With the patient reclined at 30 to 45 degrees, identify the highest point of internal jugular venous pulsation and measure its vertical distance above the sternal angle.","why":"Elevated jugular venous pressure reflects elevated right-sided filling pressures, seen in right heart failure, volume overload, or tamponade.","whySource":"curated","meaning":"Elevated jugular venous pressure reflects elevated right-sided filling pressures, seen in right heart failure, volume overload, or tamponade.","meaningSource":"curated"},{"id":"exam-04","system":"respiratory","maneuver":"Auscultate the lungs for crackles.","findings":["Clear bilaterally","Bibasilar crackles"],"how":null,"why":"Bibasilar crackles suggest pulmonary edema from left heart failure; focal crackles suggest pneumonia.","whySource":"curated","meaning":"Bibasilar crackles suggest pulmonary edema from left heart failure; focal crackles suggest pneumonia.","meaningSource":"curated"},{"id":"exam-05","system":"endocrine","maneuver":"Assess the thyroid for goiter or tremor.","findings":["Normal thyroid exam, no tremor","Goiter or fine tremor"],"how":null,"why":null,"whySource":null,"meaning":"Goiter or a fine tremor suggests hyperthyroidism as the precipitant of the AF; check thyroid function, since treating the thyroid disease is key to durable rhythm control.","meaningSource":"ai-draft"},{"id":"exam-06","system":"cardiovascular","maneuver":"Compare the apical heart rate to the radial pulse rate for a pulse deficit.","findings":["Apical and radial rates concordant","Pulse deficit present"],"how":null,"why":"A pulse deficit, where the apical rate exceeds the palpable radial rate, occurs in atrial fibrillation.","whySource":"curated","meaning":"A pulse deficit, where the apical rate exceeds the palpable radial rate, occurs in atrial fibrillation.","meaningSource":"curated"},{"id":"exam-07","system":"neurologic","maneuver":"Assess mental status and perfusion.","findings":["Alert with normal perfusion","Altered mental status or poor perfusion"],"how":null,"why":null,"whySource":null,"meaning":"Altered mental status or poor perfusion marks the patient as unstable regardless of the blood pressure number — this finding pushes management toward emergent cardioversion.","meaningSource":"ai-draft"},{"id":"exam-08","system":"cardiovascular","maneuver":"Assess peripheral pulses for an acutely cool or pulseless limb suggesting embolism.","findings":["Symmetric, warm extremities","Cool or pulseless extremity"],"how":null,"why":"A cool or pulseless extremity suggests acute arterial occlusion from embolism.","whySource":"curated","meaning":"A cool or pulseless extremity suggests acute arterial occlusion from embolism.","meaningSource":"curated"},{"id":"exam-09","system":"skin","maneuver":"Inspect the skin for ecchymosis related to anticoagulation.","findings":["No ecchymosis","Ecchymosis present"],"how":null,"why":null,"whySource":null,"meaning":"Ecchymosis in an anticoagulated patient suggests over-anticoagulation or a bleeding tendency; check the INR if on warfarin and review bleeding risk before continuing or adjusting therapy.","meaningSource":"ai-draft"},{"id":"exam-10","system":"cardiovascular","maneuver":"Inspect and palpate the calves for asymmetric swelling or tenderness.","findings":["Symmetric, no swelling or tenderness","Unilateral swelling or tenderness"],"how":null,"why":null,"whySource":null,"meaning":"Unilateral calf swelling or tenderness raises concern for deep vein thrombosis, which changes anticoagulation decisions and warrants duplex ultrasound.","meaningSource":"ai-draft"}],"reviewNeeded":{"whyMissing":13,"howMissing":9}},{"id":"acute-coronary-syndrome","title":"Acute coronary syndrome / NSTEMI/STEMI","aliases":["heart attack","myocardial infarction","NSTEMI","STEMI"],"history":[{"id":"history-01","system":"cardiovascular","question":"Can you describe the pain — is it a pressure or squeezing feeling, does it feel sharp or worse with certain positions, or is it more of an ache in your jaw or stomach?","listenFor":["Pressure or squeezing, substernal, radiating to the arm or jaw","Atypical location, such as epigastric or jaw pain alone","Sharp, positional, or pleuritic pain"],"why":"Substernal pressure radiating to the arm, jaw, or neck is the classic description of anginal chest pain.","whySource":"curated","meaning":"Substernal pressure radiating to the arm, jaw, or neck is the classic description of anginal chest pain.","meaningSource":"curated"},{"id":"history-02","system":"cardiovascular","question":"How long did the pain last — did it go away in under 10 minutes, resolve within 20 minutes with rest or nitroglycerin, or is it still going on?","listenFor":["Under 10 minutes, fully resolved","10 to 20 minutes, resolved with rest or nitroglycerin","Persistent for more than 20 minutes"],"why":"Angina resolving within 20 minutes with rest or nitroglycerin fits unstable angina; pain persisting beyond 20 minutes suggests myocardial infarction.","whySource":"curated","meaning":"Angina resolving within 20 minutes with rest or nitroglycerin fits unstable angina; pain persisting beyond 20 minutes suggests myocardial infarction.","meaningSource":"curated"},{"id":"history-03","system":"cardiovascular","question":"Did you break out in a sweat along with the pain?","listenFor":["No diaphoresis","Diaphoresis accompanying the pain"],"why":null,"whySource":null,"meaning":"Diaphoresis with ischemic symptoms reflects the autonomic surge of acute coronary syndrome and marks a higher-risk presentation. In a patient with a convincing story, it strengthens the case for admission and early cardiology involvement.","meaningSource":"ai-draft"},{"id":"history-04","system":"gastrointestinal","question":"Did you feel nauseated or vomit along with the pain?","listenFor":["Neither","Nausea","Vomiting"],"why":null,"whySource":null,"meaning":"Nausea and vomiting commonly accompany acute coronary syndrome — particularly inferior ischemia with vagal activation — so their presence supports rather than distracts from the cardiac diagnosis. Do not attribute them to a primary GI cause until ischemia has been addressed.","meaningSource":"ai-draft"},{"id":"history-05","system":"cardiovascular","question":"Did the pain spread anywhere, like into your arm, jaw, neck, or back?","listenFor":["No radiation","Radiation to the arm, jaw, or neck","Radiation to the back"],"why":null,"whySource":null,"meaning":"Radiation to the arm, jaw, or neck is classic for myocardial ischemia. Radiation to the back instead raises concern for aortic dissection — a finding that should redirect the workup to emergent aortic imaging rather than a routine ACS rule-out.","meaningSource":"ai-draft"},{"id":"history-06","system":"cardiovascular","question":"Have you been diagnosed with coronary artery disease, and have you had a stent or bypass surgery before?","listenFor":["No known coronary artery disease","Known coronary artery disease, no prior intervention","Prior myocardial infarction, angioplasty, or bypass surgery"],"why":null,"whySource":null,"meaning":"Known coronary disease — especially a prior stent or bypass — makes recurrent ischemia far more likely, and new angina after PCI raises the specific concern of stent thrombosis or restenosis. These patients warrant urgent cardiology involvement and a low threshold for catheterization.","meaningSource":"ai-draft"},{"id":"history-07","system":"cardiovascular","question":"Do you have high blood pressure, diabetes, high cholesterol, smoke, or have a family history of early heart disease?","listenFor":["No known risk factors","One or two risk factors: hypertension, diabetes, hyperlipidemia, smoking, or family history","Three or more risk factors"],"why":null,"whySource":null,"meaning":"Counting risk factors (hypertension, diabetes, hyperlipidemia, smoking, family history of early disease) estimates pretest probability and feeds risk-stratification scores: more factors mean a lower threshold to admit. But no risk factors still cannot rule out ACS when the story is convincing.","meaningSource":"ai-draft"},{"id":"history-08","system":"medication","question":"Have you used cocaine or another stimulant drug in the past day?","listenFor":["No stimulant use","Stimulant use within the preceding 24 hours"],"why":null,"whySource":null,"meaning":"Cocaine or stimulant use within the preceding 24 hours raises the risk of vasospasm-mediated MI, aortic dissection, and arrhythmia on top of ordinary plaque rupture. Work these patients up as ACS, and consider that vasospasm may still be active.","meaningSource":"ai-draft"},{"id":"history-09","system":"respiratory","question":"Have you felt unusually short of breath, even without chest pain?","listenFor":["No dyspnea","Dyspnea as an anginal equivalent"],"why":"Dyspnea can be an anginal equivalent of myocardial ischemia, especially in older adults and patients with diabetes.","whySource":"curated","meaning":"Dyspnea can be an anginal equivalent of myocardial ischemia, especially in older adults and patients with diabetes.","meaningSource":"curated"},{"id":"history-10","system":"neurologic","question":"Did you feel like you were going to pass out, or did you actually pass out during this?","listenFor":["Neither","Near-syncope","Syncope"],"why":null,"whySource":null,"meaning":"Syncope or near-syncope during ischemic symptoms suggests a malignant arrhythmia or a hemodynamically significant event rather than stable angina. Put the patient on continuous telemetry, check orthostatics and rhythm, and treat it as a high-risk feature.","meaningSource":"ai-draft"},{"id":"history-11","system":"cardiovascular","question":"Do you need extra pillows to breathe at night, wake up gasping for air, or have new leg swelling?","listenFor":["None of these","Orthopnea or paroxysmal nocturnal dyspnea","Leg swelling"],"why":"Waking up gasping for air, relieved by sitting up (paroxysmal nocturnal dyspnea), reflects pulmonary edema from elevated left-sided filling pressures, as in left heart failure.","whySource":"curated","meaning":"Waking up gasping for air, relieved by sitting up (paroxysmal nocturnal dyspnea), reflects pulmonary edema from elevated left-sided filling pressures, as in left heart failure.","meaningSource":"curated"},{"id":"history-12","system":"cardiovascular","question":"Did you feel your heart racing or fluttering along with this?","listenFor":["No palpitations","Palpitations"],"why":null,"whySource":null,"meaning":"Palpitations with ischemic symptoms raise concern for a tachyarrhythmia — atrial fibrillation, ventricular tachycardia, or another rhythm disturbance — which may be both consequence and driver of the ischemia. Capture a rhythm strip on continuous telemetry, since the arrhythmia changes management.","meaningSource":"ai-draft"},{"id":"history-13","system":"medication","question":"Are you on a blood thinner, or have you had a stomach or intestinal bleed in the past?","listenFor":["Neither","Current anticoagulant use","Prior gastrointestinal bleed"],"why":"Blood thinner use increases bleeding risk and severity, and affects reversal decisions.","whySource":"curated","meaning":"Blood thinner use increases bleeding risk and severity, and affects reversal decisions.","meaningSource":"curated"},{"id":"history-14","system":"cardiovascular","question":"Have you had this same pain before, and if so, is it happening more often, getting worse, or coming on with less activity than it used to?","listenFor":["First episode of this pain","Recurrent episodes with a stable pattern","Crescendo pattern of increasing frequency, severity, or lower exertional threshold"],"why":"A crescendo pattern of more frequent, more severe, or lower-threshold angina defines unstable angina.","whySource":"curated","meaning":"A crescendo pattern of more frequent, more severe, or lower-threshold angina defines unstable angina.","meaningSource":"curated"}],"exam":[{"id":"exam-01","system":"general","maneuver":"Assess hemodynamic stability.","findings":["Normotensive, warm and well-perfused","Hypotensive with cool extremities, concern for cardiogenic shock","Hypoxic with signs of pulmonary edema"],"how":null,"why":"Hypotension with cool extremities and pulmonary edema suggests cardiogenic shock from pump failure.","whySource":"curated","meaning":"Hypotension with cool extremities and pulmonary edema suggests cardiogenic shock from pump failure.","meaningSource":"curated"},{"id":"exam-02","system":"cardiovascular","maneuver":"Auscultate heart sounds for a gallop.","findings":["Normal S1 and S2, no gallop","S3 gallop","S4 gallop"],"how":null,"why":"An S3 gallop reflects rapid early ventricular filling and suggests left ventricular systolic dysfunction or volume overload, as in heart failure.","whySource":"curated","meaning":"An S3 gallop reflects rapid early ventricular filling and suggests left ventricular systolic dysfunction or volume overload, as in heart failure.","meaningSource":"curated"},{"id":"exam-03","system":"cardiovascular","maneuver":"Auscultate for a new murmur, which could indicate a mechanical complication.","findings":["No murmur","New murmur"],"how":null,"why":"A new murmur after myocardial infarction suggests a mechanical complication such as papillary muscle rupture or ventricular septal rupture.","whySource":"curated","meaning":"A new murmur after myocardial infarction suggests a mechanical complication such as papillary muscle rupture or ventricular septal rupture.","meaningSource":"curated"},{"id":"exam-04","system":"respiratory","maneuver":"Auscultate the lungs for crackles.","findings":["Clear bilaterally","Bibasilar crackles","Diffuse crackles consistent with pulmonary edema"],"how":null,"why":"Diffuse bilateral crackles suggest acute pulmonary edema.","whySource":"curated","meaning":"Diffuse bilateral crackles suggest acute pulmonary edema.","meaningSource":"curated"},{"id":"exam-05","system":"cardiovascular","maneuver":"Assess jugular venous pressure.","findings":["Normal jugular venous pressure","Elevated jugular venous pressure"],"how":"With the patient reclined at 30 to 45 degrees, identify the highest point of internal jugular venous pulsation and measure its vertical distance above the sternal angle.","why":"Elevated jugular venous pressure reflects elevated right-sided filling pressures, seen in right heart failure, volume overload, or tamponade.","whySource":"curated","meaning":"Elevated jugular venous pressure reflects elevated right-sided filling pressures, seen in right heart failure, volume overload, or tamponade.","meaningSource":"curated"},{"id":"exam-06","system":"cardiovascular","maneuver":"Palpate peripheral pulses for symmetry to help exclude aortic dissection.","findings":["Symmetric pulses","Asymmetric or diminished pulse"],"how":null,"why":"Asymmetric or diminished pulses suggest aortic dissection.","whySource":"curated","meaning":"Asymmetric or diminished pulses suggest aortic dissection.","meaningSource":"curated"},{"id":"exam-07","system":"musculoskeletal","maneuver":"Palpate the chest wall to help exclude a musculoskeletal cause.","findings":["Reproducible chest wall tenderness","Nontender chest wall"],"how":null,"why":null,"whySource":null,"meaning":"Reproducible chest wall tenderness lowers the likelihood of ACS but does not rule it out — a meaningful minority of ACS patients have some tenderness. Treat it as one low-risk data point within the full clinical picture, never as a standalone rule-out.","meaningSource":"ai-draft"},{"id":"exam-08","system":"neurologic","maneuver":"Assess mental status and perfusion.","findings":["Alert with good perfusion","Altered mental status or poor perfusion"],"how":null,"why":null,"whySource":null,"meaning":"Altered mental status or poor perfusion in suspected ACS signals cardiogenic shock or a malignant arrhythmia. Check blood pressure and rhythm immediately — hypotension with ischemia is an indication for emergent reperfusion, not a routine rule-out.","meaningSource":"ai-draft"},{"id":"exam-09","system":"skin","maneuver":"Assess skin for diaphoresis, pallor, or mottling.","findings":["Normal skin","Diaphoretic, pale, or mottled"],"how":null,"why":"Mottled skin indicates poor peripheral perfusion in shock.","whySource":"curated","meaning":"Mottled skin indicates poor peripheral perfusion in shock.","meaningSource":"curated"},{"id":"exam-10","system":"hematologic","maneuver":"Inspect any vascular access site for active bleeding or hematoma.","findings":["No bleeding, no access site or site normal","Active bleeding or hematoma at an access site"],"how":null,"why":null,"whySource":null,"meaning":"Active bleeding or an expanding hematoma at a vascular access site flags a bleeding complication — critical information before starting or escalating anticoagulation or taking the patient for catheterization. A groin hematoma with hypotension raises concern for retroperitoneal hemorrhage.","meaningSource":"ai-draft"}],"reviewNeeded":{"whyMissing":11,"howMissing":9}},{"id":"stroke-tia","title":"Stroke (CVA) or TIA","aliases":["cerebrovascular accident","transient ischemic attack"],"history":[{"id":"history-01","system":"neurologic","question":"What time were you last seen acting and looking completely normal?","listenFor":["Within the past 4.5 hours","Between 4.5 and 24 hours ago","More than 24 hours ago or unknown"],"why":"The time last known well determines eligibility for thrombolysis and thrombectomy in acute ischemic stroke.","whySource":"curated","meaning":"The time last known well determines eligibility for thrombolysis and thrombectomy in acute ischemic stroke.","meaningSource":"curated"},{"id":"history-02","system":"neurologic","question":"Did your symptoms hit you all at once at their worst, get worse in sudden steps, or build up gradually over hours?","listenFor":["Sudden onset, maximal deficit immediately","Stepwise progression","Gradual progression over hours"],"why":null,"whySource":null,"meaning":"A deficit that is maximal at onset is classic for ischemic stroke, particularly embolic; stepwise worsening suggests stuttering ischemia or stroke-in-evolution needing urgent evaluation. Gradual progression over hours points away from stroke toward mimics such as migraine, Todd's paresis, or a mass lesion.","meaningSource":"ai-draft"},{"id":"history-03","system":"neurologic","question":"Are your symptoms still going on, or did they completely go away, and if so how quickly?","listenFor":["Symptoms persistent","Resolved completely within an hour","Resolved within 24 hours"],"why":"Deficits resolving completely within 24 hours define transient ischemic attack rather than completed stroke.","whySource":"curated","meaning":"Deficits resolving completely within 24 hours define transient ischemic attack rather than completed stroke.","meaningSource":"curated"},{"id":"history-04","system":"neurologic","question":"Do you have a headache along with this, and if so, is it the worst headache of your life?","listenFor":["No headache","Mild headache","Severe, worst-of-life headache"],"why":null,"whySource":null,"meaning":"A sudden worst-of-life headache is the hallmark of subarachnoid hemorrhage and is a can't-miss alternative when neurologic symptoms are present. Any severe headache with new deficits should prompt emergent noncontrast head CT; mild headache alone is nonspecific.","meaningSource":"ai-draft"},{"id":"history-05","system":"neurologic","question":"Did anyone see you shake or convulse when this started?","listenFor":["No witnessed seizure activity","Witnessed seizure activity"],"why":null,"whySource":null,"meaning":"Witnessed shaking at onset suggests a seizure with postictal (Todd's) weakness mimicking stroke — though seizures can also complicate acute stroke itself. A positive answer should prompt EEG consideration and careful review, since the treatment paths diverge.","meaningSource":"ai-draft"},{"id":"history-06","system":"medication","question":"Are you currently taking a blood thinner?","listenFor":["Not anticoagulated","Currently anticoagulated"],"why":"Blood thinner use increases bleeding risk and severity, and affects reversal decisions.","whySource":"curated","meaning":"Blood thinner use increases bleeding risk and severity, and affects reversal decisions.","meaningSource":"curated"},{"id":"history-07","system":"musculoskeletal","question":"Have you hit your head recently?","listenFor":["No recent head trauma","Recent head trauma"],"why":null,"whySource":null,"meaning":"Recent head trauma raises concern for traumatic hemorrhage or subdural hematoma mimicking stroke — and significant recent trauma is a contraindication to thrombolysis. A positive answer means neuroimaging before any reperfusion decision.","meaningSource":"ai-draft"},{"id":"history-08","system":"cardiovascular","question":"Have you been diagnosed with atrial fibrillation?","listenFor":["No known atrial fibrillation","Known atrial fibrillation"],"why":null,"whySource":null,"meaning":"Atrial fibrillation is the most common cardioembolic source — a stroke in a patient with AF is presumed cardioembolic until proven otherwise, which changes secondary prevention toward anticoagulation. It also prompts a rhythm check now, since new AF may be the culprit.","meaningSource":"ai-draft"},{"id":"history-09","system":"endocrine","question":"Do you have diabetes, and could your blood sugar have dropped low before this started?","listenFor":["No known diabetes","Known diabetes with possible hypoglycemia symptoms"],"why":null,"whySource":null,"meaning":"Hypoglycemia is a classic stroke mimic that can produce focal deficits — including aphasia and hemiparesis — that resolve completely with glucose. Check a bedside glucose immediately in every suspected stroke; it's the fastest reversible cause and must be corrected before thrombolysis decisions.","meaningSource":"ai-draft"},{"id":"history-10","system":"neurologic","question":"Do you get migraines with visual or sensory auras, and does this feel like one of those?","listenFor":["No history of migraine with aura","Known migraine with aura, resembles prior episodes"],"why":null,"whySource":null,"meaning":"Migraine with aura — especially hemiplegic migraine — is a leading stroke mimic; symptoms identical to prior auras argue against acute stroke. But a first-ever event, or aura in an older patient without migraine history, still demands full stroke workup.","meaningSource":"ai-draft"},{"id":"history-11","system":"neurologic","question":"Have you had trouble finding the right words, or has your speech sounded slurred?","listenFor":["No speech change","Difficulty finding words","Slurred speech"],"why":null,"whySource":null,"meaning":"Trouble finding words points to aphasia — a dominant (usually left) hemisphere lesion — while slurred but correctly chosen words indicate dysarthria, which localizes less specifically. Making this distinction sharpens lesion localization and the neurologic exam.","meaningSource":"ai-draft"},{"id":"history-12","system":"eyes","question":"Have you had any change in your vision, like losing sight in one eye, a blind spot, or double vision?","listenFor":["No vision change","Monocular vision loss","Visual field cut or double vision"],"why":"Transient monocular vision loss (amaurosis fugax) suggests carotid embolic disease.","whySource":"curated","meaning":"Transient monocular vision loss (amaurosis fugax) suggests carotid embolic disease.","meaningSource":"curated"},{"id":"history-13","system":"neurologic","question":"Have you felt dizzy, off-balance, or clumsy with your arms or legs?","listenFor":["None of these","Vertigo or imbalance","Limb incoordination"],"why":null,"whySource":null,"meaning":"Vertigo, imbalance, or limb clumsiness points to posterior circulation (brainstem or cerebellar) stroke — the territory most commonly missed. Positive answers should prompt testing for nystagmus, gait ataxia, and cranial nerve signs, since isolated dizziness can be the only warning of a basilar event.","meaningSource":"ai-draft"},{"id":"history-14","system":"cardiovascular","question":"Has your blood pressure been well controlled, and have you been told you have narrowing in your neck arteries?","listenFor":["Well-controlled hypertension, no known carotid disease","Poorly controlled hypertension","Known carotid artery disease"],"why":null,"whySource":null,"meaning":"Uncontrolled hypertension is the leading modifiable stroke risk factor and raises concern for hemorrhagic stroke; known carotid stenosis points to large-artery atherosclerosis as the mechanism and should prompt carotid imaging. Both answers directly shape secondary prevention.","meaningSource":"ai-draft"}],"exam":[{"id":"exam-01","system":"neurologic","maneuver":"Assess for facial droop.","findings":["Symmetric facial movement","Unilateral facial droop"],"how":null,"why":"New facial droop suggests stroke.","whySource":"curated","meaning":"New facial droop suggests stroke.","meaningSource":"curated"},{"id":"exam-02","system":"neurologic","maneuver":"Assess for arm drift or weakness.","findings":["No drift or weakness","Unilateral arm drift or weakness"],"how":null,"why":null,"whySource":null,"meaning":"Unilateral arm drift or weakness localizes to the contralateral motor cortex or corticospinal tract and is one of the most sensitive bedside markers of acute stroke. A positive finding strengthens the stroke diagnosis and feeds directly into severity scales.","meaningSource":"ai-draft"},{"id":"exam-03","system":"neurologic","maneuver":"Assess for leg weakness.","findings":["No leg weakness","Unilateral leg weakness"],"how":null,"why":null,"whySource":null,"meaning":"Unilateral leg weakness localizes to the contralateral motor system — leg-predominant weakness suggests anterior cerebral artery territory, while combined arm and leg weakness points to middle cerebral artery territory. Asymmetry here is a core stroke-localizing finding.","meaningSource":"ai-draft"},{"id":"exam-04","system":"neurologic","maneuver":"Assess speech and language.","findings":["Normal speech and language","Dysarthria","Aphasia"],"how":null,"why":null,"whySource":null,"meaning":"Aphasia (impaired comprehension or word-finding) localizes to the dominant hemisphere, usually the left middle cerebral artery territory; dysarthria (slurred articulation with intact language) is less localizing but still supports a central lesion. Documenting which one is present sharpens both diagnosis and severity scoring.","meaningSource":"ai-draft"},{"id":"exam-05","system":"eyes","maneuver":"Assess visual fields.","findings":["Full visual fields","Visual field cut"],"how":null,"why":"A visual field cut localizes to the contralateral optic tract or occipital lobe.","whySource":"curated","meaning":"A visual field cut localizes to the contralateral optic tract or occipital lobe.","meaningSource":"curated"},{"id":"exam-06","system":"neurologic","maneuver":"Assess for gaze deviation.","findings":["Midline gaze","Forced gaze deviation"],"how":null,"why":"Forced gaze deviation suggests a large hemispheric stroke, with the eyes deviated toward the side of the lesion.","whySource":"curated","meaning":"Forced gaze deviation suggests a large hemispheric stroke, with the eyes deviated toward the side of the lesion.","meaningSource":"curated"},{"id":"exam-07","system":"neurologic","maneuver":"Assess sensation for a unilateral deficit.","findings":["Normal sensation","Unilateral sensory loss"],"how":null,"why":null,"whySource":null,"meaning":"Unilateral sensory loss supports a central rather than peripheral process — its distribution (face, arm, leg) helps localize to thalamic, parietal, or brainstem territory. Isolated sensory symptoms can also represent a TIA or small-vessel event worth the same urgent workup.","meaningSource":"ai-draft"},{"id":"exam-08","system":"neurologic","maneuver":"Assess coordination with finger-to-nose and heel-to-shin testing.","findings":["Normal coordination","Dysmetria or ataxia"],"how":null,"why":null,"whySource":null,"meaning":"Dysmetria or ataxia on finger-to-nose and heel-to-shin testing points to cerebellar involvement — a posterior circulation stroke until proven otherwise. Combined with vertigo or imbalance, this is a high-risk pattern that is easy to miss on a cursory exam.","meaningSource":"ai-draft"},{"id":"exam-09","system":"neurologic","maneuver":"Assess level of consciousness.","findings":["Alert","Drowsy","Unresponsive"],"how":null,"why":null,"whySource":null,"meaning":"A depressed level of consciousness suggests a large hemispheric stroke with swelling, a basilar artery occlusion, intracerebral hemorrhage, or a non-stroke mimic such as intoxication. Any decline mandates airway assessment and emergent imaging — drowsiness after stroke onset can herald herniation.","meaningSource":"ai-draft"},{"id":"exam-10","system":"cardiovascular","maneuver":"Measure blood pressure.","findings":["Normotensive","Hypertensive, requiring management before thrombolysis consideration"],"how":null,"why":null,"whySource":null,"meaning":"Blood pressure determines thrombolysis eligibility — severe hypertension must be controlled below guideline thresholds before lytics can be given safely, and markedly elevated pressure itself raises concern for hemorrhage. Recheck frequently; the treatment window depends on it.","meaningSource":"ai-draft"},{"id":"exam-11","system":"cardiovascular","maneuver":"Assess cardiac rhythm.","findings":["Regular rhythm","Irregular rhythm"],"how":null,"why":null,"whySource":null,"meaning":"An irregular rhythm suggests atrial fibrillation as the embolic source — the finding that most directly changes secondary prevention toward anticoagulation. Even a single irregular pulse on exam should prompt ECG confirmation and telemetry.","meaningSource":"ai-draft"},{"id":"exam-12","system":"neurologic","maneuver":"Assess pupil size and symmetry for a herniation syndrome.","findings":["Normal, reactive, and symmetric","Asymmetric or a fixed, dilated pupil"],"how":null,"why":"A fixed, dilated pupil suggests uncal herniation from elevated intracranial pressure, a neurosurgical emergency.","whySource":"curated","meaning":"A fixed, dilated pupil suggests uncal herniation from elevated intracranial pressure, a neurosurgical emergency.","meaningSource":"curated"}],"reviewNeeded":{"whyMissing":18,"howMissing":12}},{"id":"cellulitis-ssti","title":"Cellulitis / skin and soft tissue infection","aliases":["cellulitis","skin infection","abscess"],"history":[{"id":"history-01","system":"skin","question":"Has the redness spread slowly over days, or rapidly over just a few hours?","listenFor":["Gradual spread over days","Rapid spread over hours"],"why":null,"whySource":null,"meaning":"Spread measured in hours rather than days is a red flag for necrotizing soft tissue infection or another rapidly progressive process. Examine for crepitus, bullae, pain out of proportion, and systemic toxicity — and escalate urgently if any are present.","meaningSource":"ai-draft"},{"id":"history-02","system":"skin","question":"Does the pain feel proportionate to how the area looks, or is it much more painful than it looks?","listenFor":["Pain proportionate to the redness","Pain out of proportion to the visible findings"],"why":"Pain out of proportion to the physical findings is a red flag for necrotizing soft tissue infection or mesenteric ischemia.","whySource":"curated","meaning":"Pain out of proportion to the physical findings is a red flag for necrotizing soft tissue infection or mesenteric ischemia.","meaningSource":"curated"},{"id":"history-03","system":"infectious","question":"Have you had a fever with shaking chills?","listenFor":["No fever","Subjective fever","Fever with rigors"],"why":"Fever with shaking chills (rigors) suggests bacteremia.","whySource":"curated","meaning":"Fever with shaking chills (rigors) suggests bacteremia.","meaningSource":"curated"},{"id":"history-04","system":"skin","question":"Is any pus or fluid draining from the area?","listenFor":["No purulent drainage","Purulent drainage present"],"why":null,"whySource":null,"meaning":"Purulent drainage signals an abscess or purulent cellulitis rather than simple nonpurulent cellulitis. A fluctuant collection needs incision and drainage — the decisive therapy — with antibiotics as adjunct, so examine for fluctuance rather than just prescribing.","meaningSource":"ai-draft"},{"id":"history-05","system":"skin","question":"Did you have a cut, wound, bite, or injection at that spot before this started?","listenFor":["No known preceding skin break","Known wound, bite, or injection site","Recent skin trauma"],"why":null,"whySource":null,"meaning":"A preceding cut, bite, or injection identifies the portal of entry and the likely organisms. An injection site additionally raises concern for abscess and — in people who inject drugs — endocarditis or septic emboli, so ask about fever and listen for murmurs when that history fits.","meaningSource":"ai-draft"},{"id":"history-06","system":"endocrine","question":"Do you have diabetes, and if so, do you have numbness or reduced feeling in your feet?","listenFor":["No known diabetes","Known diabetes without neuropathy","Known diabetes with peripheral neuropathy"],"why":null,"whySource":null,"meaning":"Diabetes — especially with neuropathy and poor perfusion — turns minor foot trauma into a limb-threatening infection, raises the risk of osteomyelitis and poor healing, and means the patient may never have felt the original injury. Examine the feet carefully and involve wound or podiatry care early.","meaningSource":"ai-draft"},{"id":"history-07","system":"medication","question":"Are you on chemotherapy, a transplant medication, or long-term steroids?","listenFor":["No chronic immunosuppression","Chronic immunosuppression"],"why":null,"whySource":null,"meaning":"Chronic immunosuppression from chemotherapy, transplant medications, or long-term steroids broadens the differential to opportunistic and fungal organisms and blunts the usual inflammatory signs. Use a lower threshold for cultures, imaging, and specialist input — these infections declare themselves late.","meaningSource":"ai-draft"},{"id":"history-08","system":"medication","question":"Do you currently inject drugs?","listenFor":["No active intravenous drug use","Active intravenous drug use"],"why":"Intravenous drug use raises risk for bacteremia, endocarditis, and soft tissue infection.","whySource":"curated","meaning":"Intravenous drug use raises risk for bacteremia, endocarditis, and soft tissue infection.","meaningSource":"curated"},{"id":"history-09","system":"skin","question":"Have you had infections in this same spot before, or do you have chronic swelling in that limb?","listenFor":["First episode at this site","Recurrent episodes at the same site","Known chronic lymphedema"],"why":null,"whySource":null,"meaning":"Recurrent cellulitis at the same site — especially with chronic lymphedema — reflects impaired lymphatic drainage that both invites and perpetuates infection. Look for and treat interdigital tinea pedis as the entry point, and consider prophylactic antibiotics if episodes keep recurring.","meaningSource":"ai-draft"},{"id":"history-10","system":"cardiovascular","question":"Is the leg swollen without any redness or warmth?","listenFor":["Erythema and warmth present, typical of cellulitis","Isolated swelling without erythema or warmth"],"why":null,"whySource":null,"meaning":"Swelling without erythema or warmth argues against cellulitis — consider deep vein thrombosis, heart failure, venous stasis, or lymphedema instead. Note that bilateral symmetric changes favor stasis dermatitis over infection, which is usually unilateral.","meaningSource":"ai-draft"},{"id":"history-11","system":"infectious","question":"Have you or your family noticed any new confusion along with this infection?","listenFor":["No confusion or altered mental status","Confusion or altered mental status"],"why":"New confusion marks severity of systemic illness and suggests acute organ dysfunction, as in severe infection, sepsis, or metabolic derangement.","whySource":"curated","meaning":"New confusion marks severity of systemic illness and suggests acute organ dysfunction, as in severe infection, sepsis, or metabolic derangement.","meaningSource":"curated"},{"id":"history-12","system":"infectious","question":"Was the wound exposed to salt water, fresh water, or soil?","listenFor":["No relevant water or soil exposure","Salt water or fresh water exposure","Soil exposure"],"why":null,"whySource":null,"meaning":"Salt-water exposure raises concern for Vibrio vulnificus, fresh water for Aeromonas, and soil for atypical organisms beyond ordinary streptococci and staphylococci — especially dangerous in liver disease or immunocompromise, where these infections can turn necrotizing. Let the exposure history drive empiric coverage and urgency.","meaningSource":"ai-draft"},{"id":"history-13","system":"infectious","question":"Were you bitten by an animal or insect before this started?","listenFor":["Neither","Animal bite","Insect bite"],"why":null,"whySource":null,"meaning":"Animal bites suggest Pasteurella and warrant prompt antibiotics and wound care — cat bites in particular can seed joints and tendon sheaths. Insect bites are a common portal for ordinary streptococcal cellulitis; either way, ask about rapid spread and systemic signs.","meaningSource":"ai-draft"}],"exam":[{"id":"exam-01","system":"skin","maneuver":"Inspect the borders of the erythema.","findings":["Well-demarcated borders","Poorly demarcated, spreading borders"],"how":null,"why":null,"whySource":null,"meaning":"Well-demarcated, raised borders with a sharp edge suggest erysipelas (superficial streptococcal infection); poorly demarcated, spreading erythema is typical of deeper cellulitis. Either way, mark the leading edge with a pen and recheck it — advancing borders despite antibiotics signal treatment failure.","meaningSource":"ai-draft"},{"id":"exam-02","system":"skin","maneuver":"Inspect for bullae, crepitus, or skin necrosis.","findings":["None of these","Bullae present","Crepitus or skin necrosis"],"how":null,"why":null,"whySource":null,"meaning":"Bullae, crepitus, or skin necrosis are hallmarks of necrotizing soft tissue infection — a surgical emergency. With pain out of proportion, rapid progression, or systemic toxicity alongside these findings, get emergent surgical consultation rather than watchful waiting.","meaningSource":"ai-draft"},{"id":"exam-03","system":"skin","maneuver":"Palpate for fluctuance suggesting an underlying abscess.","findings":["No fluctuance","Fluctuant mass"],"how":null,"why":"Fluctuance suggests an underlying abscess that needs drainage.","whySource":"curated","meaning":"Fluctuance suggests an underlying abscess that needs drainage.","meaningSource":"curated"},{"id":"exam-04","system":"skin","maneuver":"Inspect for lymphangitic streaking.","findings":["No streaking","Lymphangitic streaking present"],"how":null,"why":"Lymphangitic streaking suggests infection spreading along lymphatic channels.","whySource":"curated","meaning":"Lymphangitic streaking suggests infection spreading along lymphatic channels.","meaningSource":"curated"},{"id":"exam-05","system":"hematologic","maneuver":"Palpate for tender regional lymphadenopathy.","findings":["No regional lymphadenopathy","Tender regional lymphadenopathy"],"how":null,"why":"Tender regional nodes suggest reactive lymphadenitis from a nearby infection.","whySource":"curated","meaning":"Tender regional nodes suggest reactive lymphadenitis from a nearby infection.","meaningSource":"curated"},{"id":"exam-06","system":"skin","maneuver":"Assess whether the pain on exam is proportionate to the visible findings.","findings":["Pain proportionate to exam findings","Pain out of proportion to exam findings"],"how":null,"why":"Pain out of proportion to the physical findings is a red flag for necrotizing soft tissue infection or mesenteric ischemia.","whySource":"curated","meaning":"Pain out of proportion to the physical findings is a red flag for necrotizing soft tissue infection or mesenteric ischemia.","meaningSource":"curated"},{"id":"exam-07","system":"neurologic","maneuver":"Assess sensation over the affected area.","findings":["Normal sensation","Decreased sensation or anesthesia over the area"],"how":null,"why":null,"whySource":null,"meaning":"Decreased sensation over the area points to underlying peripheral neuropathy — common in diabetes and a marker of a high-risk foot — so probe for painless ulcers and check pulses. Document the deficit, since progressive anesthesia can also reflect deeper tissue destruction in severe infection.","meaningSource":"ai-draft"},{"id":"exam-08","system":"general","maneuver":"Assess general appearance and vital signs.","findings":["Well-appearing, normal vital signs","Toxic-appearing, tachycardic","Hypotensive or septic-appearing"],"how":null,"why":"A toxic appearance with abnormal vital signs suggests severe systemic illness or sepsis.","whySource":"curated","meaning":"A toxic appearance with abnormal vital signs suggests severe systemic illness or sepsis.","meaningSource":"curated"},{"id":"exam-09","system":"cardiovascular","maneuver":"Assess distal pulses and perfusion of the affected limb.","findings":["Normal distal pulses and perfusion","Diminished pulses or poor perfusion"],"how":null,"why":null,"whySource":null,"meaning":"Diminished distal pulses or poor perfusion flags underlying arterial disease, which impairs healing and antibiotic delivery — and in a rapidly tense, painful limb, loss of perfusion raises concern for compartment syndrome. Either finding needs urgent vascular or surgical input.","meaningSource":"ai-draft"},{"id":"exam-10","system":"musculoskeletal","maneuver":"Assess any adjacent joint for involvement.","findings":["No adjacent joint involvement","Adjacent joint swelling or restricted motion"],"how":null,"why":null,"whySource":null,"meaning":"Swelling or restricted motion of an adjacent joint raises concern for septic arthritis rather than isolated cellulitis. Aspirate the joint promptly, because a septic joint needs urgent drainage and changes both antibiotics and disposition.","meaningSource":"ai-draft"}],"reviewNeeded":{"whyMissing":14,"howMissing":10}},{"id":"dka-hhs","title":"Diabetes mellitus with complications (DKA, HHS)","aliases":["diabetic ketoacidosis","hyperosmolar hyperglycemic state"],"history":[{"id":"history-01","system":"endocrine","question":"Have you been urinating much more than usual?","listenFor":["No polyuria","Polyuria"],"why":"Polyuria and polydipsia reflect osmotic diuresis from hyperglycemia.","whySource":"curated","meaning":"Polyuria and polydipsia reflect osmotic diuresis from hyperglycemia.","meaningSource":"curated"},{"id":"history-02","system":"endocrine","question":"Have you been unusually thirsty?","listenFor":["No polydipsia","Polydipsia"],"why":"Polyuria and polydipsia reflect osmotic diuresis from hyperglycemia.","whySource":"curated","meaning":"Polyuria and polydipsia reflect osmotic diuresis from hyperglycemia.","meaningSource":"curated"},{"id":"history-03","system":"endocrine","question":"Have you been diagnosed with diabetes before, and if so, do you take insulin or pills for it?","listenFor":["Known type 1 diabetes on insulin","Known type 2 diabetes","No prior diabetes diagnosis, possible new onset"],"why":null,"whySource":null,"meaning":"Known type 1 diabetes on insulin makes diabetic ketoacidosis the default emergency, while type 2 diabetes skews toward hyperosmolar state. No prior diabetes diagnosis with severe hyperglycemia means new-onset diabetes — a different workup and a different discharge education plan.","meaningSource":"ai-draft"},{"id":"history-04","system":"medication","question":"Have you been taking your insulin as prescribed, or has your insulin pump had any problems?","listenFor":["Adherent, no pump issues","Missed insulin doses","Insulin pump malfunction or interruption"],"why":"Missed insulin doses are a leading precipitant of diabetic ketoacidosis.","whySource":"curated","meaning":"Missed insulin doses are a leading precipitant of diabetic ketoacidosis.","meaningSource":"curated"},{"id":"history-05","system":"gastrointestinal","question":"Do you have belly pain?","listenFor":["No abdominal pain","Abdominal pain"],"why":null,"whySource":null,"meaning":"Abdominal pain is common in DKA itself and usually resolves with treatment — but pain that is severe, focal, or persists after the acidosis clears should prompt a search for a precipitant like pancreatitis or a true surgical abdomen, which DKA can both mimic and mask.","meaningSource":"ai-draft"},{"id":"history-06","system":"gastrointestinal","question":"Have you had nausea or vomiting?","listenFor":["Neither","Nausea","Vomiting"],"why":null,"whySource":null,"meaning":"Nausea and vomiting are classic in DKA and worsen dehydration and electrolyte losses. In hyperosmolar state, vomiting more often reflects the precipitating illness — so keep looking for the trigger rather than attributing everything to the metabolic derangement.","meaningSource":"ai-draft"},{"id":"history-07","system":"infectious","question":"Have you had a fever or felt sick before this started?","listenFor":["No fever or infectious symptoms","Fever or infectious symptoms"],"why":null,"whySource":null,"meaning":"Infection is the most common precipitant of both DKA and HHS. Fever or infectious symptoms mean you must find and treat the source — urine, lungs, skin and feet, lines, blood — because the crisis will not resolve while the infection smolders.","meaningSource":"ai-draft"},{"id":"history-08","system":"medication","question":"Are you taking a diabetes medication that ends in -gliflozin, like empagliflozin or canagliflozin?","listenFor":["Not on an SGLT2 inhibitor","Currently on an SGLT2 inhibitor"],"why":"SGLT2 inhibitors (gliflozins) can precipitate euglycemic diabetic ketoacidosis.","whySource":"curated","meaning":"SGLT2 inhibitors (gliflozins) can precipitate euglycemic diabetic ketoacidosis.","meaningSource":"curated"},{"id":"history-09","system":"neurologic","question":"Compared to normal, is the patient acting the same, a little more confused, or very sleepy and hard to wake up?","listenFor":["Alert and at baseline per family or caregiver","Mild new confusion","Significant lethargy or unresponsiveness"],"why":"New confusion marks severity of systemic illness and suggests acute organ dysfunction, as in severe infection, sepsis, or metabolic derangement.","whySource":"curated","meaning":"New confusion marks severity of systemic illness and suggests acute organ dysfunction, as in severe infection, sepsis, or metabolic derangement.","meaningSource":"curated"},{"id":"history-10","system":"medication","question":"Have you been drinking a lot of alcohol recently?","listenFor":["No recent heavy alcohol use","Recent heavy alcohol use"],"why":null,"whySource":null,"meaning":"Recent heavy alcohol use raises the alternative of alcoholic ketoacidosis and signals likely missed insulin doses and poor intake. Check the beta-hydroxybutyrate and glucose pattern to distinguish it, and ask about pancreatitis as a precipitant.","meaningSource":"ai-draft"},{"id":"history-11","system":"cardiovascular","question":"Have you had any chest pain?","listenFor":["No chest pain","Chest pain"],"why":null,"whySource":null,"meaning":"Chest pain in a hyperglycemic crisis raises concern for myocardial infarction as the precipitant — diabetics can have silent or atypical ischemia. Get an ECG and troponin rather than attributing the pain to the metabolic derangement.","meaningSource":"ai-draft"},{"id":"history-12","system":"endocrine","question":"Have you lost weight without trying over the past few weeks?","listenFor":["No unintentional weight loss","Unintentional weight loss over recent weeks"],"why":null,"whySource":null,"meaning":"Unintentional weight loss over weeks alongside hyperglycemia points to prolonged insulin deficiency — classic for new-onset type 1 diabetes — and argues against a brief, reversible cause.","meaningSource":"ai-draft"},{"id":"history-13","system":"functional","question":"Have you had trouble affording or getting access to your insulin?","listenFor":["No barrier identified","Cost or access barrier","Intentional nonadherence"],"why":null,"whySource":null,"meaning":"Cost or access barriers to insulin are among the most common — and most fixable — drivers of DKA. Identifying the barrier changes the discharge plan from a lecture to a social-work referral, samples, or a cheaper regimen.","meaningSource":"ai-draft"},{"id":"history-14","system":"endocrine","question":"Have you had an episode like this before, where your blood sugar was dangerously high?","listenFor":["First episode","Recurrent episodes"],"why":null,"whySource":null,"meaning":"Recurrent episodes point to an ongoing driver — missed doses, pump failure, insulin omission in an eating disorder, or an unaddressed access barrier. The workup shifts from 'what happened this time' to 'what keeps happening,' and prevention becomes the intervention.","meaningSource":"ai-draft"}],"exam":[{"id":"exam-01","system":"neurologic","maneuver":"Assess mental status.","findings":["Alert and oriented","Lethargic","Obtunded or comatose"],"how":null,"why":null,"whySource":null,"meaning":"Mental status tracks severity: lethargy is expected in DKA, but obtundation or coma raises concern for hyperosmolar state, severe acidosis, or an alternate cause such as stroke or overdose. Reassess frequently — worsening mentation during treatment raises concern for cerebral edema.","meaningSource":"ai-draft"},{"id":"exam-02","system":"respiratory","maneuver":"Assess respiratory pattern for Kussmaul breathing.","findings":["Normal breathing pattern","Rapid, deep Kussmaul breathing"],"how":null,"why":"Rapid, deep Kussmaul breathing is respiratory compensation for severe metabolic acidosis, as in diabetic ketoacidosis.","whySource":"curated","meaning":"Rapid, deep Kussmaul breathing is respiratory compensation for severe metabolic acidosis, as in diabetic ketoacidosis.","meaningSource":"curated"},{"id":"exam-03","system":"ent","maneuver":"Assess breath odor for a fruity or acetone smell.","findings":["Absent","Present"],"how":null,"why":"A fruity or acetone breath odor suggests ketoacidosis.","whySource":"curated","meaning":"A fruity or acetone breath odor suggests ketoacidosis.","meaningSource":"curated"},{"id":"exam-04","system":"general","maneuver":"Assess hydration status.","findings":["Euvolemic","Dry mucous membranes or poor skin turgor","Severe dehydration with hypotension"],"how":null,"why":"Documenting volume status (hypovolemic, euvolemic, or hypervolemic) guides fluid management and helps distinguish prerenal, intrinsic, and volume-overload causes of kidney injury and electrolyte disturbances.","whySource":"curated","meaning":"Documenting volume status (hypovolemic, euvolemic, or hypervolemic) guides fluid management and helps distinguish prerenal, intrinsic, and volume-overload causes of kidney injury and electrolyte disturbances.","meaningSource":"curated"},{"id":"exam-05","system":"gastrointestinal","maneuver":"Palpate the abdomen for tenderness.","findings":["Nontender","Diffuse tenderness without peritoneal signs"],"how":null,"why":null,"whySource":null,"meaning":"Diffuse mild tenderness without guarding is common in DKA and should resolve with treatment. True peritoneal signs — guarding, rebound, rigidity — do not belong to DKA and demand a surgical evaluation.","meaningSource":"ai-draft"},{"id":"exam-06","system":"endocrine","maneuver":"Check fingerstick glucose.","findings":["Under 250 mg/dL","250 to 600 mg/dL","Over 600 mg/dL, suggesting hyperosmolar state"],"how":"Prick the side of the fingertip rather than the pad, and apply the blood drop to the test strip.","why":"Glucose over 600 mg/dL with altered mentation suggests hyperosmolar hyperglycemic state.","whySource":"curated","meaning":"Glucose over 600 mg/dL with altered mentation suggests hyperosmolar hyperglycemic state.","meaningSource":"curated"},{"id":"exam-07","system":"cardiovascular","maneuver":"Assess vital signs for tachycardia or hypotension.","findings":["Normal vital signs","Tachycardic","Hypotensive"],"how":null,"why":null,"whySource":null,"meaning":"Tachycardia and hypotension reflect the profound volume depletion of osmotic diuresis and guide how aggressively to resuscitate. Persistent hypotension after fluids should prompt a search for sepsis or another shock state.","meaningSource":"ai-draft"},{"id":"exam-08","system":"skin","maneuver":"Assess skin turgor.","findings":["Normal skin turgor","Poor turgor or tenting"],"how":null,"why":null,"whySource":null,"meaning":"Poor skin turgor or tenting confirms clinically significant dehydration from osmotic diuresis — a bedside gauge of how far behind on fluids the patient is, though it is less reliable in older adults.","meaningSource":"ai-draft"},{"id":"exam-09","system":"infectious","maneuver":"Examine for a focal infectious source.","findings":["No focal source identified","Focal source identified"],"how":null,"why":null,"whySource":null,"meaning":"A focused search for the infectious trigger — lungs, urine, skin and feet, lines, abdomen — is mandatory, because treating the hyperglycemia without the underlying infection leaves the precipitant in place.","meaningSource":"ai-draft"},{"id":"exam-10","system":"neurologic","maneuver":"Assess for a focal neurologic deficit or seizure activity, which can occur with hyperosmolar state.","findings":["No focal deficit or seizure","Focal neurologic deficit or seizure activity"],"how":null,"why":null,"whySource":null,"meaning":"Hyperosmolar state itself can produce focal deficits and seizures that mimic stroke — but do not assume the metabolic derangement explains everything. If deficits persist after initial treatment or the story fits a vascular event, image the brain.","meaningSource":"ai-draft"}],"reviewNeeded":{"whyMissing":15,"howMissing":9}},{"id":"acute-kidney-injury","title":"Acute kidney injury","aliases":["AKI","acute renal failure"],"history":[{"id":"history-01","system":"gastrointestinal","question":"Have you been eating and drinking normally, or have you had vomiting or diarrhea?","listenFor":["Normal oral intake","Poor oral intake","Vomiting or diarrhea"],"why":null,"whySource":null,"meaning":"Vomiting, diarrhea, or poor intake points to volume depletion — the most common and most reversible cause of AKI (prerenal). A positive answer should prompt volume assessment and a fluid challenge when appropriate, plus review of diuretics.","meaningSource":"ai-draft"},{"id":"history-02","system":"genitourinary","question":"Have you noticed a change in how much you're urinating?","listenFor":["Normal urine output","Decreased urine output","No urine output"],"why":"Decreased urine output suggests volume depletion or acute kidney injury.","whySource":"curated","meaning":"Decreased urine output suggests volume depletion or acute kidney injury.","meaningSource":"curated"},{"id":"history-03","system":"cardiovascular","question":"Do you have heart failure or cirrhosis?","listenFor":["Neither","Known heart failure","Known cirrhosis"],"why":null,"whySource":null,"meaning":"Heart failure causes AKI through poor forward perfusion plus renal venous congestion (cardiorenal syndrome), while cirrhosis predisposes to hepatorenal physiology — both mimic simple dehydration but need disease-specific management rather than fluids alone. Knowing these comorbidities reframes the entire AKI workup.","meaningSource":"ai-draft"},{"id":"history-04","system":"medication","question":"Have you taken any ibuprofen, naproxen, or other NSAID pain relievers recently?","listenFor":["No recent NSAID use","Recent NSAID use"],"why":"NSAIDs reduce renal perfusion and promote sodium and water retention, worsening kidney function, heart failure, and potassium excretion.","whySource":"curated","meaning":"NSAIDs reduce renal perfusion and promote sodium and water retention, worsening kidney function, heart failure, and potassium excretion.","meaningSource":"curated"},{"id":"history-05","system":"medication","question":"Do you take a blood pressure medication ending in -pril or -sartan, or a water pill?","listenFor":["None of these","ACE inhibitor or ARB use","Diuretic use"],"why":null,"whySource":null,"meaning":"ACE inhibitors, ARBs, and diuretics are the classic medication precipitants — they lower intraglomerular pressure, which becomes dangerous during volume depletion or with bilateral renal artery stenosis. A positive answer means holding or adjusting these drugs and reviewing the full nephrotoxin list (NSAIDs, contrast).","meaningSource":"ai-draft"},{"id":"history-06","system":"medication","question":"Have you had a CT scan or other imaging test with contrast dye recently?","listenFor":["No recent contrast administration","Recent intravenous contrast administration"],"why":"Intravenous contrast can precipitate acute kidney injury, especially with volume depletion.","whySource":"curated","meaning":"Intravenous contrast can precipitate acute kidney injury, especially with volume depletion.","meaningSource":"curated"},{"id":"history-07","system":"medication","question":"Have you started a new antibiotic recently, along with a rash or fever?","listenFor":["No new antibiotic with rash or fever","New antibiotic with rash or fever"],"why":"A new antibiotic with rash or fever suggests acute interstitial nephritis.","whySource":"curated","meaning":"A new antibiotic with rash or fever suggests acute interstitial nephritis.","meaningSource":"curated"},{"id":"history-08","system":"genitourinary","question":"Have you had trouble starting your stream or noticed it's weaker than usual, or do you have an enlarged prostate, stones, or a bladder condition?","listenFor":["No voiding difficulty","Difficulty voiding or weak stream","Known benign prostatic hyperplasia, stones, or neurogenic bladder"],"why":"Difficulty voiding or a weak stream suggests obstructive uropathy.","whySource":"curated","meaning":"Difficulty voiding or a weak stream suggests obstructive uropathy.","meaningSource":"curated"},{"id":"history-09","system":"genitourinary","question":"Do you have a urinary catheter, and has it been draining normally?","listenFor":["No catheter","Catheter present, functioning normally","Catheter present, concern for blockage"],"why":"A blocked urinary catheter causes obstructive kidney injury.","whySource":"curated","meaning":"A blocked urinary catheter causes obstructive kidney injury.","meaningSource":"curated"},{"id":"history-10","system":"musculoskeletal","question":"Have you had significant muscle pain, or has your urine looked dark like tea or cola?","listenFor":["Neither","Muscle pain","Dark, tea-colored urine"],"why":"Dark tea-colored urine with muscle pain or after crush injury suggests rhabdomyolysis with myoglobinuria.","whySource":"curated","meaning":"Dark tea-colored urine with muscle pain or after crush injury suggests rhabdomyolysis with myoglobinuria.","meaningSource":"curated"},{"id":"history-11","system":"musculoskeletal","question":"Were you stuck in one position for a long time, down on the floor for a while after a fall, or crushed under something heavy?","listenFor":["None of these","Prolonged immobilization or extended down time after a fall","Crush injury"],"why":"Crush injury releases myoglobin that can precipitate acute kidney injury.","whySource":"curated","meaning":"Crush injury releases myoglobin that can precipitate acute kidney injury.","meaningSource":"curated"},{"id":"history-12","system":"genitourinary","question":"Have you seen blood in your urine, or noticed new swelling or high blood pressure?","listenFor":["None of these","Hematuria","New edema and hypertension"],"why":"Hematuria with new edema and hypertension suggests glomerulonephritis.","whySource":"curated","meaning":"Hematuria with new edema and hypertension suggests glomerulonephritis.","meaningSource":"curated"},{"id":"history-13","system":"genitourinary","question":"Do you have chronic kidney disease, and has your kidney function been stable or worsening lately?","listenFor":["No known chronic kidney disease","Known chronic kidney disease, stable baseline","Known chronic kidney disease with a recent creatinine increase"],"why":null,"whySource":null,"meaning":"Knowing the baseline creatinine separates acute injury from chronic disease — a recent rise on known CKD means an acute, potentially reversible insult superimposed on limited reserve and deserves the full AKI workup. Without a baseline, compare to prior records before labeling it acute.","meaningSource":"ai-draft"},{"id":"history-14","system":"cardiovascular","question":"Have you had an episode of very low blood pressure recently, or lost a significant amount of blood?","listenFor":["Neither","Recent hypotensive episode","Recent significant blood loss"],"why":"A recent hypotensive episode suggests significant volume loss or shock.","whySource":"curated","meaning":"A recent hypotensive episode suggests significant volume loss or shock.","meaningSource":"curated"}],"exam":[{"id":"exam-01","system":"general","maneuver":"Assess overall volume status.","findings":["Euvolemic","Hypovolemic, with dry mucous membranes or poor turgor","Hypervolemic, with edema or elevated jugular venous pressure"],"how":"With the patient reclined at 30 to 45 degrees, identify the highest point of internal jugular venous pulsation and measure its vertical distance above the sternal angle.","why":"Documenting volume status (hypovolemic, euvolemic, or hypervolemic) guides fluid management and helps distinguish prerenal, intrinsic, and volume-overload causes of kidney injury and electrolyte disturbances.","whySource":"curated","meaning":"Documenting volume status (hypovolemic, euvolemic, or hypervolemic) guides fluid management and helps distinguish prerenal, intrinsic, and volume-overload causes of kidney injury and electrolyte disturbances.","meaningSource":"curated"},{"id":"exam-02","system":"cardiovascular","maneuver":"Assess jugular venous pressure.","findings":["Normal jugular venous pressure","Elevated jugular venous pressure"],"how":"With the patient reclined at 30 to 45 degrees, identify the highest point of internal jugular venous pulsation and measure its vertical distance above the sternal angle.","why":"Elevated jugular venous pressure reflects elevated right-sided filling pressures, seen in right heart failure, volume overload, or tamponade.","whySource":"curated","meaning":"Elevated jugular venous pressure reflects elevated right-sided filling pressures, seen in right heart failure, volume overload, or tamponade.","meaningSource":"curated"},{"id":"exam-03","system":"cardiovascular","maneuver":"Inspect and palpate the lower extremities for edema.","findings":["No peripheral edema","Peripheral edema present"],"how":null,"why":null,"whySource":null,"meaning":"Peripheral edema argues against simple volume depletion and points toward cardiorenal syndrome, nephrotic-range protein loss, or over-resuscitation — which flips management from fluids toward diuresis. Its absence keeps prerenal hypovolemia on the table.","meaningSource":"ai-draft"},{"id":"exam-04","system":"genitourinary","maneuver":"Assess for bladder distention.","findings":["Nondistended","Distended, palpable bladder"],"how":null,"why":"A distended, palpable bladder indicates urinary retention.","whySource":"curated","meaning":"A distended, palpable bladder indicates urinary retention.","meaningSource":"curated"},{"id":"exam-05","system":"genitourinary","maneuver":"Assess for costovertebral-angle tenderness.","findings":["None","Unilateral costovertebral-angle tenderness","Bilateral costovertebral-angle tenderness"],"how":null,"why":"Costovertebral angle tenderness suggests pyelonephritis.","whySource":"curated","meaning":"Costovertebral angle tenderness suggests pyelonephritis.","meaningSource":"curated"},{"id":"exam-06","system":"skin","maneuver":"Inspect the skin for a new rash.","findings":["No new rash","New rash present"],"how":null,"why":null,"whySource":null,"meaning":"A new rash with AKI points to acute interstitial nephritis (often drug-induced — antibiotics, PPIs, NSAIDs), vasculitis, or atheroembolic disease rather than simple prerenal causes. A positive finding should trigger a medication review and nephrology input, since drug withdrawal or steroids may be indicated.","meaningSource":"ai-draft"},{"id":"exam-07","system":"musculoskeletal","maneuver":"Palpate muscle groups for focal tenderness or swelling suggesting rhabdomyolysis.","findings":["No focal muscle tenderness or swelling","Focal muscle tenderness or swelling"],"how":null,"why":null,"whySource":null,"meaning":"Focal muscle tenderness or swelling suggests rhabdomyolysis — from crush injury, prolonged immobility, statins, or seizures — whose myoglobin injures renal tubules. A positive finding should prompt a CK level and aggressive volume resuscitation, which is the mainstay of prevention.","meaningSource":"ai-draft"},{"id":"exam-08","system":"cardiovascular","maneuver":"Assess orthostatic vital signs when safe.","findings":["Negative orthostatics","Positive orthostatic hypotension"],"how":"Measure blood pressure and heart rate after 5 minutes supine, then at 1 and 3 minutes after standing; a sustained drop of 20 mmHg systolic or 10 mmHg diastolic within 3 minutes is positive.","why":null,"whySource":null,"meaning":"Positive orthostatics (a sustained 20/10 mmHg drop within 3 minutes of standing) support volume depletion as the prerenal driver of the AKI, pointing toward fluid repletion. Negative orthostatics don't exclude hypovolemia but push toward intrinsic or postrenal causes.","meaningSource":"ai-draft"},{"id":"exam-09","system":"gastrointestinal","maneuver":"Assess for ascites or jaundice suggesting hepatorenal physiology.","findings":["Neither","Ascites","Jaundice"],"how":null,"why":null,"whySource":null,"meaning":"Ascites or jaundice with AKI suggests hepatorenal physiology — severe liver disease causing renal vasoconstriction — which needs albumin plus vasoconstrictor therapy and hepatology input rather than fluids alone. This pattern carries a poor prognosis and changes goals-of-care conversations.","meaningSource":"ai-draft"},{"id":"exam-10","system":"genitourinary","maneuver":"Assess urine output, by catheter if placed.","findings":["Adequate urine output","Minimal or absent output despite a functioning catheter"],"how":null,"why":"Minimal output despite a functioning catheter indicates intrinsic or prerenal failure rather than obstruction.","whySource":"curated","meaning":"Minimal output despite a functioning catheter indicates intrinsic or prerenal failure rather than obstruction.","meaningSource":"curated"}],"reviewNeeded":{"whyMissing":9,"howMissing":7}},{"id":"upper-gastrointestinal-bleeding","title":"Gastrointestinal bleeding (upper)","aliases":["upper GI bleed","hematemesis"],"history":[{"id":"history-01","system":"hematologic","question":"Have you vomited anything that looked like blood or coffee grounds?","listenFor":["No hematemesis","Coffee-ground emesis","Bright red blood hematemesis"],"why":"Bright red hematemesis suggests brisk, active upper gastrointestinal bleeding.","whySource":"curated","meaning":"Bright red hematemesis suggests brisk, active upper gastrointestinal bleeding.","meaningSource":"curated"},{"id":"history-02","system":"hematologic","question":"Have your stools been black and tarry?","listenFor":["No melena","Melena"],"why":"Melena (black, tarry stools) indicates upper gastrointestinal bleeding.","whySource":"curated","meaning":"Melena (black, tarry stools) indicates upper gastrointestinal bleeding.","meaningSource":"curated"},{"id":"history-03","system":"medication","question":"Do you regularly take ibuprofen or another NSAID, or aspirin?","listenFor":["Neither","NSAID use","Aspirin or antiplatelet use"],"why":"NSAIDs and aspirin impair gastric mucosal protection and platelet function, raising gastrointestinal bleeding risk.","whySource":"curated","meaning":"NSAIDs and aspirin impair gastric mucosal protection and platelet function, raising gastrointestinal bleeding risk.","meaningSource":"curated"},{"id":"history-04","system":"medication","question":"Are you on a blood thinner?","listenFor":["No anticoagulant use","Anticoagulant use"],"why":"Blood thinner use increases bleeding risk and severity, and affects reversal decisions.","whySource":"curated","meaning":"Blood thinner use increases bleeding risk and severity, and affects reversal decisions.","meaningSource":"curated"},{"id":"history-05","system":"gastrointestinal","question":"Do you have cirrhosis or known varices in your esophagus?","listenFor":["Neither","Known cirrhosis","Known esophageal varices"],"why":"Esophageal varices can cause massive, life-threatening upper gastrointestinal bleeding.","whySource":"curated","meaning":"Esophageal varices can cause massive, life-threatening upper gastrointestinal bleeding.","meaningSource":"curated"},{"id":"history-06","system":"medication","question":"Do you drink alcohol heavily?","listenFor":["No heavy alcohol use","Heavy alcohol use"],"why":null,"whySource":null,"meaning":"Heavy alcohol use raises the likelihood of variceal bleeding from portal hypertension and of alcoholic liver disease with coagulopathy; it also warns that standard risk scores and platelet/INR values must be interpreted in the context of liver dysfunction.","meaningSource":"ai-draft"},{"id":"history-07","system":"gastrointestinal","question":"Did you have forceful retching or vomiting right before you noticed the blood?","listenFor":["No preceding retching or vomiting","Forceful retching or vomiting preceded the bleeding"],"why":"Forceful retching before hematemesis suggests a Mallory-Weiss tear.","whySource":"curated","meaning":"Forceful retching before hematemesis suggests a Mallory-Weiss tear.","meaningSource":"curated"},{"id":"history-08","system":"gastrointestinal","question":"Have you been diagnosed with a stomach ulcer or an H. pylori infection?","listenFor":["Neither","Known peptic ulcer disease","Known Helicobacter pylori infection"],"why":null,"whySource":null,"meaning":"Known peptic ulcer disease or H. pylori infection makes an ulcer the leading source of the bleed, which guides both resuscitation expectations and the decision to test for and treat H. pylori after the acute episode; neither history keeps variceal or malignant sources off the table.","meaningSource":"ai-draft"},{"id":"history-09","system":"hematologic","question":"Have you been diagnosed with a cancer of the stomach or esophagus?","listenFor":["No known malignancy","Known upper gastrointestinal malignancy"],"why":null,"whySource":null,"meaning":"A known stomach or esophageal cancer makes a malignant tumor the likely bleeding source, which changes prognosis and may alter decisions about aggressive endoscopic intervention; no known malignancy keeps the usual ulcer and variceal sources at the top of the differential.","meaningSource":"ai-draft"},{"id":"history-10","system":"cardiovascular","question":"Have you had surgery on your aorta, like a graft or aneurysm repair?","listenFor":["No known aortic graft or repair","Known prior aortic graft or aneurysm repair"],"why":"A prior aortic graft raises concern for aortoenteric fistula, a rare but lethal cause of bleeding.","whySource":"curated","meaning":"A prior aortic graft raises concern for aortoenteric fistula, a rare but lethal cause of bleeding.","meaningSource":"curated"},{"id":"history-11","system":"gastrointestinal","question":"Do you have trouble swallowing?","listenFor":["No dysphagia","Dysphagia"],"why":null,"whySource":null,"meaning":"Dysphagia alongside bleeding points toward an esophageal source — stricture, cancer, or severe esophagitis — rather than a simple gastric or duodenal ulcer; it also flags a possible malignant process and a higher-risk airway during endoscopy.","meaningSource":"ai-draft"},{"id":"history-12","system":"gastrointestinal","question":"Have you lost weight without trying?","listenFor":["No unintentional weight loss","Unintentional weight loss"],"why":null,"whySource":null,"meaning":"Unintentional weight loss suggests a malignant cause of the bleed rather than a benign ulcer or variceal source; it should prompt a post-stabilization cancer workup rather than closing the case at ulcer management.","meaningSource":"ai-draft"},{"id":"history-13","system":"neurologic","question":"Have you felt like you were going to pass out, or did you actually pass out with this bleeding?","listenFor":["Neither","Presyncope","Syncope"],"why":null,"whySource":null,"meaning":"Presyncope or syncope with the bleed signals significant blood loss and poor cerebral perfusion — a marker of severity that predicts worse outcomes and pushes toward urgent resuscitation and expedited endoscopy; absence of these symptoms suggests a milder bleed so far.","meaningSource":"ai-draft"},{"id":"history-14","system":"gastrointestinal","question":"Do you have pain in your upper belly along with the bleeding?","listenFor":["No epigastric pain","Epigastric pain"],"why":null,"whySource":null,"meaning":"Epigastric pain with the bleed favors a peptic ulcer as the source, while painless bleeding is more typical of varices or a malignant source; either way, pain does not rule any source out, but it refines the pre-endoscopy likelihood.","meaningSource":"ai-draft"}],"exam":[{"id":"exam-01","system":"cardiovascular","maneuver":"Assess hemodynamic stability.","findings":["Normotensive, stable","Tachycardic","Hypotensive or in shock"],"how":null,"why":null,"whySource":null,"meaning":"Tachycardia and hypotension quantify how much blood has been lost and dictate the pace of resuscitation — tachycardia alone suggests significant ongoing loss, and hypotension or shock means the patient is decompensating and needs immediate large-bore access, transfusion, and urgent endoscopy; stable vitals allow a more measured approach.","meaningSource":"ai-draft"},{"id":"exam-02","system":"cardiovascular","maneuver":"Assess orthostatic vital signs when safe.","findings":["Negative orthostatics","Positive orthostatic hypotension"],"how":"Measure blood pressure and heart rate after 5 minutes supine, then at 1 and 3 minutes after standing; a sustained drop of 20 mmHg systolic or 10 mmHg diastolic within 3 minutes is positive.","why":null,"whySource":null,"meaning":"Positive orthostatics reveal clinically significant volume loss even when resting vitals look normal, since young patients compensate until they crash; they support a moderate-to-severe bleed requiring aggressive resuscitation, while negative orthostatics suggest a smaller or already-compensated loss — skip the test entirely if the patient is unstable.","meaningSource":"ai-draft"},{"id":"exam-03","system":"hematologic","maneuver":"Inspect conjunctiva and nail beds for pallor.","findings":["Normal color","Conjunctival or nail-bed pallor"],"how":null,"why":"Pallor of the conjunctivae, nail beds, or palmar creases suggests anemia.","whySource":"curated","meaning":"Pallor of the conjunctivae, nail beds, or palmar creases suggests anemia.","meaningSource":"curated"},{"id":"exam-04","system":"gastrointestinal","maneuver":"Palpate the abdomen for tenderness.","findings":["Nontender","Epigastric tenderness","Diffuse tenderness with peritoneal signs"],"how":null,"why":null,"whySource":null,"meaning":"Abdominal palpation looks for the source and for complications: epigastric tenderness supports an ulcer, while diffuse tenderness with peritoneal signs suggests perforation of an ulcer — a surgical emergency that changes the plan from endoscopy to surgical consultation; a nontender abdomen is typical of variceal bleeding.","meaningSource":"ai-draft"},{"id":"exam-05","system":"skin","maneuver":"Inspect for stigmata of chronic liver disease.","findings":["No stigmata of liver disease","Spider angiomata or palmar erythema","Jaundice"],"how":null,"why":"Spider angiomas, palmar erythema, and caput medusae are cutaneous stigmata of chronic liver disease.","whySource":"curated","meaning":"Spider angiomas, palmar erythema, and caput medusae are cutaneous stigmata of chronic liver disease.","meaningSource":"curated"},{"id":"exam-06","system":"gastrointestinal","maneuver":"Assess the abdomen for ascites or splenomegaly.","findings":["Neither","Ascites","Splenomegaly"],"how":null,"why":"Splenomegaly suggests portal hypertension, hematologic disease, or systemic infection.","whySource":"curated","meaning":"Splenomegaly suggests portal hypertension, hematologic disease, or systemic infection.","meaningSource":"curated"},{"id":"exam-07","system":"gastrointestinal","maneuver":"Perform a rectal examination.","findings":["Normal, guaiac negative, or deferred as not indicated","Melena on examination","Bright red blood on examination"],"how":null,"why":"Melena (black, tarry stools) indicates upper gastrointestinal bleeding.","whySource":"curated","meaning":"Melena (black, tarry stools) indicates upper gastrointestinal bleeding.","meaningSource":"curated"},{"id":"exam-08","system":"neurologic","maneuver":"Assess mental status.","findings":["Alert and oriented","Confused or altered"],"how":null,"why":null,"whySource":null,"meaning":"Altered mental status during a bleed indicates cerebral hypoperfusion from severe blood loss — or hepatic encephalopathy in a patient with liver disease — and marks the bleed as life-threatening; it demands immediate resuscitation and airway protection, not further history-taking.","meaningSource":"ai-draft"},{"id":"exam-09","system":"gastrointestinal","maneuver":"Assess nasogastric aspirate, if placed.","findings":["Not performed or clear aspirate","Coffee-ground aspirate","Bright red blood aspirate"],"how":null,"why":"Coffee-ground emesis suggests upper gastrointestinal bleeding with blood partially digested by stomach acid.","whySource":"curated","meaning":"Coffee-ground emesis suggests upper gastrointestinal bleeding with blood partially digested by stomach acid.","meaningSource":"curated"},{"id":"exam-10","system":"skin","maneuver":"Inspect skin and mucosa for bleeding suggesting coagulopathy.","findings":["No ecchymosis or petechiae","Ecchymosis or petechiae present"],"how":null,"why":"Petechiae or ecchymosis suggest thrombocytopenia or another bleeding diathesis.","whySource":"curated","meaning":"Petechiae or ecchymosis suggest thrombocytopenia or another bleeding diathesis.","meaningSource":"curated"}],"reviewNeeded":{"whyMissing":11,"howMissing":9}},{"id":"lower-gastrointestinal-bleeding","title":"Gastrointestinal bleeding (lower)","aliases":["lower GI bleed","hematochezia"],"history":[{"id":"history-01","system":"hematologic","question":"What did the blood from your rectum look like — bright red, or dark maroon?","listenFor":["No rectal bleeding","Bright red blood per rectum","Dark maroon stool"],"why":"Bright red blood per rectum suggests a lower gastrointestinal or anorectal source.","whySource":"curated","meaning":"Bright red blood per rectum suggests a lower gastrointestinal or anorectal source.","meaningSource":"curated"},{"id":"history-02","system":"hematologic","question":"Was the blood only on the toilet paper, coating the outside of the stool, or mixed throughout it?","listenFor":["Blood on toilet paper only","Blood coating the outside of the stool","Blood mixed within the stool"],"why":"Blood mixed within the stool suggests a more proximal colonic source; blood only on toilet paper suggests an anorectal source.","whySource":"curated","meaning":"Blood mixed within the stool suggests a more proximal colonic source; blood only on toilet paper suggests an anorectal source.","meaningSource":"curated"},{"id":"history-03","system":"gastrointestinal","question":"Is the bleeding painful, or painless?","listenFor":["Painless bleeding","Painful bleeding with defecation"],"why":"Painful bleeding with defecation suggests an anal fissure or thrombosed hemorrhoid.","whySource":"curated","meaning":"Painful bleeding with defecation suggests an anal fissure or thrombosed hemorrhoid.","meaningSource":"curated"},{"id":"history-04","system":"medication","question":"Are you on a blood thinner?","listenFor":["No anticoagulant use","Anticoagulant use"],"why":"Blood thinner use increases bleeding risk and severity, and affects reversal decisions.","whySource":"curated","meaning":"Blood thinner use increases bleeding risk and severity, and affects reversal decisions.","meaningSource":"curated"},{"id":"history-05","system":"medication","question":"Do you regularly take ibuprofen or another NSAID, or aspirin?","listenFor":["Neither","NSAID use","Aspirin or antiplatelet use"],"why":"NSAIDs and aspirin impair gastric mucosal protection and platelet function, raising gastrointestinal bleeding risk.","whySource":"curated","meaning":"NSAIDs and aspirin impair gastric mucosal protection and platelet function, raising gastrointestinal bleeding risk.","meaningSource":"curated"},{"id":"history-06","system":"gastrointestinal","question":"Have you been told you have diverticulosis?","listenFor":["No known diverticulosis","Known diverticulosis"],"why":"Diverticulosis is the most common cause of brisk painless lower gastrointestinal bleeding in older adults.","whySource":"curated","meaning":"Diverticulosis is the most common cause of brisk painless lower gastrointestinal bleeding in older adults.","meaningSource":"curated"},{"id":"history-07","system":"gastrointestinal","question":"Do you have inflammatory bowel disease, like Crohn's or ulcerative colitis?","listenFor":["No known inflammatory bowel disease","Known inflammatory bowel disease"],"why":null,"whySource":null,"meaning":"Inflammatory bowel disease is a leading cause of lower gastrointestinal bleeding in younger patients; an IBD flare bleeds from inflamed mucosa and may need anti-inflammatory treatment rather than just transfusion.","meaningSource":"ai-draft"},{"id":"history-08","system":"medication","question":"Have you had a colonoscopy or polyp removed recently?","listenFor":["No recent colonoscopy or polypectomy","Recent colonoscopy or polypectomy"],"why":"Recent polypectomy can cause delayed post-procedure bleeding.","whySource":"curated","meaning":"Recent polypectomy can cause delayed post-procedure bleeding.","meaningSource":"curated"},{"id":"history-09","system":"hematologic","question":"Have you been diagnosed with colon cancer, or does anyone in your family have a history of colon cancer?","listenFor":["Neither","Known colorectal malignancy","Family history of colorectal cancer"],"why":null,"whySource":null,"meaning":"Known colorectal cancer raises malignancy as the bleeding source and changes the urgency and planning of endoscopic evaluation; a family history raises concern for hereditary cancer syndromes and earlier, more aggressive investigation.","meaningSource":"ai-draft"},{"id":"history-10","system":"gastrointestinal","question":"Have your bowel habits changed recently, or has the shape of your stool gotten narrower?","listenFor":["No change in bowel habits","Change in bowel habits or stool caliber"],"why":"Change in bowel habits or narrowing stool caliber raises concern for colorectal malignancy.","whySource":"curated","meaning":"Change in bowel habits or narrowing stool caliber raises concern for colorectal malignancy.","meaningSource":"curated"},{"id":"history-11","system":"cardiovascular","question":"Have you had an episode of very low blood pressure recently?","listenFor":["No recent hypotensive episode","Recent hypotensive episode"],"why":"A recent hypotensive episode suggests significant volume loss or shock.","whySource":"curated","meaning":"A recent hypotensive episode suggests significant volume loss or shock.","meaningSource":"curated"},{"id":"history-12","system":"gastrointestinal","question":"Have you ever had radiation therapy to your pelvis?","listenFor":["No prior pelvic radiation therapy","Prior pelvic radiation therapy"],"why":"Prior pelvic radiation can cause radiation proctitis with bleeding.","whySource":"curated","meaning":"Prior pelvic radiation can cause radiation proctitis with bleeding.","meaningSource":"curated"},{"id":"history-13","system":"neurologic","question":"Have you felt like you were going to pass out, or did you actually pass out with this bleeding?","listenFor":["Neither","Presyncope","Syncope"],"why":null,"whySource":null,"meaning":"Presyncope or syncope with bleeding indicates significant blood loss and cerebral hypoperfusion — marking a severe bleed that needs resuscitation, transfusion consideration, and urgent gastroenterology or surgical involvement.","meaningSource":"ai-draft"},{"id":"history-14","system":"infectious","question":"Have you had diarrhea or a fever along with the bleeding?","listenFor":["Neither","Diarrhea","Fever"],"why":null,"whySource":null,"meaning":"Bloody diarrhea with fever points toward infectious or inflammatory colitis rather than diverticular or hemorrhoidal bleeding — directing the workup to stool studies and inflammatory markers instead of only looking for a bleeding vessel.","meaningSource":"ai-draft"}],"exam":[{"id":"exam-01","system":"cardiovascular","maneuver":"Assess hemodynamic stability.","findings":["Normotensive, stable","Tachycardic","Hypotensive or in shock"],"how":null,"why":null,"whySource":null,"meaning":"Hemodynamic instability — tachycardia progressing to hypotension — quantifies bleed severity: shock triggers massive transfusion protocol and ICU-level care, while stable vitals allow a more measured diagnostic workup.","meaningSource":"ai-draft"},{"id":"exam-02","system":"cardiovascular","maneuver":"Assess orthostatic vital signs when safe.","findings":["Negative orthostatics","Positive orthostatic hypotension"],"how":"Measure blood pressure and heart rate after 5 minutes supine, then at 1 and 3 minutes after standing; a sustained drop of 20 mmHg systolic or 10 mmHg diastolic within 3 minutes is positive.","why":null,"whySource":null,"meaning":"Positive orthostatics uncover volume depletion not apparent while supine, helping estimate blood loss severity and guiding fluid resuscitation before vitals deteriorate at rest.","meaningSource":"ai-draft"},{"id":"exam-03","system":"hematologic","maneuver":"Inspect conjunctiva and nail beds for pallor.","findings":["Normal color","Conjunctival or nail-bed pallor"],"how":null,"why":"Pallor of the conjunctivae, nail beds, or palmar creases suggests anemia.","whySource":"curated","meaning":"Pallor of the conjunctivae, nail beds, or palmar creases suggests anemia.","meaningSource":"curated"},{"id":"exam-04","system":"gastrointestinal","maneuver":"Palpate the abdomen for tenderness.","findings":["Nontender","Focal tenderness","Diffuse tenderness with peritoneal signs"],"how":null,"why":null,"whySource":null,"meaning":"Peritoneal signs with gastrointestinal bleeding raise concern for ischemic colitis, perforation, or severe inflammatory colitis — surgical considerations — while focal tenderness can localize the source (e.g., diverticular disease).","meaningSource":"ai-draft"},{"id":"exam-05","system":"gastrointestinal","maneuver":"Inspect the perianal area.","findings":["Normal appearance","Visible hemorrhoids","Anal fissure"],"how":null,"why":"Visible hemorrhoids are a common cause of bright red blood on toilet paper.","whySource":"curated","meaning":"Visible hemorrhoids are a common cause of bright red blood on toilet paper.","meaningSource":"curated"},{"id":"exam-06","system":"gastrointestinal","maneuver":"Perform a rectal examination.","findings":["Normal or deferred as not indicated","Gross blood on examination","Palpable mass on examination"],"how":null,"why":null,"whySource":null,"meaning":"The rectal exam confirms the blood is truly rectal (not vaginal or urethral), characterizes the stool (bright red blood versus melena), and a palpable mass raises concern for rectal malignancy.","meaningSource":"ai-draft"},{"id":"exam-07","system":"gastrointestinal","maneuver":"Assess stool color and character.","findings":["Normal brown stool","Bright red blood","Maroon stool or melena"],"how":null,"why":"Melena (black, tarry stools) indicates upper gastrointestinal bleeding.","whySource":"curated","meaning":"Melena (black, tarry stools) indicates upper gastrointestinal bleeding.","meaningSource":"curated"},{"id":"exam-08","system":"neurologic","maneuver":"Assess mental status.","findings":["Alert and oriented","Confused or altered"],"how":null,"why":null,"whySource":null,"meaning":"Confusion or altered mental status reflects cerebral hypoperfusion from blood loss — a severity marker indicating shock even when blood pressure has not yet fallen.","meaningSource":"ai-draft"},{"id":"exam-09","system":"skin","maneuver":"Inspect skin and mucosa for bleeding suggesting coagulopathy.","findings":["No ecchymosis or petechiae","Ecchymosis or petechiae present"],"how":null,"why":"Petechiae or ecchymosis suggest thrombocytopenia or another bleeding diathesis.","whySource":"curated","meaning":"Petechiae or ecchymosis suggest thrombocytopenia or another bleeding diathesis.","meaningSource":"curated"},{"id":"exam-10","system":"gastrointestinal","maneuver":"Assess for abdominal distention.","findings":["No distention","Distention present"],"how":null,"why":null,"whySource":null,"meaning":"Abdominal distention with bleeding raises concern for obstruction, toxic megacolon, or a large intraluminal blood load — each of which changes management beyond simple resuscitation.","meaningSource":"ai-draft"}],"reviewNeeded":{"whyMissing":10,"howMissing":9}},{"id":"hyponatremia","title":"Electrolyte abnormality – hyponatremia","aliases":["low sodium","SIADH"],"history":[{"id":"history-01","system":"general","question":"Have you felt unusually thirsty or dizzy, or noticed swelling or shortness of breath?","listenFor":["No symptoms of volume depletion or overload","Thirst or dizziness suggesting hypovolemia","Edema or dyspnea suggesting volume overload"],"why":null,"whySource":null,"meaning":"Volume status is the key branch point in hyponatremia: thirst, dizziness, and orthostasis suggest hypovolemia (treated with isotonic saline), while edema, dyspnea, and crackles suggest hypervolemia from heart failure, cirrhosis, or nephrosis (treated with fluid restriction and diuresis). Euvolemia points instead to SIADH, adrenal insufficiency, or hypothyroidism.","meaningSource":"ai-draft"},{"id":"history-02","system":"medication","question":"Are you taking a water pill, and if so, do you know which kind?","listenFor":["No diuretic use","Thiazide diuretic use","Loop diuretic use"],"why":"Thiazide diuretics are a common cause of hyponatremia.","whySource":"curated","meaning":"Thiazide diuretics are a common cause of hyponatremia.","meaningSource":"curated"},{"id":"history-03","system":"gastrointestinal","question":"Have you had vomiting or diarrhea recently?","listenFor":["Neither","Vomiting","Diarrhea"],"why":null,"whySource":null,"meaning":"Vomiting or diarrhea causes hypovolemic hyponatremia through combined sodium and water loss with ADH-driven water retention — volume repletion with isotonic saline is the treatment. Without GI losses, look to medications (especially thiazides), adrenal causes, or SIADH.","meaningSource":"ai-draft"},{"id":"history-04","system":"endocrine","question":"Have you been drinking an unusually large amount of water or other fluids?","listenFor":["No excessive fluid intake","Excessive water or fluid intake"],"why":"Excessive water intake can cause dilutional hyponatremia.","whySource":"curated","meaning":"Excessive water intake can cause dilutional hyponatremia.","meaningSource":"curated"},{"id":"history-05","system":"medication","question":"Are you taking an antidepressant or a seizure medication like carbamazepine?","listenFor":["No SIADH-associated medication","Currently taking an SIADH-associated medication"],"why":"Antidepressants and carbamazepine can cause SIADH with hyponatremia.","whySource":"curated","meaning":"Antidepressants and carbamazepine can cause SIADH with hyponatremia.","meaningSource":"curated"},{"id":"history-06","system":"hematologic","question":"Have you been diagnosed with cancer, particularly lung cancer?","listenFor":["No known malignancy","Known malignancy other than lung cancer","Known lung cancer"],"why":"Lung cancer can cause SIADH with hyponatremia.","whySource":"curated","meaning":"Lung cancer can cause SIADH with hyponatremia.","meaningSource":"curated"},{"id":"history-07","system":"endocrine","question":"Have you lost weight without trying, or noticed new darkening of your skin?","listenFor":["No adrenal insufficiency symptoms","Fatigue and unintentional weight loss","New skin darkening"],"why":null,"whySource":null,"meaning":"Unintentional weight loss with new skin hyperpigmentation suggests primary adrenal insufficiency, which causes hyponatremia through cortisol and aldosterone deficiency. Adrenal crisis is life-threatening and treated with stress-dose steroids — check a morning cortisol and ACTH rather than attributing the sodium to another cause.","meaningSource":"ai-draft"},{"id":"history-08","system":"endocrine","question":"Have you felt unusually cold, gained weight, or become more constipated than usual?","listenFor":["No hypothyroid symptoms","Cold intolerance","Weight gain or constipation"],"why":"Cold intolerance with weight gain and constipation suggests hypothyroidism.","whySource":"curated","meaning":"Cold intolerance with weight gain and constipation suggests hypothyroidism.","meaningSource":"curated"},{"id":"history-09","system":"cardiovascular","question":"Do you have heart failure, cirrhosis, or a kidney condition called nephrotic syndrome?","listenFor":["None of these","Known heart failure","Known cirrhosis or nephrotic syndrome"],"why":null,"whySource":null,"meaning":"Heart failure, cirrhosis, and nephrotic syndrome are the classic hypervolemic causes of hyponatremia, driven by arterial underfilling and ADH release; identifying one directs treatment at the underlying disease plus fluid restriction. Absent all three, SIADH or adrenal/thyroid disease becomes more likely.","meaningSource":"ai-draft"},{"id":"history-10","system":"neurologic","question":"Have you had a headache, nausea, or confusion along with this?","listenFor":["None of these","Headache or nausea","Confusion or lethargy"],"why":"Headache, nausea, confusion, or seizures indicate severe symptomatic hyponatremia needing urgent treatment.","whySource":"curated","meaning":"Headache, nausea, confusion, or seizures indicate severe symptomatic hyponatremia needing urgent treatment.","meaningSource":"curated"},{"id":"history-11","system":"neurologic","question":"Did anyone witness you having a seizure?","listenFor":["No witnessed seizure","Witnessed seizure"],"why":null,"whySource":null,"meaning":"A witnessed seizure marks severe, symptomatic hyponatremia — typically with a rapid fall to very low levels — and is an indication for hypertonic saline to stop the seizure and raise the sodium urgently. No seizure does not mean the sodium is safe: confusion, lethargy, and gait instability are also dangerous.","meaningSource":"ai-draft"},{"id":"history-12","system":"general","question":"Have these symptoms been building gradually over weeks, or did they come on suddenly within the past two days?","listenFor":["Chronic, gradual onset over weeks","Acute onset within 48 hours"],"why":"Acute hyponatremia (under 48 hours) risks cerebral edema; chronic hyponatremia risks osmotic demyelination if corrected too fast.","whySource":"curated","meaning":"Acute hyponatremia (under 48 hours) risks cerebral edema; chronic hyponatremia risks osmotic demyelination if corrected too fast.","meaningSource":"curated"},{"id":"history-13","system":"musculoskeletal","question":"Did you do an endurance exercise, like a marathon, while drinking a lot of water?","listenFor":["No recent endurance exercise with excess water intake","Recent endurance exercise with excess water intake"],"why":null,"whySource":null,"meaning":"Exercise-associated hyponatremia from drinking beyond thirst during prolonged exertion is a distinct and common cause in runners — treatment is fluid restriction (hypertonic saline if encephalopathic), not isotonic fluids, which worsen it. Without this history, work through the standard hypovolemic, euvolemic, and hypervolemic categories.","meaningSource":"ai-draft"}],"exam":[{"id":"exam-01","system":"general","maneuver":"Assess overall volume status.","findings":["Euvolemic","Hypovolemic, with dry mucous membranes or orthostatic change","Hypervolemic, with edema, elevated jugular venous pressure, or ascites"],"how":"With the patient reclined at 30 to 45 degrees, identify the highest point of internal jugular venous pulsation and measure its vertical distance above the sternal angle.","why":"Documenting volume status (hypovolemic, euvolemic, or hypervolemic) guides fluid management and helps distinguish prerenal, intrinsic, and volume-overload causes of kidney injury and electrolyte disturbances.","whySource":"curated","meaning":"Documenting volume status (hypovolemic, euvolemic, or hypervolemic) guides fluid management and helps distinguish prerenal, intrinsic, and volume-overload causes of kidney injury and electrolyte disturbances.","meaningSource":"curated"},{"id":"exam-02","system":"neurologic","maneuver":"Assess mental status.","findings":["Alert","Lethargic or confused","Obtunded"],"how":null,"why":null,"whySource":null,"meaning":"Mental status tracks the neurologic severity of hyponatremia: lethargy and confusion signal symptomatic disease needing urgent correction, and obtundation in acute severe hyponatremia raises herniation concern. An alert patient still needs correction, but at the slower safe rate to avoid osmotic demyelination.","meaningSource":"ai-draft"},{"id":"exam-03","system":"skin","maneuver":"Assess skin turgor.","findings":["Normal skin turgor","Poor skin turgor"],"how":null,"why":null,"whySource":null,"meaning":"Poor skin turgor supports hypovolemia as the mechanism, favoring volume repletion with isotonic saline; normal turgor keeps euvolemic causes such as SIADH on the table. Turgor is least reliable in the elderly, so corroborate with orthostatics and mucous membranes.","meaningSource":"ai-draft"},{"id":"exam-04","system":"cardiovascular","maneuver":"Assess jugular venous pressure.","findings":["Normal jugular venous pressure","Elevated jugular venous pressure"],"how":"With the patient reclined at 30 to 45 degrees, identify the highest point of internal jugular venous pulsation and measure its vertical distance above the sternal angle.","why":"Elevated jugular venous pressure reflects elevated right-sided filling pressures, seen in right heart failure, volume overload, or tamponade.","whySource":"curated","meaning":"Elevated jugular venous pressure reflects elevated right-sided filling pressures, seen in right heart failure, volume overload, or tamponade.","meaningSource":"curated"},{"id":"exam-05","system":"cardiovascular","maneuver":"Inspect and palpate the lower extremities for edema.","findings":["No peripheral edema","Peripheral edema present"],"how":null,"why":null,"whySource":null,"meaning":"Peripheral edema identifies hypervolemic hyponatremia from heart failure, cirrhosis, or nephrotic syndrome, where treatment is fluid restriction and addressing the underlying disease rather than giving saline. Absent edema moves the workup toward hypovolemic or euvolemic causes.","meaningSource":"ai-draft"},{"id":"exam-06","system":"gastrointestinal","maneuver":"Assess the abdomen for ascites.","findings":["No ascites","Ascites present"],"how":null,"why":null,"whySource":null,"meaning":"Ascites confirms hypervolemic hyponatremia from cirrhosis, where portal hypertension and splanchnic vasodilation drive ADH release — management is sodium restriction, diuretics, and fluid restriction, not saline. New ascites with fever or pain should also prompt evaluation for spontaneous bacterial peritonitis.","meaningSource":"ai-draft"},{"id":"exam-07","system":"endocrine","maneuver":"Assess the thyroid and deep tendon reflexes.","findings":["Normal thyroid exam and reflexes","Goiter or delayed reflex relaxation"],"how":null,"why":null,"whySource":null,"meaning":"A goiter or delayed reflex relaxation suggests hypothyroidism, an euvolemic cause of hyponatremia that corrects with thyroid hormone replacement. Normal thyroid exam and reflexes make hypothyroidism less likely but do not exclude it — check TSH when the sodium has no other explanation.","meaningSource":"ai-draft"},{"id":"exam-08","system":"skin","maneuver":"Inspect the skin for hyperpigmentation.","findings":["Normal skin color","Skin hyperpigmentation"],"how":null,"why":"New hyperpigmentation of skin creases and scars suggests primary adrenal insufficiency.","whySource":"curated","meaning":"New hyperpigmentation of skin creases and scars suggests primary adrenal insufficiency.","meaningSource":"curated"},{"id":"exam-09","system":"neurologic","maneuver":"Assess deep tendon reflexes.","findings":["Normal reflexes","Diminished reflexes"],"how":null,"why":null,"whySource":null,"meaning":"Diminished reflexes are a nonspecific finding that can accompany hypothyroidism or other metabolic derangements, so read them together with the thyroid exam and volume status rather than as a standalone clue to the sodium. They add little on their own to hyponatremia classification.","meaningSource":"ai-draft"},{"id":"exam-10","system":"neurologic","maneuver":"Assess for active or recent seizure activity.","findings":["None observed","Active or recent seizure activity"],"how":null,"why":null,"whySource":null,"meaning":"Active or recent seizure activity defines severe symptomatic hyponatremia requiring emergent hypertonic saline to halt the seizure and raise the sodium acutely. If the patient is postictal and the sodium is only mildly low, look for another seizure cause rather than attributing it to the sodium alone.","meaningSource":"ai-draft"}],"reviewNeeded":{"whyMissing":13,"howMissing":8}},{"id":"hyperkalemia","title":"Electrolyte abnormality – hyperkalemia","aliases":["high potassium"],"history":[{"id":"history-01","system":"genitourinary","question":"Do you have kidney disease, and if you're on dialysis, have you missed a session?","listenFor":["Neither","Known chronic kidney disease, no missed dialysis","Known dialysis dependence with a missed session"],"why":"A missed dialysis session can cause uremia, hyperkalemia, and volume overload.","whySource":"curated","meaning":"A missed dialysis session can cause uremia, hyperkalemia, and volume overload.","meaningSource":"curated"},{"id":"history-02","system":"medication","question":"Do you take a blood pressure medication ending in -pril or -sartan, or a potassium-sparing water pill like spironolactone?","listenFor":["Neither","ACE inhibitor or ARB use","Potassium-sparing diuretic use"],"why":"Potassium-sparing diuretics and ACE inhibitors or ARBs impair renal potassium excretion.","whySource":"curated","meaning":"Potassium-sparing diuretics and ACE inhibitors or ARBs impair renal potassium excretion.","meaningSource":"curated"},{"id":"history-03","system":"medication","question":"Have you taken any ibuprofen or other NSAIDs recently?","listenFor":["No NSAID use","NSAID use"],"why":"NSAIDs reduce renal perfusion and promote sodium and water retention, worsening kidney function, heart failure, and potassium excretion.","whySource":"curated","meaning":"NSAIDs reduce renal perfusion and promote sodium and water retention, worsening kidney function, heart failure, and potassium excretion.","meaningSource":"curated"},{"id":"history-04","system":"medication","question":"Have you taken the antibiotic trimethoprim-sulfamethoxazole (Bactrim) recently?","listenFor":["No recent trimethoprim-sulfamethoxazole use","Recent trimethoprim-sulfamethoxazole use"],"why":"Trimethoprim impairs renal potassium excretion and can cause hyperkalemia.","whySource":"curated","meaning":"Trimethoprim impairs renal potassium excretion and can cause hyperkalemia.","meaningSource":"curated"},{"id":"history-05","system":"medication","question":"Do you take a potassium supplement, or use a salt substitute?","listenFor":["Neither","Potassium supplement use","Salt substitute use"],"why":"Salt substitutes contain potassium chloride and can cause hyperkalemia.","whySource":"curated","meaning":"Salt substitutes contain potassium chloride and can cause hyperkalemia.","meaningSource":"curated"},{"id":"history-06","system":"musculoskeletal","question":"Have you had significant muscle pain, or has your urine looked dark like tea or cola?","listenFor":["Neither","Muscle pain","Dark, tea-colored urine"],"why":"Dark tea-colored urine with muscle pain or after crush injury suggests rhabdomyolysis with myoglobinuria.","whySource":"curated","meaning":"Dark tea-colored urine with muscle pain or after crush injury suggests rhabdomyolysis with myoglobinuria.","meaningSource":"curated"},{"id":"history-07","system":"hematologic","question":"Have you been diagnosed with cancer, or started chemotherapy recently?","listenFor":["Neither","Known malignancy","Recently started chemotherapy"],"why":null,"whySource":null,"meaning":"Recent chemotherapy for a bulky or chemosensitive malignancy raises concern for tumor lysis syndrome, where dying cells flood the blood with potassium, phosphate, and uric acid — an oncologic emergency. A positive answer should prompt checks of phosphate, uric acid, and calcium alongside aggressive hydration.","meaningSource":"ai-draft"},{"id":"history-08","system":"neurologic","question":"Have you felt weak or noticed numbness or tingling?","listenFor":["Neither","Mild weakness or paresthesias","Severe weakness or paralysis"],"why":"Severe weakness or flaccid paralysis suggests hyperkalemic effects on skeletal muscle.","whySource":"curated","meaning":"Severe weakness or flaccid paralysis suggests hyperkalemic effects on skeletal muscle.","meaningSource":"curated"},{"id":"history-09","system":"cardiovascular","question":"Have you felt your heart racing, or did you pass out?","listenFor":["Neither","Palpitations","Syncope or near-syncope"],"why":null,"whySource":null,"meaning":"Palpitations or syncope suggest hyperkalemia is already impairing cardiac conduction — a warning sign of impending bradyarrhythmia or arrest. Any cardiac symptom makes this an emergency: get an ECG immediately and prepare calcium, insulin–glucose, and cardiac monitoring.","meaningSource":"ai-draft"},{"id":"history-10","system":"endocrine","question":"Have you lost weight without trying, or noticed new darkening of your skin?","listenFor":["No adrenal insufficiency symptoms","Fatigue and unintentional weight loss","New skin darkening"],"why":null,"whySource":null,"meaning":"Unintentional weight loss with new skin darkening suggests primary adrenal insufficiency — aldosterone deficiency impairs renal potassium excretion, causing hyperkalemia with hyponatremia and hypotension. A positive answer should prompt a morning cortisol and consideration of stress-dose steroids.","meaningSource":"ai-draft"},{"id":"history-11","system":"endocrine","question":"Do you have diabetes, and have you noticed excessive thirst, urination, or a fruity breath smell?","listenFor":["No known diabetes","Known diabetes with polyuria or polydipsia","Known diabetes with symptoms of diabetic ketoacidosis"],"why":"A fruity or acetone breath odor suggests ketoacidosis.","whySource":"curated","meaning":"A fruity or acetone breath odor suggests ketoacidosis.","meaningSource":"curated"},{"id":"history-12","system":"hematologic","question":"Have you received a large blood transfusion recently?","listenFor":["No recent transfusion","Recent large-volume blood transfusion"],"why":null,"whySource":null,"meaning":"Stored red cells leak potassium during storage, so large or rapid transfusions — especially in patients with renal impairment — can spike serum potassium acutely. A positive history means rechecking potassium promptly and slowing the transfusion if hyperkalemia is confirmed.","meaningSource":"ai-draft"},{"id":"history-13","system":"musculoskeletal","question":"Were you crushed under something heavy, or stuck in one position for a long time?","listenFor":["Neither","Crush injury","Prolonged immobilization or extended down time"],"why":"Crush injury releases myoglobin that can precipitate acute kidney injury.","whySource":"curated","meaning":"Crush injury releases myoglobin that can precipitate acute kidney injury.","meaningSource":"curated"}],"exam":[{"id":"exam-01","system":"cardiovascular","maneuver":"Assess cardiac rhythm.","findings":["Regular rate and rhythm","Bradycardic","Irregular rhythm"],"how":null,"why":null,"whySource":null,"meaning":"Bradycardia or an irregular rhythm may reflect hyperkalemia's effect on cardiac conduction — progressive PR prolongation, QRS widening, and heart block precede arrest. Any rhythm abnormality should prompt an immediate ECG to look for peaked T waves or QRS widening.","meaningSource":"ai-draft"},{"id":"exam-02","system":"neurologic","maneuver":"Assess muscle strength.","findings":["Normal strength","Mild weakness","Severe weakness or flaccid paralysis"],"how":null,"why":null,"whySource":null,"meaning":"Ascending weakness or flaccid paralysis is a neuromuscular manifestation of severe hyperkalemia — when respiratory muscles are involved it becomes an airway emergency. Progressive weakness should trigger immediate potassium-lowering therapy and close respiratory monitoring.","meaningSource":"ai-draft"},{"id":"exam-03","system":"neurologic","maneuver":"Assess deep tendon reflexes.","findings":["Normal reflexes","Diminished or absent reflexes"],"how":null,"why":null,"whySource":null,"meaning":"Diminished or absent reflexes accompany the ascending weakness of severe hyperkalemia and help confirm a neuromuscular — rather than central — pattern. Taken with weakness, it strengthens the case that potassium itself is causing symptoms.","meaningSource":"ai-draft"},{"id":"exam-04","system":"general","maneuver":"Assess overall volume status.","findings":["Euvolemic","Hypervolemic, with edema","Hypovolemic"],"how":null,"why":"Documenting volume status (hypovolemic, euvolemic, or hypervolemic) guides fluid management and helps distinguish prerenal, intrinsic, and volume-overload causes of kidney injury and electrolyte disturbances.","whySource":"curated","meaning":"Documenting volume status (hypovolemic, euvolemic, or hypervolemic) guides fluid management and helps distinguish prerenal, intrinsic, and volume-overload causes of kidney injury and electrolyte disturbances.","meaningSource":"curated"},{"id":"exam-05","system":"musculoskeletal","maneuver":"Palpate muscle groups for focal tenderness or swelling suggesting rhabdomyolysis.","findings":["No focal muscle tenderness or swelling","Focal muscle tenderness or swelling"],"how":null,"why":null,"whySource":null,"meaning":"Focal muscle tenderness or swelling suggests rhabdomyolysis, which releases large intracellular potassium stores into the blood — a direct cause of the hyperkalemia. A positive finding should prompt a CK level and aggressive fluid resuscitation.","meaningSource":"ai-draft"},{"id":"exam-06","system":"genitourinary","maneuver":"Inspect the dialysis access site, if present.","findings":["No dialysis access or site normal and functioning","Dialysis access with concern for thrombosis or infection"],"how":null,"why":null,"whySource":null,"meaning":"In dialysis-dependent patients, a thrombosed or infected access means potassium cannot be cleared — missed or impossible dialysis is the most common precipitant of severe hyperkalemia. Any access concern should prompt urgent nephrology evaluation, since dialysis may be the definitive treatment.","meaningSource":"ai-draft"},{"id":"exam-07","system":"skin","maneuver":"Inspect the skin for hyperpigmentation.","findings":["Normal skin color","Skin hyperpigmentation"],"how":null,"why":"New hyperpigmentation of skin creases and scars suggests primary adrenal insufficiency.","whySource":"curated","meaning":"New hyperpigmentation of skin creases and scars suggests primary adrenal insufficiency.","meaningSource":"curated"},{"id":"exam-08","system":"neurologic","maneuver":"Assess mental status.","findings":["Alert","Confused or lethargic"],"how":null,"why":null,"whySource":null,"meaning":"Confusion or lethargy is nonspecific but, in hyperkalemia, may reflect uremia in a dialysis patient or poor cerebral perfusion from bradycardia — both reasons to treat urgently rather than watchfully. It also signals the patient may not be safe for outpatient management.","meaningSource":"ai-draft"},{"id":"exam-09","system":"genitourinary","maneuver":"Assess urine output.","findings":["Normal urine output","Decreased or absent urine output"],"how":null,"why":null,"whySource":null,"meaning":"Decreased or absent urine output means the kidneys cannot excrete potassium — impaired excretion is the most common mechanism of hyperkalemia and predicts that medical therapy alone may fail. Oliguria with hyperkalemia should prompt early nephrology involvement, since dialysis may be required.","meaningSource":"ai-draft"},{"id":"exam-10","system":"cardiovascular","maneuver":"Palpate peripheral pulses for regularity and quality.","findings":["Regular, normal pulses","Irregular or weak pulses"],"how":null,"why":null,"whySource":null,"meaning":"Irregular or weak pulses may reflect an arrhythmia or poor perfusion from hyperkalemia-induced bradycardia — a bedside clue that the potassium is already affecting the heart. Pair this with an immediate ECG and continuous monitoring.","meaningSource":"ai-draft"}],"reviewNeeded":{"whyMissing":12,"howMissing":10}},{"id":"falls-fall-related-injury","title":"Falls / fall-related injury","aliases":["fall","mechanical fall"],"history":[{"id":"history-01","system":"functional","question":"Did you trip or slip, or do you not remember what happened before you fell?","listenFor":["Witnessed mechanical fall, tripped or slipped","Unwitnessed fall","Witnessed loss of consciousness before falling"],"why":"Loss of consciousness before a fall suggests syncope rather than a mechanical trip.","whySource":"curated","meaning":"Loss of consciousness before a fall suggests syncope rather than a mechanical trip.","meaningSource":"curated"},{"id":"history-02","system":"neurologic","question":"Did you feel lightheaded, or have chest pain or a racing heart right before you fell?","listenFor":["No prodrome, tripped or slipped","Presyncope or lightheadedness before falling","Chest pain or palpitations before falling"],"why":null,"whySource":null,"meaning":"A prodrome of lightheadedness, chest pain, or palpitations points to a syncopal fall — from orthostatic hypotension, an arrhythmia, or cardiac ischemia — while a trip or slip with no warning suggests a mechanical or environmental cause; the distinction decides whether the workup targets the heart and blood pressure or balance and the home environment.","meaningSource":"ai-draft"},{"id":"history-03","system":"neurologic","question":"Did you black out or lose consciousness during the fall?","listenFor":["No loss of consciousness","Brief loss of consciousness","Prolonged loss of consciousness"],"why":null,"whySource":null,"meaning":"Brief loss of consciousness fits syncope (vasovagal, orthostatic, or arrhythmic), while prolonged loss of consciousness raises concern for seizure or another neurologic event; no loss of consciousness at all makes a mechanical fall more likely. The answer guides whether to pursue cardiac monitoring, neurologic evaluation, or fall-prevention measures.","meaningSource":"ai-draft"},{"id":"history-04","system":"musculoskeletal","question":"Did you hit your head when you fell?","listenFor":["No head strike","Head strike without loss of consciousness","Head strike with loss of consciousness"],"why":null,"whySource":null,"meaning":"A head strike raises the risk of intracranial injury — especially in patients on anticoagulants or antiplatelets — and lowers the threshold for head CT and neurologic observation; no head strike makes significant brain injury unlikely.","meaningSource":"ai-draft"},{"id":"history-05","system":"medication","question":"Are you on a blood thinner?","listenFor":["No anticoagulant use","Anticoagulant use"],"why":"Blood thinner use increases bleeding risk and severity, and affects reversal decisions.","whySource":"curated","meaning":"Blood thinner use increases bleeding risk and severity, and affects reversal decisions.","meaningSource":"curated"},{"id":"history-06","system":"functional","question":"How many times have you fallen in the past year?","listenFor":["First fall in the past year","Two or more falls in the past year"],"why":null,"whySource":null,"meaning":"Two or more falls in a year marks a recurrent faller who needs a multifactorial fall-risk assessment (medications, vision, gait, home hazards) and targeted prevention; a single first fall is more often circumstantial.","meaningSource":"ai-draft"},{"id":"history-07","system":"medication","question":"Do you take any sleep or sedative medications?","listenFor":["No sedative or hypnotic use","Sedative or hypnotic use"],"why":null,"whySource":null,"meaning":"Sedatives and hypnotics impair alertness, reaction time, and balance and are among the most modifiable fall risk factors — identifying them opens the door to deprescribing, dose reduction, or safer alternatives.","meaningSource":"ai-draft"},{"id":"history-08","system":"medication","question":"Has your blood pressure medication been started or increased recently?","listenFor":["No recent antihypertensive change","New or increased antihypertensive dose"],"why":"New or increased antihypertensives can cause orthostatic hypotension and falls.","whySource":"curated","meaning":"New or increased antihypertensives can cause orthostatic hypotension and falls.","meaningSource":"curated"},{"id":"history-09","system":"musculoskeletal","question":"How long were you on the ground before you were able to get up or someone found you?","listenFor":["Under one hour","Several hours","Unable to get up until found after a prolonged period"],"why":"Prolonged time on the floor risks rhabdomyolysis, pressure injury, and dehydration.","whySource":"curated","meaning":"Prolonged time on the floor risks rhabdomyolysis, pressure injury, and dehydration.","meaningSource":"curated"},{"id":"history-10","system":"eyes","question":"Do you have any known vision problems?","listenFor":["No known vision impairment","Known vision impairment"],"why":null,"whySource":null,"meaning":"Impaired vision limits detection of trip hazards and judging distances, making it a reversible contributor to falls; confirming it prompts an eye exam and correction (glasses, cataract referral) rather than assuming the falls are purely neurologic.","meaningSource":"ai-draft"},{"id":"history-11","system":"musculoskeletal","question":"Are you able to put weight on the leg or arm that's hurting?","listenFor":["No pain preventing weight-bearing","Hip or extremity pain","Unable to bear weight at all"],"why":null,"whySource":null,"meaning":"Inability to bear weight after a fall strongly suggests a fracture — in an older adult with hip pain, a hip fracture until proven otherwise — and mandates imaging; being able to walk makes a major fracture less likely but does not rule out occult injury.","meaningSource":"ai-draft"},{"id":"history-12","system":"medication","question":"Did you drink alcohol before you fell?","listenFor":["No alcohol use prior to the fall","Alcohol use prior to the fall"],"why":null,"whySource":null,"meaning":"Alcohol intoxication impairs balance and judgment and is a reversible precipitant of the fall; a pattern of drinking before falls also flags alcohol use as an ongoing risk to address.","meaningSource":"ai-draft"},{"id":"history-13","system":"functional","question":"Was there anything at home that might have contributed, like poor lighting or clutter on the floor?","listenFor":["No environmental hazard identified","Environmental hazard identified, such as poor lighting or clutter"],"why":null,"whySource":null,"meaning":"Environmental hazards — poor lighting, clutter, loose rugs, missing handrails — are modifiable causes of falls; identifying them leads to a home safety assessment and concrete fixes that prevent the next fall.","meaningSource":"ai-draft"},{"id":"history-14","system":"neurologic","question":"Did you feel the room spinning right before you fell?","listenFor":["No vertigo or spinning sensation","Vertigo or spinning sensation preceding the fall"],"why":"Vertigo before a fall suggests a vestibular or posterior circulation cause.","whySource":"curated","meaning":"Vertigo before a fall suggests a vestibular or posterior circulation cause.","meaningSource":"curated"}],"exam":[{"id":"exam-01","system":"skin","maneuver":"Inspect the scalp for hematoma or laceration.","findings":["No scalp hematoma or laceration","Scalp hematoma or laceration present"],"how":null,"why":null,"whySource":null,"meaning":"A scalp hematoma or laceration marks the site and force of a head strike, guides wound repair, and signals the need to evaluate for underlying skull fracture or intracranial injury — particularly in anticoagulated patients.","meaningSource":"ai-draft"},{"id":"exam-02","system":"neurologic","maneuver":"Assess for a focal neurologic deficit.","findings":["No focal deficit","Focal deficit present"],"how":null,"why":null,"whySource":null,"meaning":"A new focal deficit after a fall raises two urgent possibilities: a stroke that caused the fall, or a traumatic brain injury from it; either way it warrants emergent neuroimaging rather than attributing the fall to clumsiness.","meaningSource":"ai-draft"},{"id":"exam-03","system":"neurologic","maneuver":"Assess mental status.","findings":["Alert and oriented","Altered mental status"],"how":null,"why":null,"whySource":null,"meaning":"Altered mental status after a fall may reflect head injury, intoxication, hypoglycemia, or an underlying medical precipitant such as infection — it must be worked up as a cause or consequence of the fall, not dismissed as baseline confusion.","meaningSource":"ai-draft"},{"id":"exam-04","system":"cardiovascular","maneuver":"Assess orthostatic vital signs when safe.","findings":["Negative orthostatics","Positive orthostatic hypotension"],"how":"Measure blood pressure and heart rate after 5 minutes supine, then at 1 and 3 minutes after standing; a sustained drop of 20 mmHg systolic or 10 mmHg diastolic within 3 minutes is positive.","why":null,"whySource":null,"meaning":"Positive orthostatic hypotension identifies a treatable precipitant of syncopal falls — volume depletion, culprit medications, or autonomic dysfunction — and directs management toward fluids, medication review, and countermeasures; negative orthostatics make a cardiac arrhythmia or vasovagal cause relatively more likely.","meaningSource":"ai-draft"},{"id":"exam-05","system":"cardiovascular","maneuver":"Assess cardiac rhythm.","findings":["Regular rhythm","Irregular rhythm"],"how":null,"why":null,"whySource":null,"meaning":"An irregular rhythm (such as atrial fibrillation) suggests an arrhythmic cause for a syncopal fall and carries stroke risk, prompting ECG and rhythm monitoring; a regular rhythm makes a primary arrhythmia less likely.","meaningSource":"ai-draft"},{"id":"exam-06","system":"musculoskeletal","maneuver":"Assess the hip and pelvis for a suspected fracture.","findings":["Normal, able to bear weight","Pain with a shortened, externally rotated leg suggesting fracture"],"how":null,"why":"A shortened, externally rotated leg after a fall suggests a hip fracture.","whySource":"curated","meaning":"A shortened, externally rotated leg after a fall suggests a hip fracture.","meaningSource":"curated"},{"id":"exam-07","system":"musculoskeletal","maneuver":"Inspect extremities for deformity or swelling.","findings":["No deformity or swelling","Deformity or swelling present"],"how":null,"why":null,"whySource":null,"meaning":"Deformity or swelling signals a fracture or dislocation needing imaging and orthopedic input; absence of deformity does not rule out fracture — hip and wrist fractures can present with minimal deformity.","meaningSource":"ai-draft"},{"id":"exam-08","system":"skin","maneuver":"Inspect for pressure injury or skin breakdown from prolonged time on the ground.","findings":["No pressure injury or skin breakdown","Pressure injury or skin breakdown present"],"how":null,"why":null,"whySource":null,"meaning":"Skin breakdown after a fall suggests a prolonged 'long lie' on the ground, which brings risks of rhabdomyolysis, dehydration, and acute kidney injury — check creatine kinase and renal function — and marks the patient as too frail to get up alone.","meaningSource":"ai-draft"},{"id":"exam-09","system":"musculoskeletal","maneuver":"Assess gait and balance when safe.","findings":["Normal gait and balance","Unsteady gait","Unable to ambulate safely"],"how":null,"why":null,"whySource":null,"meaning":"Unsteady gait or inability to ambulate safely reveals the residual deficit driving fall risk and determines whether the patient can return home, needs physical therapy and an assistive device, or requires supervised placement.","meaningSource":"ai-draft"},{"id":"exam-10","system":"eyes","maneuver":"Assess visual acuity.","findings":["Normal visual acuity","Impaired visual acuity"],"how":null,"why":null,"whySource":null,"meaning":"Bedside visual acuity testing confirms whether poor vision contributed to the fall; documented impairment supports referral for correction, which is one of the few proven fall-prevention interventions.","meaningSource":"ai-draft"}],"reviewNeeded":{"whyMissing":18,"howMissing":9}},{"id":"dizziness-vertigo","title":"Dizziness / vertigo","aliases":["vertigo","lightheadedness"],"history":[{"id":"history-01","system":"neurologic","question":"Does it feel like the room is spinning, like you're about to faint, or just unsteady without spinning?","listenFor":["Spinning, room-spinning vertigo","Lightheaded, near-fainting sensation","Unsteadiness or imbalance without spinning"],"why":null,"whySource":null,"meaning":"The quality of the sensation triages the differential: true spinning (vertigo) points to a vestibular cause, feeling about to faint (presyncope) points to a cardiovascular or orthostatic cause, and unsteadiness without spinning (disequilibrium) points to a neurologic or sensory cause.","meaningSource":"ai-draft"},{"id":"history-02","system":"neurologic","question":"Do the episodes last just a few seconds, several hours, or has it been constant for days?","listenFor":["Brief episodes lasting seconds","Continuous vertigo lasting days","Episodic vertigo lasting hours"],"why":null,"whySource":null,"meaning":"Duration discriminates the cause: seconds suggests BPPV or orthostatic presyncope, minutes raises concern for TIA, hours fits vestibular migraine or Ménière disease, and days of constant vertigo fits vestibular neuritis — persistent vertigo lasting days with nystagmus should still prompt a check for central signs.","meaningSource":"ai-draft"},{"id":"history-03","system":"neurologic","question":"Does the dizziness happen when you roll over in bed or look up?","listenFor":["Not positional","Triggered by rolling over in bed or looking up"],"why":"Vertigo triggered by rolling over in bed or looking up suggests benign paroxysmal positional vertigo.","whySource":"curated","meaning":"Vertigo triggered by rolling over in bed or looking up suggests benign paroxysmal positional vertigo.","meaningSource":"curated"},{"id":"history-04","system":"ent","question":"Have you noticed any hearing loss or ringing in your ears?","listenFor":["Neither","Hearing loss","Tinnitus"],"why":null,"whySource":null,"meaning":"Hearing loss or tinnitus localizes the problem to the inner ear, as in Ménière disease, labyrinthitis, or an acoustic neuroma; vertigo without any auditory symptoms favors BPPV, vestibular neuritis, or a central cause.","meaningSource":"ai-draft"},{"id":"history-05","system":"neurologic","question":"Have you had double vision, facial numbness, weakness, or clumsiness in your arms or legs along with the dizziness?","listenFor":["None of these","Double vision or facial numbness","Limb weakness or incoordination"],"why":null,"whySource":null,"meaning":"Double vision, facial numbness, weakness, or clumsiness alongside dizziness are red flags for posterior circulation stroke or another central lesion — this combination warrants emergent stroke evaluation and neuroimaging.","meaningSource":"ai-draft"},{"id":"history-06","system":"neurologic","question":"Do you have a headache along with the dizziness?","listenFor":["No headache","Headache accompanying the dizziness"],"why":null,"whySource":null,"meaning":"Headache with vertigo suggests vestibular migraine, especially with a migraine history; a sudden severe or worst-ever headache is a red flag for a vascular cause and needs urgent evaluation.","meaningSource":"ai-draft"},{"id":"history-07","system":"infectious","question":"Did you have a cold or upper respiratory infection before this started?","listenFor":["No preceding upper respiratory infection","Preceding upper respiratory infection"],"why":null,"whySource":null,"meaning":"A recent cold or upper respiratory infection before vertigo onset suggests vestibular neuritis or labyrinthitis, which typically follows a viral illness and presents with days of constant vertigo.","meaningSource":"ai-draft"},{"id":"history-08","system":"cardiovascular","question":"Do you have coronary artery disease, an irregular heartbeat, or a family history of sudden cardiac death?","listenFor":["None of these","Known coronary artery disease or arrhythmia","Family history of sudden cardiac death"],"why":null,"whySource":null,"meaning":"Coronary disease, an irregular heartbeat, or family history of sudden cardiac death raise concern that the dizziness is cardiac syncope or presyncope from an arrhythmia — check an EKG and consider cardiac monitoring.","meaningSource":"ai-draft"},{"id":"history-09","system":"medication","question":"Have you started a new blood pressure medication or an antibiotic that can affect hearing or balance?","listenFor":["Neither","New antihypertensive","New ototoxic medication"],"why":"Aminoglycosides, loop diuretics, and other ototoxic drugs can cause vertigo and hearing loss.","whySource":"curated","meaning":"Aminoglycosides, loop diuretics, and other ototoxic drugs can cause vertigo and hearing loss.","meaningSource":"curated"},{"id":"history-10","system":"endocrine","question":"Do you have diabetes, and did you feel shaky, sweaty, or hungry along with the dizziness?","listenFor":["No known diabetes","Known diabetes without hypoglycemic symptoms","Known diabetes with hypoglycemic symptoms"],"why":"Hypoglycemia causes neuroglycopenic symptoms such as confusion, diaphoresis, and tremor, and needs urgent correction.","whySource":"curated","meaning":"Hypoglycemia causes neuroglycopenic symptoms such as confusion, diaphoresis, and tremor, and needs urgent correction.","meaningSource":"curated"},{"id":"history-11","system":"psychiatric","question":"Did this happen during a stressful moment when you were breathing fast?","listenFor":["No situational anxiety trigger","Situational anxiety trigger with hyperventilation"],"why":null,"whySource":null,"meaning":"Lightheadedness during stress with rapid breathing suggests hyperventilation, which lowers CO2 and causes tingling and lightheadedness; recognizing this pattern avoids unnecessary workup once other causes are excluded.","meaningSource":"ai-draft"},{"id":"history-12","system":"hematologic","question":"Have you been told you're anemic or have low blood counts?","listenFor":["No known anemia","Known anemia"],"why":null,"whySource":null,"meaning":"Anemia reduces oxygen delivery and commonly causes lightheadedness and fatigue; a positive history should prompt a hemoglobin check as a reversible contributor.","meaningSource":"ai-draft"},{"id":"history-13","system":"neurologic","question":"Have you had episodes like this before?","listenFor":["First episode","Recurrent similar episodes"],"why":null,"whySource":null,"meaning":"Prior similar episodes point to a recurrent condition such as BPPV, Ménière disease, vestibular migraine, or TIA, and the pattern of recurrences helps narrow it; a first-ever episode raises the stakes for an acute cause like stroke.","meaningSource":"ai-draft"}],"exam":[{"id":"exam-01","system":"neurologic","maneuver":"Assess for nystagmus.","findings":["No nystagmus","Unidirectional horizontal nystagmus","Direction-changing or vertical nystagmus"],"how":null,"why":"Direction-changing or vertical nystagmus suggests a central cause of vertigo, such as posterior circulation stroke, rather than a peripheral one.","whySource":"curated","meaning":"Direction-changing or vertical nystagmus suggests a central cause of vertigo, such as posterior circulation stroke, rather than a peripheral one.","meaningSource":"curated"},{"id":"exam-02","system":"neurologic","maneuver":"Assess for skew deviation.","findings":["Absent","Present"],"how":null,"why":"Skew deviation suggests a central cause of vertigo rather than a peripheral one.","whySource":"curated","meaning":"Skew deviation suggests a central cause of vertigo rather than a peripheral one.","meaningSource":"curated"},{"id":"exam-03","system":"musculoskeletal","maneuver":"Assess tandem gait when safe.","findings":["Normal tandem gait","Unable to walk tandem, ataxic gait"],"how":null,"why":null,"whySource":null,"meaning":"An ataxic or unable-to-tandem gait signals cerebellar or posterior fossa involvement rather than a peripheral vestibular problem — a central cause that warrants urgent neuroimaging.","meaningSource":"ai-draft"},{"id":"exam-04","system":"cardiovascular","maneuver":"Assess orthostatic vital signs when safe.","findings":["Negative orthostatics","Positive orthostatic hypotension"],"how":"Measure blood pressure and heart rate after 5 minutes supine, then at 1 and 3 minutes after standing; a sustained drop of 20 mmHg systolic or 10 mmHg diastolic within 3 minutes is positive.","why":null,"whySource":null,"meaning":"A significant blood pressure drop on standing identifies orthostatic hypotension from volume depletion, autonomic dysfunction, or medications — a treatable cause of presyncope-type dizziness.","meaningSource":"ai-draft"},{"id":"exam-05","system":"cardiovascular","maneuver":"Assess cardiac rhythm.","findings":["Regular rhythm","Irregular rhythm"],"how":null,"why":null,"whySource":null,"meaning":"An irregular rhythm suggests atrial fibrillation or another arrhythmia as the cause of presyncope or syncope; confirm with an EKG and evaluate stroke risk if AF is found.","meaningSource":"ai-draft"},{"id":"exam-06","system":"neurologic","maneuver":"Perform the Dix-Hallpike maneuver when clinically appropriate.","findings":["Negative or not indicated","Positive, reproduces vertigo with nystagmus"],"how":"Turn the patient's head 45 degrees to one side, then briskly lay them back with the head hanging about 20 degrees below horizontal; watch the eyes for vertigo and nystagmus.","why":"A positive Dix-Hallpike maneuver, reproducing vertigo with nystagmus, suggests benign paroxysmal positional vertigo.","whySource":"curated","meaning":"A positive Dix-Hallpike maneuver, reproducing vertigo with nystagmus, suggests benign paroxysmal positional vertigo.","meaningSource":"curated"},{"id":"exam-07","system":"ent","maneuver":"Assess hearing.","findings":["Normal hearing bilaterally","Unilateral hearing loss"],"how":null,"why":null,"whySource":null,"meaning":"Unilateral hearing loss with vertigo points to a peripheral inner-ear lesion such as Ménière disease, labyrinthitis, or acoustic neuroma — refer for audiology and ENT evaluation.","meaningSource":"ai-draft"},{"id":"exam-08","system":"neurologic","maneuver":"Assess for a focal neurologic deficit.","findings":["No focal deficit","Focal deficit present"],"how":null,"why":null,"whySource":null,"meaning":"Any focal neurologic deficit with dizziness indicates a central cause, most urgently posterior circulation stroke — activate stroke evaluation and obtain emergent neuroimaging.","meaningSource":"ai-draft"},{"id":"exam-09","system":"hematologic","maneuver":"Inspect conjunctiva and nail beds for pallor.","findings":["Normal color","Conjunctival or nail-bed pallor"],"how":null,"why":"Pallor of the conjunctivae, nail beds, or palmar creases suggests anemia.","whySource":"curated","meaning":"Pallor of the conjunctivae, nail beds, or palmar creases suggests anemia.","meaningSource":"curated"},{"id":"exam-10","system":"neurologic","maneuver":"Assess coordination with finger-to-nose testing.","findings":["Normal coordination","Dysmetria"],"how":null,"why":null,"whySource":null,"meaning":"Dysmetria on finger-to-nose testing localizes the lesion to the cerebellum, pointing to a central cause such as stroke rather than a peripheral vestibular disorder — obtain urgent neuroimaging.","meaningSource":"ai-draft"}],"reviewNeeded":{"whyMissing":16,"howMissing":8}},{"id":"severe-new-headache","title":"Headache (severe or new-onset)","aliases":["worst headache of life","thunderclap headache"],"history":[{"id":"history-01","system":"neurologic","question":"Did the headache build up gradually over hours, or hit you at full intensity within a minute?","listenFor":["Gradual onset over hours","Thunderclap onset, maximal intensity within a minute"],"why":"A thunderclap headache, reaching maximal intensity within a minute, raises concern for subarachnoid hemorrhage.","whySource":"curated","meaning":"A thunderclap headache, reaching maximal intensity within a minute, raises concern for subarachnoid hemorrhage.","meaningSource":"curated"},{"id":"history-02","system":"neurologic","question":"Does this headache feel like the ones you usually get, or is this the worst headache of your life?","listenFor":["Similar to prior headaches","First-ever severe headache or worst of life"],"why":"A thunderclap headache, reaching maximal intensity within a minute, raises concern for subarachnoid hemorrhage.","whySource":"curated","meaning":"A thunderclap headache, reaching maximal intensity within a minute, raises concern for subarachnoid hemorrhage.","meaningSource":"curated"},{"id":"history-03","system":"infectious","question":"Do you have a fever along with the headache?","listenFor":["No fever","Fever"],"why":null,"whySource":null,"meaning":"Fever with headache raises concern for central nervous system infection — meningitis or encephalitis — and warrants urgent evaluation, often including lumbar puncture after imaging.","meaningSource":"ai-draft"},{"id":"history-04","system":"neurologic","question":"Is your neck stiff along with the headache?","listenFor":["No neck stiffness","Neck stiffness"],"why":"Neck stiffness with fever and headache suggests meningitis.","whySource":"curated","meaning":"Neck stiffness with fever and headache suggests meningitis.","meaningSource":"curated"},{"id":"history-05","system":"eyes","question":"Has your vision changed or blurred along with the headache?","listenFor":["No vision change","Blurred vision","Vision loss"],"why":null,"whySource":null,"meaning":"Visual changes with headache suggest raised intracranial pressure, migraine aura, or — in older adults — giant cell arteritis; frank vision loss is a red flag requiring urgent ophthalmologic and neurologic workup.","meaningSource":"ai-draft"},{"id":"history-06","system":"neurologic","question":"Have you had any weakness, numbness, or trouble speaking along with the headache?","listenFor":["None of these","Weakness or numbness","Speech change"],"why":null,"whySource":null,"meaning":"Focal weakness, numbness, or speech change with headache points toward stroke, hemorrhage, or a mass lesion rather than a primary headache disorder, and requires emergent neuroimaging.","meaningSource":"ai-draft"},{"id":"history-07","system":"musculoskeletal","question":"Does your jaw hurt when you chew, or is your scalp tender to touch?","listenFor":["Neither","Jaw claudication","Scalp tenderness"],"why":"Jaw claudication and scalp tenderness in an adult over 50 suggest giant cell arteritis.","whySource":"curated","meaning":"Jaw claudication and scalp tenderness in an adult over 50 suggest giant cell arteritis.","meaningSource":"curated"},{"id":"history-08","system":"general","question":"How old are you?","listenFor":["Under 50 years old","50 years or older"],"why":"New headache over age 50 raises concern for giant cell arteritis, malignancy, or subarachnoid hemorrhage.","whySource":"curated","meaning":"New headache over age 50 raises concern for giant cell arteritis, malignancy, or subarachnoid hemorrhage.","meaningSource":"curated"},{"id":"history-09","system":"neurologic","question":"Does the headache get worse when you strain, cough, or bear down, or when you lie flat?","listenFor":["No positional or straining component","Worse with straining, coughing, or bearing down","Worse lying flat, improved standing"],"why":"Headache worse lying flat and better standing suggests elevated intracranial pressure; the reverse suggests low pressure from a cerebrospinal fluid leak.","whySource":"curated","meaning":"Headache worse lying flat and better standing suggests elevated intracranial pressure; the reverse suggests low pressure from a cerebrospinal fluid leak.","meaningSource":"curated"},{"id":"history-10","system":"musculoskeletal","question":"Do you have neck pain, or did you have a recent neck injury or chiropractic adjustment?","listenFor":["Neither","Neck pain","Recent neck trauma or chiropractic manipulation"],"why":"Recent neck trauma or chiropractic manipulation raises concern for cervical artery dissection.","whySource":"curated","meaning":"Recent neck trauma or chiropractic manipulation raises concern for cervical artery dissection.","meaningSource":"curated"},{"id":"history-11","system":"reproductive","question":"Are you currently pregnant or recently gave birth, and has your blood pressure been high?","listenFor":["Not pregnant or postpartum","Pregnant or postpartum with elevated blood pressure"],"why":"Elevated blood pressure in pregnancy or the postpartum period raises concern for preeclampsia.","whySource":"curated","meaning":"Elevated blood pressure in pregnancy or the postpartum period raises concern for preeclampsia.","meaningSource":"curated"},{"id":"history-12","system":"hematologic","question":"Have you been diagnosed with cancer, or are you on medications that suppress your immune system?","listenFor":["Neither","Known malignancy","Known immunosuppression"],"why":null,"whySource":null,"meaning":"Known malignancy raises concern for brain metastases; immunosuppression broadens the infection differential (including opportunistic organisms) and lowers the threshold for imaging and lumbar puncture.","meaningSource":"ai-draft"},{"id":"history-13","system":"medication","question":"Are you on a blood thinner?","listenFor":["No anticoagulant use","Anticoagulant use"],"why":"Blood thinner use increases bleeding risk and severity, and affects reversal decisions.","whySource":"curated","meaning":"Blood thinner use increases bleeding risk and severity, and affects reversal decisions.","meaningSource":"curated"},{"id":"history-14","system":"musculoskeletal","question":"Have you hit your head recently?","listenFor":["No recent head trauma","Recent head trauma"],"why":null,"whySource":null,"meaning":"Recent head trauma raises concern for subdural hematoma or other traumatic intracranial injury, which can present days later with headache — guiding the decision to obtain head CT.","meaningSource":"ai-draft"}],"exam":[{"id":"exam-01","system":"neurologic","maneuver":"Assess mental status.","findings":["Alert and oriented","Confused or altered"],"how":null,"why":null,"whySource":null,"meaning":"Altered mental status with headache suggests encephalitis, intracranial hemorrhage, or raised intracranial pressure — a red flag combination that requires emergent neuroimaging.","meaningSource":"ai-draft"},{"id":"exam-02","system":"neurologic","maneuver":"Assess for nuchal rigidity.","findings":["Absent","Present"],"how":null,"why":"Nuchal rigidity suggests meningeal irritation, as in meningitis or subarachnoid hemorrhage.","whySource":"curated","meaning":"Nuchal rigidity suggests meningeal irritation, as in meningitis or subarachnoid hemorrhage.","meaningSource":"curated"},{"id":"exam-03","system":"neurologic","maneuver":"Assess for a focal neurologic deficit.","findings":["No focal deficit","Focal deficit present"],"how":null,"why":null,"whySource":null,"meaning":"A focal neurologic deficit with headache points to a secondary cause — stroke, hemorrhage, or mass lesion — rather than a primary headache, and mandates urgent imaging.","meaningSource":"ai-draft"},{"id":"exam-04","system":"neurologic","maneuver":"Assess pupil size and symmetry.","findings":["Normal, reactive, and symmetric","Asymmetric or a fixed, dilated pupil"],"how":null,"why":"A fixed, dilated pupil suggests uncal herniation from elevated intracranial pressure, a neurosurgical emergency.","whySource":"curated","meaning":"A fixed, dilated pupil suggests uncal herniation from elevated intracranial pressure, a neurosurgical emergency.","meaningSource":"curated"},{"id":"exam-05","system":"eyes","maneuver":"Assess for papilledema on fundoscopic exam.","findings":["Absent","Present"],"how":null,"why":"Papilledema suggests elevated intracranial pressure.","whySource":"curated","meaning":"Papilledema suggests elevated intracranial pressure.","meaningSource":"curated"},{"id":"exam-06","system":"musculoskeletal","maneuver":"Palpate the temporal arteries.","findings":["Nontender","Tender or thickened temporal artery"],"how":null,"why":"A tender or thickened temporal artery in an older adult suggests giant cell arteritis.","whySource":"curated","meaning":"A tender or thickened temporal artery in an older adult suggests giant cell arteritis.","meaningSource":"curated"},{"id":"exam-07","system":"cardiovascular","maneuver":"Measure blood pressure.","findings":["Normotensive","Severely hypertensive"],"how":null,"why":null,"whySource":null,"meaning":"Severe hypertension with headache raises concern for hypertensive emergency with end-organ effects; markedly elevated blood pressure also increases the risk of hemorrhagic causes.","meaningSource":"ai-draft"},{"id":"exam-08","system":"musculoskeletal","maneuver":"Assess neck range of motion and tenderness.","findings":["Normal range of motion, nontender","Decreased range of motion or tenderness"],"how":null,"why":null,"whySource":null,"meaning":"Decreased neck range of motion or nuchal rigidity suggests meningeal irritation — meningitis or subarachnoid hemorrhage — while a supple, nontender neck makes those less likely.","meaningSource":"ai-draft"},{"id":"exam-09","system":"eyes","maneuver":"Assess visual fields and acuity.","findings":["Normal fields and acuity","Visual field cut or reduced acuity"],"how":null,"why":"A visual field cut localizes to the contralateral optic tract or occipital lobe.","whySource":"curated","meaning":"A visual field cut localizes to the contralateral optic tract or occipital lobe.","meaningSource":"curated"},{"id":"exam-10","system":"skin","maneuver":"Inspect the skin for a petechial or purpuric rash.","findings":["No rash","Petechial or purpuric rash"],"how":null,"why":"A petechial or purpuric rash with fever suggests meningococcemia or another vasculitic emergency.","whySource":"curated","meaning":"A petechial or purpuric rash with fever suggests meningococcemia or another vasculitic emergency.","meaningSource":"curated"}],"reviewNeeded":{"whyMissing":9,"howMissing":10}},{"id":"anemia","title":"Anemia (symptomatic or unexplained)","aliases":["low hemoglobin","low hematocrit"],"history":[{"id":"history-01","system":"hematologic","question":"Have you noticed black, tarry stools, red blood in your stool, or vomited blood?","listenFor":["No signs of gastrointestinal bleeding","Melena or hematochezia","Hematemesis"],"why":"Black, tarry stools (melena), hematochezia, or hematemesis indicate gastrointestinal bleeding; melena points to an upper source.","whySource":"curated","meaning":"Black, tarry stools (melena), hematochezia, or hematemesis indicate gastrointestinal bleeding; melena points to an upper source.","meaningSource":"curated"},{"id":"history-02","system":"reproductive","question":"Have your periods been unusually heavy?","listenFor":["Not applicable or normal menses","Heavy menstrual bleeding"],"why":"Heavy menstrual bleeding is a common cause of iron deficiency anemia.","whySource":"curated","meaning":"Heavy menstrual bleeding is a common cause of iron deficiency anemia.","meaningSource":"curated"},{"id":"history-03","system":"hematologic","question":"How is your diet — do you eat enough iron-rich or B12-rich foods, or are you vegan or vegetarian without supplements?","listenFor":["Adequate dietary intake","Poor dietary iron or B12 intake","Vegan or vegetarian diet without supplementation"],"why":"A vegan diet without supplementation risks B12 deficiency with macrocytic anemia.","whySource":"curated","meaning":"A vegan diet without supplementation risks B12 deficiency with macrocytic anemia.","meaningSource":"curated"},{"id":"history-04","system":"general","question":"How severe has your fatigue been — mild, or bad enough to limit your daily activities?","listenFor":["No unusual fatigue","Mild fatigue","Severe fatigue limiting activity"],"why":null,"whySource":null,"meaning":"Fatigue that limits daily activity signals more severe or more acute anemia than mild tiredness. Sudden-onset severe fatigue points toward acute blood loss, while gradual fatigue fits chronic causes like iron deficiency — the tempo narrows the differential.","meaningSource":"ai-draft"},{"id":"history-05","system":"skin","question":"Have your skin or eyes turned yellow, or has your urine looked dark?","listenFor":["Neither","Jaundice","Dark urine"],"why":null,"whySource":null,"meaning":"Jaundice or dark urine with anemia points toward hemolysis — the dark urine may be hemoglobinuria. Check bilirubin, LDH, haptoglobin, reticulocytes, and a smear rather than defaulting to iron studies.","meaningSource":"ai-draft"},{"id":"history-06","system":"genitourinary","question":"Do you have chronic kidney disease?","listenFor":["No known chronic kidney disease","Known chronic kidney disease"],"why":null,"whySource":null,"meaning":"Chronic kidney disease directly causes anemia through reduced erythropoietin production. In a CKD patient, some anemia is expected — the question becomes whether it is worse than baseline or has a superimposed cause such as GI blood loss.","meaningSource":"ai-draft"},{"id":"history-07","system":"hematologic","question":"Have you been diagnosed with cancer?","listenFor":["No known malignancy","Known malignancy"],"why":null,"whySource":null,"meaning":"Known malignancy broadens the differential to anemia of chronic disease, marrow infiltration, chemotherapy effect, or occult bleeding. In a cancer patient, new or worsening anemia should prompt a look for bleeding and a medication review before assuming it is 'just the cancer.'","meaningSource":"ai-draft"},{"id":"history-08","system":"hematologic","question":"Have you noticed easy bruising, or bleeding from your gums or nose?","listenFor":["Neither","Easy bruising","Bleeding gums or epistaxis"],"why":"Easy bruising or mucosal bleeding with anemia suggests pancytopenia or marrow failure.","whySource":"curated","meaning":"Easy bruising or mucosal bleeding with anemia suggests pancytopenia or marrow failure.","meaningSource":"curated"},{"id":"history-09","system":"hematologic","question":"Does anyone in your family have sickle cell disease or thalassemia?","listenFor":["No known family history","Known family history of sickle cell disease or thalassemia"],"why":"Family history of sickle cell disease or thalassemia suggests a hemoglobinopathy.","whySource":"curated","meaning":"Family history of sickle cell disease or thalassemia suggests a hemoglobinopathy.","meaningSource":"curated"},{"id":"history-10","system":"medication","question":"Do you drink alcohol heavily?","listenFor":["No heavy alcohol use","Heavy alcohol use"],"why":null,"whySource":null,"meaning":"Heavy alcohol use raises several causes at once — folate deficiency, liver disease with bleeding risk, and marrow suppression. Macrocytosis in a drinker should prompt folate and B12 levels plus a GI bleeding history.","meaningSource":"ai-draft"},{"id":"history-11","system":"medication","question":"Do you regularly take ibuprofen or another NSAID, or aspirin?","listenFor":["Neither","NSAID use","Aspirin or antiplatelet use"],"why":"NSAIDs and aspirin impair gastric mucosal protection and platelet function, raising gastrointestinal bleeding risk.","whySource":"curated","meaning":"NSAIDs and aspirin impair gastric mucosal protection and platelet function, raising gastrointestinal bleeding risk.","meaningSource":"curated"},{"id":"history-12","system":"neurologic","question":"Have you had numbness or tingling, or trouble with your balance while walking?","listenFor":["Neither","Paresthesias","Gait imbalance"],"why":null,"whySource":null,"meaning":"Numbness, tingling, or gait imbalance with macrocytic anemia points to vitamin B12 deficiency causing subacute combined degeneration of the cord. Treat promptly — delayed treatment can leave permanent neurologic damage — and do not give folate alone before checking B12.","meaningSource":"ai-draft"},{"id":"history-13","system":"musculoskeletal","question":"Have you had surgery or an injury recently?","listenFor":["Neither","Recent surgery","Recent trauma"],"why":null,"whySource":null,"meaning":"Recent surgery or trauma raises acute blood loss as the cause. Compare with prior hemoglobin values and look for ongoing bleeding, since postoperative anemia that keeps falling needs a source found, not just iron.","meaningSource":"ai-draft"},{"id":"history-14","system":"cardiovascular","question":"Have you been short of breath with activity, or had chest pain or palpitations?","listenFor":["Neither","Dyspnea on exertion","Chest pain or palpitations"],"why":"Exertional dyspnea and palpitations reflect reduced oxygen-carrying capacity in anemia.","whySource":"curated","meaning":"Exertional dyspnea and palpitations reflect reduced oxygen-carrying capacity in anemia.","meaningSource":"curated"}],"exam":[{"id":"exam-01","system":"hematologic","maneuver":"Inspect conjunctiva and palmar creases for pallor.","findings":["Normal color","Conjunctival or palmar crease pallor"],"how":null,"why":"Pallor of the conjunctivae, nail beds, or palmar creases suggests anemia.","whySource":"curated","meaning":"Pallor of the conjunctivae, nail beds, or palmar creases suggests anemia.","meaningSource":"curated"},{"id":"exam-02","system":"skin","maneuver":"Inspect skin and sclerae for jaundice.","findings":["Absent","Present"],"how":null,"why":null,"whySource":null,"meaning":"Jaundice on exam corroborates a hemolytic process. Pair it with labs — indirect bilirubin, LDH, haptoglobin, reticulocytes — and examine the spleen, since splenomegaly supports hemolysis or a marrow process.","meaningSource":"ai-draft"},{"id":"exam-03","system":"cardiovascular","maneuver":"Auscultate the heart for tachycardia or a flow murmur.","findings":["Normal rate, no murmur","Tachycardic","Flow murmur present"],"how":null,"why":"A systolic flow murmur can accompany the high-output state of severe anemia.","whySource":"curated","meaning":"A systolic flow murmur can accompany the high-output state of severe anemia.","meaningSource":"curated"},{"id":"exam-04","system":"cardiovascular","maneuver":"Assess orthostatic vital signs when safe.","findings":["Negative orthostatics","Positive orthostatic hypotension"],"how":"Measure blood pressure and heart rate after 5 minutes supine, then at 1 and 3 minutes after standing; a sustained drop of 20 mmHg systolic or 10 mmHg diastolic within 3 minutes is positive.","why":null,"whySource":null,"meaning":"Positive orthostatics — a sustained drop of at least 20 mmHg systolic or 10 mmHg diastolic within 3 minutes of standing — suggest intravascular volume depletion or recent blood loss. In an anemic patient, they argue for an acute bleed or ongoing losses rather than a stable chronic anemia.","meaningSource":"ai-draft"},{"id":"exam-05","system":"ent","maneuver":"Inspect the tongue and lips for glossitis or angular cheilitis.","findings":["Normal oral exam","Glossitis or angular cheilitis"],"how":null,"why":"Glossitis and angular cheilitis suggest B12, iron, or other nutritional deficiency.","whySource":"curated","meaning":"Glossitis and angular cheilitis suggest B12, iron, or other nutritional deficiency.","meaningSource":"curated"},{"id":"exam-06","system":"gastrointestinal","maneuver":"Palpate the abdomen for splenomegaly.","findings":["No splenomegaly","Splenomegaly present"],"how":null,"why":"Splenomegaly suggests portal hypertension, hematologic disease, or systemic infection.","whySource":"curated","meaning":"Splenomegaly suggests portal hypertension, hematologic disease, or systemic infection.","meaningSource":"curated"},{"id":"exam-07","system":"hematologic","maneuver":"Palpate for lymphadenopathy.","findings":["No lymphadenopathy","Lymphadenopathy present"],"how":null,"why":"Lymphadenopathy suggests infection, malignancy, or systemic inflammatory disease.","whySource":"curated","meaning":"Lymphadenopathy suggests infection, malignancy, or systemic inflammatory disease.","meaningSource":"curated"},{"id":"exam-08","system":"gastrointestinal","maneuver":"Perform a rectal examination when indicated.","findings":["Normal, guaiac negative, or deferred as not indicated","Melena or gross blood on examination"],"how":null,"why":"Melena (black, tarry stools) indicates upper gastrointestinal bleeding.","whySource":"curated","meaning":"Melena (black, tarry stools) indicates upper gastrointestinal bleeding.","meaningSource":"curated"},{"id":"exam-09","system":"skin","maneuver":"Inspect skin for petechiae or ecchymosis.","findings":["None","Petechiae or ecchymosis present"],"how":null,"why":"Petechiae or ecchymosis suggest thrombocytopenia or another bleeding diathesis.","whySource":"curated","meaning":"Petechiae or ecchymosis suggest thrombocytopenia or another bleeding diathesis.","meaningSource":"curated"},{"id":"exam-10","system":"neurologic","maneuver":"Assess vibration sense, proprioception, and gait for B12-related neuropathy.","findings":["Normal sensation and gait","Decreased vibration or proprioception, or ataxic gait"],"how":null,"why":"Loss of vibration sense and proprioception with gait ataxia suggests B12 deficiency neuropathy.","whySource":"curated","meaning":"Loss of vibration sense and proprioception with gait ataxia suggests B12 deficiency neuropathy.","meaningSource":"curated"}],"reviewNeeded":{"whyMissing":9,"howMissing":9}},{"id":"alcohol-withdrawal","title":"Alcohol withdrawal","aliases":["delirium tremens","DTs"],"history":[{"id":"history-01","system":"medication","question":"When was your last drink?","listenFor":["More than 7 days since last drink","48 hours to 7 days since last drink","Within the past 48 hours"],"why":"Alcohol withdrawal typically begins 6 to 24 hours after the last drink and peaks at 48 to 96 hours.","whySource":"curated","meaning":"Alcohol withdrawal typically begins 6 to 24 hours after the last drink and peaks at 48 to 96 hours.","meaningSource":"curated"},{"id":"history-02","system":"medication","question":"How much do you typically drink in a day, and how long have you been drinking that much?","listenFor":["Light to moderate use","Heavy daily use","History of severe, long-standing dependence"],"why":null,"whySource":null,"meaning":"Heavier daily intake and longer duration of dependence raise the risk of severe withdrawal, seizures, and delirium tremens, and should drive prophylactic or symptom-triggered benzodiazepine protocols with closer monitoring. Light or moderate use lowers but does not eliminate risk — withdrawal can still occur in binge drinkers.","meaningSource":"ai-draft"},{"id":"history-03","system":"neurologic","question":"Have you ever had a seizure from stopping alcohol before?","listenFor":["No prior withdrawal seizure","Prior withdrawal seizure"],"why":"Prior alcohol withdrawal seizures predict severe withdrawal and guide prophylaxis intensity.","whySource":"curated","meaning":"Prior alcohol withdrawal seizures predict severe withdrawal and guide prophylaxis intensity.","meaningSource":"curated"},{"id":"history-04","system":"neurologic","question":"Have you ever had delirium tremens, or severe confusion and shaking, from stopping alcohol before?","listenFor":["No prior delirium tremens","Prior episode of delirium tremens"],"why":"Prior delirium tremens or alcohol withdrawal seizures predict severe withdrawal and guide prophylaxis intensity.","whySource":"curated","meaning":"Prior delirium tremens or alcohol withdrawal seizures predict severe withdrawal and guide prophylaxis intensity.","meaningSource":"curated"},{"id":"history-05","system":"neurologic","question":"Are you shaking, anxious, or feeling agitated right now?","listenFor":["None of these","Mild tremor or anxiety","Marked agitation"],"why":null,"whySource":null,"meaning":"Tremor, anxiety, and agitation are the earliest signs of alcohol withdrawal and anchor symptom-triggered scoring (CIWA-Ar); marked agitation signals moderate-to-severe withdrawal needing prompt benzodiazepine treatment. Absence of symptoms may simply mean the patient has not yet entered the withdrawal window.","meaningSource":"ai-draft"},{"id":"history-06","system":"psychiatric","question":"Have you been seeing or hearing things that aren't there?","listenFor":["No hallucinations","Auditory or visual hallucinations with intact orientation","Hallucinations with disorientation"],"why":null,"whySource":null,"meaning":"Hallucinations with intact orientation are typical of alcohol withdrawal (alcoholic hallucinosis) and usually respond to benzodiazepines, but hallucinations with disorientation suggest delirium tremens, a medical emergency with significant mortality. New hallucinations should also prompt consideration of intoxication, other drugs, or primary psychosis.","meaningSource":"ai-draft"},{"id":"history-07","system":"gastrointestinal","question":"Have you had nausea or vomiting?","listenFor":["Neither","Nausea","Vomiting"],"why":null,"whySource":null,"meaning":"Nausea and vomiting are early autonomic features of withdrawal and contribute to dehydration and electrolyte loss. Persistent vomiting in a chronic drinker also raises concern for gastritis, pancreatitis, or GI bleeding — evaluate rather than assuming it is all withdrawal.","meaningSource":"ai-draft"},{"id":"history-08","system":"hematologic","question":"Have you been eating regular meals recently?","listenFor":["Adequate nutrition","Poor nutrition or malnourishment"],"why":null,"whySource":null,"meaning":"Poor nutrition in a chronic drinker flags thiamine deficiency and Wernicke's risk — give thiamine before or with any glucose. Malnourishment also predicts worse withdrawal outcomes and electrolyte derangements (magnesium, phosphate) that lower the seizure threshold.","meaningSource":"ai-draft"},{"id":"history-09","system":"medication","question":"Are you taking any benzodiazepines or opioids?","listenFor":["Neither","Concurrent benzodiazepine use","Concurrent opioid use"],"why":null,"whySource":null,"meaning":"Concurrent benzodiazepine use changes the picture — benzodiazepines cross-tolerate with alcohol and their withdrawal is similarly dangerous, requiring a coordinated taper. Concurrent opioid use adds an opioid withdrawal syndrome (highly symptomatic but less dangerous) and changes analgesia and sedation planning.","meaningSource":"ai-draft"},{"id":"history-10","system":"gastrointestinal","question":"Do you have cirrhosis or another liver disease?","listenFor":["No known liver disease","Known cirrhosis or liver disease"],"why":null,"whySource":null,"meaning":"Known cirrhosis alters withdrawal management: long half-life benzodiazepines accumulate in liver failure, so shorter-acting agents (lorazepam, oxazepam) are preferred. Cirrhosis also raises the stakes for GI bleeding, hepatic encephalopathy (which mimics withdrawal), and coagulopathy.","meaningSource":"ai-draft"},{"id":"history-11","system":"medication","question":"Have you been trying to cut down on your own, on alcohol or a benzodiazepine, before coming in?","listenFor":["No recent self-tapering","Recent self-tapering or dose reduction"],"why":null,"whySource":null,"meaning":"Recent self-tapering or dose reduction explains the timing of withdrawal symptoms and confirms the dependence pattern. It also identifies a motivated patient — an opportunity for addiction-medicine referral — but unsupervised tapers carry seizure risk, so medical supervision is still needed.","meaningSource":"ai-draft"},{"id":"history-12","system":"psychiatric","question":"Have you had any thoughts of harming yourself?","listenFor":["No suicidal ideation","Suicidal ideation present"],"why":null,"whySource":null,"meaning":"Alcohol withdrawal and intoxication markedly raise suicide risk, so every withdrawal presentation needs a safety assessment. Suicidal ideation present requires one-to-one precautions and psychiatric involvement — intoxication or withdrawal is never a reason to skip the safety screen.","meaningSource":"ai-draft"},{"id":"history-13","system":"gastrointestinal","question":"Have you been eating and drinking normally in the days before you came in?","listenFor":["Normal oral intake","Poor oral intake preceding admission"],"why":null,"whySource":null,"meaning":"Poor oral intake in the days before admission predicts dehydration, electrolyte depletion, and a higher seizure risk during withdrawal, and helps explain an early or severe presentation. Normal intake lowers but does not eliminate these risks — labs still guide repletion.","meaningSource":"ai-draft"}],"exam":[{"id":"exam-01","system":"neurologic","maneuver":"Assess for tremor.","findings":["Absent","Mild tremor","Coarse or marked tremor"],"how":null,"why":null,"whySource":null,"meaning":"Tremor is the hallmark early sign of alcohol withdrawal: mild tremor supports early withdrawal managed with symptom-triggered benzodiazepines, while coarse or marked tremor suggests more severe withdrawal needing aggressive treatment and monitoring. Absent tremor does not rule out withdrawal, especially early or late in the course.","meaningSource":"ai-draft"},{"id":"exam-02","system":"skin","maneuver":"Assess for diaphoresis.","findings":["Absent","Present"],"how":null,"why":null,"whySource":null,"meaning":"Diaphoresis reflects the autonomic hyperactivity of withdrawal and adds to the severity score; its presence supports active withdrawal needing treatment. Absence is common early and does not exclude withdrawal — combine with tremor, agitation, and vitals for the full picture.","meaningSource":"ai-draft"},{"id":"exam-03","system":"cardiovascular","maneuver":"Assess vital sign stability.","findings":["Normal vital signs","Tachycardic or hypertensive","Severe autonomic instability"],"how":null,"why":"Severe autonomic instability with agitation suggests impending delirium tremens.","whySource":"curated","meaning":"Severe autonomic instability with agitation suggests impending delirium tremens.","meaningSource":"curated"},{"id":"exam-04","system":"neurologic","maneuver":"Assess orientation.","findings":["Oriented to person, place, and time","Disoriented"],"how":null,"why":null,"whySource":null,"meaning":"Disorientation marks progression from simple withdrawal toward delirium tremens, which carries significant mortality and requires ICU-level care with high-dose benzodiazepines. Intact orientation keeps the patient in the milder spectrum but does not guarantee they will stay there — withdrawal can escalate over hours to days.","meaningSource":"ai-draft"},{"id":"exam-05","system":"psychiatric","maneuver":"Assess agitation level.","findings":["Calm and cooperative","Agitated","Combative"],"how":null,"why":null,"whySource":null,"meaning":"Agitation level stratifies withdrawal severity: a calm, cooperative patient may be managed on a medical floor with symptom-triggered dosing, while agitation — and especially combativeness — signals severe withdrawal needing escalating benzodiazepine doses, often in a monitored setting, plus safety precautions.","meaningSource":"ai-draft"},{"id":"exam-06","system":"neurologic","maneuver":"Assess for hallucinations.","findings":["None observed","Hallucinations observed"],"how":null,"why":null,"whySource":null,"meaning":"Observed hallucinations confirm the withdrawal syndrome is active and usually respond to benzodiazepine treatment. If accompanied by disorientation or autonomic instability, they signal delirium tremens rather than simple alcoholic hallucinosis — distinguish the two because DTs demand ICU care.","meaningSource":"ai-draft"},{"id":"exam-07","system":"neurologic","maneuver":"Assess for nystagmus, ataxia, or ophthalmoplegia suggesting Wernicke encephalopathy.","findings":["None of these","Nystagmus or ataxia","Ophthalmoplegia"],"how":null,"why":"Nystagmus or ophthalmoplegia with ataxia and confusion is the classic triad of Wernicke encephalopathy from thiamine deficiency.","whySource":"curated","meaning":"Nystagmus or ophthalmoplegia with ataxia and confusion is the classic triad of Wernicke encephalopathy from thiamine deficiency.","meaningSource":"curated"},{"id":"exam-08","system":"skin","maneuver":"Inspect for stigmata of chronic liver disease.","findings":["No stigmata of liver disease","Spider angiomata or jaundice"],"how":null,"why":"Spider angiomas, palmar erythema, and caput medusae are cutaneous stigmata of chronic liver disease.","whySource":"curated","meaning":"Spider angiomas, palmar erythema, and caput medusae are cutaneous stigmata of chronic liver disease.","meaningSource":"curated"},{"id":"exam-09","system":"neurologic","maneuver":"Assess for active or recent seizure activity.","findings":["None observed","Active or recent seizure activity"],"how":null,"why":null,"whySource":null,"meaning":"Alcohol withdrawal seizures are a red flag for severe dependence and predict delirium tremens; they are treated with benzodiazepines, not standard antiepileptics. A first seizure in this setting still warrants evaluation for other causes (head trauma, metabolic derangement) rather than automatic attribution to withdrawal.","meaningSource":"ai-draft"},{"id":"exam-10","system":"skin","maneuver":"Inspect the skin for bruising or needle marks.","findings":["None","Bruising or needle marks present"],"how":null,"why":"Needle track marks suggest intravenous drug use and raise concern for bacteremia, endocarditis, or soft tissue infection.","whySource":"curated","meaning":"Needle track marks suggest intravenous drug use and raise concern for bacteremia, endocarditis, or soft tissue infection.","meaningSource":"curated"}],"reviewNeeded":{"whyMissing":16,"howMissing":10}},{"id":"acute-pancreatitis","title":"Acute pancreatitis","aliases":["pancreatitis"],"history":[{"id":"history-01","system":"gastrointestinal","question":"Where is your belly pain, and does it spread through to your back?","listenFor":["Epigastric pain radiating to the back","Epigastric pain without radiation","Diffuse abdominal pain"],"why":"Epigastric pain radiating to the back is classic for acute pancreatitis.","whySource":"curated","meaning":"Epigastric pain radiating to the back is classic for acute pancreatitis.","meaningSource":"curated"},{"id":"history-02","system":"medication","question":"Did you drink heavily or binge drink before this pain started?","listenFor":["No heavy alcohol use","Heavy or binge alcohol use preceding symptoms"],"why":"Heavy alcohol use and gallstones are the two leading causes of acute pancreatitis.","whySource":"curated","meaning":"Heavy alcohol use and gallstones are the two leading causes of acute pancreatitis.","meaningSource":"curated"},{"id":"history-03","system":"gastrointestinal","question":"Do you have any prior episodes of abdominal pain that occurs specifically after you eat, or have you been told you have gallstones?","listenFor":["None known","Known gallstones or biliary colic"],"why":null,"whySource":null,"meaning":"Postprandial pain or known gallstones points to gallstone pancreatitis, the most common cause, which makes a gallbladder ultrasound the key next test and cholecystectomy the likely definitive treatment; no biliary history keeps alcohol, hypertriglyceridemia, and drug causes on the table.","meaningSource":"ai-draft"},{"id":"history-04","system":"endocrine","question":"Have you been told you have high triglycerides?","listenFor":["No known hypertriglyceridemia","Known hypertriglyceridemia"],"why":"Severe hypertriglyceridemia (typically over 1000 mg/dL) can precipitate pancreatitis.","whySource":"curated","meaning":"Severe hypertriglyceridemia (typically over 1000 mg/dL) can precipitate pancreatitis.","meaningSource":"curated"},{"id":"history-05","system":"medication","question":"Have you had a procedure recently to look at your bile ducts, called an ERCP?","listenFor":["No recent ERCP","Recent ERCP procedure"],"why":"ERCP can precipitate post-procedure pancreatitis.","whySource":"curated","meaning":"ERCP can precipitate post-procedure pancreatitis.","meaningSource":"curated"},{"id":"history-06","system":"medication","question":"Have you started a new medication recently, like a weight-loss or diabetes injection, an immune-suppressing drug, or a seizure medication?","listenFor":["No new pancreatitis-associated medication","New pancreatitis-associated medication started"],"why":"GLP-1 agonists, immunosuppressants, and some antiepileptics are associated with pancreatitis.","whySource":"curated","meaning":"GLP-1 agonists, immunosuppressants, and some antiepileptics are associated with pancreatitis.","meaningSource":"curated"},{"id":"history-07","system":"gastrointestinal","question":"Have you been vomiting along with the pain?","listenFor":["No vomiting","Vomiting"],"why":null,"whySource":null,"meaning":"Vomiting is common in pancreatitis from ileus and inflammation, but persistent vomiting raises concern for gastric outlet involvement, developing ileus, or a complication such as a pseudocyst compressing nearby structures; it also worsens dehydration and electrolyte loss, so antiemetic and fluid management need attention.","meaningSource":"ai-draft"},{"id":"history-08","system":"infectious","question":"Have you had a fever along with the pain?","listenFor":["No fever","Fever"],"why":null,"whySource":null,"meaning":"Fever in pancreatitis can simply reflect systemic inflammation, but it also raises concern for infected pancreatic necrosis — the most dangerous complication — especially if fever persists beyond the first days or appears later in the course; early fever alone should not trigger empiric antibiotics, but late or persistent fever warrants evaluation for infection.","meaningSource":"ai-draft"},{"id":"history-09","system":"hematologic","question":"Have you lost weight without trying, or been told you have a mass on your pancreas?","listenFor":["Neither","Unintentional weight loss","Known pancreatic mass or malignancy"],"why":null,"whySource":null,"meaning":"Unintentional weight loss or a known pancreatic mass raises concern for a malignant obstruction of the pancreatic duct causing the pancreatitis, which changes the workup toward malignancy staging rather than routine gallstone management; neither keeps the usual gallstone or alcohol causes off the table in a first episode.","meaningSource":"ai-draft"},{"id":"history-10","system":"gastrointestinal","question":"Have you had pancreatitis before?","listenFor":["First episode","Recurrent episodes"],"why":null,"whySource":null,"meaning":"Recurrent episodes point to an ongoing underlying cause — untreated gallstones, continued alcohol use, hypertriglyceridemia, or a genetic/structural cause — and warrant an etiology-focused workup (including sphincter of Oddi or pancreas divisum evaluation if unexplained); a first episode is managed more straightforwardly with the standard gallstone and alcohol screen.","meaningSource":"ai-draft"},{"id":"history-11","system":"gastrointestinal","question":"Does anyone in your family have a history of pancreatitis?","listenFor":["No known family history","Known family history of pancreatitis"],"why":null,"whySource":null,"meaning":"A family history of pancreatitis suggests a hereditary cause such as PRSS1 or CFTR variants, especially with recurrent episodes in a younger patient without alcohol or gallstone risk; it should prompt genetic counseling consideration after common causes are excluded.","meaningSource":"ai-draft"},{"id":"history-12","system":"musculoskeletal","question":"Have you had a recent injury to your abdomen?","listenFor":["No recent abdominal trauma","Recent abdominal trauma"],"why":null,"whySource":null,"meaning":"Recent abdominal trauma can cause pancreatitis from direct pancreatic injury or duct disruption, a mechanism easily missed when gallstones and alcohol dominate the differential; a positive history should prompt imaging focused on ductal integrity, since duct disruption may need endoscopic or surgical repair.","meaningSource":"ai-draft"},{"id":"history-13","system":"endocrine","question":"Do you have diabetes?","listenFor":["No known diabetes","Known diabetes"],"why":null,"whySource":null,"meaning":"Diabetes is relevant in two directions: new or worsening diabetes can follow pancreatic injury or signal an underlying pancreatic problem, and hypertriglyceridemia-related pancreatitis often coexists with diabetes; it also affects fluid and insulin management during the admission.","meaningSource":"ai-draft"}],"exam":[{"id":"exam-01","system":"gastrointestinal","maneuver":"Palpate the abdomen for epigastric tenderness.","findings":["Nontender","Epigastric tenderness","Diffuse tenderness with guarding or rigidity"],"how":null,"why":"Guarding, rebound, or rigidity on palpation suggests peritonitis.","whySource":"curated","meaning":"Guarding, rebound, or rigidity on palpation suggests peritonitis.","meaningSource":"curated"},{"id":"exam-02","system":"gastrointestinal","maneuver":"Auscultate bowel sounds.","findings":["Normal bowel sounds","Hypoactive or absent bowel sounds"],"how":null,"why":null,"whySource":null,"meaning":"Hypoactive or absent bowel sounds reflect the ileus that commonly accompanies pancreatic inflammation, which supports the diagnosis and explains nausea and distention; persistent absence raises concern for a more severe or complicated course rather than a mild self-limited episode.","meaningSource":"ai-draft"},{"id":"exam-03","system":"skin","maneuver":"Inspect skin and sclerae for jaundice.","findings":["Absent","Present"],"how":null,"why":null,"whySource":null,"meaning":"Jaundice suggests a biliary cause — a gallstone impacted in the common bile duct — which changes management toward urgent biliary imaging and possible ERCP if cholangitis develops; absent jaundice keeps gallstone, alcohol, and metabolic causes equally in play.","meaningSource":"ai-draft"},{"id":"exam-04","system":"skin","maneuver":"Inspect the flanks and periumbilical area for Grey Turner or Cullen sign.","findings":["Absent","Present"],"how":null,"why":"Flank ecchymosis (Grey Turner sign) or periumbilical ecchymosis (Cullen sign) suggests retroperitoneal hemorrhage, as in severe pancreatitis.","whySource":"curated","meaning":"Flank ecchymosis (Grey Turner sign) or periumbilical ecchymosis (Cullen sign) suggests retroperitoneal hemorrhage, as in severe pancreatitis.","meaningSource":"curated"},{"id":"exam-05","system":"general","maneuver":"Assess hemodynamic stability.","findings":["Normotensive, stable","Tachycardic","Hypotensive or in shock"],"how":null,"why":null,"whySource":null,"meaning":"Hemodynamic stability stratifies severity: tachycardia and hypotension signal third-spacing, systemic inflammatory response, or developing necrotizing pancreatitis and demand aggressive fluid resuscitation and close monitoring; stable vitals suggest a milder episode that may be managed with more modest support.","meaningSource":"ai-draft"},{"id":"exam-06","system":"general","maneuver":"Assess for fever or toxic appearance.","findings":["Well-appearing, afebrile","Febrile or toxic-appearing"],"how":null,"why":"A toxic appearance with abnormal vital signs suggests severe systemic illness or sepsis.","whySource":"curated","meaning":"A toxic appearance with abnormal vital signs suggests severe systemic illness or sepsis.","meaningSource":"curated"},{"id":"exam-07","system":"respiratory","maneuver":"Assess oxygenation for a pulmonary complication.","findings":["Normal oxygenation","Hypoxemic"],"how":null,"why":null,"whySource":null,"meaning":"Hypoxemia is an early warning sign of severe pancreatitis — from systemic inflammation causing acute lung injury or ARDS, pleural effusions, or atelectasis — and its presence moves the patient toward ICU-level monitoring; normal oxygenation is reassuring but does not guarantee a mild course.","meaningSource":"ai-draft"},{"id":"exam-08","system":"gastrointestinal","maneuver":"Assess for abdominal distention.","findings":["No distention","Distention present"],"how":null,"why":null,"whySource":null,"meaning":"Abdominal distention in pancreatitis usually reflects ileus and fluid third-spacing, but marked or worsening distention raises concern for complications such as ascites, a pseudocyst, or intra-abdominal hypertension; it should prompt re-examination and imaging if it progresses.","meaningSource":"ai-draft"},{"id":"exam-09","system":"gastrointestinal","maneuver":"Assess for a Murphy sign.","findings":["Negative","Positive"],"how":"Hook your fingers under the right costal margin at the midclavicular line and ask the patient to inhale deeply; abrupt inspiratory arrest from pain is a positive Murphy sign.","why":"A positive Murphy sign (inspiratory arrest on palpation of the right upper quadrant) suggests acute cholecystitis.","whySource":"curated","meaning":"A positive Murphy sign (inspiratory arrest on palpation of the right upper quadrant) suggests acute cholecystitis.","meaningSource":"curated"},{"id":"exam-10","system":"neurologic","maneuver":"Assess mental status.","findings":["Alert and oriented","Confused or altered"],"how":null,"why":null,"whySource":null,"meaning":"Altered mental status in pancreatitis signals severe systemic disease — hypoperfusion, hypoxemia, or metabolic derangement — and marks a patient who needs escalation of care, often to the ICU; a clear sensorium is reassuring for a milder course.","meaningSource":"ai-draft"}],"reviewNeeded":{"whyMissing":14,"howMissing":9}},{"id":"venous-thromboembolism","title":"Venous thromboembolism (DVT/PE)","aliases":["deep vein thrombosis","pulmonary embolism"],"history":[{"id":"history-01","system":"cardiovascular","question":"Is one of your legs more swollen than the other?","listenFor":["No leg swelling","Unilateral leg swelling"],"why":"New unilateral leg swelling suggests deep vein thrombosis.","whySource":"curated","meaning":"New unilateral leg swelling suggests deep vein thrombosis.","meaningSource":"curated"},{"id":"history-02","system":"cardiovascular","question":"Do you have pain or tenderness in your calf?","listenFor":["No calf pain or tenderness","Calf pain or tenderness"],"why":"Calf pain or tenderness with swelling suggests deep vein thrombosis.","whySource":"curated","meaning":"Calf pain or tenderness with swelling suggests deep vein thrombosis.","meaningSource":"curated"},{"id":"history-03","system":"respiratory","question":"Do you have any sharp chest pain that's worse when you breathe in?","listenFor":["No pleuritic chest pain","Pleuritic chest pain"],"why":"Pleuritic chest pain with sudden dyspnea suggests pulmonary embolism.","whySource":"curated","meaning":"Pleuritic chest pain with sudden dyspnea suggests pulmonary embolism.","meaningSource":"curated"},{"id":"history-04","system":"respiratory","question":"Did your shortness of breath come on gradually, or suddenly?","listenFor":["No dyspnea","Gradual dyspnea","Sudden-onset dyspnea"],"why":"Sudden-onset dyspnea suggests pulmonary embolism or pneumothorax.","whySource":"curated","meaning":"Sudden-onset dyspnea suggests pulmonary embolism or pneumothorax.","meaningSource":"curated"},{"id":"history-05","system":"respiratory","question":"Have you coughed up any blood?","listenFor":["No hemoptysis","Hemoptysis"],"why":"Hemoptysis with pleuritic pain and dyspnea suggests pulmonary infarction from embolism.","whySource":"curated","meaning":"Hemoptysis with pleuritic pain and dyspnea suggests pulmonary infarction from embolism.","meaningSource":"curated"},{"id":"history-06","system":"neurologic","question":"Have you felt like you were going to pass out, or did you actually pass out?","listenFor":["Neither","Presyncope","Syncope"],"why":null,"whySource":null,"meaning":"Syncope or presyncope in suspected pulmonary embolism suggests a large clot burden with obstructive shock or right-ventricular strain — a high-risk feature that escalates urgency and monitoring.","meaningSource":"ai-draft"},{"id":"history-07","system":"functional","question":"Have you had surgery or been hospitalized recently?","listenFor":["Neither","Recent surgery","Recent hospitalization"],"why":null,"whySource":null,"meaning":"Recent surgery or hospitalization with immobilization is a major provoking factor for venous thromboembolism; it raises pretest probability and counts toward clinical prediction scores.","meaningSource":"ai-draft"},{"id":"history-08","system":"functional","question":"Have you been immobile for a long stretch, or traveled on a trip longer than four hours recently?","listenFor":["Neither","Prolonged immobilization","Long-distance travel over four hours"],"why":"Prolonged travel over 4 hours is a provoking risk factor for venous thromboembolism.","whySource":"curated","meaning":"Prolonged travel over 4 hours is a provoking risk factor for venous thromboembolism.","meaningSource":"curated"},{"id":"history-09","system":"hematologic","question":"Do you have an active cancer diagnosis?","listenFor":["No active malignancy","Active malignancy"],"why":null,"whySource":null,"meaning":"Active cancer is a strong prothrombotic risk factor that raises pretest probability for VTE and influences both the choice and duration of anticoagulation.","meaningSource":"ai-draft"},{"id":"history-10","system":"cardiovascular","question":"Have you had a blood clot in your leg or lung before?","listenFor":["No known prior VTE","Known prior deep vein thrombosis or pulmonary embolism"],"why":null,"whySource":null,"meaning":"A prior deep vein thrombosis or pulmonary embolism is one of the strongest predictors of recurrence; it substantially raises pretest probability and lowers the threshold for imaging.","meaningSource":"ai-draft"},{"id":"history-11","system":"reproductive","question":"Are you on hormone therapy or birth control pills, or currently pregnant or recently gave birth?","listenFor":["None of these","Hormone therapy or oral contraceptive use","Pregnant or postpartum"],"why":null,"whySource":null,"meaning":"Estrogen exposure (oral contraceptives, hormone therapy) and pregnancy or the postpartum period are prothrombotic states that raise VTE risk and pretest probability, and they affect anticoagulant choice.","meaningSource":"ai-draft"},{"id":"history-12","system":"hematologic","question":"Have you been diagnosed with a clotting disorder, or does anyone in your family have a history of blood clots?","listenFor":["Neither","Known thrombophilia","Family history of venous thromboembolism"],"why":"Thrombophilia raises the risk of recurrent venous thromboembolism.","whySource":"curated","meaning":"Thrombophilia raises the risk of recurrent venous thromboembolism.","meaningSource":"curated"},{"id":"history-13","system":"medication","question":"Do you currently have, or did you recently have, a central line or PICC line?","listenFor":["No central venous catheter","Current or recent central venous catheter"],"why":"A central venous catheter is a risk factor for upper extremity deep vein thrombosis.","whySource":"curated","meaning":"A central venous catheter is a risk factor for upper extremity deep vein thrombosis.","meaningSource":"curated"},{"id":"history-14","system":"musculoskeletal","question":"Have you had a recent leg injury, or are you in a cast or brace?","listenFor":["Neither","Recent leg trauma","Recent cast or immobilization device"],"why":"Limb immobilization in a cast raises deep vein thrombosis risk.","whySource":"curated","meaning":"Limb immobilization in a cast raises deep vein thrombosis risk.","meaningSource":"curated"}],"exam":[{"id":"exam-01","system":"cardiovascular","maneuver":"Compare leg circumference for asymmetric swelling.","findings":["Symmetric legs","Unilateral swelling"],"how":null,"why":null,"whySource":null,"meaning":"Asymmetric leg swelling is the cardinal bedside sign of deep vein thrombosis; symmetric legs make DVT less likely but do not exclude it, especially with bilateral disease.","meaningSource":"ai-draft"},{"id":"exam-02","system":"cardiovascular","maneuver":"Palpate the calf for tenderness or a cord.","findings":["None","Tenderness","Palpable cord"],"how":null,"why":"Unilateral calf swelling, tenderness, or a palpable cord suggests deep vein thrombosis.","whySource":"curated","meaning":"Unilateral calf swelling, tenderness, or a palpable cord suggests deep vein thrombosis.","meaningSource":"curated"},{"id":"exam-03","system":"skin","maneuver":"Assess the leg for warmth and erythema to help distinguish DVT from cellulitis.","findings":["Neither","Warmth and erythema present"],"how":null,"why":null,"whySource":null,"meaning":"Warmth and erythema favor cellulitis but can also occur with DVT, so the two often coexist in the differential — the distinction directs initial treatment (antibiotics versus anticoagulation), and ultrasound is frequently needed to settle it.","meaningSource":"ai-draft"},{"id":"exam-04","system":"cardiovascular","maneuver":"Assess heart rate.","findings":["Normal rate","Tachycardic"],"how":null,"why":null,"whySource":null,"meaning":"Tachycardia is both a clinical prediction criterion and a marker of PE severity, reflecting the cardiopulmonary strain of the clot burden.","meaningSource":"ai-draft"},{"id":"exam-05","system":"respiratory","maneuver":"Assess oxygen saturation.","findings":["Normal saturation","Hypoxemic"],"how":null,"why":null,"whySource":null,"meaning":"Hypoxemia suggests pulmonary embolism with ventilation-perfusion mismatch and gauges severity; normal oxygen saturation does not rule out PE.","meaningSource":"ai-draft"},{"id":"exam-06","system":"general","maneuver":"Assess hemodynamic stability.","findings":["Normotensive","Hypotensive or in shock"],"how":null,"why":null,"whySource":null,"meaning":"Hypotension or shock defines high-risk (massive) pulmonary embolism with obstructive physiology — an emergency that shifts management toward reperfusion options and ICU care.","meaningSource":"ai-draft"},{"id":"exam-07","system":"cardiovascular","maneuver":"Assess jugular venous pressure and heart sounds for right heart strain.","findings":["Normal jugular venous pressure and heart sounds","Elevated jugular venous pressure or a loud pulmonic component of S2"],"how":"With the patient reclined at 30 to 45 degrees, identify the highest point of internal jugular venous pulsation and measure its vertical distance above the sternal angle.","why":"A loud pulmonic component of S2 with elevated jugular venous pressure suggests right heart strain from pulmonary embolism.","whySource":"curated","meaning":"A loud pulmonic component of S2 with elevated jugular venous pressure suggests right heart strain from pulmonary embolism.","meaningSource":"curated"},{"id":"exam-08","system":"respiratory","maneuver":"Auscultate the lungs for focal findings.","findings":["Clear bilaterally","Focal findings, such as a pleural rub or decreased breath sounds"],"how":null,"why":"A pleural friction rub suggests pulmonary infarction or pleural inflammation.","whySource":"curated","meaning":"A pleural friction rub suggests pulmonary infarction or pleural inflammation.","meaningSource":"curated"},{"id":"exam-09","system":"skin","maneuver":"Assess for cyanosis.","findings":["Absent","Present"],"how":null,"why":null,"whySource":null,"meaning":"Cyanosis signals severe hypoxemia and a large physiologic burden from the embolism — a bedside marker of a high-risk presentation.","meaningSource":"ai-draft"},{"id":"exam-10","system":"neurologic","maneuver":"Assess mental status and perfusion.","findings":["Alert with good perfusion","Altered mental status or poor perfusion"],"how":null,"why":null,"whySource":null,"meaning":"Altered mental status or poor perfusion in suspected PE indicates shock — concerning for massive PE with obstructive physiology — and demands immediate resuscitation and escalation.","meaningSource":"ai-draft"}],"reviewNeeded":{"whyMissing":12,"howMissing":9}},{"id":"asthma-exacerbation","title":"Asthma exacerbation","aliases":["asthma attack","reactive airway"],"history":[{"id":"history-01","system":"respiratory","question":"Did anything seem to trigger this — an allergen, a cold, or exercise?","listenFor":["No clear trigger identified","Known allergen exposure","Viral upper respiratory infection","Exercise-induced"],"why":null,"whySource":null,"meaning":"Identifying the trigger shapes both treatment and prevention — a viral URI is the most common precipitant and supports systemic steroids, while allergen or exercise triggers point to avoidance strategies and controller escalation. No clear trigger with severe symptoms should raise concern for an alternative diagnosis.","meaningSource":"ai-draft"},{"id":"history-02","system":"medication","question":"Do you have a known sensitivity to aspirin or NSAIDs like ibuprofen?","listenFor":["No known sensitivity","Known NSAID or aspirin sensitivity"],"why":"Aspirin or NSAID sensitivity can trigger severe bronchospasm (aspirin-exacerbated respiratory disease).","whySource":"curated","meaning":"Aspirin or NSAID sensitivity can trigger severe bronchospasm (aspirin-exacerbated respiratory disease).","meaningSource":"curated"},{"id":"history-03","system":"respiratory","question":"Do you take a daily controller inhaler for your asthma, and has it been keeping you well controlled?","listenFor":["Well-controlled on a controller medication","Poorly controlled, frequent rescue inhaler use","No controller medication prescribed"],"why":null,"whySource":null,"meaning":"Poor baseline control or no controller medication predicts a more severe exacerbation and a higher likelihood of needing systemic steroids or admission. Frequent rescue inhaler use marks uncontrolled asthma that needs step-up controller therapy after the acute episode.","meaningSource":"ai-draft"},{"id":"history-04","system":"respiratory","question":"Have you ever been hospitalized or put on a breathing machine for an asthma attack before?","listenFor":["No prior severe exacerbation","Prior hospitalization without ICU admission","Prior ICU admission or intubation"],"why":null,"whySource":null,"meaning":"A prior ICU admission or intubation for asthma is the strongest predictor of a life-threatening attack — these patients can deteriorate rapidly and silently. A positive history lowers the threshold for ICU-level monitoring even when they initially look well.","meaningSource":"ai-draft"},{"id":"history-05","system":"medication","question":"How often have you been using your rescue inhaler?","listenFor":["Fewer than twice a week","Daily use","Using the rescue inhaler more than every few hours currently"],"why":null,"whySource":null,"meaning":"Escalating rescue inhaler use quantifies both severity and control — needing it every few hours signals a severe exacerbation that will likely require systemic steroids, while use less than twice weekly suggests well-controlled baseline disease.","meaningSource":"ai-draft"},{"id":"history-06","system":"respiratory","question":"Are you able to speak in full sentences right now, or do you have to stop and catch your breath?","listenFor":["Able to speak in full sentences","Speaks in phrases","Speaks in single words or unable to speak"],"why":"Speaking only in single words marks a severe asthma exacerbation.","whySource":"curated","meaning":"Speaking only in single words marks a severe asthma exacerbation.","meaningSource":"curated"},{"id":"history-07","system":"respiratory","question":"Have you been waking up at night because of your asthma?","listenFor":["No nighttime awakening","Occasional nighttime awakening","Frequent nighttime awakening"],"why":null,"whySource":null,"meaning":"Nighttime awakening is a guideline marker of asthma control — frequent nocturnal symptoms mean the asthma is uncontrolled even between exacerbations and the controller regimen needs stepping up. Its absence supports milder, better-controlled disease.","meaningSource":"ai-draft"},{"id":"history-08","system":"respiratory","question":"Do you feel tightness in your chest?","listenFor":["No chest tightness","Chest tightness"],"why":null,"whySource":null,"meaning":"Chest tightness reflects active bronchospasm and tracks with exacerbation severity — but new or atypical chest pain during an attack should also prompt consideration of pneumothorax or cardiac ischemia. Worsening tightness despite treatment suggests the exacerbation is not responding.","meaningSource":"ai-draft"},{"id":"history-09","system":"medication","question":"Do you smoke, or are you regularly around someone else's smoke?","listenFor":["No smoke exposure","Active smoking or secondhand smoke exposure"],"why":null,"whySource":null,"meaning":"Tobacco smoke worsens asthma control, blunts corticosteroid responsiveness, and in older smokers raises concern for asthma–COPD overlap. Any exposure should prompt cessation counseling as part of the exacerbation plan, not just acute treatment.","meaningSource":"ai-draft"},{"id":"history-10","system":"medication","question":"Have you taken a course of oral steroids for your asthma recently?","listenFor":["No recent oral steroid course","Recent oral steroid course"],"why":null,"whySource":null,"meaning":"A recent oral steroid course marks frequently exacerbating, poorly controlled asthma — and relapse shortly after finishing suggests the current regimen is failing and needs escalation. Repeated courses also raise concern for steroid side effects including adrenal suppression.","meaningSource":"ai-draft"},{"id":"history-11","system":"skin","question":"Did you break out in hives or notice facial swelling along with this episode?","listenFor":["Neither","Hives","Facial swelling"],"why":"Hives with facial swelling or throat tightness after an exposure suggests anaphylaxis, which can rapidly obstruct the airway.","whySource":"curated","meaning":"Hives with facial swelling or throat tightness after an exposure suggests anaphylaxis, which can rapidly obstruct the airway.","meaningSource":"curated"},{"id":"history-12","system":"ent","question":"Does it feel like your throat is tight, or has your voice changed?","listenFor":["Neither","Throat tightness","Voice change"],"why":"Throat tightness or voice change suggests upper airway edema or obstruction rather than bronchospasm alone.","whySource":"curated","meaning":"Throat tightness or voice change suggests upper airway edema or obstruction rather than bronchospasm alone.","meaningSource":"curated"}],"exam":[{"id":"exam-01","system":"respiratory","maneuver":"Assess work of breathing and ability to speak in full sentences.","findings":["Normal work of breathing, speaks in full sentences","Accessory muscle use","Unable to speak in full sentences"],"how":null,"why":"Inability to speak in full sentences marks severe respiratory distress or fatigue.","whySource":"curated","meaning":"Inability to speak in full sentences marks severe respiratory distress or fatigue.","meaningSource":"curated"},{"id":"exam-02","system":"respiratory","maneuver":"Auscultate for wheeze and air movement.","findings":["Normal air entry, no wheeze","Wheeze with adequate air movement","Minimal air movement, silent chest"],"how":null,"why":"A silent chest with minimal air movement signals severe airflow obstruction and impending respiratory failure.","whySource":"curated","meaning":"A silent chest with minimal air movement signals severe airflow obstruction and impending respiratory failure.","meaningSource":"curated"},{"id":"exam-03","system":"respiratory","maneuver":"Assess oxygen saturation.","findings":["Normal saturation","Mildly hypoxemic","Severely hypoxemic"],"how":null,"why":null,"whySource":null,"meaning":"Oxygen saturation quantifies exacerbation severity — significant hypoxemia despite supplemental oxygen signals a severe attack needing escalation, while normal saturation early on doesn't exclude severe obstruction. Trending sats guides response to treatment and disposition.","meaningSource":"ai-draft"},{"id":"exam-04","system":"cardiovascular","maneuver":"Assess for pulsus paradoxus.","findings":["Absent","Present"],"how":"Measure systolic pressure during slow inspiration and expiration; an inspiratory fall greater than 10 mmHg is abnormal.","why":"Pulsus paradoxus reflects exaggerated intrathoracic pressure swings, seen in severe airflow obstruction and in cardiac tamponade.","whySource":"curated","meaning":"Pulsus paradoxus reflects exaggerated intrathoracic pressure swings, seen in severe airflow obstruction and in cardiac tamponade.","meaningSource":"curated"},{"id":"exam-05","system":"neurologic","maneuver":"Assess mental status for fatigue or drowsiness.","findings":["Alert","Drowsy or fatigued"],"how":null,"why":null,"whySource":null,"meaning":"Drowsiness or fatigue during an asthma attack suggests carbon dioxide retention and impending respiratory failure — the patient is tiring out. This is a red flag for ICU care and possible intubation, not reassurance that they're resting.","meaningSource":"ai-draft"},{"id":"exam-06","system":"respiratory","maneuver":"Assess breath sounds for asymmetry suggesting pneumothorax.","findings":["Symmetric breath sounds","Unilateral decreased breath sounds"],"how":null,"why":null,"whySource":null,"meaning":"Unilateral decreased breath sounds during an asthma exacerbation raises concern for pneumothorax — from barotrauma, especially if positive-pressure ventilation was used — or a mucus plug causing lobar collapse. Either needs urgent imaging, since a tension pneumothorax can be fatal.","meaningSource":"ai-draft"},{"id":"exam-07","system":"skin","maneuver":"Inspect the skin for hives or angioedema.","findings":["None","Hives or angioedema present"],"how":null,"why":null,"whySource":null,"meaning":"Hives or angioedema alongside wheezing points to anaphylaxis rather than isolated asthma — and anaphylaxis needs intramuscular epinephrine first, not just bronchodilators. Missing this distinction can be fatal.","meaningSource":"ai-draft"},{"id":"exam-08","system":"ent","maneuver":"Assess for stridor.","findings":["Absent","Present"],"how":null,"why":"Stridor indicates upper airway obstruction and is an airway emergency.","whySource":"curated","meaning":"Stridor indicates upper airway obstruction and is an airway emergency.","meaningSource":"curated"},{"id":"exam-09","system":"cardiovascular","maneuver":"Assess for an S3 gallop or elevated jugular venous pressure suggesting a cardiac contributor.","findings":["Neither","S3 gallop or elevated jugular venous pressure"],"how":"With the patient reclined at 30 to 45 degrees, identify the highest point of internal jugular venous pulsation and measure its vertical distance above the sternal angle.","why":"An S3 gallop or elevated jugular venous pressure suggests a cardiac contributor to dyspnea rather than asthma alone.","whySource":"curated","meaning":"An S3 gallop or elevated jugular venous pressure suggests a cardiac contributor to dyspnea rather than asthma alone.","meaningSource":"curated"},{"id":"exam-10","system":"skin","maneuver":"Assess for cyanosis.","findings":["Absent","Present"],"how":null,"why":null,"whySource":null,"meaning":"Cyanosis is a late, ominous sign of severe hypoxemia — by the time it's visible, the patient is critically ill. Its presence should prompt immediate escalation to ICU-level care and preparation for airway intervention.","meaningSource":"ai-draft"}],"reviewNeeded":{"whyMissing":13,"howMissing":8}},{"id":"clostridioides-difficile-colitis","title":"Clostridium difficile colitis","aliases":["C. diff","pseudomembranous colitis"],"history":[{"id":"history-01","system":"medication","question":"Have you taken any antibiotics in the past eight weeks?","listenFor":["No recent antibiotic use","Recent antibiotic course within 8 weeks"],"why":null,"whySource":null,"meaning":"Recent antibiotics — even up to 8 weeks prior — are the single strongest risk factor for C. difficile, because they disrupt the normal gut flora. Identifying the culprit antibiotic also matters for stewardship and for choosing therapy that will not perpetuate the cycle.","meaningSource":"ai-draft"},{"id":"history-02","system":"gastrointestinal","question":"How many loose stools have you been having per day?","listenFor":["Fewer than 3 loose stools per day","3 to 9 loose stools per day","10 or more loose stools per day"],"why":null,"whySource":null,"meaning":"Stool frequency helps grade severity: 3 or more loose stools a day defines clinically significant diarrhea worth testing, while 10 or more a day with systemic signs marks severe disease that needs prompt treatment and closer monitoring.","meaningSource":"ai-draft"},{"id":"history-03","system":"gastrointestinal","question":"Do you have belly pain or cramping?","listenFor":["None","Mild cramping","Severe abdominal pain"],"why":null,"whySource":null,"meaning":"Cramping is expected, but severe abdominal pain raises concern for severe or complicated colitis — especially with distention or falling stool output, which can herald ileus or toxic megacolon.","meaningSource":"ai-draft"},{"id":"history-04","system":"infectious","question":"Have you had a fever with shaking chills?","listenFor":["No fever","Subjective fever","Documented fever with rigors"],"why":"Fever with shaking chills (rigors) suggests bacteremia.","whySource":"curated","meaning":"Fever with shaking chills (rigors) suggests bacteremia.","meaningSource":"curated"},{"id":"history-05","system":"hematologic","question":"Have you noticed blood in your stool?","listenFor":["No blood in stool","Blood in stool"],"why":null,"whySource":null,"meaning":"Bloody stool can occur in C. difficile but should also prompt consideration of inflammatory bowel disease or ischemic colitis. If bleeding is prominent or the picture does not fit, do not anchor on C. diff alone.","meaningSource":"ai-draft"},{"id":"history-06","system":"infectious","question":"Have you been hospitalized or stayed in a nursing home or long-term care facility recently?","listenFor":["Neither","Recent hospitalization","Long-term care facility stay"],"why":null,"whySource":null,"meaning":"Recent hospitalization or long-term care stay is the classic exposure — but community-acquired C. difficile is increasingly common, so absence of healthcare contact does not exclude it, particularly with recent antibiotics.","meaningSource":"ai-draft"},{"id":"history-07","system":"gastrointestinal","question":"Have you had C. diff before?","listenFor":["First episode","Recurrent episode"],"why":null,"whySource":null,"meaning":"A prior episode markedly raises the risk of recurrence. Recurrent disease changes management toward tapered or pulsed vancomycin or fidaxomicin — and after multiple recurrences, fecal microbiota transplantation.","meaningSource":"ai-draft"},{"id":"history-08","system":"gastrointestinal","question":"Do you have inflammatory bowel disease, like Crohn's or ulcerative colitis?","listenFor":["No known inflammatory bowel disease","Known inflammatory bowel disease"],"why":null,"whySource":null,"meaning":"Inflammatory bowel disease both increases C. difficile risk and mimics it. Test for C. diff during any IBD flare, because treating a flare with steroids while missing concurrent C. difficile worsens outcomes.","meaningSource":"ai-draft"},{"id":"history-09","system":"medication","question":"Are you on chemotherapy, a transplant medication, or long-term steroids?","listenFor":["No chronic immunosuppression","Chronic immunosuppression"],"why":null,"whySource":null,"meaning":"Immunosuppression increases both the risk of C. difficile and the risk of severe, refractory disease. These patients warrant a lower threshold for testing, early effective therapy, and attention to drug interactions with treatment.","meaningSource":"ai-draft"},{"id":"history-10","system":"medication","question":"Do you regularly take an acid reducer like omeprazole or another proton pump inhibitor?","listenFor":["No chronic PPI use","Chronic PPI use"],"why":null,"whySource":null,"meaning":"Chronic proton pump inhibitor use is a modifiable risk factor for C. difficile. Review whether the PPI is still indicated and stop it if not, since ongoing acid suppression favors recurrence.","meaningSource":"ai-draft"},{"id":"history-11","system":"gastrointestinal","question":"Has your belly become more swollen or distended while your bowel movements have actually slowed down or stopped?","listenFor":["No distention or decreased output","Distention with decreased stool output despite ongoing diarrhea"],"why":null,"whySource":null,"meaning":"New distention with slowing or stopping of stool output despite ongoing diarrhea signals ileus or impending toxic megacolon — a surgical emergency. Get an abdominal image, involve surgery early, and do not rely on stool frequency alone to judge severity.","meaningSource":"ai-draft"},{"id":"history-12","system":"neurologic","question":"Have you or your family noticed any confusion or unusual sleepiness?","listenFor":["Neither","Confusion","Lethargy"],"why":null,"whySource":null,"meaning":"New confusion or lethargy marks systemic toxicity and severe disease. It should prompt assessment for sepsis and megacolon and ICU-level care rather than routine ward management.","meaningSource":"ai-draft"}],"exam":[{"id":"exam-01","system":"gastrointestinal","maneuver":"Palpate the abdomen for tenderness.","findings":["Nontender","Diffuse tenderness","Tenderness with guarding or rigidity"],"how":null,"why":"Guarding, rebound, or rigidity on palpation suggests peritonitis.","whySource":"curated","meaning":"Guarding, rebound, or rigidity on palpation suggests peritonitis.","meaningSource":"curated"},{"id":"exam-02","system":"gastrointestinal","maneuver":"Assess for abdominal distention.","findings":["No distention","Distention present"],"how":null,"why":null,"whySource":null,"meaning":"Abdominal distention in C. difficile raises concern for ileus or toxic megacolon — especially with decreased stool output or worsening pain. Image promptly and involve surgery.","meaningSource":"ai-draft"},{"id":"exam-03","system":"gastrointestinal","maneuver":"Auscultate bowel sounds.","findings":["Normal bowel sounds","Hyperactive bowel sounds","Hypoactive or absent bowel sounds"],"how":null,"why":null,"whySource":null,"meaning":"Hyperactive bowel sounds fit active diarrheal colitis; hypoactive or absent sounds with distention suggest ileus — a sign the disease is progressing to a complicated course that needs escalation.","meaningSource":"ai-draft"},{"id":"exam-04","system":"general","maneuver":"Assess hemodynamic stability.","findings":["Normotensive","Tachycardic","Hypotensive or in shock"],"how":null,"why":null,"whySource":null,"meaning":"Tachycardia or hypotension signals sepsis or severe volume depletion. Resuscitate, broaden the evaluation for complications like megacolon or perforation, and consider ICU care.","meaningSource":"ai-draft"},{"id":"exam-05","system":"general","maneuver":"Assess for fever.","findings":["Afebrile","Febrile"],"how":null,"why":null,"whySource":null,"meaning":"Fever reflects the inflammatory response and supports clinically significant colitis. Persistent high fever with worsening pain or distention should prompt re-evaluation for complicated disease.","meaningSource":"ai-draft"},{"id":"exam-06","system":"skin","maneuver":"Assess hydration status.","findings":["Normal hydration","Dry mucous membranes or poor skin turgor"],"how":null,"why":null,"whySource":null,"meaning":"Dry mucous membranes or poor skin turgor quantify the volume depletion from days of watery diarrhea. Guide fluid resuscitation by exam and vitals, not just by reported stool counts.","meaningSource":"ai-draft"},{"id":"exam-07","system":"neurologic","maneuver":"Assess mental status.","findings":["Alert and oriented","Confused or lethargic"],"how":null,"why":null,"whySource":null,"meaning":"Confusion or lethargy in C. difficile colitis signals systemic toxicity or sepsis — the same red flag as in the history — and an indication to escalate care and look for megacolon or perforation.","meaningSource":"ai-draft"},{"id":"exam-08","system":"gastrointestinal","maneuver":"Perform a rectal examination when indicated.","findings":["Normal or deferred as not indicated","Gross blood on examination"],"how":null,"why":null,"whySource":null,"meaning":"A rectal exam is not routine in C. difficile, but it is indicated when bleeding, obstruction, or an alternate source is in question. Gross blood should prompt consideration of inflammatory bowel disease or another colitis rather than C. diff alone.","meaningSource":"ai-draft"},{"id":"exam-09","system":"gastrointestinal","maneuver":"Assess for peritoneal signs suggesting perforation.","findings":["Absent","Rebound or rigidity present"],"how":null,"why":"Guarding, rebound, or rigidity on palpation suggests peritonitis.","whySource":"curated","meaning":"Guarding, rebound, or rigidity on palpation suggests peritonitis.","meaningSource":"curated"},{"id":"exam-10","system":"genitourinary","maneuver":"Assess urine output.","findings":["Normal urine output","Decreased urine output"],"how":null,"why":"Decreased urine output suggests volume depletion or acute kidney injury.","whySource":"curated","meaning":"Decreased urine output suggests volume depletion or acute kidney injury.","meaningSource":"curated"}],"reviewNeeded":{"whyMissing":18,"howMissing":10}},{"id":"diabetic-foot-infection","title":"Diabetic foot infection","aliases":["diabetic foot ulcer","foot infection"],"history":[{"id":"history-01","system":"skin","question":"How long have you had this wound?","listenFor":["New wound, under one week","Chronic wound present for weeks","Chronic non-healing wound present for months"],"why":null,"whySource":null,"meaning":"Wound duration distinguishes an acute injury from a chronic ulcer; longer-standing wounds raise concern for underlying osteomyelitis and signal the need for deeper evaluation and more aggressive management.","meaningSource":"ai-draft"},{"id":"history-02","system":"skin","question":"Is anything draining from the wound?","listenFor":["No drainage","Serous drainage","Purulent drainage"],"why":null,"whySource":null,"meaning":"Drainage from the wound suggests active infection, and purulent drainage should be cultured before antibiotics are started to guide therapy; the character of the drainage also helps gauge severity.","meaningSource":"ai-draft"},{"id":"history-03","system":"neurologic","question":"Can you feel pain at the wound site, or do you have numbness there from neuropathy?","listenFor":["Pain present at the site","No pain due to known neuropathy","No pain reported despite a deep wound"],"why":null,"whySource":null,"meaning":"Neuropathy masks pain, so an insensate foot can harbor a severe infection the patient barely feels; numbness at the wound site marks a high-risk foot that needs careful examination regardless of reported pain.","meaningSource":"ai-draft"},{"id":"history-04","system":"infectious","question":"Have you had a fever?","listenFor":["No fever","Fever"],"why":null,"whySource":null,"meaning":"Fever signals systemic involvement beyond a local wound infection and escalates the severity classification, pointing toward the need for admission and IV antibiotics.","meaningSource":"ai-draft"},{"id":"history-05","system":"neurologic","question":"Have you been diagnosed with nerve damage or neuropathy in your feet?","listenFor":["No known peripheral neuropathy","Known peripheral neuropathy"],"why":null,"whySource":null,"meaning":"Peripheral neuropathy is the key predisposing factor for diabetic foot ulcers — loss of protective sensation allows unnoticed trauma — and its presence marks the patient for lifelong foot surveillance.","meaningSource":"ai-draft"},{"id":"history-06","system":"cardiovascular","question":"Have you been diagnosed with poor circulation in your legs, or had an amputation before?","listenFor":["Neither","Known peripheral arterial disease","Prior amputation"],"why":null,"whySource":null,"meaning":"Poor leg circulation impairs healing and raises amputation risk, while a prior amputation marks the highest-risk foot; both findings should prompt vascular assessment and urgent specialty referral.","meaningSource":"ai-draft"},{"id":"history-07","system":"endocrine","question":"How has your blood sugar control been recently?","listenFor":["Good glycemic control per patient report","Poor glycemic control"],"why":null,"whySource":null,"meaning":"Poor glycemic control impairs wound healing and immune response, so recent control guides both the urgency of glucose management and expectations for how the wound will heal.","meaningSource":"ai-draft"},{"id":"history-08","system":"endocrine","question":"How long have you had diabetes?","listenFor":["Under 10 years","10 years or more"],"why":null,"whySource":null,"meaning":"Longer duration of diabetes correlates with more neuropathy, vascular disease, and prior ulceration — context that raises the pretest probability of a complicated infection.","meaningSource":"ai-draft"},{"id":"history-09","system":"cardiovascular","question":"Do you get calf pain when you walk that goes away when you rest?","listenFor":["No claudication symptoms","Calf pain with walking, relieved by rest"],"why":"Calf pain with walking that resolves with rest (claudication) suggests peripheral arterial disease.","whySource":"curated","meaning":"Calf pain with walking that resolves with rest (claudication) suggests peripheral arterial disease.","meaningSource":"curated"},{"id":"history-10","system":"skin","question":"Has the redness been spreading quickly, and have you been feeling sick overall?","listenFor":["Gradual, localized to the wound","Rapid spread with systemic illness"],"why":null,"whySource":null,"meaning":"Rapidly spreading redness with systemic illness is a red flag for necrotizing infection or sepsis — this needs emergent evaluation and urgent surgical consultation, not routine wound care.","meaningSource":"ai-draft"},{"id":"history-11","system":"musculoskeletal","question":"Can you see bone in the wound, or has a doctor ever told you they could feel bone through it?","listenFor":["Neither","Visible bone or prior probe-to-bone finding"],"why":"Visible bone or a positive probe-to-bone test strongly suggests underlying osteomyelitis.","whySource":"curated","meaning":"Visible bone or a positive probe-to-bone test strongly suggests underlying osteomyelitis.","meaningSource":"curated"},{"id":"history-12","system":"musculoskeletal","question":"Have you had a foot ulcer or amputation before?","listenFor":["Neither","Prior foot ulcer","Prior amputation"],"why":null,"whySource":null,"meaning":"A prior ulcer or amputation is the strongest predictor of another foot complication; these patients need aggressive treatment of the current wound and a prevention plan once it heals.","meaningSource":"ai-draft"},{"id":"history-13","system":"functional","question":"Could this have started from an ill-fitting shoe or an injury you didn't notice?","listenFor":["No identifiable trauma","Ill-fitting footwear or unnoticed trauma"],"why":null,"whySource":null,"meaning":"In an insensate foot, unnoticed trauma from ill-fitting shoes is the classic inciting event; identifying the source guides offloading and footwear counseling to prevent recurrence.","meaningSource":"ai-draft"}],"exam":[{"id":"exam-01","system":"skin","maneuver":"Assess wound depth.","findings":["Superficial","Extends to subcutaneous tissue","Extends to bone or joint"],"how":null,"why":null,"whySource":null,"meaning":"Depth determines severity: a superficial wound is managed differently from one reaching tendon, joint, or bone, and involvement of bone or joint raises concern for osteomyelitis or septic arthritis requiring imaging and often surgery.","meaningSource":"ai-draft"},{"id":"exam-02","system":"skin","maneuver":"Measure the extent of surrounding erythema.","findings":["Under 2 cm of surrounding erythema","2 cm or more of surrounding erythema"],"how":null,"why":null,"whySource":null,"meaning":"The extent of surrounding erythema classifies infection severity — erythema of 2 cm or more defines at least moderate infection — which determines whether oral or IV antibiotics and admission are needed.","meaningSource":"ai-draft"},{"id":"exam-03","system":"skin","maneuver":"Inspect for purulent drainage.","findings":["None","Purulent drainage present"],"how":null,"why":null,"whySource":null,"meaning":"Purulent drainage confirms infection rather than colonization and should be cultured before antibiotics; its presence supports starting empiric therapy promptly.","meaningSource":"ai-draft"},{"id":"exam-04","system":"cardiovascular","maneuver":"Palpate pedal pulses.","findings":["Palpable pedal pulses","Diminished pulses","Absent pulses"],"how":null,"why":"Absent pedal pulses suggest peripheral arterial disease with impaired wound healing.","whySource":"curated","meaning":"Absent pedal pulses suggest peripheral arterial disease with impaired wound healing.","meaningSource":"curated"},{"id":"exam-05","system":"neurologic","maneuver":"Assess protective sensation with a monofilament.","findings":["Intact protective sensation","Loss of protective sensation"],"how":"With the patient's eyes closed, press the 10-g monofilament perpendicular against the plantar skin until it bends, holding about 1 second per site.","why":"Loss of protective sensation allows unnoticed trauma that leads to ulceration.","whySource":"curated","meaning":"Loss of protective sensation allows unnoticed trauma that leads to ulceration.","meaningSource":"curated"},{"id":"exam-06","system":"musculoskeletal","maneuver":"Perform a probe-to-bone test.","findings":["Negative","Positive, bone palpable through the wound"],"how":null,"why":"A positive probe-to-bone test (palpable bone through the ulcer) strongly suggests underlying osteomyelitis.","whySource":"curated","meaning":"A positive probe-to-bone test (palpable bone through the ulcer) strongly suggests underlying osteomyelitis.","meaningSource":"curated"},{"id":"exam-07","system":"general","maneuver":"Assess for systemic signs of infection.","findings":["Afebrile and hemodynamically stable","Febrile or tachycardic","Hypotensive or septic-appearing"],"how":null,"why":null,"whySource":null,"meaning":"Fever, tachycardia, hypotension, or a septic appearance define severe infection with systemic toxicity — these patients need admission, IV antibiotics, and urgent surgical evaluation.","meaningSource":"ai-draft"},{"id":"exam-08","system":"skin","maneuver":"Inspect for crepitus or necrotic tissue.","findings":["None","Crepitus or necrotic tissue present"],"how":null,"why":"Crepitus or necrotic tissue suggests necrotizing infection or gas gangrene.","whySource":"curated","meaning":"Crepitus or necrotic tissue suggests necrotizing infection or gas gangrene.","meaningSource":"curated"},{"id":"exam-09","system":"musculoskeletal","maneuver":"Inspect the foot for deformity or Charcot changes.","findings":["Normal foot architecture","Deformity or Charcot changes present"],"how":null,"why":null,"whySource":null,"meaning":"Deformity or Charcot changes alter pressure points and complicate wound healing; Charcot arthropathy itself can mimic infection with a warm swollen foot, so distinguishing the two changes management entirely.","meaningSource":"ai-draft"},{"id":"exam-10","system":"skin","maneuver":"Inspect for lymphangitic streaking.","findings":["None","Lymphangitic streaking present"],"how":null,"why":"Lymphangitic streaking suggests infection spreading along lymphatic channels.","whySource":"curated","meaning":"Lymphangitic streaking suggests infection spreading along lymphatic channels.","meaningSource":"curated"}],"reviewNeeded":{"whyMissing":16,"howMissing":9}},{"id":"hypertensive-urgency-emergency","title":"Hypertensive urgency/emergency","aliases":["severe hypertension","hypertensive emergency"],"history":[{"id":"history-01","system":"neurologic","question":"Do you have a headache, or has your vision changed?","listenFor":["Neither","Headache","Vision change"],"why":null,"whySource":null,"meaning":"Headache or vision changes with severe hypertension suggest end-organ involvement such as hypertensive encephalopathy or retinal damage — their presence moves the diagnosis from urgency toward emergency.","meaningSource":"ai-draft"},{"id":"history-02","system":"cardiovascular","question":"Do you have chest pain, and does it feel like it's tearing through to your back?","listenFor":["No chest pain","Chest pain without radiation to the back","Chest pain tearing through to the back"],"why":"Sudden tearing chest pain radiating to the back is the classic presentation of aortic dissection.","whySource":"curated","meaning":"Sudden tearing chest pain radiating to the back is the classic presentation of aortic dissection.","meaningSource":"curated"},{"id":"history-03","system":"respiratory","question":"Are you short of breath?","listenFor":["No dyspnea","Mild dyspnea with exertion","Severe dyspnea at rest"],"why":null,"whySource":null,"meaning":"Shortness of breath raises concern for pulmonary edema or acute heart failure as end-organ damage from severe hypertension, which requires emergent evaluation and treatment.","meaningSource":"ai-draft"},{"id":"history-04","system":"neurologic","question":"Have you or your family noticed any new confusion?","listenFor":["No new confusion","New confusion"],"why":"New confusion marks severity of systemic illness and suggests acute organ dysfunction, as in severe infection, sepsis, or metabolic derangement.","whySource":"curated","meaning":"New confusion marks severity of systemic illness and suggests acute organ dysfunction, as in severe infection, sepsis, or metabolic derangement.","meaningSource":"curated"},{"id":"history-05","system":"neurologic","question":"Have you had any weakness, numbness, or trouble speaking on one side?","listenFor":["None of these","Focal weakness or numbness","Speech change"],"why":null,"whySource":null,"meaning":"Unilateral weakness, numbness, or trouble speaking with severe hypertension suggests acute stroke — an emergency where blood pressure management follows stroke protocols, not routine lowering.","meaningSource":"ai-draft"},{"id":"history-06","system":"medication","question":"Have you missed doses of your blood pressure medication recently?","listenFor":["No missed doses","Missed one or more doses of blood pressure medication"],"why":null,"whySource":null,"meaning":"Missed antihypertensive doses are the most common reversible cause of severe asymptomatic hypertension; identifying nonadherence points to restarting the regimen and counseling rather than an extensive new workup.","meaningSource":"ai-draft"},{"id":"history-07","system":"reproductive","question":"Are you currently pregnant or did you recently give birth?","listenFor":["Not pregnant or postpartum","Pregnant or postpartum"],"why":null,"whySource":null,"meaning":"Pregnancy or recent delivery raises concern for preeclampsia or eclampsia, which have different blood pressure thresholds and management — severe hypertension in this setting is an obstetric emergency.","meaningSource":"ai-draft"},{"id":"history-08","system":"medication","question":"Have you used cocaine, methamphetamine, or another stimulant recently?","listenFor":["No stimulant use","Recent stimulant use"],"why":null,"whySource":null,"meaning":"Cocaine, methamphetamine, and other stimulants are reversible causes of severe hypertension; identifying use guides specific management and avoids therapies that could worsen vasospasm.","meaningSource":"ai-draft"},{"id":"history-09","system":"endocrine","question":"Have you had episodes of pounding headaches, sweating, and a racing heart that come and go?","listenFor":["No episodic symptoms","Episodic headache, diaphoresis, and palpitations"],"why":"Episodic headache with diaphoresis and palpitations suggests pheochromocytoma.","whySource":"curated","meaning":"Episodic headache with diaphoresis and palpitations suggests pheochromocytoma.","meaningSource":"curated"},{"id":"history-10","system":"general","question":"Are you in a lot of pain, or feeling especially anxious right now?","listenFor":["Neither","Significant pain","Significant anxiety"],"why":null,"whySource":null,"meaning":"Severe pain or anxiety can transiently elevate blood pressure; treating the pain or anxiety and rechecking avoids overtreating a number that will settle on its own.","meaningSource":"ai-draft"},{"id":"history-11","system":"genitourinary","question":"Have you noticed a change in how much you're urinating?","listenFor":["Normal urine output","Decreased urine output"],"why":"Decreased urine output suggests volume depletion or acute kidney injury.","whySource":"curated","meaning":"Decreased urine output suggests volume depletion or acute kidney injury.","meaningSource":"curated"},{"id":"history-12","system":"eyes","question":"Has your vision gotten blurry or spotty?","listenFor":["No visual change","Blurred or spotty vision"],"why":"Visual changes suggest hypertensive end-organ injury to the eye or brain.","whySource":"curated","meaning":"Visual changes suggest hypertensive end-organ injury to the eye or brain.","meaningSource":"curated"},{"id":"history-13","system":"cardiovascular","question":"Do you have kidney disease, and has your blood pressure been consistently hard to control?","listenFor":["Neither","Known chronic kidney disease","Long-standing poorly controlled hypertension"],"why":null,"whySource":null,"meaning":"Kidney disease is both a cause and a consequence of severe hypertension, and consistently hard-to-control pressure suggests resistant hypertension needing evaluation for secondary causes and regimen optimization.","meaningSource":"ai-draft"}],"exam":[{"id":"exam-01","system":"cardiovascular","maneuver":"Measure blood pressure in both arms.","findings":["Concordant blood pressure in both arms","Significant discrepancy between arms"],"how":null,"why":"A systolic blood pressure discrepancy between arms suggests aortic dissection.","whySource":"curated","meaning":"A systolic blood pressure discrepancy between arms suggests aortic dissection.","meaningSource":"curated"},{"id":"exam-02","system":"neurologic","maneuver":"Assess mental status.","findings":["Alert and oriented","Confused or altered"],"how":null,"why":null,"whySource":null,"meaning":"Confusion or altered mental status with severe hypertension suggests hypertensive encephalopathy or stroke — end-organ damage that defines a hypertensive emergency requiring immediate treatment.","meaningSource":"ai-draft"},{"id":"exam-03","system":"neurologic","maneuver":"Assess for a focal neurologic deficit.","findings":["No focal deficit","Focal deficit present"],"how":null,"why":null,"whySource":null,"meaning":"A focal neurologic deficit with severe hypertension points to acute stroke as the end-organ injury; this redirects care to emergent stroke evaluation with careful blood pressure management.","meaningSource":"ai-draft"},{"id":"exam-04","system":"eyes","maneuver":"Assess for papilledema or hemorrhages on fundoscopic exam.","findings":["Normal fundoscopic exam","Papilledema or retinal hemorrhages"],"how":null,"why":"Papilledema suggests elevated intracranial pressure.","whySource":"curated","meaning":"Papilledema suggests elevated intracranial pressure.","meaningSource":"curated"},{"id":"exam-05","system":"respiratory","maneuver":"Auscultate the lungs for crackles.","findings":["Clear bilaterally","Bibasilar crackles","Diffuse crackles consistent with pulmonary edema"],"how":null,"why":"Diffuse bilateral crackles suggest acute pulmonary edema.","whySource":"curated","meaning":"Diffuse bilateral crackles suggest acute pulmonary edema.","meaningSource":"curated"},{"id":"exam-06","system":"cardiovascular","maneuver":"Auscultate heart sounds for a gallop or new murmur.","findings":["Normal heart sounds","S3 or S4 gallop","New murmur"],"how":null,"why":"An S4 gallop reflects forceful atrial contraction into a stiff ventricle, as in hypertensive heart disease or ischemia.","whySource":"curated","meaning":"An S4 gallop reflects forceful atrial contraction into a stiff ventricle, as in hypertensive heart disease or ischemia.","meaningSource":"curated"},{"id":"exam-07","system":"cardiovascular","maneuver":"Palpate peripheral pulses for symmetry to help exclude aortic dissection.","findings":["Symmetric pulses","Asymmetric or diminished pulse"],"how":null,"why":"Asymmetric or diminished pulses suggest aortic dissection.","whySource":"curated","meaning":"Asymmetric or diminished pulses suggest aortic dissection.","meaningSource":"curated"},{"id":"exam-08","system":"cardiovascular","maneuver":"Inspect and palpate the lower extremities for edema.","findings":["No peripheral edema","Peripheral edema present"],"how":null,"why":null,"whySource":null,"meaning":"Peripheral edema suggests cardiac or renal end-organ involvement from severe hypertension, and in a pregnant patient raises concern for preeclampsia — both findings escalate urgency.","meaningSource":"ai-draft"},{"id":"exam-09","system":"reproductive","maneuver":"Assess for hyperreflexia or clonus when pregnancy-related hypertension is a concern.","findings":["Not applicable or normal reflexes","Hyperreflexia or clonus present"],"how":null,"why":"Hyperreflexia or clonus in a pregnant or postpartum patient suggests preeclampsia with heightened seizure risk.","whySource":"curated","meaning":"Hyperreflexia or clonus in a pregnant or postpartum patient suggests preeclampsia with heightened seizure risk.","meaningSource":"curated"},{"id":"exam-10","system":"genitourinary","maneuver":"Assess urine output.","findings":["Normal urine output","Decreased urine output"],"how":null,"why":"Decreased urine output suggests volume depletion or acute kidney injury.","whySource":"curated","meaning":"Decreased urine output suggests volume depletion or acute kidney injury.","meaningSource":"curated"}],"reviewNeeded":{"whyMissing":11,"howMissing":10}},{"id":"uncontrolled-nausea-vomiting","title":"Nausea and vomiting (uncontrolled)","aliases":["nausea","vomiting"],"history":[{"id":"history-01","system":"gastrointestinal","question":"Have you vomited anything that looked like blood or coffee grounds, or bile that was bright green or yellow?","listenFor":["Neither","Coffee-ground or bloody emesis","Bilious emesis"],"why":"Bilious vomiting suggests obstruction distal to the ampulla of Vater.","whySource":"curated","meaning":"Bilious vomiting suggests obstruction distal to the ampulla of Vater.","meaningSource":"curated"},{"id":"history-02","system":"gastrointestinal","question":"Are you able to keep any liquids down?","listenFor":["Tolerating oral fluids","Unable to tolerate oral fluids"],"why":null,"whySource":null,"meaning":"Inability to keep liquids down marks the threshold where outpatient management fails — the patient needs IV fluids and likely admission — and predicts dehydration and acute kidney injury if it persists.","meaningSource":"ai-draft"},{"id":"history-03","system":"gastrointestinal","question":"Do you have belly pain along with the nausea?","listenFor":["No abdominal pain","Abdominal pain"],"why":null,"whySource":null,"meaning":"Abdominal pain localizes the source: epigastric or right-upper-quadrant pain suggests gallbladder, pancreatic, or ulcer disease, while absent pain points toward medication, metabolic, or central nervous system causes.","meaningSource":"ai-draft"},{"id":"history-04","system":"gastrointestinal","question":"Are you able to pass gas or have a bowel movement?","listenFor":["Passing flatus and stool normally","Obstipation with abdominal distention"],"why":"Inability to pass gas or stool (obstipation) with distention suggests complete bowel obstruction.","whySource":"curated","meaning":"Inability to pass gas or stool (obstipation) with distention suggests complete bowel obstruction.","meaningSource":"curated"},{"id":"history-05","system":"gastrointestinal","question":"Have you had abdominal surgery in the past?","listenFor":["No prior abdominal surgery","Prior abdominal surgery"],"why":null,"whySource":null,"meaning":"Prior abdominal surgery is the key risk factor for adhesive small-bowel obstruction; vomiting in this patient must be treated as obstruction until imaging rules it out.","meaningSource":"ai-draft"},{"id":"history-06","system":"neurologic","question":"Do you have a headache along with the nausea?","listenFor":["No headache","Headache"],"why":null,"whySource":null,"meaning":"Headache accompanying nausea shifts the differential toward intracranial causes — migraine, meningitis, or raised intracranial pressure — rather than a primary gastrointestinal problem.","meaningSource":"ai-draft"},{"id":"history-07","system":"neurologic","question":"Does the nausea come with dizziness or a spinning sensation?","listenFor":["No vertigo","Vertigo accompanying the nausea"],"why":null,"whySource":null,"meaning":"Vertigo with nausea points to a vestibular cause (such as benign positional vertigo or vestibular neuritis) rather than the gut; associated neurologic symptoms raise concern for posterior circulation stroke.","meaningSource":"ai-draft"},{"id":"history-08","system":"medication","question":"Have you started any new medications recently, including chemotherapy or a new pain medication?","listenFor":["No new medication","New medication started"],"why":null,"whySource":null,"meaning":"New medications — especially opioids, chemotherapy, and antibiotics — are common and reversible causes of nausea; identifying the culprit allows stopping, substituting, or adding prophylactic antiemetics.","meaningSource":"ai-draft"},{"id":"history-09","system":"medication","question":"Do you use cannabis regularly, and if so, does hot showers relieve the nausea?","listenFor":["No regular cannabis use","Regular cannabis use, hot showers relieve symptoms","Regular cannabis use without symptom relief pattern"],"why":"Nausea relieved by hot showers in a regular cannabis user suggests cannabinoid hyperemesis syndrome.","whySource":"curated","meaning":"Nausea relieved by hot showers in a regular cannabis user suggests cannabinoid hyperemesis syndrome.","meaningSource":"curated"},{"id":"history-10","system":"reproductive","question":"Is there any chance you could be pregnant?","listenFor":["Not applicable or not pregnant","Possible pregnancy"],"why":"Pregnancy status changes the differential diagnosis, medication safety, and imaging choices.","whySource":"curated","meaning":"Pregnancy status changes the differential diagnosis, medication safety, and imaging choices.","meaningSource":"curated"},{"id":"history-11","system":"endocrine","question":"Do you have diabetes, and have you noticed excessive thirst, urination, or a fruity breath smell?","listenFor":["No known diabetes","Known diabetes with polyuria or polydipsia","Known diabetes with fruity breath odor"],"why":"A fruity or acetone breath odor suggests ketoacidosis.","whySource":"curated","meaning":"A fruity or acetone breath odor suggests ketoacidosis.","meaningSource":"curated"},{"id":"history-12","system":"gastrointestinal","question":"Do you have known gallstones or liver disease?","listenFor":["Neither","Known gallstones","Known liver disease"],"why":null,"whySource":null,"meaning":"Known gallstones point toward biliary colic or cholecystitis; known liver disease raises hepatic causes and changes which medications and doses are safe to use.","meaningSource":"ai-draft"},{"id":"history-13","system":"cardiovascular","question":"Do you have chest pain or a squeezing feeling along with the nausea?","listenFor":["No chest pain","Chest pain or pressure"],"why":null,"whySource":null,"meaning":"Nausea can be the presenting symptom of myocardial ischemia, particularly in women and older adults — chest pressure with nausea warrants an ECG rather than being written off as gastritis.","meaningSource":"ai-draft"},{"id":"history-14","system":"hematologic","question":"Are you currently on chemotherapy, or did you have chemotherapy recently?","listenFor":["No chemotherapy","Current or recent chemotherapy"],"why":null,"whySource":null,"meaning":"Chemotherapy-induced nausea is expected and managed with scheduled antiemetic regimens rather than as-needed treatment alone; recent chemotherapy also flags neutropenia risk if fever develops.","meaningSource":"ai-draft"},{"id":"history-15","system":"endocrine","question":"Have you lost weight without trying, or noticed new darkening of your skin?","listenFor":["No adrenal insufficiency symptoms","Fatigue and unintentional weight loss","New skin darkening"],"why":null,"whySource":null,"meaning":"Unintentional weight loss suggests malignancy or chronic systemic disease; new skin darkening suggests primary adrenal insufficiency (Addison disease), in which nausea and vomiting are presenting features — both warrant targeted testing, including cortisol evaluation.","meaningSource":"ai-draft"}],"exam":[{"id":"exam-01","system":"general","maneuver":"Assess hydration status and orthostatic vital signs when safe.","findings":["Euvolemic, no orthostatic change","Dry mucous membranes or poor turgor","Positive orthostatic hypotension"],"how":"Measure blood pressure and heart rate after 5 minutes supine, then at 1 and 3 minutes after standing; a sustained drop of 20 mmHg systolic or 10 mmHg diastolic within 3 minutes is positive.","why":"Documenting volume status (hypovolemic, euvolemic, or hypervolemic) guides fluid management and helps distinguish prerenal, intrinsic, and volume-overload causes of kidney injury and electrolyte disturbances.","whySource":"curated","meaning":"Documenting volume status (hypovolemic, euvolemic, or hypervolemic) guides fluid management and helps distinguish prerenal, intrinsic, and volume-overload causes of kidney injury and electrolyte disturbances.","meaningSource":"curated"},{"id":"exam-02","system":"gastrointestinal","maneuver":"Palpate the abdomen for tenderness, guarding, and rebound.","findings":["Soft, nontender","Focal tenderness without guarding","Guarding, rebound, or rigidity"],"how":null,"why":"Guarding, rebound, or rigidity on palpation suggests peritonitis.","whySource":"curated","meaning":"Guarding, rebound, or rigidity on palpation suggests peritonitis.","meaningSource":"curated"},{"id":"exam-03","system":"gastrointestinal","maneuver":"Inspect for distention and auscultate bowel sounds.","findings":["Normal bowel sounds, no distention","Distended with high-pitched or hyperactive bowel sounds","Distended and silent"],"how":null,"why":"High-pitched, hyperactive bowel sounds suggest early mechanical obstruction; absent bowel sounds suggest ileus or late obstruction.","whySource":"curated","meaning":"High-pitched, hyperactive bowel sounds suggest early mechanical obstruction; absent bowel sounds suggest ileus or late obstruction.","meaningSource":"curated"},{"id":"exam-04","system":"gastrointestinal","maneuver":"Assess the right upper quadrant for a Murphy sign.","findings":["Negative Murphy sign","Positive Murphy sign"],"how":"Hook your fingers under the right costal margin at the midclavicular line and ask the patient to inhale deeply; abrupt inspiratory arrest from pain is a positive Murphy sign.","why":"A positive Murphy sign (inspiratory arrest on palpation of the right upper quadrant) suggests acute cholecystitis.","whySource":"curated","meaning":"A positive Murphy sign (inspiratory arrest on palpation of the right upper quadrant) suggests acute cholecystitis.","meaningSource":"curated"},{"id":"exam-05","system":"neurologic","maneuver":"Assess for nystagmus or a focal neurologic deficit.","findings":["Neither","Nystagmus","Focal deficit present"],"how":null,"why":null,"whySource":null,"meaning":"Nystagmus supports a peripheral vestibular cause of the nausea; a focal neurologic deficit instead points to a central cause such as stroke and requires urgent neuroimaging.","meaningSource":"ai-draft"},{"id":"exam-06","system":"skin","maneuver":"Inspect skin and sclerae for jaundice.","findings":["Absent","Present"],"how":null,"why":null,"whySource":null,"meaning":"Jaundice narrows the differential to hepatobiliary causes — cholecystitis, cholangitis, hepatitis, or biliary obstruction — and directs the workup to liver tests and biliary imaging.","meaningSource":"ai-draft"},{"id":"exam-07","system":"endocrine","maneuver":"Check fingerstick glucose.","findings":["Normal glucose","Hypoglycemic","Hyperglycemic"],"how":"Prick the side of the fingertip rather than the pad, and apply the blood drop to the test strip.","why":"Hypoglycemia causes neuroglycopenic symptoms such as confusion, diaphoresis, and tremor, and needs urgent correction.","whySource":"curated","meaning":"Hypoglycemia causes neuroglycopenic symptoms such as confusion, diaphoresis, and tremor, and needs urgent correction.","meaningSource":"curated"},{"id":"exam-08","system":"respiratory","maneuver":"Assess respiratory pattern for Kussmaul breathing.","findings":["Normal breathing pattern","Rapid, deep Kussmaul breathing"],"how":null,"why":"Rapid, deep Kussmaul breathing is respiratory compensation for severe metabolic acidosis, as in diabetic ketoacidosis.","whySource":"curated","meaning":"Rapid, deep Kussmaul breathing is respiratory compensation for severe metabolic acidosis, as in diabetic ketoacidosis.","meaningSource":"curated"},{"id":"exam-09","system":"gastrointestinal","maneuver":"Examine hernia sites for a bulge and reducibility.","findings":["No hernia identified","Reducible hernia","Tender, irreducible or incarcerated hernia"],"how":null,"why":"A tender, irreducible hernia suggests incarceration or strangulation, which needs urgent surgical evaluation.","whySource":"curated","meaning":"A tender, irreducible hernia suggests incarceration or strangulation, which needs urgent surgical evaluation.","meaningSource":"curated"},{"id":"exam-10","system":"cardiovascular","maneuver":"Assess heart rate and rhythm.","findings":["Regular rate and rhythm","Tachycardic","Irregular rhythm"],"how":null,"why":null,"whySource":null,"meaning":"Tachycardia suggests volume depletion or sepsis; an irregular rhythm in a vomiting patient may reflect electrolyte shifts such as hypokalemia and should prompt an ECG and electrolyte check.","meaningSource":"ai-draft"}],"reviewNeeded":{"whyMissing":13,"howMissing":7}},{"id":"severe-diarrhea","title":"Diarrhea (severe/dehydrating)","aliases":["acute diarrhea","dehydrating diarrhea"],"history":[{"id":"history-01","system":"gastrointestinal","question":"How many watery stools have you been having per day?","listenFor":["Fewer than 3 per day","3 to 9 per day","10 or more per day"],"why":null,"whySource":null,"meaning":"Stool frequency quantifies severity: 10 or more watery stools per day defines severe disease with high dehydration and electrolyte risk, warranting aggressive rehydration and admission consideration, while fewer than 3 per day is usually managed outpatient. Frequency also guides how urgently to look for an infectious cause.","meaningSource":"ai-draft"},{"id":"history-02","system":"hematologic","question":"Have you noticed blood or mucus in your stool?","listenFor":["Neither","Blood in stool","Mucus in stool"],"why":null,"whySource":null,"meaning":"Blood in stool signals invasive or inflammatory disease — bacterial dysentery (Shigella, Campylobacter), inflammatory bowel disease, or ischemic colitis — and mandates stool studies and often endoscopic evaluation. Mucus also suggests colonic inflammation, while purely watery stool points toward secretory or viral causes.","meaningSource":"ai-draft"},{"id":"history-03","system":"infectious","question":"Have you had a fever along with the diarrhea?","listenFor":["No fever","Fever"],"why":null,"whySource":null,"meaning":"Fever suggests an invasive bacterial pathogen (Shigella, Salmonella, Campylobacter) or an inflammatory bowel disease flare rather than a viral or secretory cause, and lowers the threshold for stool cultures and antibiotics when bacterial dysentery is suspected. Afebrile watery diarrhea is more often viral, toxin-mediated, or medication-related.","meaningSource":"ai-draft"},{"id":"history-04","system":"gastrointestinal","question":"Do you have belly cramping or pain along with the diarrhea?","listenFor":["No abdominal pain","Mild cramping","Severe abdominal pain"],"why":null,"whySource":null,"meaning":"Mild cramping is typical of infectious diarrhea, but severe abdominal pain raises concern for complications — toxic megacolon, perforation, ischemic colitis, or an IBD flare — and should prompt abdominal imaging. Painless watery diarrhea favors secretory, viral, or osmotic causes.","meaningSource":"ai-draft"},{"id":"history-05","system":"medication","question":"Have you taken any antibiotics in the past eight weeks?","listenFor":["No recent antibiotic use","Recent antibiotic course"],"why":null,"whySource":null,"meaning":"Recent antibiotic use raises suspicion for Clostridioides difficile infection, especially after clindamycin, fluoroquinolones, or cephalosporins — test for C. difficile toxin and start empiric therapy (oral vancomycin or fidaxomicin) when the picture fits. No recent antibiotics makes C. difficile less likely but still possible.","meaningSource":"ai-draft"},{"id":"history-06","system":"infectious","question":"Have you traveled anywhere recently, especially outside the country?","listenFor":["No recent travel","Recent travel to a diarrheal-illness-endemic area"],"why":null,"whySource":null,"meaning":"Recent travel, especially to areas with poor sanitation, points to traveler's diarrhea (enterotoxigenic E. coli) or parasitic causes (Giardia, Entamoeba) and guides empiric therapy and stool testing. Without travel, focus on local food exposures, C. difficile, and endemic viral causes.","meaningSource":"ai-draft"},{"id":"history-07","system":"infectious","question":"Has anyone around you been sick with similar symptoms, or have you eaten anything that might have been undercooked or spoiled?","listenFor":["Neither","Sick contacts with similar symptoms","Suspect food exposure"],"why":null,"whySource":null,"meaning":"Sick contacts with similar symptoms suggest a viral outbreak (norovirus) or shared foodborne exposure, while a suspect meal points to bacterial food poisoning (Staphylococcus aureus toxin, Salmonella, Campylobacter). Identifying a common source guides public-health reporting and empiric treatment choices.","meaningSource":"ai-draft"},{"id":"history-08","system":"gastrointestinal","question":"Do you have inflammatory bowel disease, and does this feel like a prior flare?","listenFor":["No known inflammatory bowel disease","Known inflammatory bowel disease, resembles a prior flare","Known inflammatory bowel disease, feels different from prior flares"],"why":null,"whySource":null,"meaning":"In known IBD, a presentation resembling a prior flare is usually treated as a flare — but one that feels different, especially with fever after recent antibiotics, should prompt C. difficile testing, since C. difficile commonly complicates IBD. Never assume every diarrheal episode in IBD is a flare.","meaningSource":"ai-draft"},{"id":"history-09","system":"medication","question":"Are you on chemotherapy, a transplant medication, or long-term steroids?","listenFor":["No chronic immunosuppression","Chronic immunosuppression"],"why":null,"whySource":null,"meaning":"Chronic immunosuppression widens the pathogen list to cytomegalovirus, Cryptosporidium, and other opportunists, and makes severe or persistent diarrhea more dangerous — lower the threshold for stool studies, endoscopy, and admission. With abdominal pain and fever, also consider neutropenic enterocolitis.","meaningSource":"ai-draft"},{"id":"history-10","system":"genitourinary","question":"Have you noticed a change in how much you're urinating?","listenFor":["Normal urine output","Decreased urine output"],"why":"Decreased urine output suggests volume depletion or acute kidney injury.","whySource":"curated","meaning":"Decreased urine output suggests volume depletion or acute kidney injury.","meaningSource":"curated"},{"id":"history-11","system":"neurologic","question":"Have you felt lightheaded or dizzy, especially when standing up?","listenFor":["No lightheadedness","Lightheaded or dizzy on standing"],"why":"Dizziness on standing suggests orthostatic hypotension from volume depletion, autonomic dysfunction, or medications.","whySource":"curated","meaning":"Dizziness on standing suggests orthostatic hypotension from volume depletion, autonomic dysfunction, or medications.","meaningSource":"curated"},{"id":"history-12","system":"gastrointestinal","question":"Are your stools waking you up at night?","listenFor":["No nocturnal stools","Nocturnal stools"],"why":"Nocturnal stools suggest organic rather than functional diarrhea.","whySource":"curated","meaning":"Nocturnal stools suggest organic rather than functional diarrhea.","meaningSource":"curated"},{"id":"history-13","system":"gastrointestinal","question":"Have you lost weight without trying over the past several weeks?","listenFor":["No unintentional weight loss","Unintentional weight loss"],"why":null,"whySource":null,"meaning":"Unintentional weight loss over weeks suggests a chronic process — inflammatory bowel disease, celiac disease, malignancy, or chronic infection — rather than acute infectious diarrhea, and warrants a GI workup including colonoscopy. Acute diarrhea without weight loss is more often infectious and self-limited.","meaningSource":"ai-draft"},{"id":"history-14","system":"medication","question":"Do you take metformin or a laxative regularly?","listenFor":["Neither","Metformin use","Regular laxative use"],"why":"Metformin commonly causes diarrhea and gastrointestinal upset.","whySource":"curated","meaning":"Metformin commonly causes diarrhea and gastrointestinal upset.","meaningSource":"curated"}],"exam":[{"id":"exam-01","system":"general","maneuver":"Assess hydration status and orthostatic vital signs when safe.","findings":["Euvolemic, no orthostatic change","Dry mucous membranes or poor turgor","Positive orthostatic hypotension"],"how":"Measure blood pressure and heart rate after 5 minutes supine, then at 1 and 3 minutes after standing; a sustained drop of 20 mmHg systolic or 10 mmHg diastolic within 3 minutes is positive.","why":"Documenting volume status (hypovolemic, euvolemic, or hypervolemic) guides fluid management and helps distinguish prerenal, intrinsic, and volume-overload causes of kidney injury and electrolyte disturbances.","whySource":"curated","meaning":"Documenting volume status (hypovolemic, euvolemic, or hypervolemic) guides fluid management and helps distinguish prerenal, intrinsic, and volume-overload causes of kidney injury and electrolyte disturbances.","meaningSource":"curated"},{"id":"exam-02","system":"cardiovascular","maneuver":"Assess hemodynamic stability.","findings":["Normotensive, stable","Tachycardic","Hypotensive or in shock"],"how":null,"why":null,"whySource":null,"meaning":"Hemodynamic status triages the resuscitation: tachycardia signals significant volume depletion needing aggressive oral or IV rehydration, while hypotension or shock defines severe dehydration requiring IV fluids and usually admission. A normotensive, stable patient can usually be rehydrated orally.","meaningSource":"ai-draft"},{"id":"exam-03","system":"gastrointestinal","maneuver":"Palpate the abdomen for tenderness, guarding, and rebound.","findings":["Soft, nontender","Focal tenderness without guarding","Guarding, rebound, or rigidity"],"how":null,"why":"Guarding, rebound, or rigidity on palpation suggests peritonitis.","whySource":"curated","meaning":"Guarding, rebound, or rigidity on palpation suggests peritonitis.","meaningSource":"curated"},{"id":"exam-04","system":"gastrointestinal","maneuver":"Assess for abdominal distention.","findings":["No distention","Distention present"],"how":null,"why":null,"whySource":null,"meaning":"Distention in severe diarrhea raises concern for ileus, toxic megacolon, or obstruction — complications needing urgent imaging and surgical consultation. A soft, nondistended abdomen keeps the focus on medical management and rehydration.","meaningSource":"ai-draft"},{"id":"exam-05","system":"neurologic","maneuver":"Assess mental status.","findings":["Alert and oriented","Confused or lethargic"],"how":null,"why":null,"whySource":null,"meaning":"Confusion or lethargy in severe diarrhea signals severe dehydration, electrolyte derangement (especially hyponatremia), or sepsis, and marks a patient needing urgent resuscitation and labs. An alert, oriented patient suggests compensated volume status but does not rule out significant electrolyte loss.","meaningSource":"ai-draft"},{"id":"exam-06","system":"gastrointestinal","maneuver":"Perform a rectal examination when indicated.","findings":["Normal, guaiac negative, or deferred as not indicated","Gross blood on examination"],"how":null,"why":null,"whySource":null,"meaning":"A rectal exam confirms gross blood, which shifts management toward invasive or inflammatory causes, and can reveal a rectal mass or impaction. When not indicated it can be deferred, but guaiac-positive stool in diarrheal illness still points toward a lower-GI inflammatory or ischemic source.","meaningSource":"ai-draft"},{"id":"exam-07","system":"skin","maneuver":"Inspect for a new rash or joint swelling suggesting a systemic inflammatory cause.","findings":["Neither","New rash","Joint swelling"],"how":null,"why":null,"whySource":null,"meaning":"A new rash or joint swelling suggests a systemic inflammatory cause — inflammatory bowel disease with extraintestinal manifestations or a reactive process — and should prompt rheumatologic and GI evaluation. Neither finding is expected in simple infectious diarrhea.","meaningSource":"ai-draft"},{"id":"exam-08","system":"skin","maneuver":"Inspect the perianal skin for irritation or breakdown from frequent stooling.","findings":["Skin intact","Perianal irritation or breakdown"],"how":null,"why":null,"whySource":null,"meaning":"Perianal irritation or breakdown reflects the frequency and acidity of the stooling and needs barrier protection to prevent secondary infection. Severe breakdown also signals the burden of disease and supports more aggressive treatment of the underlying diarrhea.","meaningSource":"ai-draft"},{"id":"exam-09","system":"genitourinary","maneuver":"Assess urine output.","findings":["Normal urine output","Decreased urine output"],"how":null,"why":"Decreased urine output suggests volume depletion or acute kidney injury.","whySource":"curated","meaning":"Decreased urine output suggests volume depletion or acute kidney injury.","meaningSource":"curated"},{"id":"exam-10","system":"general","maneuver":"Assess body habitus and nutritional status.","findings":["Normal body habitus","Cachectic appearance"],"how":null,"why":"A cachectic appearance suggests chronic disease, malignancy, or prolonged malnutrition.","whySource":"curated","meaning":"A cachectic appearance suggests chronic disease, malignancy, or prolonged malnutrition.","meaningSource":"curated"}],"reviewNeeded":{"whyMissing":16,"howMissing":9}},{"id":"failure-to-thrive-functional-decline","title":"Failure to thrive / functional decline (elderly)","aliases":["failure to thrive","functional decline"],"history":[{"id":"history-01","system":"functional","question":"Compared to a few months ago, are you able to bathe, dress, and use the bathroom on your own, or do you need help now?","listenFor":["Independent with activities of daily living","Newly needs assistance with activities of daily living","Bedbound or fully dependent"],"why":null,"whySource":null,"meaning":"New loss of independence in basic activities of daily living is the core measure of functional decline — it quantifies severity, drives decisions about home safety and level of care, and a stepwise drop often signals an acute medical event (fall, infection, stroke) superimposed on chronic frailty rather than gradual aging.","meaningSource":"ai-draft"},{"id":"history-02","system":"functional","question":"Have you lost weight without trying over the past few months?","listenFor":["No unintentional weight loss","Unintentional weight loss"],"why":null,"whySource":null,"meaning":"Unintentional weight loss is the hallmark of failure to thrive and often precedes functional decline; it points toward malignancy, malabsorption, depression, or dysphagia as the driver and warrants a focused workup rather than attributing decline to age alone.","meaningSource":"ai-draft"},{"id":"history-03","system":"functional","question":"Has your appetite changed recently?","listenFor":["No change in appetite","Decreased appetite"],"why":null,"whySource":null,"meaning":"A recent change in appetite narrows the search: decreased appetite suggests depression, medication effect, infection, or an occult systemic illness, while preserved appetite with weight loss points toward malabsorption, hyperthyroidism, or malignancy; it also identifies a modifiable target for nutritional intervention.","meaningSource":"ai-draft"},{"id":"history-04","system":"gastrointestinal","question":"Do you have any trouble chewing or swallowing your food?","listenFor":["No difficulty chewing or swallowing","Difficulty chewing or swallowing"],"why":null,"whySource":null,"meaning":"Difficulty chewing or swallowing is a common, correctable driver of weight loss in older adults — poor dentition, ill-fitting dentures, or dysphagia — and dysphagia additionally raises aspiration risk; identifying it leads directly to dental, swallowing, or dietary referral rather than a broad medical workup.","meaningSource":"ai-draft"},{"id":"history-05","system":"psychiatric","question":"Have you been feeling down or lost interest in things you usually enjoy?","listenFor":["No low mood or anhedonia","Low mood or anhedonia"],"why":null,"whySource":null,"meaning":"Low mood and anhedonia suggest depression is driving the decline, since depression commonly causes appetite loss, weight loss, and withdrawal from activities in older adults; treating depression can reverse the whole trajectory, so it must be screened for rather than assumed to be \"just aging.\"","meaningSource":"ai-draft"},{"id":"history-06","system":"neurologic","question":"Have family or caregivers noticed your memory or thinking getting worse recently?","listenFor":["No noticed cognitive decline","Family-noticed cognitive decline"],"why":null,"whySource":null,"meaning":"Family-noticed cognitive decline suggests dementia or delirium is behind the functional loss — the patient may be forgetting meals, medications, or hygiene — and distinguishing gradual dementia from acute delirium determines whether the trigger is reversible; collateral history is essential because patients often lack insight into their own decline.","meaningSource":"ai-draft"},{"id":"history-07","system":"functional","question":"Who do you have helping you at home, and are you able to get the food, medications, and supplies you need?","listenFor":["Adequate supports, needs met","Living alone with limited supports","Unable to access food, medications, or supplies"],"why":null,"whySource":null,"meaning":"Inadequate home supports — living alone without help, or unable to access food, medications, or supplies — is a frequent, fixable cause of failure to thrive; identifying it triggers social-work, home-health, or meal-service referrals that can stabilize the patient without any further medical intervention.","meaningSource":"ai-draft"},{"id":"history-08","system":"functional","question":"Have you fallen recently?","listenFor":["No recent fall","Recent fall"],"why":null,"whySource":null,"meaning":"A recent fall may explain a sudden functional drop — through injury, fear of falling, or a head strike — or it may be the presenting sign of the underlying cause (orthostasis, arrhythmia, weakness); either way it flags fall-risk assessment and home-safety intervention as immediate next steps.","meaningSource":"ai-draft"},{"id":"history-09","system":"medication","question":"Have you started any new medications recently, especially anything for sleep, pain, or anxiety?","listenFor":["No new medication","New sedating medication started"],"why":null,"whySource":null,"meaning":"New sedating medications — sleep aids, opioids, anxiolytics, anticholinergics — are a classic reversible cause of decline in older adults, causing sedation, confusion, falls, and poor intake; a clear temporal link makes deprescribing the highest-yield intervention.","meaningSource":"ai-draft"},{"id":"history-10","system":"infectious","question":"Have you had a fever or any new pain?","listenFor":["Neither","Fever","New pain"],"why":null,"whySource":null,"meaning":"Fever or new pain points to an acute medical trigger — infection, fracture, or another new illness — behind what looks like chronic decline; older adults often present atypically, so even subtle symptoms warrant a targeted search for a reversible cause.","meaningSource":"ai-draft"},{"id":"history-11","system":"psychiatric","question":"Have you had any thoughts of harming yourself?","listenFor":["No suicidal ideation","Suicidal ideation present"],"why":null,"whySource":null,"meaning":"Suicidal ideation must be asked about directly whenever depression and decline are on the table, because older adults — especially older men — complete suicide at high rates and rarely volunteer the thought; any positive answer requires immediate safety assessment, not deferral.","meaningSource":"ai-draft"},{"id":"history-12","system":"functional","question":"Do you feel safe at home, and has anyone been physically rough with you or taken your money or belongings without permission?","listenFor":["Feels safe, no concerns","Concern for abuse, neglect, or financial exploitation"],"why":null,"whySource":null,"meaning":"Elder abuse and neglect are under-recognized drivers of failure to thrive, and patients rarely disclose them without being asked directly in a safe setting; any concern mandates a private interview, careful documentation, and referral per local reporting requirements.","meaningSource":"ai-draft"},{"id":"history-13","system":"genitourinary","question":"Have you had any accidents with your bladder or bowels recently that are new for you?","listenFor":["No new incontinence","New urinary or bowel incontinence"],"why":"New incontinence reflects loss of sphincter control and is a marker of functional decline; acute onset with back pain or leg symptoms raises concern for cauda equina syndrome.","whySource":"curated","meaning":"New incontinence reflects loss of sphincter control and is a marker of functional decline; acute onset with back pain or leg symptoms raises concern for cauda equina syndrome.","meaningSource":"curated"}],"exam":[{"id":"exam-01","system":"general","maneuver":"Assess vital signs and hydration status.","findings":["Normal vital signs, euvolemic","Abnormal vital signs or signs of dehydration"],"how":null,"why":"Documenting volume status (hypovolemic, euvolemic, or hypervolemic) guides fluid management and helps distinguish prerenal, intrinsic, and volume-overload causes of kidney injury and electrolyte disturbances.","whySource":"curated","meaning":"Documenting volume status (hypovolemic, euvolemic, or hypervolemic) guides fluid management and helps distinguish prerenal, intrinsic, and volume-overload causes of kidney injury and electrolyte disturbances.","meaningSource":"curated"},{"id":"exam-02","system":"neurologic","maneuver":"Assess attention and level of consciousness.","findings":["Alert and fully oriented","Inattentive or fluctuating alertness","Lethargic or obtunded"],"how":null,"why":"Inattention with fluctuating alertness is the hallmark of delirium.","whySource":"curated","meaning":"Inattention with fluctuating alertness is the hallmark of delirium.","meaningSource":"curated"},{"id":"exam-03","system":"general","maneuver":"Assess body habitus and nutritional status.","findings":["Normal body habitus","Cachectic appearance"],"how":null,"why":"A cachectic appearance suggests chronic disease, malignancy, or prolonged malnutrition.","whySource":"curated","meaning":"A cachectic appearance suggests chronic disease, malignancy, or prolonged malnutrition.","meaningSource":"curated"},{"id":"exam-04","system":"ent","maneuver":"Inspect the oral cavity and dentition.","findings":["Good dentition, moist mucous membranes","Poor dentition or oral lesions","Dry mucous membranes"],"how":null,"why":null,"whySource":null,"meaning":"The oral examination looks for correctable contributors to poor intake: poor dentition, oral lesions, or thrush can explain why a patient stopped eating, while dry mucous membranes suggest dehydration compounding the decline; both findings lead to concrete referrals rather than further testing.","meaningSource":"ai-draft"},{"id":"exam-05","system":"skin","maneuver":"Inspect skin and hygiene for evidence of neglect or pressure injury.","findings":["Skin intact, hygiene appropriate","Poor hygiene","Pressure ulcers or bruising in varying stages of healing"],"how":null,"why":"Pressure ulcers or bruises in varying stages of healing raise concern for neglect or abuse.","whySource":"curated","meaning":"Pressure ulcers or bruises in varying stages of healing raise concern for neglect or abuse.","meaningSource":"curated"},{"id":"exam-06","system":"musculoskeletal","maneuver":"Assess gait, balance, and safety of ambulation when safe.","findings":["Normal gait and balance","Unsteady gait","Unable to ambulate safely"],"how":null,"why":null,"whySource":null,"meaning":"Watching gait and balance directly measures fall risk and functional capacity — an unsteady gait explains recent falls and signals the need for physical therapy, assistive devices, and home-safety changes; inability to ambulate safely may mean the current living situation is no longer tenable.","meaningSource":"ai-draft"},{"id":"exam-07","system":"musculoskeletal","maneuver":"Assess proximal muscle strength.","findings":["Normal strength","Proximal muscle weakness"],"how":null,"why":"Proximal muscle weakness suggests myopathy.","whySource":"curated","meaning":"Proximal muscle weakness suggests myopathy.","meaningSource":"curated"},{"id":"exam-08","system":"cardiovascular","maneuver":"Auscultate the heart for rate, rhythm, and murmurs.","findings":["Normal rate and regular rhythm, no murmur","Irregular rhythm","Murmur present"],"how":null,"why":null,"whySource":null,"meaning":"Cardiac auscultation screens for contributors to decline that are easy to miss: an irregular rhythm suggests atrial fibrillation with poor perfusion or embolic risk, and a new murmur raises concern for endocarditis or valvular disease; both are treatable causes of \"failure to thrive.\"","meaningSource":"ai-draft"},{"id":"exam-09","system":"respiratory","maneuver":"Auscultate the lungs.","findings":["Clear bilaterally","Focal or diffuse abnormal findings"],"how":null,"why":null,"whySource":null,"meaning":"Lung auscultation searches for the occult infections and fluid overload that commonly tip frail older adults into decline — aspiration pneumonia from dysphagia, heart-failure crackles, or a new effusion; abnormal findings redirect the workup to a specific, treatable pulmonary or cardiac cause.","meaningSource":"ai-draft"},{"id":"exam-10","system":"gastrointestinal","maneuver":"Perform a rectal examination when indicated.","findings":["Normal, guaiac negative, or deferred as not indicated","Melena on rectal examination"],"how":null,"why":"Melena (black, tarry stools) indicates upper gastrointestinal bleeding.","whySource":"curated","meaning":"Melena (black, tarry stools) indicates upper gastrointestinal bleeding.","meaningSource":"curated"}],"reviewNeeded":{"whyMissing":16,"howMissing":10}},{"id":"back-pain-red-flags","title":"Back pain (with red flags/neuro deficits)","aliases":["back pain","spinal cord compression"],"history":[{"id":"history-01","system":"musculoskeletal","question":"Did this pain start after a fall or injury, or did it come on without any trauma?","listenFor":["Gradual onset without trauma","Sudden onset after a fall or injury"],"why":null,"whySource":null,"meaning":"Pain after a fall or injury raises concern for vertebral fracture — especially with osteoporosis or steroid use. Atraumatic onset in an older adult or cancer patient should still trigger a red-flag workup for pathologic fracture or metastasis rather than reassurance.","meaningSource":"ai-draft"},{"id":"history-02","system":"musculoskeletal","question":"Does the pain wake you up at night, or is it worse when you're lying flat?","listenFor":["No night pain or positional worsening","Wakes you up at night","Worse lying flat"],"why":"Night pain unrelieved by rest is a red flag for malignancy or infection.","whySource":"curated","meaning":"Night pain unrelieved by rest is a red flag for malignancy or infection.","meaningSource":"curated"},{"id":"history-03","system":"neurologic","question":"Have you had any weakness or numbness in your legs?","listenFor":["No leg weakness or numbness","Leg weakness or numbness"],"why":null,"whySource":null,"meaning":"Leg weakness or numbness localizes the problem to nerve-root or cord involvement. Bilateral symptoms, saddle anesthesia, or bladder or bowel changes point to cauda equina syndrome — a surgical emergency — so ask about those specifically.","meaningSource":"ai-draft"},{"id":"history-04","system":"neurologic","question":"Have you noticed numbness around your groin or inner thighs, like the area you'd sit on a saddle?","listenFor":["No saddle numbness","Saddle numbness present"],"why":"Saddle anesthesia with new bladder or bowel dysfunction suggests cauda equina syndrome, a surgical emergency.","whySource":"curated","meaning":"Saddle anesthesia with new bladder or bowel dysfunction suggests cauda equina syndrome, a surgical emergency.","meaningSource":"curated"},{"id":"history-05","system":"genitourinary","question":"Have you had any trouble controlling your bladder, or trouble starting your urine stream?","listenFor":["No bladder symptoms","New urinary retention or incontinence"],"why":"New urinary retention or incontinence with back pain suggests cauda equina syndrome.","whySource":"curated","meaning":"New urinary retention or incontinence with back pain suggests cauda equina syndrome.","meaningSource":"curated"},{"id":"history-06","system":"gastrointestinal","question":"Have you had any new trouble controlling your bowels?","listenFor":["No bowel symptoms","New bowel incontinence"],"why":"New bowel incontinence with back pain suggests cauda equina syndrome.","whySource":"curated","meaning":"New bowel incontinence with back pain suggests cauda equina syndrome.","meaningSource":"curated"},{"id":"history-07","system":"musculoskeletal","question":"Has your walking changed recently, like feeling unsteady or your legs giving out?","listenFor":["No gait change","New gait change or leg weakness"],"why":null,"whySource":null,"meaning":"New unsteadiness or legs giving out suggests myelopathy, severe stenosis, or cauda equina involvement rather than simple mechanical back pain. Examine strength, reflexes, and perineal sensation promptly.","meaningSource":"ai-draft"},{"id":"history-08","system":"infectious","question":"Have you had a fever along with the back pain?","listenFor":["No fever","Fever"],"why":null,"whySource":null,"meaning":"Fever with back pain raises concern for spinal infection — discitis, vertebral osteomyelitis, or epidural abscess — especially with IV drug use, recent bacteremia, or immunosuppression. This combination needs urgent imaging and labs.","meaningSource":"ai-draft"},{"id":"history-09","system":"medication","question":"Do you inject drugs?","listenFor":["No intravenous drug use","Active intravenous drug use"],"why":"Intravenous drug use raises risk for bacteremia, endocarditis, and soft tissue infection.","whySource":"curated","meaning":"Intravenous drug use raises risk for bacteremia, endocarditis, and soft tissue infection.","meaningSource":"curated"},{"id":"history-10","system":"hematologic","question":"Have you been diagnosed with cancer?","listenFor":["No known malignancy","Known malignancy"],"why":null,"whySource":null,"meaning":"Known malignancy makes metastatic disease to the spine the leading concern until proven otherwise. New back pain in a cancer patient warrants prompt imaging even without neurologic symptoms.","meaningSource":"ai-draft"},{"id":"history-11","system":"general","question":"Have you lost weight without trying, or had night sweats?","listenFor":["Neither","Unintentional weight loss","Night sweats"],"why":null,"whySource":null,"meaning":"Unintentional weight loss or night sweats with back pain point toward malignancy or chronic infection rather than mechanical pain. Pursue imaging and age-appropriate cancer evaluation.","meaningSource":"ai-draft"},{"id":"history-12","system":"medication","question":"Have you been diagnosed with osteoporosis, or are you on long-term steroids?","listenFor":["Neither","Known osteoporosis","Chronic steroid use"],"why":null,"whySource":null,"meaning":"Osteoporosis or chronic steroid use markedly raises the risk of atraumatic vertebral compression fracture — even minor trauma, or no trauma at all, can fracture an osteoporotic vertebra. Image when the pain is severe or persistent.","meaningSource":"ai-draft"},{"id":"history-13","system":"medication","question":"Are you on a blood thinner?","listenFor":["No anticoagulant use","Anticoagulant use"],"why":"Blood thinner use increases bleeding risk and severity, and affects reversal decisions.","whySource":"curated","meaning":"Blood thinner use increases bleeding risk and severity, and affects reversal decisions.","meaningSource":"curated"},{"id":"history-14","system":"musculoskeletal","question":"Have you had spine surgery in the past, or been told you have spinal disease like stenosis?","listenFor":["Neither","Prior spine surgery","Known spinal stenosis or other vertebral disease"],"why":null,"whySource":null,"meaning":"Prior spine surgery or known stenosis changes the differential toward recurrent disc herniation, hardware complications, or adjacent-segment disease — and lowers the threshold for imaging, since the anatomy is already abnormal.","meaningSource":"ai-draft"}],"exam":[{"id":"exam-01","system":"musculoskeletal","maneuver":"Palpate the spine for focal tenderness or a step-off.","findings":["No focal tenderness or step-off","Focal vertebral tenderness or step-off"],"how":null,"why":null,"whySource":null,"meaning":"Focal vertebral tenderness or a palpable step-off suggests fracture or spondylolisthesis — a structural lesion that needs imaging rather than reassurance and NSAIDs.","meaningSource":"ai-draft"},{"id":"exam-02","system":"musculoskeletal","maneuver":"Assess lower extremity strength for symmetry.","findings":["Symmetric strength throughout","Asymmetric or bilateral lower extremity weakness"],"how":null,"why":null,"whySource":null,"meaning":"Asymmetric or bilateral leg weakness maps to nerve-root or cord compromise. Document the myotomal pattern, because a new or progressive deficit changes management from conservative care to urgent imaging and possible surgical referral.","meaningSource":"ai-draft"},{"id":"exam-03","system":"neurologic","maneuver":"Assess sensation in the lower extremities and perineal region.","findings":["Normal sensation","Decreased sensation in the legs","Saddle anesthesia"],"how":null,"why":"Saddle anesthesia with new bladder or bowel dysfunction suggests cauda equina syndrome, a surgical emergency.","whySource":"curated","meaning":"Saddle anesthesia with new bladder or bowel dysfunction suggests cauda equina syndrome, a surgical emergency.","meaningSource":"curated"},{"id":"exam-04","system":"neurologic","maneuver":"Assess deep tendon reflexes in the lower extremities.","findings":["Normal reflexes","Diminished or absent reflexes","Hyperreflexia or clonus"],"how":null,"why":"Hyperreflexia or clonus suggests an upper motor neuron lesion, as in myelopathy or corticospinal tract disease.","whySource":"curated","meaning":"Hyperreflexia or clonus suggests an upper motor neuron lesion, as in myelopathy or corticospinal tract disease.","meaningSource":"curated"},{"id":"exam-05","system":"genitourinary","maneuver":"Assess rectal tone and for a distended bladder when clinically indicated.","findings":["Normal tone, nondistended bladder, or deferred as not indicated","Decreased rectal tone","Distended, palpable bladder"],"how":null,"why":"A distended, palpable bladder indicates urinary retention.","whySource":"curated","meaning":"A distended, palpable bladder indicates urinary retention.","meaningSource":"curated"},{"id":"exam-06","system":"general","maneuver":"Assess for fever.","findings":["Afebrile","Febrile"],"how":null,"why":null,"whySource":null,"meaning":"Fever on exam corroborates the history and keeps spinal infection — discitis, osteomyelitis, epidural abscess — at the top of the differential. Do not attribute it to a coincidental viral illness without evidence.","meaningSource":"ai-draft"},{"id":"exam-07","system":"skin","maneuver":"Inspect the back for a wound, needle track marks, or overlying skin infection.","findings":["Normal skin","Skin infection or needle track marks overlying the spine"],"how":null,"why":"Needle track marks suggest intravenous drug use and raise concern for bacteremia, endocarditis, or soft tissue infection.","whySource":"curated","meaning":"Needle track marks suggest intravenous drug use and raise concern for bacteremia, endocarditis, or soft tissue infection.","meaningSource":"curated"},{"id":"exam-08","system":"musculoskeletal","maneuver":"Assess straight leg raise for radicular reproduction of pain.","findings":["Negative","Positive"],"how":"With the patient supine, slowly raise the extended leg; reproduction of radiating pain below the knee between 30 and 70 degrees is positive.","why":null,"whySource":null,"meaning":"A positive straight leg raise — radiating pain below the knee reproduced between 30 and 70 degrees of leg elevation — indicates lumbosacral nerve-root tension, most often from disc herniation. Pain confined to the back or hamstring without radiation is not a true positive.","meaningSource":"ai-draft"},{"id":"exam-09","system":"musculoskeletal","maneuver":"Assess gait when safe.","findings":["Normal gait","Unsteady or unable to ambulate safely"],"how":null,"why":null,"whySource":null,"meaning":"An unsteady or unsafe gait confirms functionally significant neurologic involvement — whether from weakness, myelopathy, or severe pain. Combined with red-flag symptoms, it should accelerate imaging and referral.","meaningSource":"ai-draft"},{"id":"exam-10","system":"hematologic","maneuver":"Palpate for lymphadenopathy or a palpable mass suggesting malignancy.","findings":["None","Lymphadenopathy or palpable mass present"],"how":null,"why":"Lymphadenopathy suggests infection, malignancy, or systemic inflammatory disease.","whySource":"curated","meaning":"Lymphadenopathy suggests infection, malignancy, or systemic inflammatory disease.","meaningSource":"curated"}],"reviewNeeded":{"whyMissing":13,"howMissing":9}},{"id":"cirrhosis-liver-complications","title":"Cirrhosis/liver disease complications","aliases":["cirrhosis","hepatic decompensation"],"history":[{"id":"history-01","system":"gastrointestinal","question":"Do you have cirrhosis or liver disease, and do you know what caused it, like alcohol or hepatitis?","listenFor":["No known liver disease","Known cirrhosis from alcohol","Known cirrhosis from viral hepatitis or another cause"],"why":null,"whySource":null,"meaning":"Knowing the cause — alcohol, viral hepatitis, fatty liver, or autoimmune disease — guides what is still modifiable: ongoing alcohol use, untreated hepatitis C, and metabolic syndrome each change counseling, screening, and prognosis.","meaningSource":"ai-draft"},{"id":"history-02","system":"gastrointestinal","question":"Has your belly gotten more swollen or your pants tighter recently?","listenFor":["No increased abdominal girth","Increased abdominal girth or new ascites"],"why":null,"whySource":null,"meaning":"Increasing abdominal girth signals new or worsening ascites — a marker of decompensation. Look for triggers such as infection, bleeding, missed diuretics, or dietary indiscretion, and consider spontaneous bacterial peritonitis if fever or pain accompanies it.","meaningSource":"ai-draft"},{"id":"history-03","system":"neurologic","question":"Have family or friends said you seem more confused or are sleeping at the wrong times of day?","listenFor":["No noticed confusion or sleep-wake reversal","Family-noticed confusion or sleep-wake reversal"],"why":"Sleep-wake reversal is an early sign of hepatic encephalopathy.","whySource":"curated","meaning":"Sleep-wake reversal is an early sign of hepatic encephalopathy.","meaningSource":"curated"},{"id":"history-04","system":"gastrointestinal","question":"Have you been constipated, or have you missed doses of your lactulose?","listenFor":["No constipation, taking lactulose as prescribed","Constipation or missed lactulose doses"],"why":"Constipation and missed lactulose doses are common precipitants of hepatic encephalopathy.","whySource":"curated","meaning":"Constipation and missed lactulose doses are common precipitants of hepatic encephalopathy.","meaningSource":"curated"},{"id":"history-05","system":"hematologic","question":"Have you vomited blood, or had black, tarry stools?","listenFor":["Neither","Vomited blood","Black, tarry stools"],"why":"Black, tarry stools (melena), hematochezia, or hematemesis indicate gastrointestinal bleeding; melena points to an upper source.","whySource":"curated","meaning":"Black, tarry stools (melena), hematochezia, or hematemesis indicate gastrointestinal bleeding; melena points to an upper source.","meaningSource":"curated"},{"id":"history-06","system":"skin","question":"Has your skin or the whites of your eyes looked more yellow recently?","listenFor":["No jaundice","New or worsening jaundice"],"why":null,"whySource":null,"meaning":"New or worsening jaundice marks deteriorating liver function or new biliary obstruction. Track the trend, because rising bilirubin alongside encephalopathy or coagulopathy defines acute-on-chronic liver failure.","meaningSource":"ai-draft"},{"id":"history-07","system":"infectious","question":"Do you have a fever or new belly pain, especially if you already have fluid in your belly?","listenFor":["Neither","Fever","New abdominal pain"],"why":"Fever with new abdominal pain in a patient with ascites raises concern for spontaneous bacterial peritonitis.","whySource":"curated","meaning":"Fever with new abdominal pain in a patient with ascites raises concern for spontaneous bacterial peritonitis.","meaningSource":"curated"},{"id":"history-08","system":"genitourinary","question":"Have you noticed a change in how much you're urinating?","listenFor":["Normal urine output","Decreased urine output"],"why":"Decreased urine output suggests volume depletion or acute kidney injury.","whySource":"curated","meaning":"Decreased urine output suggests volume depletion or acute kidney injury.","meaningSource":"curated"},{"id":"history-09","system":"hematologic","question":"Have you noticed new or worse bruising, or bleeding that's hard to stop?","listenFor":["No unusual bruising or bleeding","New or worsening bruising or bleeding"],"why":null,"whySource":null,"meaning":"New bruising or hard-to-stop bleeding reflects the coagulopathy and thrombocytopenia of advanced liver disease. Correct it for active bleeding or procedures — and remember that variceal bleeding, not mucosal oozing, is the life-threatening concern to rule out.","meaningSource":"ai-draft"},{"id":"history-10","system":"medication","question":"Have you been drinking alcohol recently?","listenFor":["No recent alcohol use","Recent alcohol use"],"why":null,"whySource":null,"meaning":"Recent alcohol use in a cirrhotic patient means ongoing liver injury, raises the risk of alcoholic hepatitis superimposed on cirrhosis, and flags withdrawal risk on admission. Screen for withdrawal and offer treatment referral.","meaningSource":"ai-draft"},{"id":"history-11","system":"medication","question":"Have you been taking your water pills as prescribed?","listenFor":["Taking diuretics as prescribed","Missed or stopped diuretic doses","Not on diuretics"],"why":null,"whySource":null,"meaning":"Missed diuretic doses explain worsening ascites and edema, while overdiuresis risks acute kidney injury and electrolyte shifts. The history distinguishes simple nonadherence from diuretic resistance or a new precipitant.","meaningSource":"ai-draft"},{"id":"history-12","system":"gastrointestinal","question":"Have you ever had bleeding from varices or a fluid infection in your belly before?","listenFor":["Neither","Prior variceal bleed","Prior spontaneous bacterial peritonitis"],"why":"Prior variceal bleeding predicts recurrence and the need for secondary prophylaxis.","whySource":"curated","meaning":"Prior variceal bleeding predicts recurrence and the need for secondary prophylaxis.","meaningSource":"curated"},{"id":"history-13","system":"gastrointestinal","question":"Have you lost weight without trying, or has your appetite gotten worse?","listenFor":["Neither","Unintentional weight loss","Decreased appetite"],"why":null,"whySource":null,"meaning":"Unintentional weight loss or worsening appetite in cirrhosis raises concern for hepatocellular carcinoma or progressive decompensation with malnutrition. Make sure HCC surveillance imaging is current and assess nutritional status.","meaningSource":"ai-draft"}],"exam":[{"id":"exam-01","system":"neurologic","maneuver":"Assess attention, orientation, and level of consciousness.","findings":["Alert and fully oriented","Inattentive or disoriented","Lethargic or obtunded"],"how":null,"why":"Inattention with fluctuating alertness is the hallmark of delirium.","whySource":"curated","meaning":"Inattention with fluctuating alertness is the hallmark of delirium.","meaningSource":"curated"},{"id":"exam-02","system":"neurologic","maneuver":"Assess for asterixis by having the patient hold their arms out with wrists extended.","findings":["No asterixis","Asterixis present"],"how":"Have the patient extend both arms with wrists dorsiflexed and fingers spread; observe for 15 to 30 seconds for the flapping tremor.","why":"Asterixis (flapping tremor of the outstretched hands) suggests a metabolic encephalopathy, classically hepatic encephalopathy.","whySource":"curated","meaning":"Asterixis (flapping tremor of the outstretched hands) suggests a metabolic encephalopathy, classically hepatic encephalopathy.","meaningSource":"curated"},{"id":"exam-03","system":"gastrointestinal","maneuver":"Inspect and percuss the abdomen for distention and shifting dullness suggesting ascites.","findings":["No distention or shifting dullness","Distention with shifting dullness"],"how":null,"why":"Shifting dullness and a fluid wave suggest ascites.","whySource":"curated","meaning":"Shifting dullness and a fluid wave suggest ascites.","meaningSource":"curated"},{"id":"exam-04","system":"gastrointestinal","maneuver":"Palpate the abdomen for tenderness or guarding suggesting spontaneous bacterial peritonitis.","findings":["Soft, nontender","Diffuse tenderness","Guarding or rebound"],"how":null,"why":"Guarding, rebound, or rigidity on palpation suggests peritonitis.","whySource":"curated","meaning":"Guarding, rebound, or rigidity on palpation suggests peritonitis.","meaningSource":"curated"},{"id":"exam-05","system":"skin","maneuver":"Inspect skin and sclerae for jaundice.","findings":["Absent","Present"],"how":null,"why":null,"whySource":null,"meaning":"Jaundice on exam confirms impaired bilirubin handling. Compare with prior exams to judge whether this is chronic baseline or new decompensation, and look for accompanying asterixis or bleeding that would mark multi-system failure.","meaningSource":"ai-draft"},{"id":"exam-06","system":"skin","maneuver":"Inspect for spider angiomas, palmar erythema, caput medusae, and gynecomastia.","findings":["None of these stigmata","One or more stigmata of chronic liver disease present"],"how":null,"why":"Spider angiomas, palmar erythema, and caput medusae are cutaneous stigmata of chronic liver disease.","whySource":"curated","meaning":"Spider angiomas, palmar erythema, and caput medusae are cutaneous stigmata of chronic liver disease.","meaningSource":"curated"},{"id":"exam-07","system":"skin","maneuver":"Inspect for bruising or petechiae suggesting coagulopathy.","findings":["No bruising or petechiae","Bruising or petechiae present"],"how":null,"why":"Petechiae or ecchymosis suggest thrombocytopenia or another bleeding diathesis.","whySource":"curated","meaning":"Petechiae or ecchymosis suggest thrombocytopenia or another bleeding diathesis.","meaningSource":"curated"},{"id":"exam-08","system":"cardiovascular","maneuver":"Assess for lower extremity edema.","findings":["No peripheral edema","Peripheral edema present"],"how":null,"why":null,"whySource":null,"meaning":"Peripheral edema in cirrhosis reflects sodium retention and hypoalbuminemia. Track it alongside weight and girth to judge diuretic response — and distinguish it from cardiac or renal causes when the picture is mixed.","meaningSource":"ai-draft"},{"id":"exam-09","system":"general","maneuver":"Assess vital signs for fever or hemodynamic instability.","findings":["Normal vital signs","Febrile","Hypotensive or tachycardic"],"how":null,"why":null,"whySource":null,"meaning":"Fever in a cirrhotic patient with ascites raises concern for spontaneous bacterial peritonitis until proven otherwise — tap the ascites promptly. Hypotension or tachycardia should trigger a search for variceal bleeding or sepsis, the two great killers in decompensated cirrhosis.","meaningSource":"ai-draft"},{"id":"exam-10","system":"gastrointestinal","maneuver":"Perform a rectal examination when indicated.","findings":["Normal, guaiac negative, or deferred as not indicated","Melena on rectal examination"],"how":null,"why":"Melena (black, tarry stools) indicates upper gastrointestinal bleeding.","whySource":"curated","meaning":"Melena (black, tarry stools) indicates upper gastrointestinal bleeding.","meaningSource":"curated"}],"reviewNeeded":{"whyMissing":10,"howMissing":9}},{"id":"adrenal-insufficiency-crisis","title":"Adrenal insufficiency / adrenal crisis","aliases":["adrenal crisis","adrenal insufficiency"],"history":[{"id":"history-01","system":"endocrine","question":"Have you been feeling profoundly weak or tired, out of proportion to how sick you feel otherwise?","listenFor":["No profound fatigue","Profound, out-of-proportion fatigue"],"why":null,"whySource":null,"meaning":"Profound fatigue out of proportion to apparent illness is the classic prodrome of adrenal insufficiency — patients describe an exhaustion that rest does not fix; its presence should keep adrenal crisis on the differential even when vitals are still normal, because the collapse can be precipitous.","meaningSource":"ai-draft"},{"id":"history-02","system":"gastrointestinal","question":"Have you had nausea, vomiting, or belly pain along with the weakness?","listenFor":["None of these","Nausea or vomiting","Abdominal pain"],"why":null,"whySource":null,"meaning":"Nausea, vomiting, and abdominal pain are common presenting features of adrenal crisis and are frequently misattributed to gastroenteritis, which delays treatment; when they accompany unexplained weakness and hypotension, empiric stress-dose steroids should not wait for confirmatory labs.","meaningSource":"ai-draft"},{"id":"history-03","system":"neurologic","question":"Have you felt dizzy or lightheaded, especially when standing up?","listenFor":["No dizziness","Dizzy or lightheaded on standing"],"why":"Dizziness on standing suggests orthostatic hypotension from volume depletion, autonomic dysfunction, or medications.","whySource":"curated","meaning":"Dizziness on standing suggests orthostatic hypotension from volume depletion, autonomic dysfunction, or medications.","meaningSource":"curated"},{"id":"history-04","system":"endocrine","question":"Have you been craving salty foods, or lost weight without trying?","listenFor":["Neither","Salt craving","Unintentional weight loss"],"why":"Salt craving suggests mineralocorticoid deficiency, as in primary adrenal insufficiency.","whySource":"curated","meaning":"Salt craving suggests mineralocorticoid deficiency, as in primary adrenal insufficiency.","meaningSource":"curated"},{"id":"history-05","system":"medication","question":"Are you on a steroid medication like prednisone, and have you missed doses or run out recently?","listenFor":["Not on chronic steroids","On chronic steroids, taking as prescribed","On chronic steroids, missed doses or ran out"],"why":"Abrupt cessation of chronic steroids can precipitate adrenal crisis.","whySource":"curated","meaning":"Abrupt cessation of chronic steroids can precipitate adrenal crisis.","meaningSource":"curated"},{"id":"history-06","system":"medication","question":"Have you been sick recently, had surgery, or gone through some other stress that would normally require extra steroid dosing?","listenFor":["No recent physiologic stress","Recent illness, surgery, or major stress without stress-dose steroids"],"why":"Physiologic stress without stress-dose steroids can precipitate adrenal crisis.","whySource":"curated","meaning":"Physiologic stress without stress-dose steroids can precipitate adrenal crisis.","meaningSource":"curated"},{"id":"history-07","system":"infectious","question":"Do you have a fever or symptoms of an infection right now?","listenFor":["No fever or infection symptoms","Fever or infection symptoms present"],"why":null,"whySource":null,"meaning":"Infection is the most common precipitant of adrenal crisis, because physiologic stress outstrips the patient's limited cortisol reserve; finding fever or infection symptoms explains the decompensation and means both the infection and the cortisol deficit must be treated simultaneously.","meaningSource":"ai-draft"},{"id":"history-08","system":"skin","question":"Have you or others noticed your skin getting darker, especially in creases or scars?","listenFor":["No skin darkening","New hyperpigmentation"],"why":"New hyperpigmentation of skin creases and scars suggests primary adrenal insufficiency.","whySource":"curated","meaning":"New hyperpigmentation of skin creases and scars suggests primary adrenal insufficiency.","meaningSource":"curated"},{"id":"history-09","system":"endocrine","question":"Do you have a known adrenal, pituitary, or autoimmune condition, or have you had an adrenal crisis before?","listenFor":["None of these","Known adrenal or pituitary disease","Prior adrenal crisis"],"why":null,"whySource":null,"meaning":"Known adrenal or pituitary disease — or a prior crisis — makes adrenal crisis the leading diagnosis when the patient deteriorates, and it should lower the threshold for stress-dose steroids dramatically; absence of a known diagnosis does not exclude it, especially with autoimmune clues or chronic steroid use.","meaningSource":"ai-draft"},{"id":"history-10","system":"gastrointestinal","question":"Have you had vomiting or diarrhea that kept you from taking your usual medications?","listenFor":["No vomiting or diarrhea affecting medications","Vomiting or diarrhea preventing medication intake"],"why":null,"whySource":null,"meaning":"Vomiting or diarrhea that prevented medication intake is a classic setup for crisis in patients on chronic steroids or mineralocorticoid replacement — missed doses during a gastrointestinal illness remove the very hormones needed to weather the stress; the history directly supports empiric parenteral steroids.","meaningSource":"ai-draft"},{"id":"history-11","system":"neurologic","question":"Have you felt confused, or has anyone said you seem less alert than usual?","listenFor":["No confusion","New confusion or decreased alertness"],"why":"New confusion marks severity of systemic illness and suggests acute organ dysfunction, as in severe infection, sepsis, or metabolic derangement.","whySource":"curated","meaning":"New confusion marks severity of systemic illness and suggests acute organ dysfunction, as in severe infection, sepsis, or metabolic derangement.","meaningSource":"curated"},{"id":"history-12","system":"musculoskeletal","question":"Have you had muscle or joint pain along with the weakness?","listenFor":["No muscle or joint pain","Diffuse muscle or joint pain"],"why":null,"whySource":null,"meaning":"Diffuse muscle and joint pain are under-recognized features of cortisol deficiency and help distinguish adrenal crisis from pure sepsis or gastroenteritis when present with the characteristic weakness and GI symptoms; they add weight to an empiric-steroid decision.","meaningSource":"ai-draft"}],"exam":[{"id":"exam-01","system":"cardiovascular","maneuver":"Measure blood pressure lying and standing to assess for orthostatic hypotension.","findings":["No orthostatic change","Positive orthostatic hypotension","Hypotensive supine"],"how":"Measure blood pressure and heart rate after 5 minutes supine, then at 1 and 3 minutes after standing; a sustained drop of 20 mmHg systolic or 10 mmHg diastolic within 3 minutes is positive.","why":"Supine hypotension suggests volume depletion or adrenal crisis.","whySource":"curated","meaning":"Supine hypotension suggests volume depletion or adrenal crisis.","meaningSource":"curated"},{"id":"exam-02","system":"cardiovascular","maneuver":"Assess heart rate and overall hemodynamic stability.","findings":["Normal heart rate, hemodynamically stable","Tachycardic","In shock"],"how":null,"why":null,"whySource":null,"meaning":"Tachycardia progressing to shock is the hemodynamic signature of adrenal crisis — hypotension refractory to fluids that responds dramatically to steroids; recognizing this pattern is the indication to give stress-dose hydrocortisone empirically rather than continuing fluids alone.","meaningSource":"ai-draft"},{"id":"exam-03","system":"general","maneuver":"Assess temperature for fever.","findings":["Afebrile","Febrile"],"how":null,"why":null,"whySource":null,"meaning":"Fever in a deteriorating patient with suspected adrenal insufficiency most often signals the precipitating infection, but adrenal crisis itself can cause fever; either way, fever reinforces the need to search for and treat an infectious trigger alongside steroid replacement.","meaningSource":"ai-draft"},{"id":"exam-04","system":"skin","maneuver":"Inspect skin, creases, and scars for hyperpigmentation.","findings":["No hyperpigmentation","Hyperpigmentation present"],"how":null,"why":"New hyperpigmentation of skin creases and scars suggests primary adrenal insufficiency.","whySource":"curated","meaning":"New hyperpigmentation of skin creases and scars suggests primary adrenal insufficiency.","meaningSource":"curated"},{"id":"exam-05","system":"skin","maneuver":"Assess mucous membranes and skin turgor for dehydration.","findings":["Moist mucous membranes, normal turgor","Dry mucous membranes or poor turgor"],"how":null,"why":null,"whySource":null,"meaning":"Dry mucous membranes and poor skin turgor reflect the volume depletion and salt-wasting of mineralocorticoid deficiency, supporting adrenal crisis over simple sepsis; they guide aggressive isotonic fluid resuscitation alongside steroids.","meaningSource":"ai-draft"},{"id":"exam-06","system":"neurologic","maneuver":"Assess mental status and orientation.","findings":["Alert and oriented","Confused or lethargic","Obtunded"],"how":null,"why":null,"whySource":null,"meaning":"Progressive confusion, lethargy, or obtundation marks worsening cerebral hypoperfusion or severe hyponatremia/hypoglycemia in adrenal crisis and signals that the patient is decompensating; it is an indication for immediate steroids, glucose check, and ICU-level care.","meaningSource":"ai-draft"},{"id":"exam-07","system":"gastrointestinal","maneuver":"Palpate the abdomen for tenderness.","findings":["Soft, nontender","Diffuse tenderness","Guarding or rigidity"],"how":null,"why":"Guarding, rebound, or rigidity on palpation suggests peritonitis.","whySource":"curated","meaning":"Guarding, rebound, or rigidity on palpation suggests peritonitis.","meaningSource":"curated"},{"id":"exam-08","system":"skin","maneuver":"Inspect for vitiligo or other autoimmune skin findings.","findings":["None present","Vitiligo present"],"how":null,"why":"Vitiligo is associated with autoimmune adrenalitis.","whySource":"curated","meaning":"Vitiligo is associated with autoimmune adrenalitis.","meaningSource":"curated"},{"id":"exam-09","system":"endocrine","maneuver":"Check fingerstick glucose.","findings":["Normal glucose","Hypoglycemic"],"how":"Prick the side of the fingertip rather than the pad, and apply the blood drop to the test strip.","why":"Hypoglycemia causes neuroglycopenic symptoms such as confusion, diaphoresis, and tremor, and needs urgent correction.","whySource":"curated","meaning":"Hypoglycemia causes neuroglycopenic symptoms such as confusion, diaphoresis, and tremor, and needs urgent correction.","meaningSource":"curated"},{"id":"exam-10","system":"musculoskeletal","maneuver":"Assess proximal muscle strength.","findings":["Normal strength","Proximal muscle weakness"],"how":null,"why":"Proximal muscle weakness suggests myopathy.","whySource":"curated","meaning":"Proximal muscle weakness suggests myopathy.","meaningSource":"curated"}],"reviewNeeded":{"whyMissing":10,"howMissing":8}},{"id":"seizure-new-onset","title":"Seizure / new-onset seizure disorder","aliases":["new seizure","convulsion"],"history":[{"id":"history-01","system":"neurologic","question":"Did you or a witness see your body shake or jerk, or did you just lose consciousness without movement?","listenFor":["No witnessed shaking or jerking","Witnessed rhythmic shaking or jerking","Loss of consciousness without movement"],"why":null,"whySource":null,"meaning":"Witnessed rhythmic shaking distinguishes a generalized convulsive seizure from syncope, which can also produce brief jerking; loss of consciousness without movement raises concern for syncope or a non-convulsive event instead, which leads down a cardiac or neurologic workup rather than an epilepsy pathway.","meaningSource":"ai-draft"},{"id":"history-02","system":"neurologic","question":"Did you feel a warning or strange sensation right before it happened, like a smell, taste, or rising feeling in your stomach?","listenFor":["No warning aura","Aura present before the event"],"why":"A warning aura is itself a focal seizure onset and helps localize the epilepsy.","whySource":"curated","meaning":"A warning aura is itself a focal seizure onset and helps localize the epilepsy.","meaningSource":"curated"},{"id":"history-03","system":"genitourinary","question":"Did you bite your tongue or lose control of your bladder or bowels during the event?","listenFor":["Neither","Tongue bite","Urinary or bowel incontinence"],"why":"A tongue bite during the event favors a generalized tonic-clonic seizure over syncope.","whySource":"curated","meaning":"A tongue bite during the event favors a generalized tonic-clonic seizure over syncope.","meaningSource":"curated"},{"id":"history-04","system":"neurologic","question":"After it happened, were you confused or extremely sleepy for a while before returning to normal?","listenFor":["No postictal confusion, back to baseline immediately","Postictal confusion or drowsiness lasting minutes to hours"],"why":"Postictal confusion or drowsiness lasting minutes to hours supports a true seizure rather than syncope.","whySource":"curated","meaning":"Postictal confusion or drowsiness lasting minutes to hours supports a true seizure rather than syncope.","meaningSource":"curated"},{"id":"history-05","system":"neurologic","question":"Have you had seizures before, and if so, are you on seizure medication and taking it as prescribed?","listenFor":["No prior seizures","Known epilepsy, taking medication as prescribed","Known epilepsy, missed doses or stopped medication"],"why":"Missed antiepileptic doses are a common precipitant of breakthrough seizures.","whySource":"curated","meaning":"Missed antiepileptic doses are a common precipitant of breakthrough seizures.","meaningSource":"curated"},{"id":"history-06","system":"neurologic","question":"Have you had any weakness, numbness, trouble speaking, or vision changes since the event that haven't gone away?","listenFor":["No persistent focal symptoms","Persistent focal weakness, numbness, or speech change"],"why":null,"whySource":null,"meaning":"Focal symptoms that do not resolve after the postictal period has passed suggest a structural brain lesion — tumor, stroke, or abscess — as the seizure's cause (Todd's paresis resolves within hours); persistent deficits warrant urgent neuroimaging rather than a routine new-onset seizure workup.","meaningSource":"ai-draft"},{"id":"history-07","system":"medication","question":"Do you drink alcohol regularly, and if so, have you cut back or stopped recently?","listenFor":["No regular alcohol use","Regular alcohol use, no recent change","Regular alcohol use with recent reduction or cessation"],"why":null,"whySource":null,"meaning":"Recent reduction or cessation of regular alcohol intake is a classic trigger for withdrawal seizures, which typically occur 12–48 hours after the last drink; identifying this shifts management toward withdrawal prophylaxis with benzodiazepines rather than long-term antiepileptic therapy.","meaningSource":"ai-draft"},{"id":"history-08","system":"medication","question":"Have you used any recreational drugs recently, or missed doses of a benzodiazepine or other sedating medication?","listenFor":["Neither","Recent recreational drug use","Missed sedative or benzodiazepine dose"],"why":"Missed benzodiazepine or sedative doses can precipitate withdrawal seizures.","whySource":"curated","meaning":"Missed benzodiazepine or sedative doses can precipitate withdrawal seizures.","meaningSource":"curated"},{"id":"history-09","system":"neurologic","question":"Have you had a severe headache, fever, or stiff neck before or after the event?","listenFor":["None of these","Severe headache","Fever or neck stiffness"],"why":"Neck stiffness with fever and headache suggests meningitis.","whySource":"curated","meaning":"Neck stiffness with fever and headache suggests meningitis.","meaningSource":"curated"},{"id":"history-10","system":"neurologic","question":"Have you had a head injury or fall recently, or are you on a blood thinner?","listenFor":["Neither","Recent head injury or fall","On anticoagulant or antiplatelet medication"],"why":"Blood thinner use increases bleeding risk and severity, and affects reversal decisions.","whySource":"curated","meaning":"Blood thinner use increases bleeding risk and severity, and affects reversal decisions.","meaningSource":"curated"},{"id":"history-11","system":"hematologic","question":"Do you have a history of cancer, especially any cancer that could spread to the brain?","listenFor":["No known malignancy","Known malignancy"],"why":null,"whySource":null,"meaning":"A known malignancy — especially lung, breast, or melanoma — raises concern for brain metastases as the seizure focus; a positive history makes urgent contrast neuroimaging the priority, since the seizure may be the first sign of intracranial spread.","meaningSource":"ai-draft"},{"id":"history-12","system":"endocrine","question":"Do you have diabetes, and could your blood sugar have been very low or very high before this happened?","listenFor":["No known diabetes","Known diabetes, possible hypoglycemia","Known diabetes, possible severe hyperglycemia"],"why":null,"whySource":null,"meaning":"Hypoglycemia is a common, immediately reversible seizure trigger in diabetes and must be checked at the bedside without delay; severe hyperglycemia (hyperosmolar state) can also provoke seizures, so a glucose check is mandatory before attributing the event to epilepsy.","meaningSource":"ai-draft"},{"id":"history-13","system":"reproductive","question":"Is there any chance you could be pregnant, and if so, have you had swelling or high blood pressure this pregnancy?","listenFor":["Not applicable or not pregnant","Pregnant without preeclampsia symptoms","Pregnant with swelling or high blood pressure"],"why":"New hypertension with swelling in pregnancy raises concern for eclampsia as the cause of seizure.","whySource":"curated","meaning":"New hypertension with swelling in pregnancy raises concern for eclampsia as the cause of seizure.","meaningSource":"curated"}],"exam":[{"id":"exam-01","system":"endocrine","maneuver":"Check fingerstick glucose.","findings":["Normal glucose","Hypoglycemic","Severely hyperglycemic"],"how":"Prick the side of the fingertip rather than the pad, and apply the blood drop to the test strip.","why":"Hypoglycemia causes neuroglycopenic symptoms such as confusion, diaphoresis, and tremor, and needs urgent correction.","whySource":"curated","meaning":"Hypoglycemia causes neuroglycopenic symptoms such as confusion, diaphoresis, and tremor, and needs urgent correction.","meaningSource":"curated"},{"id":"exam-02","system":"general","maneuver":"Assess temperature for fever.","findings":["Afebrile","Febrile"],"how":null,"why":null,"whySource":null,"meaning":"Fever after a seizure raises concern for central nervous system infection — meningitis or encephalitis — as the cause, especially with altered mental status; it should prompt a lumbar puncture consideration once imaging excludes a mass lesion, rather than assuming a simple febrile trigger in an adult.","meaningSource":"ai-draft"},{"id":"exam-03","system":"neurologic","maneuver":"Assess level of consciousness and orientation.","findings":["Alert and fully oriented","Postictal confusion improving","Persistently obtunded"],"how":null,"why":"Postictal confusion or drowsiness lasting minutes to hours supports a true seizure rather than syncope.","whySource":"curated","meaning":"Postictal confusion or drowsiness lasting minutes to hours supports a true seizure rather than syncope.","meaningSource":"curated"},{"id":"exam-04","system":"neurologic","maneuver":"Assess for a focal neurologic deficit such as asymmetric weakness or facial droop.","findings":["No focal deficit","Focal deficit present"],"how":null,"why":"New facial droop suggests stroke.","whySource":"curated","meaning":"New facial droop suggests stroke.","meaningSource":"curated"},{"id":"exam-05","system":"neurologic","maneuver":"Assess neck stiffness for meningismus.","findings":["No nuchal rigidity","Nuchal rigidity present"],"how":null,"why":"Nuchal rigidity suggests meningeal irritation, as in meningitis or subarachnoid hemorrhage.","whySource":"curated","meaning":"Nuchal rigidity suggests meningeal irritation, as in meningitis or subarachnoid hemorrhage.","meaningSource":"curated"},{"id":"exam-06","system":"skin","maneuver":"Inspect the tongue for lateral bite marks.","findings":["No tongue trauma","Lateral tongue bite present"],"how":null,"why":"A lateral tongue bite favors a generalized tonic-clonic seizure over syncope.","whySource":"curated","meaning":"A lateral tongue bite favors a generalized tonic-clonic seizure over syncope.","meaningSource":"curated"},{"id":"exam-07","system":"skin","maneuver":"Inspect the scalp, face, and shoulders for injury from a fall.","findings":["No injury","Injury consistent with a fall"],"how":null,"why":null,"whySource":null,"meaning":"Injuries to the scalp, face, or shoulders corroborate a genuine convulsive event with a fall and help distinguish it from syncope or psychogenic spells; the pattern of injury can also hint at the seizure type, such as tongue biting or shoulder dislocation in tonic-clonic activity.","meaningSource":"ai-draft"},{"id":"exam-08","system":"neurologic","maneuver":"Assess for tremor, diaphoresis, and pupil size suggesting intoxication or withdrawal.","findings":["None of these","Tremor and diaphoresis suggesting withdrawal","Pupillary changes suggesting intoxication"],"how":null,"why":null,"whySource":null,"meaning":"Tremor with diaphoresis suggests alcohol or sedative withdrawal as the seizure trigger, while pupillary changes point toward intoxication with stimulants or other drugs; identifying a toxic-metabolic trigger redirects management to withdrawal treatment or toxicology rather than chronic seizure therapy.","meaningSource":"ai-draft"},{"id":"exam-09","system":"cardiovascular","maneuver":"Assess heart rate and rhythm for an arrhythmia that could explain a convulsive syncope.","findings":["Regular rate and rhythm","Irregular rhythm"],"how":null,"why":null,"whySource":null,"meaning":"An irregular rhythm raises concern that the \"seizure\" was actually convulsive syncope from a cardiac arrhythmia — transient cerebral hypoperfusion can produce myoclonic jerks that mimic epilepsy; this finding shifts the workup to cardiac monitoring and echocardiography.","meaningSource":"ai-draft"},{"id":"exam-10","system":"reproductive","maneuver":"Assess for hyperreflexia or clonus when eclampsia is a concern.","findings":["Not applicable or normal reflexes","Hyperreflexia or clonus present"],"how":null,"why":"Hyperreflexia or clonus in a pregnant or postpartum patient suggests preeclampsia with heightened seizure risk.","whySource":"curated","meaning":"Hyperreflexia or clonus in a pregnant or postpartum patient suggests preeclampsia with heightened seizure risk.","meaningSource":"curated"}],"reviewNeeded":{"whyMissing":9,"howMissing":9}},{"id":"hyperglycemia-non-dka","title":"Hyperglycemia (non-DKA)","aliases":["hyperglycemia","high blood glucose"],"history":[{"id":"history-01","system":"endocrine","question":"Do you have diabetes, and if so, is it type 1 or type 2?","listenFor":["No known diabetes","Known type 2 diabetes","Known type 1 diabetes"],"why":null,"whySource":null,"meaning":"Type 1 diabetes carries DKA risk even at moderate glucose levels and always needs ketone checking, while type 2 leans toward hyperosmolar states; the type determines which emergency to rule out and how aggressively to treat.","meaningSource":"ai-draft"},{"id":"history-02","system":"medication","question":"Have you missed doses of your insulin or diabetes medication recently?","listenFor":["Taking medication as prescribed","Missed one or more doses","Not on any diabetes medication"],"why":"Missed insulin doses are a leading precipitant of diabetic ketoacidosis.","whySource":"curated","meaning":"Missed insulin doses are a leading precipitant of diabetic ketoacidosis.","meaningSource":"curated"},{"id":"history-03","system":"genitourinary","question":"Have you been urinating much more than usual or feeling unusually thirsty?","listenFor":["Neither","Increased urination","Increased thirst"],"why":null,"whySource":null,"meaning":"Polyuria and polydipsia reflect osmotic diuresis from marked hyperglycemia and signal significant volume loss; severe symptoms raise concern for a hyperosmolar emergency rather than simple hyperglycemia.","meaningSource":"ai-draft"},{"id":"history-04","system":"neurologic","question":"Have you felt confused, unusually sleepy, or had trouble staying awake?","listenFor":["No confusion or altered alertness","Confusion or altered alertness"],"why":null,"whySource":null,"meaning":"Confusion or excessive sleepiness with hyperglycemia is a red flag for a hyperosmolar hyperglycemic state or DKA — altered mental status means this is not routine hyperglycemia and needs emergent evaluation.","meaningSource":"ai-draft"},{"id":"history-05","system":"gastrointestinal","question":"Have you had nausea, vomiting, or belly pain?","listenFor":["None of these","Nausea or vomiting","Abdominal pain"],"why":null,"whySource":null,"meaning":"Nausea, vomiting, or abdominal pain with hyperglycemia are classic DKA symptoms; their presence should prompt immediate ketone and acid-base testing even when DKA was not initially suspected.","meaningSource":"ai-draft"},{"id":"history-06","system":"respiratory","question":"Have you noticed your breathing becoming fast or deep, or a fruity smell to your breath?","listenFor":["Neither","Fast or deep breathing","Fruity breath odor"],"why":"A fruity or acetone breath odor suggests ketoacidosis.","whySource":"curated","meaning":"A fruity or acetone breath odor suggests ketoacidosis.","meaningSource":"curated"},{"id":"history-07","system":"genitourinary","question":"Have you been drinking enough fluids, or has your urine output dropped off?","listenFor":["Drinking normally, normal urine output","Poor oral intake","Decreased urine output"],"why":"Decreased urine output suggests volume depletion or acute kidney injury.","whySource":"curated","meaning":"Decreased urine output suggests volume depletion or acute kidney injury.","meaningSource":"curated"},{"id":"history-08","system":"infectious","question":"Do you have a fever, cough, or burning with urination that might explain your sugar running high?","listenFor":["None of these","Fever or cough","Burning with urination"],"why":null,"whySource":null,"meaning":"Infection is the most common precipitant of hyperglycemic crises, so fever, cough, or dysuria should trigger a search for the source — treating the infection is part of treating the glucose.","meaningSource":"ai-draft"},{"id":"history-09","system":"medication","question":"Have you started a steroid medication recently?","listenFor":["No new steroid use","Recently started steroids"],"why":"Corticosteroids raise blood glucose and can precipitate hyperglycemic crises.","whySource":"curated","meaning":"Corticosteroids raise blood glucose and can precipitate hyperglycemic crises.","meaningSource":"curated"},{"id":"history-10","system":"medication","question":"Have you been eating more sugary or carbohydrate-heavy food than usual, or drinking sugary drinks?","listenFor":["No significant dietary change","Increased sugar or carbohydrate intake"],"why":null,"whySource":null,"meaning":"A recent sugary or carbohydrate-heavy intake is a common benign explanation for a high reading; identifying it guides counseling rather than escalating therapy.","meaningSource":"ai-draft"},{"id":"history-11","system":"cardiovascular","question":"Have you had chest pain, or weakness on one side of your body, that could have triggered your sugar to rise?","listenFor":["Neither","Chest pain","New focal weakness"],"why":null,"whySource":null,"meaning":"Acute illness such as MI or stroke triggers stress hyperglycemia, so chest pain or unilateral weakness alongside high glucose is a red flag — evaluate for the underlying emergency, not just the number.","meaningSource":"ai-draft"},{"id":"history-12","system":"eyes","question":"Has your vision been blurry?","listenFor":["No visual change","Blurred vision"],"why":null,"whySource":null,"meaning":"Acute hyperglycemia causes transient blurry vision from osmotic swelling of the lens, which resolves as glucose normalizes; persistent visual changes warrant ophthalmologic evaluation for retinopathy.","meaningSource":"ai-draft"}],"exam":[{"id":"exam-01","system":"neurologic","maneuver":"Assess mental status and orientation.","findings":["Alert and fully oriented","Confused or lethargic","Obtunded or comatose"],"how":null,"why":null,"whySource":null,"meaning":"Mental status stratifies the emergency: an alert patient fits simple hyperglycemia, while confusion, lethargy, or obtundation points to DKA or a hyperosmolar state requiring emergent management.","meaningSource":"ai-draft"},{"id":"exam-02","system":"general","maneuver":"Assess hydration status and skin turgor.","findings":["Euvolemic, normal turgor","Dry mucous membranes or poor turgor"],"how":null,"why":"Documenting volume status (hypovolemic, euvolemic, or hypervolemic) guides fluid management and helps distinguish prerenal, intrinsic, and volume-overload causes of kidney injury and electrolyte disturbances.","whySource":"curated","meaning":"Documenting volume status (hypovolemic, euvolemic, or hypervolemic) guides fluid management and helps distinguish prerenal, intrinsic, and volume-overload causes of kidney injury and electrolyte disturbances.","meaningSource":"curated"},{"id":"exam-03","system":"cardiovascular","maneuver":"Measure blood pressure lying and standing to assess for orthostatic hypotension.","findings":["No orthostatic change","Positive orthostatic hypotension"],"how":"Measure blood pressure and heart rate after 5 minutes supine, then at 1 and 3 minutes after standing; a sustained drop of 20 mmHg systolic or 10 mmHg diastolic within 3 minutes is positive.","why":null,"whySource":null,"meaning":"Orthostatic hypotension reveals volume depletion from osmotic diuresis, guiding how aggressively to rehydrate; significant depletion needs IV fluids before glucose is fully corrected.","meaningSource":"ai-draft"},{"id":"exam-04","system":"respiratory","maneuver":"Assess respiratory pattern for Kussmaul breathing and check for a fruity breath odor.","findings":["Normal breathing pattern, no fruity odor","Kussmaul breathing or fruity odor present"],"how":null,"why":"A fruity or acetone breath odor suggests ketoacidosis.","whySource":"curated","meaning":"A fruity or acetone breath odor suggests ketoacidosis.","meaningSource":"curated"},{"id":"exam-05","system":"gastrointestinal","maneuver":"Palpate the abdomen for tenderness.","findings":["Soft, nontender","Diffuse tenderness","Focal tenderness or guarding"],"how":null,"why":"Guarding, rebound, or rigidity on palpation suggests peritonitis.","whySource":"curated","meaning":"Guarding, rebound, or rigidity on palpation suggests peritonitis.","meaningSource":"curated"},{"id":"exam-06","system":"general","maneuver":"Assess temperature for fever.","findings":["Afebrile","Febrile"],"how":null,"why":null,"whySource":null,"meaning":"Fever points to an infectious precipitant driving the hyperglycemia; finding and treating the source is essential because glucose will not stabilize until the infection is addressed.","meaningSource":"ai-draft"},{"id":"exam-07","system":"skin","maneuver":"Inspect the feet and skin for ulcers, cellulitis, or other infection sources.","findings":["No skin or wound infection identified","Skin or wound infection identified"],"how":null,"why":null,"whySource":null,"meaning":"The feet and skin are common hidden infection sources — foot ulcers and cellulitis frequently precipitate hyperglycemic crises — so a focused skin exam can reveal the trigger.","meaningSource":"ai-draft"},{"id":"exam-08","system":"neurologic","maneuver":"Assess for a focal neurologic deficit.","findings":["No focal deficit","Focal deficit present"],"how":null,"why":null,"whySource":null,"meaning":"A focal deficit with hyperglycemia raises concern for acute stroke, which both causes and is worsened by high glucose — this needs emergent stroke evaluation rather than glucose management alone.","meaningSource":"ai-draft"},{"id":"exam-09","system":"respiratory","maneuver":"Auscultate the lungs for a focal infiltrate.","findings":["Clear bilaterally","Focal crackles or decreased breath sounds"],"how":null,"why":null,"whySource":null,"meaning":"A focal infiltrate suggests pneumonia as the precipitant of the hyperglycemia; identifying it directs antibiotics alongside glucose control.","meaningSource":"ai-draft"},{"id":"exam-10","system":"cardiovascular","maneuver":"Assess heart rate and rhythm.","findings":["Regular rate and rhythm","Tachycardic","Irregular rhythm"],"how":null,"why":null,"whySource":null,"meaning":"Tachycardia suggests volume depletion, infection, or acidosis accompanying the hyperglycemia, while an irregular rhythm raises concern for an arrhythmia or underlying cardiac trigger — both findings should prompt an EKG and a search for the cause.","meaningSource":"ai-draft"}],"reviewNeeded":{"whyMissing":15,"howMissing":9}},{"id":"bowel-obstruction","title":"Bowel obstruction","aliases":["small bowel obstruction","SBO","large bowel obstruction"],"history":[{"id":"history-01","system":"gastrointestinal","question":"Is your belly pain crampy and coming in waves, or is it constant?","listenFor":["Crampy, intermittent, colicky pain","Constant, unrelenting pain"],"why":null,"whySource":null,"meaning":"Colicky, wave-like pain is the classic pattern of mechanical obstruction as peristalsis works against the blockage, while constant unrelenting pain suggests ischemia, strangulation, or perforation — a surgical emergency; the pain pattern is one of the fastest bedside discriminators of simple versus complicated obstruction.","meaningSource":"ai-draft"},{"id":"history-02","system":"gastrointestinal","question":"Are you able to pass gas or have a bowel movement?","listenFor":["Passing flatus and stool normally","Passing flatus but no stool","Unable to pass gas or stool"],"why":"Inability to pass gas or stool (obstipation) with distention suggests complete bowel obstruction.","whySource":"curated","meaning":"Inability to pass gas or stool (obstipation) with distention suggests complete bowel obstruction.","meaningSource":"curated"},{"id":"history-03","system":"gastrointestinal","question":"Have you been vomiting, and if so, does it look greenish-yellow or like stool?","listenFor":["No vomiting","Bilious vomiting","Feculent-appearing vomiting"],"why":"Bilious vomiting suggests obstruction distal to the ampulla of Vater.","whySource":"curated","meaning":"Bilious vomiting suggests obstruction distal to the ampulla of Vater.","meaningSource":"curated"},{"id":"history-04","system":"gastrointestinal","question":"Has your belly become visibly more swollen or distended?","listenFor":["No distention","Distention present"],"why":null,"whySource":null,"meaning":"Visible distention supports a mechanical obstruction with trapped gas and fluid proximal to the blockage; absent distention does not exclude obstruction — especially early or with a high (proximal) blockage — but marked distention raises concern for severity and complications.","meaningSource":"ai-draft"},{"id":"history-05","system":"gastrointestinal","question":"Have you had abdominal surgery in the past?","listenFor":["No prior abdominal surgery","Prior abdominal surgery"],"why":null,"whySource":null,"meaning":"Prior abdominal surgery makes adhesive small-bowel obstruction the leading cause, since adhesions are the most common etiology overall; no prior surgery pushes the differential toward hernias, malignancy, Crohn's strictures, or volvulus instead.","meaningSource":"ai-draft"},{"id":"history-06","system":"gastrointestinal","question":"Have you noticed a bulge in your groin or at a prior surgical scar that you can push back in, or that's stuck out and painful?","listenFor":["No bulge noticed","Reducible bulge","Painful, irreducible bulge"],"why":null,"whySource":null,"meaning":"A painful, irreducible (incarcerated) bulge signals a strangulated hernia — a surgical emergency with risk of bowel ischemia — while a reducible bulge suggests a hernia that may be the obstruction's cause but is not yet strangulated; any tender irreducible bulge needs urgent surgical evaluation.","meaningSource":"ai-draft"},{"id":"history-07","system":"hematologic","question":"Have you been diagnosed with cancer, especially of the colon, ovary, or stomach?","listenFor":["No known malignancy","Known malignancy"],"why":null,"whySource":null,"meaning":"Known colon, ovarian, or gastric cancer raises concern for malignant obstruction from tumor, carcinomatosis, or strictures, which changes management toward oncology involvement and often a less surgical approach; no known malignancy keeps adhesions and hernias at the top.","meaningSource":"ai-draft"},{"id":"history-08","system":"gastrointestinal","question":"Do you have Crohn's disease or another condition that has caused bowel narrowing before?","listenFor":["No known inflammatory bowel disease or stricture","Known Crohn's disease or prior bowel stricture"],"why":null,"whySource":null,"meaning":"Crohn's disease or known strictures point to a benign inflammatory or fibrotic narrowing as the cause, which may respond to medical management (steroids, bowel rest) rather than surgery; this history also warns that repeated episodes are likely.","meaningSource":"ai-draft"},{"id":"history-09","system":"infectious","question":"Do you have a fever, or has the pain become constant and severe in one specific spot?","listenFor":["Neither","Fever","Constant severe localized pain"],"why":null,"whySource":null,"meaning":"Fever or constant severe localized pain suggests complicated obstruction — ischemia, strangulation, or early perforation — rather than a simple adhesive blockage; either finding escalates the case to urgent surgical consultation and expedited imaging.","meaningSource":"ai-draft"},{"id":"history-10","system":"hematologic","question":"Have you noticed blood in your stool, or had unintentional weight loss recently?","listenFor":["Neither","Blood in stool","Unintentional weight loss"],"why":null,"whySource":null,"meaning":"Blood in the stool suggests a malignant or inflammatory source of the obstruction rather than simple adhesions, while unintentional weight loss points toward an underlying malignancy; both findings broaden the workup beyond a routine adhesive obstruction.","meaningSource":"ai-draft"},{"id":"history-11","system":"medication","question":"Are you on opioid pain medication, or have you been unusually constipated before this started?","listenFor":["Neither","Regular opioid use","Chronic constipation at baseline"],"why":null,"whySource":null,"meaning":"Regular opioid use causes severe constipation and can precipitate or mimic obstruction through opioid-induced bowel dysfunction, a medically manageable contributor; chronic baseline constipation similarly suggests a functional component that may respond to laxatives and opioid adjustment alongside standard obstruction care.","meaningSource":"ai-draft"},{"id":"history-12","system":"genitourinary","question":"Have you noticed a change in how much you're urinating?","listenFor":["Normal urine output","Decreased urine output"],"why":"Decreased urine output suggests volume depletion or acute kidney injury.","whySource":"curated","meaning":"Decreased urine output suggests volume depletion or acute kidney injury.","meaningSource":"curated"}],"exam":[{"id":"exam-01","system":"gastrointestinal","maneuver":"Inspect the abdomen for distention and visible peristalsis.","findings":["No distention","Distention present","Distention with visible peristaltic waves"],"how":null,"why":"Visible peristaltic waves suggest mechanical bowel obstruction.","whySource":"curated","meaning":"Visible peristaltic waves suggest mechanical bowel obstruction.","meaningSource":"curated"},{"id":"exam-02","system":"gastrointestinal","maneuver":"Auscultate bowel sounds.","findings":["Normal bowel sounds","High-pitched, hyperactive bowel sounds","Absent bowel sounds"],"how":null,"why":"High-pitched, hyperactive bowel sounds suggest early mechanical obstruction; absent bowel sounds suggest ileus or late obstruction.","whySource":"curated","meaning":"High-pitched, hyperactive bowel sounds suggest early mechanical obstruction; absent bowel sounds suggest ileus or late obstruction.","meaningSource":"curated"},{"id":"exam-03","system":"gastrointestinal","maneuver":"Palpate the abdomen for tenderness, guarding, and rebound.","findings":["Soft, nontender","Diffusely tender without guarding","Focal tenderness, guarding, or rigidity"],"how":null,"why":"Guarding, rebound, or rigidity on palpation suggests peritonitis.","whySource":"curated","meaning":"Guarding, rebound, or rigidity on palpation suggests peritonitis.","meaningSource":"curated"},{"id":"exam-04","system":"gastrointestinal","maneuver":"Examine the inguinal, femoral, and umbilical hernia sites for a bulge and its reducibility.","findings":["No hernia identified","Reducible hernia","Tender, irreducible or incarcerated hernia"],"how":null,"why":"A tender, irreducible hernia suggests incarceration or strangulation, which needs urgent surgical evaluation.","whySource":"curated","meaning":"A tender, irreducible hernia suggests incarceration or strangulation, which needs urgent surgical evaluation.","meaningSource":"curated"},{"id":"exam-05","system":"skin","maneuver":"Inspect the abdomen for surgical scars.","findings":["No surgical scars","Prior surgical scars present"],"how":null,"why":null,"whySource":null,"meaning":"Surgical scars corroborate an adhesive cause — the most common etiology of small-bowel obstruction — and their location can hint at where adhesions formed; absent scars push the search toward hernias, malignancy, or other causes.","meaningSource":"ai-draft"},{"id":"exam-06","system":"general","maneuver":"Assess temperature for fever.","findings":["Afebrile","Febrile"],"how":null,"why":null,"whySource":null,"meaning":"Fever suggests complicated obstruction with ischemia, strangulation, or perforation rather than a simple blockage, and it should accelerate surgical consultation and imaging; afebrile patients with stable exams may be candidates for initial conservative management.","meaningSource":"ai-draft"},{"id":"exam-07","system":"cardiovascular","maneuver":"Assess hemodynamic stability.","findings":["Normotensive, stable","Tachycardic","Hypotensive or in shock"],"how":null,"why":null,"whySource":null,"meaning":"Tachycardia and hypotension signal third-spacing, developing sepsis from ischemic bowel, or perforation — all markers of a complicated obstruction needing urgent resuscitation and surgical involvement; stable vitals support a trial of conservative management with close monitoring.","meaningSource":"ai-draft"},{"id":"exam-08","system":"gastrointestinal","maneuver":"Perform a rectal examination to assess for stool, mass, or blood.","findings":["Normal, stool present, guaiac negative","Empty rectal vault","Mass or gross blood on examination"],"how":null,"why":null,"whySource":null,"meaning":"The rectal examination looks for the cause and for red flags: an empty vault supports distal obstruction, a palpable mass suggests malignancy, and gross blood points to ischemia or a malignant source; stool present with a negative guaiac makes a complete distal obstruction less likely.","meaningSource":"ai-draft"},{"id":"exam-09","system":"general","maneuver":"Assess hydration status and mucous membranes.","findings":["Euvolemic, moist mucous membranes","Dry mucous membranes or poor turgor"],"how":null,"why":"Documenting volume status (hypovolemic, euvolemic, or hypervolemic) guides fluid management and helps distinguish prerenal, intrinsic, and volume-overload causes of kidney injury and electrolyte disturbances.","whySource":"curated","meaning":"Documenting volume status (hypovolemic, euvolemic, or hypervolemic) guides fluid management and helps distinguish prerenal, intrinsic, and volume-overload causes of kidney injury and electrolyte disturbances.","meaningSource":"curated"},{"id":"exam-10","system":"genitourinary","maneuver":"Assess urine output.","findings":["Normal urine output","Decreased urine output"],"how":null,"why":"Decreased urine output suggests volume depletion or acute kidney injury.","whySource":"curated","meaning":"Decreased urine output suggests volume depletion or acute kidney injury.","meaningSource":"curated"}],"reviewNeeded":{"whyMissing":13,"howMissing":10}},{"id":"cholecystitis-biliary-colic","title":"Cholecystitis / biliary colic","aliases":["cholecystitis","biliary colic","gallbladder pain"],"history":[{"id":"history-01","system":"gastrointestinal","question":"Does your pain come on specifically after eating, especially fatty food?","listenFor":["No relationship to eating","Pain specifically after fatty meals"],"why":null,"whySource":null,"meaning":"Fatty meals trigger cholecystokinin-mediated gallbladder contraction against an obstructing stone — pain after fatty food is the classic biliary colic pattern. No meal relationship broadens the differential toward ulcer, pancreatic, or cardiac causes.","meaningSource":"ai-draft"},{"id":"history-02","system":"gastrointestinal","question":"Where is the pain, and does it radiate to your back or right shoulder blade?","listenFor":["No radiation","Radiates to the back","Radiates to the right shoulder blade"],"why":"Pain radiating to the right shoulder blade or scapula is referred pain from gallbladder irritation via the phrenic nerve.","whySource":"curated","meaning":"Pain radiating to the right shoulder blade or scapula is referred pain from gallbladder irritation via the phrenic nerve.","meaningSource":"curated"},{"id":"history-03","system":"gastrointestinal","question":"Has this pain happened before and gone away on its own within a few hours?","listenFor":["First episode","Prior similar episodes that resolved on their own"],"why":null,"whySource":null,"meaning":"Prior brief episodes that resolved on their own within hours are classic for biliary colic — and a first prolonged, unremitting episode suggests progression to acute cholecystitis. This history establishes the natural history and urgency.","meaningSource":"ai-draft"},{"id":"history-04","system":"gastrointestinal","question":"Is the pain constant now, or has it lasted longer than six hours?","listenFor":["Pain resolved within a few hours as usual","Constant pain lasting more than six hours"],"why":"Biliary colic usually resolves within hours; constant pain beyond six hours suggests acute cholecystitis.","whySource":"curated","meaning":"Biliary colic usually resolves within hours; constant pain beyond six hours suggests acute cholecystitis.","meaningSource":"curated"},{"id":"history-05","system":"infectious","question":"Do you have a fever or chills along with the pain?","listenFor":["Neither","Fever","Shaking chills"],"why":"Fever with shaking chills (rigors) suggests bacteremia.","whySource":"curated","meaning":"Fever with shaking chills (rigors) suggests bacteremia.","meaningSource":"curated"},{"id":"history-06","system":"skin","question":"Has your skin or the whites of your eyes looked yellow?","listenFor":["No jaundice","Jaundice present"],"why":null,"whySource":null,"meaning":"Jaundice with biliary pain suggests a common bile duct stone causing obstruction — raising concern for ascending cholangitis, especially with fever. A positive answer should prompt liver function tests, urgent imaging, and evaluation for ERCP.","meaningSource":"ai-draft"},{"id":"history-07","system":"genitourinary","question":"Has your urine looked darker than usual, or your stool looked pale or clay-colored?","listenFor":["Neither","Dark urine","Pale or clay-colored stool"],"why":"Dark urine with pale or clay-colored stools and pruritus suggests cholestatic biliary obstruction.","whySource":"curated","meaning":"Dark urine with pale or clay-colored stools and pruritus suggests cholestatic biliary obstruction.","meaningSource":"curated"},{"id":"history-08","system":"skin","question":"Has your skin been itchy?","listenFor":["No pruritus","Pruritus present"],"why":"Pruritus with jaundice suggests cholestasis from biliary obstruction.","whySource":"curated","meaning":"Pruritus with jaundice suggests cholestasis from biliary obstruction.","meaningSource":"curated"},{"id":"history-09","system":"gastrointestinal","question":"Do you have any prior episodes of abdominal pain that occurs specifically after you eat, or have you been told you have gallstones?","listenFor":["Neither","Prior episodes of postprandial pain","Known gallstones"],"why":null,"whySource":null,"meaning":"Known gallstones with recurrent postprandial pain gives a high pretest probability for biliary disease and makes ultrasound the clear first test. Without either, keep the differential broad — many RUQ pain mimics exist.","meaningSource":"ai-draft"},{"id":"history-10","system":"gastrointestinal","question":"Do you have back pain that wraps around from your abdomen, or have you had pancreatitis before?","listenFor":["Neither","Pain radiating around to the back","Known prior pancreatitis"],"why":null,"whySource":null,"meaning":"Gallstones are the most common cause of acute pancreatitis, and pain radiating straight through to the back suggests pancreatic involvement rather than isolated biliary colic. A positive answer should prompt a lipase level, since gallstone pancreatitis changes management.","meaningSource":"ai-draft"},{"id":"history-11","system":"cardiovascular","question":"Do you have chest pain or shortness of breath along with this pain?","listenFor":["Neither","Chest pain","Shortness of breath"],"why":null,"whySource":null,"meaning":"Biliary pain can mimic acute coronary syndrome, and missing a cardiac cause is the dangerous error — any chest pain or shortness of breath with upper abdominal pain should prompt an ECG and cardiac workup. Don't anchor on gallstones before the heart is cleared.","meaningSource":"ai-draft"},{"id":"history-12","system":"reproductive","question":"Is there any chance you could be pregnant?","listenFor":["Not applicable or not pregnant","Possible pregnancy"],"why":"Pregnancy status changes the differential diagnosis, medication safety, and imaging choices.","whySource":"curated","meaning":"Pregnancy status changes the differential diagnosis, medication safety, and imaging choices.","meaningSource":"curated"},{"id":"history-13","system":"gastrointestinal","question":"Do you have burning stomach pain that improves or worsens specifically with eating, suggesting an ulcer?","listenFor":["No ulcer-type pain pattern","Burning pain that improves with eating","Burning pain that worsens with eating"],"why":null,"whySource":null,"meaning":"Burning pain that improves with eating suggests duodenal ulcer disease, while pain that worsens with eating points toward gastric ulcer — both distinct from biliary colic's post-fatty-meal pattern. Sorting this out guides whether to trial acid suppression or pursue biliary imaging.","meaningSource":"ai-draft"}],"exam":[{"id":"exam-01","system":"gastrointestinal","maneuver":"Assess the right upper quadrant for a Murphy sign.","findings":["Negative Murphy sign","Positive Murphy sign"],"how":"Hook your fingers under the right costal margin at the midclavicular line and ask the patient to inhale deeply; abrupt inspiratory arrest from pain is a positive Murphy sign.","why":"A positive Murphy sign (inspiratory arrest on palpation of the right upper quadrant) suggests acute cholecystitis.","whySource":"curated","meaning":"A positive Murphy sign (inspiratory arrest on palpation of the right upper quadrant) suggests acute cholecystitis.","meaningSource":"curated"},{"id":"exam-02","system":"gastrointestinal","maneuver":"Palpate the abdomen for tenderness, guarding, and rebound.","findings":["Soft, nontender","Focal right upper quadrant tenderness without guarding","Guarding, rebound, or rigidity"],"how":null,"why":"Guarding, rebound, or rigidity on palpation suggests peritonitis.","whySource":"curated","meaning":"Guarding, rebound, or rigidity on palpation suggests peritonitis.","meaningSource":"curated"},{"id":"exam-03","system":"general","maneuver":"Assess temperature for fever.","findings":["Afebrile","Febrile"],"how":null,"why":null,"whySource":null,"meaning":"Fever separates acute cholecystitis — an inflamed, potentially infected gallbladder needing antibiotics and surgical evaluation — from uncomplicated biliary colic, which is typically afebrile. Febrile RUQ pain should also prompt a search for cholangitis.","meaningSource":"ai-draft"},{"id":"exam-04","system":"skin","maneuver":"Inspect skin and sclerae for jaundice.","findings":["Absent","Present"],"how":null,"why":null,"whySource":null,"meaning":"Visible jaundice confirms significant hyperbilirubinemia and, with biliary pain, points to common bile duct obstruction — raising concern for choledocholithiasis or cholangitis. It should prompt urgent labs, imaging, and gastroenterology involvement.","meaningSource":"ai-draft"},{"id":"exam-05","system":"cardiovascular","maneuver":"Assess hemodynamic stability.","findings":["Normotensive, stable","Tachycardic","Hypotensive or in shock"],"how":null,"why":null,"whySource":null,"meaning":"Hypotension or shock with biliary pain suggests septic cholangitis or gangrenous cholecystitis — surgical emergencies needing resuscitation and urgent intervention. Stable vitals support uncomplicated disease, but tachycardia alone warrants close monitoring.","meaningSource":"ai-draft"},{"id":"exam-06","system":"gastrointestinal","maneuver":"Palpate the epigastrium for tenderness suggesting pancreatitis.","findings":["Nontender","Epigastric tenderness"],"how":null,"why":null,"whySource":null,"meaning":"Epigastric tenderness supports pancreatitis in the differential of upper abdominal pain — paired with a lipase level, it helps separate pancreatic from purely biliary disease. Marked tenderness with systemic signs should raise concern for necrotizing pancreatitis.","meaningSource":"ai-draft"},{"id":"exam-07","system":"gastrointestinal","maneuver":"Assess for a palpable gallbladder or right upper quadrant mass.","findings":["No palpable mass","Palpable mass or distended gallbladder"],"how":null,"why":null,"whySource":null,"meaning":"A palpably distended gallbladder with jaundice invokes Courvoisier's law — suggesting malignant biliary obstruction (such as pancreatic head cancer) rather than stones, since chronically inflamed stone-filled gallbladders rarely distend. This finding should prompt cross-sectional imaging for malignancy.","meaningSource":"ai-draft"},{"id":"exam-08","system":"cardiovascular","maneuver":"Auscultate the heart and lungs to help exclude a cardiac or pulmonary source of pain.","findings":["Normal heart and lung sounds","Abnormal heart or lung findings"],"how":null,"why":null,"whySource":null,"meaning":"Right lower lobe pneumonia, pulmonary embolism, and inferior MI can all present as upper abdominal pain — abnormal heart or lung findings redirect the workup away from the gallbladder. This quick listen guards against anchoring on a biliary diagnosis.","meaningSource":"ai-draft"},{"id":"exam-09","system":"gastrointestinal","maneuver":"Assess for diffuse peritoneal signs suggesting perforation.","findings":["No peritoneal signs","Diffuse guarding or rigidity"],"how":null,"why":"Guarding, rebound, or rigidity on palpation suggests peritonitis.","whySource":"curated","meaning":"Guarding, rebound, or rigidity on palpation suggests peritonitis.","meaningSource":"curated"},{"id":"exam-10","system":"neurologic","maneuver":"Assess mental status.","findings":["Alert and oriented","Confused or lethargic"],"how":null,"why":null,"whySource":null,"meaning":"Confusion or lethargy with biliary pain and fever completes Reynolds' pentad for severe ascending cholangitis — a septic emergency. Any altered mental status here should prompt immediate resuscitation, broad-spectrum antibiotics, and urgent biliary drainage evaluation.","meaningSource":"ai-draft"}],"reviewNeeded":{"whyMissing":14,"howMissing":9}},{"id":"osteoarthritis-joint-pain","title":"Osteoarthritis-related admission/joint pain","aliases":["osteoarthritis","joint pain"],"history":[{"id":"history-01","system":"musculoskeletal","question":"Which joints are bothering you, and have you had this same pain in these joints for months or years?","listenFor":["New joint pain, not present before","Chronic joint pain, similar to baseline","Chronic joint pain, but this feels worse or different"],"why":null,"whySource":null,"meaning":"Establishing whether this is chronic baseline pain versus new or different pain separates an osteoarthritis flare from a new superimposed process — septic arthritis, fracture, or crystal disease. A change from baseline deserves a fresh workup, not reassurance.","meaningSource":"ai-draft"},{"id":"history-02","system":"musculoskeletal","question":"Is your joint stiffness worst first thing in the morning, and if so, how long does it last?","listenFor":["Morning stiffness less than 30 minutes","Morning stiffness more than an hour"],"why":"Morning stiffness lasting more than an hour suggests inflammatory arthritis; stiffness under 30 minutes suggests osteoarthritis.","whySource":"curated","meaning":"Morning stiffness lasting more than an hour suggests inflammatory arthritis; stiffness under 30 minutes suggests osteoarthritis.","meaningSource":"curated"},{"id":"history-03","system":"musculoskeletal","question":"Does the pain get worse with activity and better with rest?","listenFor":["Worse with activity, better with rest","Pain present even at rest"],"why":null,"whySource":null,"meaning":"Pain that worsens with activity and eases with rest is the classic mechanical pattern of osteoarthritis. Pain at rest or at night points away from OA toward inflammatory arthritis, infection, or malignancy — a red-flag distinction.","meaningSource":"ai-draft"},{"id":"history-04","system":"infectious","question":"Do you have a fever along with the joint pain?","listenFor":["No fever","Fever"],"why":null,"whySource":null,"meaning":"Fever with acute joint pain makes septic arthritis the diagnosis to exclude first — it can destroy cartilage within hours. A positive answer should prompt urgent arthrocentesis with synovial fluid analysis and cultures, not watchful waiting.","meaningSource":"ai-draft"},{"id":"history-05","system":"musculoskeletal","question":"Has one joint become suddenly hot, red, and swollen?","listenFor":["No acute hot, red, swollen joint","Single joint acutely hot, red, and swollen"],"why":"An acutely hot, red, swollen single joint raises concern for septic arthritis, which needs urgent joint aspiration.","whySource":"curated","meaning":"An acutely hot, red, swollen single joint raises concern for septic arthritis, which needs urgent joint aspiration.","meaningSource":"curated"},{"id":"history-06","system":"musculoskeletal","question":"Have you had a recent joint injection, surgery, or skin infection near this joint?","listenFor":["None of these","Recent joint injection or surgery","Nearby skin infection"],"why":null,"whySource":null,"meaning":"A recent injection, surgery, or nearby skin infection provides a direct route for bacteria into the joint — sharply raising the probability of septic arthritis. Any of these with a hot joint should prompt urgent orthopedic and infectious disease involvement.","meaningSource":"ai-draft"},{"id":"history-07","system":"functional","question":"Has this pain made it harder for you to walk, get up from a chair, or care for yourself at home?","listenFor":["No functional change","New difficulty with walking or transfers","New difficulty with self-care"],"why":null,"whySource":null,"meaning":"New difficulty walking, transferring, or caring for oneself determines disposition — safe discharge planning, physical therapy, and home safety all hinge on function. It also flags severity: inability to bear weight raises concern for fracture or septic arthritis.","meaningSource":"ai-draft"},{"id":"history-08","system":"musculoskeletal","question":"Have you fallen or injured the joint recently?","listenFor":["No recent fall or trauma","Recent fall or trauma to the joint"],"why":null,"whySource":null,"meaning":"Recent trauma shifts the differential to fracture, hemarthrosis, or ligament injury — especially in anticoagulated or osteoporotic patients. It also prompts asking why the fall happened, since the joint pain may be secondary to syncope or weakness.","meaningSource":"ai-draft"},{"id":"history-09","system":"medication","question":"Have you been taking NSAIDs or other pain medications regularly for this?","listenFor":["No regular NSAID or analgesic use","Regular NSAID use","Regular opioid use"],"why":"NSAIDs reduce renal perfusion and promote sodium and water retention, worsening kidney function, heart failure, and potassium excretion.","whySource":"curated","meaning":"NSAIDs reduce renal perfusion and promote sodium and water retention, worsening kidney function, heart failure, and potassium excretion.","meaningSource":"curated"},{"id":"history-10","system":"musculoskeletal","question":"Have multiple small joints in your hands or feet become swollen and painful, on both sides of your body?","listenFor":["No symmetric small-joint involvement","Symmetric small-joint swelling and pain"],"why":null,"whySource":null,"meaning":"Symmetric swelling of the small joints of the hands and feet is the classic rheumatoid arthritis pattern — osteoarthritis favors distal interphalangeal joints, the thumb base, and large weight-bearing joints asymmetrically. A positive answer should prompt rheumatoid factor, anti-CCP, and rheumatology referral.","meaningSource":"ai-draft"},{"id":"history-11","system":"musculoskeletal","question":"Has your big toe or another single joint suddenly become extremely painful, often overnight?","listenFor":["No sudden severe monoarticular pain","Sudden severe pain, often in the big toe"],"why":"Sudden severe pain in a single joint, classically the big toe, suggests acute gout.","whySource":"curated","meaning":"Sudden severe pain in a single joint, classically the big toe, suggests acute gout.","meaningSource":"curated"}],"exam":[{"id":"exam-01","system":"musculoskeletal","maneuver":"Inspect the affected joint for erythema, warmth, and swelling.","findings":["No erythema, warmth, or swelling","Swelling without erythema or warmth","Erythema and warmth present"],"how":null,"why":null,"whySource":null,"meaning":"Erythema and warmth signal an inflammatory or infectious process — septic arthritis, gout, or cellulitis — rather than osteoarthritis, whose swelling is typically cool and non-erythematous. A hot, red joint with fever is septic arthritis until proven otherwise.","meaningSource":"ai-draft"},{"id":"exam-02","system":"musculoskeletal","maneuver":"Palpate for a joint effusion.","findings":["No effusion","Effusion present"],"how":null,"why":null,"whySource":null,"meaning":"An effusion confirms pathology inside the joint space rather than surrounding soft tissue — and a tense effusion in a febrile patient is an indication for urgent arthrocentesis. The fluid itself, once sampled, distinguishes infection, crystals, and inflammation.","meaningSource":"ai-draft"},{"id":"exam-03","system":"musculoskeletal","maneuver":"Assess active and passive range of motion of the affected joint.","findings":["Full range of motion","Limited range of motion from pain or stiffness","Unable to move the joint at all"],"how":null,"why":null,"whySource":null,"meaning":"A joint the patient cannot move at all — pseudoparalysis — suggests septic arthritis or fracture rather than an osteoarthritis flare, which typically limits but doesn't abolish movement. Complete loss of motion should prompt urgent imaging and joint aspiration.","meaningSource":"ai-draft"},{"id":"exam-04","system":"musculoskeletal","maneuver":"Assess for crepitus with joint movement.","findings":["No crepitus","Crepitus present"],"how":null,"why":null,"whySource":null,"meaning":"Crepitus with movement reflects cartilage loss and is a classic osteoarthritis finding in a chronic joint. New crepitus after trauma, however, suggests fracture — interpret it in the context of onset.","meaningSource":"ai-draft"},{"id":"exam-05","system":"musculoskeletal","maneuver":"Assess joint stability with stress testing when appropriate.","findings":["Stable joint","Instability present"],"how":null,"why":null,"whySource":null,"meaning":"Instability on stress testing points to ligament injury or advanced joint destruction rather than uncomplicated osteoarthritis. A stable joint with a typical OA pattern supports conservative management; instability may need orthopedic evaluation.","meaningSource":"ai-draft"},{"id":"exam-06","system":"general","maneuver":"Assess temperature for fever.","findings":["Afebrile","Febrile"],"how":null,"why":null,"whySource":null,"meaning":"An objective fever combined with joint findings makes septic arthritis the leading concern — it can destroy a joint within hours. Febrile patients with a hot or effusive joint need urgent arthrocentesis, not a routine OA workup.","meaningSource":"ai-draft"},{"id":"exam-07","system":"musculoskeletal","maneuver":"Assess for bony deformity, joint malalignment, and muscle wasting around the joint.","findings":["No deformity or wasting","Bony deformity or malalignment","Surrounding muscle wasting"],"how":null,"why":null,"whySource":null,"meaning":"Bony deformity, malalignment, or chronic muscle wasting marks long-standing joint disease — the stigmata of advanced osteoarthritis. Acute malalignment, in contrast, suggests fracture or dislocation and needs urgent imaging.","meaningSource":"ai-draft"},{"id":"exam-08","system":"musculoskeletal","maneuver":"Assess distal pulses, capillary refill, and sensation distal to the affected joint.","findings":["Normal distal perfusion and sensation","Diminished distal perfusion or sensation"],"how":"Press the nail bed firmly for 5 seconds, release, and count the seconds until color returns; return after more than 2 to 3 seconds is delayed.","why":"Delayed capillary refill indicates impaired perfusion, whether from systemic poor perfusion (as in shock) or local arterial compromise.","whySource":"curated","meaning":"Delayed capillary refill indicates impaired perfusion, whether from systemic poor perfusion (as in shock) or local arterial compromise.","meaningSource":"curated"},{"id":"exam-09","system":"functional","maneuver":"Assess gait and ability to bear weight when safe.","findings":["Normal gait, full weight bearing","Antalgic gait","Unable to bear weight"],"how":null,"why":null,"whySource":null,"meaning":"An antalgic gait confirms the joint as the pain source, while inability to bear weight at all raises concern for fracture or septic arthritis and generally requires imaging. Gait assessment also determines whether discharge home is safe.","meaningSource":"ai-draft"},{"id":"exam-10","system":"musculoskeletal","maneuver":"Examine other joints for symmetric involvement.","findings":["Isolated joint involvement","Symmetric polyarticular involvement"],"how":null,"why":null,"whySource":null,"meaning":"Symmetric involvement of other joints points to a systemic inflammatory arthritis like rheumatoid disease rather than isolated osteoarthritis. An isolated joint keeps the focus on mechanical, infectious, or crystal-induced causes in that joint.","meaningSource":"ai-draft"}],"reviewNeeded":{"whyMissing":16,"howMissing":9}},{"id":"rheumatoid-arthritis-flare-joint-infection","title":"Rheumatoid arthritis flare/joint infection","aliases":["rheumatoid arthritis flare","septic arthritis"],"history":[{"id":"history-01","system":"musculoskeletal","question":"Do you have rheumatoid arthritis, and does this pain feel like your usual flares?","listenFor":["No known rheumatoid arthritis","Known rheumatoid arthritis, feels like a typical flare","Known rheumatoid arthritis, feels different from prior flares"],"why":null,"whySource":null,"meaning":"Knowing whether the patient has rheumatoid arthritis — and whether this episode matches their usual flare pattern — is the starting fork: a typical flare points toward rheumatologic management, while a presentation that feels different from prior flares raises concern for septic arthritis, which is a joint-destroying emergency.","meaningSource":"ai-draft"},{"id":"history-02","system":"musculoskeletal","question":"Are multiple joints affected on both sides of your body, or is it just one joint?","listenFor":["Symmetric, multiple joints","Single joint only"],"why":null,"whySource":null,"meaning":"Symmetric polyarticular involvement favors a rheumatoid flare, while a single hot joint is the classic presentation of septic arthritis; this distribution is one of the strongest bedside discriminators, and monoarthritis in a rheumatoid patient should be treated as infected until proven otherwise.","meaningSource":"ai-draft"},{"id":"history-03","system":"infectious","question":"Do you have a fever or chills along with the joint pain?","listenFor":["Neither","Fever","Shaking chills"],"why":"Fever with shaking chills (rigors) suggests bacteremia.","whySource":"curated","meaning":"Fever with shaking chills (rigors) suggests bacteremia.","meaningSource":"curated"},{"id":"history-04","system":"musculoskeletal","question":"Did this joint pain come on suddenly and get severe within a day or two?","listenFor":["Gradual onset over days to weeks","Rapid onset over hours to a day"],"why":null,"whySource":null,"meaning":"Rapid onset over hours to a day favors septic arthritis or crystal disease, while gradual onset over days to weeks favors a rheumatoid flare; speed of onset directly affects urgency — a rapidly progressive hot joint needs same-day arthrocentesis.","meaningSource":"ai-draft"},{"id":"history-05","system":"musculoskeletal","question":"Is the affected joint too painful to move or bear weight on at all?","listenFor":["Painful but still able to move or bear some weight","Unable to move the joint or bear weight at all"],"why":null,"whySource":null,"meaning":"Inability to move the joint or bear any weight suggests septic arthritis, which produces severe pain with any motion; a flare is painful but usually still allows some movement — complete refusal to move the joint is a red flag for infection.","meaningSource":"ai-draft"},{"id":"history-06","system":"skin","question":"Have you had a skin infection, cut, or wound near this joint recently?","listenFor":["No nearby skin infection or wound","Recent nearby skin infection or wound"],"why":null,"whySource":null,"meaning":"A nearby skin infection, cut, or wound provides a portal of entry for bacteria to seed the joint, strongly supporting septic arthritis; its absence does not exclude infection, since hematogenous seeding can occur without a visible source.","meaningSource":"ai-draft"},{"id":"history-07","system":"musculoskeletal","question":"Have you had a joint injection, joint surgery, or a joint replacement in this joint?","listenFor":["None of these","Recent joint injection","Prosthetic or previously operated joint"],"why":null,"whySource":null,"meaning":"A recent joint injection, surgery, or prosthetic joint dramatically raises the risk of septic arthritis — prosthetic joints can become infected even without recent procedures; any of these histories in a hot joint mandates urgent orthopedic and infectious-disease involvement.","meaningSource":"ai-draft"},{"id":"history-08","system":"medication","question":"Are you on a biologic medication, steroids, or another medication that suppresses your immune system?","listenFor":["No immunosuppressive medication","On biologic or DMARD therapy","On chronic steroids"],"why":null,"whySource":null,"meaning":"Biologics, DMARDs, and chronic steroids blunt the immune response and the classic signs of infection, so septic arthritis can present subtly in immunosuppressed rheumatoid patients; knowing the medication list lowers the threshold for arthrocentesis and broadens the organisms to consider.","meaningSource":"ai-draft"},{"id":"history-09","system":"musculoskeletal","question":"How long does your morning stiffness in this joint usually last?","listenFor":["Less than 30 minutes","More than an hour"],"why":"Morning stiffness lasting more than an hour suggests inflammatory arthritis; stiffness under 30 minutes suggests osteoarthritis.","whySource":"curated","meaning":"Morning stiffness lasting more than an hour suggests inflammatory arthritis; stiffness under 30 minutes suggests osteoarthritis.","meaningSource":"curated"},{"id":"history-10","system":"medication","question":"Have you missed doses of your rheumatoid arthritis medication recently?","listenFor":["Taking medication as prescribed","Missed one or more doses"],"why":null,"whySource":null,"meaning":"Missed rheumatoid arthritis medication doses can precipitate a flare, which points toward a rheumatologic rather than infectious cause when the presentation is otherwise typical; adherence history helps interpret an ambiguous presentation.","meaningSource":"ai-draft"},{"id":"history-11","system":"cardiovascular","question":"Do you inject drugs, or have you had a recent bloodstream infection?","listenFor":["Neither","Intravenous drug use","Recent bloodstream infection"],"why":"Intravenous drug use raises risk for bacteremia, endocarditis, and soft tissue infection.","whySource":"curated","meaning":"Intravenous drug use raises risk for bacteremia, endocarditis, and soft tissue infection.","meaningSource":"curated"},{"id":"history-12","system":"general","question":"Have you had fatigue, dry eyes, dry mouth, or rashes along with the joint symptoms?","listenFor":["None of these","Fatigue with dry eyes or mouth","New rash"],"why":null,"whySource":null,"meaning":"Systemic features like fatigue with dry eyes or mouth suggest active systemic rheumatoid disease or secondary Sjögren's supporting a flare, while a new rash raises concern for vasculitis or a reactive process; these associated symptoms help place the joint pain in a systemic context.","meaningSource":"ai-draft"}],"exam":[{"id":"exam-01","system":"musculoskeletal","maneuver":"Inspect the affected joint for erythema, warmth, and swelling.","findings":["No erythema or warmth","Warmth and erythema present"],"how":null,"why":null,"whySource":null,"meaning":"Warmth and erythema over the joint favor an acute inflammatory or infectious process over chronic degenerative change; in a single hot, red joint, septic arthritis must be excluded with arthrocentesis regardless of the patient's rheumatoid history.","meaningSource":"ai-draft"},{"id":"exam-02","system":"musculoskeletal","maneuver":"Palpate for a joint effusion.","findings":["No effusion","Effusion present"],"how":null,"why":null,"whySource":null,"meaning":"A palpable effusion confirms true intra-articular pathology and identifies a target for arthrocentesis — the definitive test that distinguishes septic arthritis from flare or crystal disease by cell count, crystals, and culture; no effusion makes septic arthritis less likely but does not exclude it.","meaningSource":"ai-draft"},{"id":"exam-03","system":"musculoskeletal","maneuver":"Assess active and passive range of motion of the affected joint.","findings":["Full range of motion, tolerated","Limited range of motion from pain","Refuses any passive movement due to pain"],"how":null,"why":null,"whySource":null,"meaning":"Pain with any passive movement — especially refusal to allow passive motion — is characteristic of septic arthritis, while a flare typically permits some passive range; this finding is one of the most specific bedside signs pushing toward urgent joint aspiration.","meaningSource":"ai-draft"},{"id":"exam-04","system":"musculoskeletal","maneuver":"Examine contralateral and other joints for symmetric synovitis.","findings":["Isolated joint involvement","Symmetric polyarticular synovitis"],"how":null,"why":null,"whySource":null,"meaning":"Symmetric synovitis in other joints supports a systemic rheumatoid flare, while an isolated hot joint with quiet joints elsewhere points toward septic arthritis; the rest of the joint examination is therefore essential context for interpreting the single painful joint.","meaningSource":"ai-draft"},{"id":"exam-05","system":"general","maneuver":"Assess temperature for fever.","findings":["Afebrile","Febrile"],"how":null,"why":null,"whySource":null,"meaning":"Fever supports an infectious or highly inflammatory process and raises the urgency of excluding septic arthritis; however, absence of fever does not rule out joint infection, especially in patients on immunosuppressants or steroids that blunt the febrile response.","meaningSource":"ai-draft"},{"id":"exam-06","system":"cardiovascular","maneuver":"Assess hemodynamic stability.","findings":["Normotensive, stable","Tachycardic","Hypotensive or in shock"],"how":null,"why":null,"whySource":null,"meaning":"Tachycardia, hypotension, or shock in a patient with a hot joint suggests the infection has become systemic — bacteremia or sepsis from septic arthritis — and demands immediate resuscitation, blood cultures, and broad-spectrum antibiotics alongside urgent joint drainage.","meaningSource":"ai-draft"},{"id":"exam-07","system":"skin","maneuver":"Inspect for a nearby skin portal of entry such as a wound, ulcer, or cellulitis.","findings":["No skin portal identified","Skin portal of entry present"],"how":null,"why":null,"whySource":null,"meaning":"Finding a wound, ulcer, or cellulitis near the joint identifies the likely source of bacterial seeding and strengthens the case for septic arthritis; it also guides empiric antibiotic choice toward skin flora such as Staphylococcus aureus.","meaningSource":"ai-draft"},{"id":"exam-08","system":"musculoskeletal","maneuver":"Inspect for chronic rheumatoid deformities such as ulnar deviation or swan-neck deformity.","findings":["No chronic deformity","Chronic rheumatoid deformity present"],"how":null,"why":null,"whySource":null,"meaning":"Chronic rheumatoid deformities confirm long-standing rheumatoid disease and support that the patient is at risk for both flares and atypical presentations of infection; they also remind the examiner that damaged joints are more vulnerable to seeding during bacteremia.","meaningSource":"ai-draft"},{"id":"exam-09","system":"cardiovascular","maneuver":"Auscultate the heart for a new murmur suggesting endocarditis as a source of septic arthritis.","findings":["No murmur","New murmur present"],"how":null,"why":"A new murmur in a person who injects drugs suggests infective endocarditis.","whySource":"curated","meaning":"A new murmur in a person who injects drugs suggests infective endocarditis.","meaningSource":"curated"},{"id":"exam-10","system":"musculoskeletal","maneuver":"Assess distal pulses, capillary refill, sensation, and strength distal to the affected joint.","findings":["Normal distal perfusion, sensation, and strength","Diminished distal perfusion, sensation, or strength"],"how":"Press the nail bed firmly for 5 seconds, release, and count the seconds until color returns; return after more than 2 to 3 seconds is delayed.","why":"Delayed capillary refill indicates impaired perfusion, whether from systemic poor perfusion (as in shock) or local arterial compromise.","whySource":"curated","meaning":"Delayed capillary refill indicates impaired perfusion, whether from systemic poor perfusion (as in shock) or local arterial compromise.","meaningSource":"curated"}],"reviewNeeded":{"whyMissing":17,"howMissing":9}},{"id":"psychiatric-crisis-medical-comorbidity","title":"Psychiatric crisis with medical comorbidity","aliases":["psychiatric crisis","medical clearance"],"history":[{"id":"history-01","system":"psychiatric","question":"Are you having any thoughts of hurting or killing yourself right now?","listenFor":["No suicidal ideation","Passive suicidal ideation without a plan","Active suicidal ideation with a plan or intent"],"why":null,"whySource":null,"meaning":"Suicidal ideation with a plan or intent is the highest-risk finding and mandates immediate safety measures — one-to-one observation, removal of means, and involuntary-hold evaluation where appropriate. Passive ideation without a plan still requires a full safety assessment and close follow-up, never dismissal.","meaningSource":"ai-draft"},{"id":"history-02","system":"psychiatric","question":"Are you having any thoughts of hurting someone else?","listenFor":["No homicidal ideation","Homicidal ideation present"],"why":null,"whySource":null,"meaning":"Homicidal ideation present requires immediate safety intervention: assess for an identifiable target, means, and intent, and know your jurisdiction's duty-to-warn obligations. This is a psychiatric emergency regardless of the underlying medical comorbidity.","meaningSource":"ai-draft"},{"id":"history-03","system":"psychiatric","question":"Have you taken any pills, medications, or other substances in an attempt to harm yourself?","listenFor":["No ingestion","Reported ingestion or overdose attempt"],"why":"Any reported ingestion warrants evaluation for toxic effects and delayed toxicity.","whySource":"curated","meaning":"Any reported ingestion warrants evaluation for toxic effects and delayed toxicity.","meaningSource":"curated"},{"id":"history-04","system":"psychiatric","question":"Are you hearing voices or seeing things that other people don't, and if so, are they telling you to do anything?","listenFor":["No hallucinations","Hallucinations without command content","Command hallucinations"],"why":null,"whySource":null,"meaning":"Command hallucinations — voices telling the patient to act — markedly raise the risk of harm to self or others and require urgent containment and treatment. Hallucinations without command content still need evaluation for psychosis versus medical causes (delirium, intoxication), which the medical workup must exclude.","meaningSource":"ai-draft"},{"id":"history-05","system":"neurologic","question":"Did this confusion or behavior change come on suddenly, over hours to days, or has it been your usual pattern for a long time?","listenFor":["Chronic, longstanding baseline","Sudden onset over hours to days"],"why":"Sudden behavior change over hours to days suggests delirium or a medical cause rather than primary psychiatric illness.","whySource":"curated","meaning":"Sudden behavior change over hours to days suggests delirium or a medical cause rather than primary psychiatric illness.","meaningSource":"curated"},{"id":"history-06","system":"medication","question":"Have you been drinking alcohol or using drugs recently, or stopped using something you normally use?","listenFor":["Neither","Recent alcohol or drug use","Recent cessation of alcohol or drug use"],"why":null,"whySource":null,"meaning":"Recent substance use can directly cause or mimic psychosis, agitation, and mood symptoms, while recent cessation raises alcohol or benzodiazepine withdrawal — a medical emergency that can kill. Sorting intoxication from withdrawal from primary psychiatric illness determines whether the patient needs detox, medical stabilization, or psychiatric admission.","meaningSource":"ai-draft"},{"id":"history-07","system":"psychiatric","question":"Do you have a diagnosed psychiatric condition, and have you been taking your psychiatric medications as prescribed?","listenFor":["No known psychiatric diagnosis","Known psychiatric diagnosis, taking medications as prescribed","Known psychiatric diagnosis, missed medications"],"why":null,"whySource":null,"meaning":"Missed psychiatric medications are the most common reversible trigger of a crisis and often the fastest fix — restarting the regimen can resolve the episode. A first presentation with no known diagnosis raises the pretest probability of a medical cause and warrants a fuller organic workup.","meaningSource":"ai-draft"},{"id":"history-08","system":"infectious","question":"Have you had a fever or felt physically ill along with this?","listenFor":["No fever or physical illness","Fever or physical illness present"],"why":null,"whySource":null,"meaning":"Fever or physical illness alongside psychiatric symptoms raises delirium and medical mimics (infection, encephalitis) to the top — new psychosis with fever is a medical emergency until proven otherwise. Absent fever does not exclude a medical cause, but it lowers the urgency of an infectious workup.","meaningSource":"ai-draft"},{"id":"history-09","system":"neurologic","question":"Have you had a headache, weakness, or numbness along with this?","listenFor":["None of these","Headache","Weakness or numbness"],"why":null,"whySource":null,"meaning":"Headache with new psychiatric symptoms raises concern for intracranial pathology — subarachnoid hemorrhage, mass, or encephalitis — while focal weakness or numbness points to stroke or a focal lesion masquerading as psychiatric illness. These are 'never miss' findings that demand neuroimaging.","meaningSource":"ai-draft"},{"id":"history-10","system":"endocrine","question":"Do you have diabetes or thyroid disease that could be affecting how you feel?","listenFor":["Neither","Known diabetes","Known thyroid disease"],"why":null,"whySource":null,"meaning":"Diabetes (hypo- or hyperglycemia) and thyroid disease (thyroid storm or myxedema) are classic medical mimics of psychiatric crisis that are rapidly reversible — check glucose and TSH early. Unrecognized glucose or thyroid derangement in an agitated patient can be fatal if treated as purely psychiatric.","meaningSource":"ai-draft"},{"id":"history-11","system":"functional","question":"Do you have somewhere safe to go, and someone who can help keep you safe if you leave here today?","listenFor":["Safe environment and support available","No safe environment or support available"],"why":null,"whySource":null,"meaning":"Discharge safety hinges on this: a patient with no safe place to go or no one to help keep them safe cannot be discharged to an unsafe environment, and disposition must account for housing and support. Available support is a protective factor that meaningfully lowers short-term risk.","meaningSource":"ai-draft"},{"id":"history-12","system":"psychiatric","question":"Have you been hospitalized for a psychiatric reason before, and did anything specific trigger this episode?","listenFor":["No prior psychiatric hospitalization","Prior psychiatric hospitalization, similar trigger","Prior psychiatric hospitalization, new or unclear trigger"],"why":null,"whySource":null,"meaning":"Prior hospitalizations establish the pattern: a similar trigger suggests a recurrent, manageable illness course, while a new or unclear trigger in a previously stable patient raises concern for a medical cause, substance change, or new psychosocial stressor needing investigation.","meaningSource":"ai-draft"}],"exam":[{"id":"exam-01","system":"neurologic","maneuver":"Assess level of consciousness, attention, and orientation.","findings":["Alert, attentive, and fully oriented","Inattentive or fluctuating alertness","Obtunded"],"how":null,"why":"Inattention with fluctuating alertness is the hallmark of delirium.","whySource":"curated","meaning":"Inattention with fluctuating alertness is the hallmark of delirium.","meaningSource":"curated"},{"id":"exam-02","system":"general","maneuver":"Assess vital signs for fever or hemodynamic abnormality.","findings":["Normal vital signs","Febrile","Tachycardic or hypertensive"],"how":null,"why":null,"whySource":null,"meaning":"Fever in a psychiatric crisis points to infection or neuroleptic malignant syndrome as a medical driver and must be worked up before psychiatric disposition. Tachycardia or hypertension suggests sympathomimetic intoxication, withdrawal, or thyroid storm — all medical emergencies that change management.","meaningSource":"ai-draft"},{"id":"exam-03","system":"endocrine","maneuver":"Check fingerstick glucose.","findings":["Normal glucose","Hypoglycemic","Hyperglycemic"],"how":"Prick the side of the fingertip rather than the pad, and apply the blood drop to the test strip.","why":"Hypoglycemia causes neuroglycopenic symptoms such as confusion, diaphoresis, and tremor, and needs urgent correction.","whySource":"curated","meaning":"Hypoglycemia causes neuroglycopenic symptoms such as confusion, diaphoresis, and tremor, and needs urgent correction.","meaningSource":"curated"},{"id":"exam-04","system":"medication","maneuver":"Assess pupil size and reactivity for signs of intoxication or withdrawal.","findings":["Normal pupils","Constricted pupils","Dilated pupils"],"how":null,"why":"Constricted pupils suggest opioid intoxication.","whySource":"curated","meaning":"Constricted pupils suggest opioid intoxication.","meaningSource":"curated"},{"id":"exam-05","system":"medication","maneuver":"Assess for tremor and diaphoresis suggesting withdrawal.","findings":["No tremor or diaphoresis","Tremor or diaphoresis present"],"how":null,"why":"Tremor with diaphoresis suggests alcohol or sedative withdrawal.","whySource":"curated","meaning":"Tremor with diaphoresis suggests alcohol or sedative withdrawal.","meaningSource":"curated"},{"id":"exam-06","system":"neurologic","maneuver":"Assess for a focal neurologic deficit.","findings":["No focal deficit","Focal deficit present"],"how":null,"why":null,"whySource":null,"meaning":"A focal deficit in a patient presenting with psychiatric symptoms identifies a neurologic cause — stroke, mass, or demyelinating lesion — and is an emergency. No focal deficit keeps delirium, intoxication, and primary psychiatric illness higher but does not eliminate a central cause.","meaningSource":"ai-draft"},{"id":"exam-07","system":"psychiatric","maneuver":"Assess speech, thought process, and thought content.","findings":["Linear, coherent thought process","Disorganized speech or thought process","Delusional content present"],"how":null,"why":null,"whySource":null,"meaning":"Disorganized speech or thought process suggests psychosis, mania, or delirium rather than a mood or anxiety presentation, while delusional content identifies fixed false beliefs that carry safety risk. Linear, coherent thought makes primary psychosis less likely but does not rule out mood disorders or suicidality.","meaningSource":"ai-draft"},{"id":"exam-08","system":"skin","maneuver":"Inspect the skin for self-harm injuries, needle marks, or evidence of trauma.","findings":["No injuries identified","Self-harm injuries or needle marks present"],"how":null,"why":"Needle track marks suggest intravenous drug use and raise concern for bacteremia, endocarditis, or soft tissue infection.","whySource":"curated","meaning":"Needle track marks suggest intravenous drug use and raise concern for bacteremia, endocarditis, or soft tissue infection.","meaningSource":"curated"},{"id":"exam-09","system":"cardiovascular","maneuver":"Assess heart rate and rhythm.","findings":["Regular rate and rhythm","Tachycardic","Irregular rhythm"],"how":null,"why":null,"whySource":null,"meaning":"Tachycardia in a psychiatric crisis suggests intoxication (stimulants), withdrawal, thyroid storm, or anticholinergic toxicity — medical causes needing evaluation. An irregular rhythm raises concern for cardiac effects of psychotropic medications or underlying arrhythmia and should prompt an ECG.","meaningSource":"ai-draft"},{"id":"exam-10","system":"neurologic","maneuver":"Assess gait and coordination when safe.","findings":["Normal gait and coordination","Ataxic or unsteady"],"how":null,"why":null,"whySource":null,"meaning":"Ataxia or unsteadiness points to intoxication, sedative effect, cerebellar pathology, or Wernicke's encephalopathy rather than a primary psychiatric cause, and changes the workup. Normal gait is reassuring but does not exclude intoxication or early neurologic disease.","meaningSource":"ai-draft"}],"reviewNeeded":{"whyMissing":15,"howMissing":9}},{"id":"substance-use-complications","title":"Substance use disorder complications","aliases":["substance use","intoxication","withdrawal"],"history":[{"id":"history-01","system":"medication","question":"What substance did you last use, how much, and when?","listenFor":["No recent substance use","Used within the past few hours","Used more than a day ago"],"why":null,"whySource":null,"meaning":"The specific substance, amount, and timing determine whether you are seeing intoxication, impending withdrawal, or overdose risk — and set expectations for the clinical course over the next hours (e.g., stimulant crash versus opioid respiratory depression).","meaningSource":"ai-draft"},{"id":"history-02","system":"medication","question":"Do you inject the substance, and if so, where?","listenFor":["No injection use","Injection use, peripheral sites only","Injection use, including groin or neck sites"],"why":null,"whySource":null,"meaning":"Injection use raises the risk of skin abscesses, bacteremia, and endocarditis; groin or neck injection signals central-vein use with higher risk of deep vein thrombosis, vascular injury, and endocarditis, and directs the exam to those sites.","meaningSource":"ai-draft"},{"id":"history-03","system":"medication","question":"When did you last drink alcohol, and how much do you typically drink per day?","listenFor":["No regular alcohol use","Regular use, still drinking","Regular heavy use, stopped in the past few days"],"why":null,"whySource":null,"meaning":"Heavy alcohol use stopped in the past few days predicts alcohol withdrawal — seizures and delirium tremens typically emerge 6–72 hours after the last drink — triggering withdrawal monitoring and prophylaxis; continued drinking points instead to intoxication or medical complications.","meaningSource":"ai-draft"},{"id":"history-04","system":"neurologic","question":"Have you ever had a seizure or seen things that weren't there when stopping alcohol before?","listenFor":["No prior withdrawal seizures or hallucinations","Prior withdrawal seizure","Prior withdrawal hallucinations or delirium tremens"],"why":"Prior delirium tremens or alcohol withdrawal seizures predict severe withdrawal and guide prophylaxis intensity.","whySource":"curated","meaning":"Prior delirium tremens or alcohol withdrawal seizures predict severe withdrawal and guide prophylaxis intensity.","meaningSource":"curated"},{"id":"history-05","system":"gastrointestinal","question":"Are you having tremors, sweating, nausea, or anxiety since your last use?","listenFor":["None of these","Mild tremor or anxiety","Significant sweating, nausea, or tremor"],"why":"Tremor, sweating, nausea, and anxiety after the last use suggest alcohol or sedative withdrawal.","whySource":"curated","meaning":"Tremor, sweating, nausea, and anxiety after the last use suggest alcohol or sedative withdrawal.","meaningSource":"curated"},{"id":"history-06","system":"gastrointestinal","question":"Are you having body aches, runny nose, yawning, or diarrhea suggesting opioid withdrawal?","listenFor":["None of these","Mild opioid withdrawal symptoms","Severe opioid withdrawal symptoms"],"why":"Rhinorrhea, yawning, diaphoresis, myalgias, and diarrhea are classic signs of opioid withdrawal.","whySource":"curated","meaning":"Rhinorrhea, yawning, diaphoresis, myalgias, and diarrhea are classic signs of opioid withdrawal.","meaningSource":"curated"},{"id":"history-07","system":"cardiovascular","question":"Have you had chest pain or a racing heart since using?","listenFor":["Neither","Chest pain","Racing heart or palpitations"],"why":null,"whySource":null,"meaning":"Chest pain after stimulant use (cocaine, methamphetamine) raises concern for coronary vasospasm and acute coronary syndrome and warrants an ECG and cardiac workup; palpitations suggest arrhythmia, another stimulant complication.","meaningSource":"ai-draft"},{"id":"history-08","system":"respiratory","question":"Has anyone had to give you naloxone or rescue breaths recently because you stopped breathing?","listenFor":["No recent overdose event","Recent overdose requiring naloxone or rescue breathing"],"why":"Needing naloxone or rescue breathing indicates a prior opioid overdose with respiratory depression.","whySource":"curated","meaning":"Needing naloxone or rescue breathing indicates a prior opioid overdose with respiratory depression.","meaningSource":"curated"},{"id":"history-09","system":"infectious","question":"Do you have a fever, or redness and swelling at an injection site?","listenFor":["Neither","Fever","Redness or swelling at an injection site"],"why":null,"whySource":null,"meaning":"Fever in a person who injects drugs raises concern for endocarditis, bacteremia, or a deep soft-tissue infection; redness or swelling at an injection site points to cellulitis or abscess needing examination and likely drainage.","meaningSource":"ai-draft"},{"id":"history-10","system":"psychiatric","question":"Are you having any thoughts of hurting or killing yourself?","listenFor":["No suicidal ideation","Suicidal ideation present"],"why":null,"whySource":null,"meaning":"Intoxication and withdrawal both elevate suicide risk, and substance use is a common context for self-harm; a positive answer triggers immediate psychiatric safety evaluation and changes disposition.","meaningSource":"ai-draft"},{"id":"history-11","system":"neurologic","question":"Have you taken multiple substances together, including any pills, sedatives, or other drugs?","listenFor":["No polysubstance use","Polysubstance use reported"],"why":null,"whySource":null,"meaning":"Polysubstance use complicates both overdose treatment and withdrawal management — for example, combined alcohol and sedative dependence produces a more dangerous withdrawal — and broadens monitoring beyond a single toxidrome.","meaningSource":"ai-draft"},{"id":"history-12","system":"psychiatric","question":"Are you interested in starting treatment or medication for your substance use, like methadone, buprenorphine, or naltrexone?","listenFor":["Not currently interested","Interested in starting treatment"],"why":null,"whySource":null,"meaning":"An expressed interest in treatment is an actionable window: the admission can be used to start buprenorphine or methadone, offer naltrexone, and connect to harm-reduction and follow-up resources rather than only managing the acute complication.","meaningSource":"ai-draft"}],"exam":[{"id":"exam-01","system":"neurologic","maneuver":"Assess level of consciousness and respiratory drive.","findings":["Alert with normal respiratory drive","Sedated but arousable","Unresponsive or inadequate respiratory drive"],"how":null,"why":null,"whySource":null,"meaning":"Depressed consciousness with inadequate respiratory drive is the signature of opioid overdose — the immediate life threat — and calls for airway management and naloxone; alertness with agitation points instead toward stimulant intoxication or withdrawal.","meaningSource":"ai-draft"},{"id":"exam-02","system":"medication","maneuver":"Assess pupil size.","findings":["Normal pupils","Pinpoint pupils","Dilated pupils"],"how":null,"why":"Pinpoint pupils suggest opioid intoxication; dilated or sluggish pupils suggest sympathomimetic, anticholinergic, or withdrawal states.","whySource":"curated","meaning":"Pinpoint pupils suggest opioid intoxication; dilated or sluggish pupils suggest sympathomimetic, anticholinergic, or withdrawal states.","meaningSource":"curated"},{"id":"exam-03","system":"medication","maneuver":"Assess for tremor, diaphoresis, and agitation suggesting withdrawal.","findings":["None present","Mild tremor or diaphoresis","Marked tremor, diaphoresis, or agitation"],"how":null,"why":null,"whySource":null,"meaning":"Tremor, diaphoresis, and agitation are autonomic signs of withdrawal (alcohol, benzodiazepine, or opioid); marked signs demand urgent withdrawal treatment, while their absence makes active withdrawal less likely.","meaningSource":"ai-draft"},{"id":"exam-04","system":"cardiovascular","maneuver":"Assess heart rate and blood pressure.","findings":["Normal vital signs","Tachycardic or hypertensive","Bradycardic or hypotensive"],"how":null,"why":null,"whySource":null,"meaning":"Stimulant intoxication and alcohol withdrawal typically produce tachycardia and hypertension, while opioid or sedative intoxication produces bradycardia and hypotension — the vital-sign pattern helps identify the toxidrome and its severity.","meaningSource":"ai-draft"},{"id":"exam-05","system":"general","maneuver":"Assess temperature for fever.","findings":["Afebrile","Febrile"],"how":null,"why":null,"whySource":null,"meaning":"Fever in this population should prompt a search for infection — endocarditis, abscess, pneumonia — rather than being attributed to withdrawal alone; persistent hyperthermia can also accompany severe stimulant intoxication.","meaningSource":"ai-draft"},{"id":"exam-06","system":"skin","maneuver":"Inspect injection sites and skin for track marks, abscess, or cellulitis.","findings":["No skin or soft tissue infection","Track marks without active infection","Abscess or cellulitis present"],"how":null,"why":"Needle track marks suggest intravenous drug use and raise concern for bacteremia, endocarditis, or soft tissue infection.","whySource":"curated","meaning":"Needle track marks suggest intravenous drug use and raise concern for bacteremia, endocarditis, or soft tissue infection.","meaningSource":"curated"},{"id":"exam-07","system":"cardiovascular","maneuver":"Auscultate the heart for a new murmur suggesting endocarditis.","findings":["No murmur","New murmur present"],"how":null,"why":"A new murmur in a person who injects drugs suggests infective endocarditis.","whySource":"curated","meaning":"A new murmur in a person who injects drugs suggests infective endocarditis.","meaningSource":"curated"},{"id":"exam-08","system":"psychiatric","maneuver":"Assess for hallucinations or perceptual disturbance.","findings":["No hallucinations","Hallucinations present"],"how":null,"why":null,"whySource":null,"meaning":"Hallucinations suggest stimulant-induced psychosis or alcohol withdrawal (delirium tremens), both of which need medical management and a safe, monitored setting rather than being dismissed as intoxication behavior.","meaningSource":"ai-draft"},{"id":"exam-09","system":"neurologic","maneuver":"Assess for tremor progressing to seizure activity or delirium.","findings":["No seizure activity or delirium","Active seizure or delirium tremens"],"how":null,"why":"Prior delirium tremens or alcohol withdrawal seizures predict severe withdrawal and guide prophylaxis intensity.","whySource":"curated","meaning":"Prior delirium tremens or alcohol withdrawal seizures predict severe withdrawal and guide prophylaxis intensity.","meaningSource":"curated"},{"id":"exam-10","system":"skin","maneuver":"Inspect for injury or bruising suggesting a fall or assault while intoxicated.","findings":["No injury","Injury present"],"how":null,"why":null,"whySource":null,"meaning":"Injury or bruising in an intoxicated patient may be occult or have an unreliable history — the exam screens for trauma sustained while impaired, including possible assault, that the patient cannot report.","meaningSource":"ai-draft"}],"reviewNeeded":{"whyMissing":14,"howMissing":10}},{"id":"social-admission-placement-caregiver-failure","title":"Social admission (placement/caregiver failure)","aliases":["placement","caregiver failure","social admission"],"history":[{"id":"history-01","system":"functional","question":"Who normally helps you at home, and has something changed with that person or their availability?","listenFor":["No change in caregiver availability","Caregiver unavailable, hospitalized, or deceased","Caregiver burned out or unable to continue"],"why":null,"whySource":null,"meaning":"A change in the caregiver — illness, hospitalization, death, or burnout — is often the acute trigger that turns a manageable situation into an unsafe one; naming it determines whether the fix is restoring support, arranging respite, or pursuing placement.","meaningSource":"ai-draft"},{"id":"history-02","system":"functional","question":"Compared to before, are you able to bathe, dress, and use the bathroom on your own, or do you need help now?","listenFor":["Independent with activities of daily living","Newly needs assistance with activities of daily living","Bedbound or fully dependent"],"why":null,"whySource":null,"meaning":"New dependence in basic activities of daily living (bathing, dressing, toileting) defines the care gap driving the admission and sets the level of help needed — from a home aide for a few ADLs to facility care for total dependence.","meaningSource":"ai-draft"},{"id":"history-03","system":"functional","question":"Do you have a safe place to sleep tonight if you left the hospital right now?","listenFor":["Safe housing available","No safe housing available"],"why":null,"whySource":null,"meaning":"No safe place to sleep tonight means the patient cannot be discharged tonight regardless of medical stability; the answer forces discharge planning to solve housing first, through shelters, family, or placement.","meaningSource":"ai-draft"},{"id":"history-04","system":"functional","question":"Are you able to get your groceries, medications, and other supplies on your own?","listenFor":["Able to access food and medications independently","Unable to access food or medications without help"],"why":null,"whySource":null,"meaning":"Inability to obtain food or medications independently signals failure of instrumental ADLs, which undermines chronic disease control (missed doses, poor nutrition) and points to a need for home services or meal and medication support.","meaningSource":"ai-draft"},{"id":"history-05","system":"functional","question":"Have you fallen recently, and if so, how many times?","listenFor":["No recent falls","One recent fall","Multiple recent falls"],"why":null,"whySource":null,"meaning":"Recent falls mark an unsafe living situation, frailty, or an occult medical precipitant; multiple falls escalate the urgency for supervision, a home safety evaluation, or a higher level of care.","meaningSource":"ai-draft"},{"id":"history-06","system":"neurologic","question":"Have family or caregivers noticed your memory or thinking getting worse recently?","listenFor":["No noticed cognitive decline","Family-noticed cognitive decline"],"why":null,"whySource":null,"meaning":"Family-noticed cognitive decline raises delirium versus dementia: new or fluctuating decline suggests delirium from a medical precipitant (infection, metabolic derangement) needing workup, while gradual decline suggests dementia affecting safety and decision-making capacity.","meaningSource":"ai-draft"},{"id":"history-07","system":"functional","question":"Do you feel safe at home, and has anyone been physically rough with you or taken your money or belongings without permission?","listenFor":["Feels safe, no concerns","Concern for abuse or neglect","Concern for financial exploitation"],"why":null,"whySource":null,"meaning":"Concerns for physical abuse, neglect, or financial exploitation change the disposition entirely — they trigger consideration of mandatory reporting and adult protective services involvement and may make returning home unsafe.","meaningSource":"ai-draft"},{"id":"history-08","system":"genitourinary","question":"Have you had any new accidents with your bladder or bowels?","listenFor":["No new incontinence","New urinary or bowel incontinence"],"why":"New incontinence reflects loss of sphincter control and is a marker of functional decline; acute onset with back pain or leg symptoms raises concern for cauda equina syndrome.","whySource":"curated","meaning":"New incontinence reflects loss of sphincter control and is a marker of functional decline; acute onset with back pain or leg symptoms raises concern for cauda equina syndrome.","meaningSource":"curated"},{"id":"history-09","system":"infectious","question":"Have you had a fever or new pain that might explain feeling worse?","listenFor":["Neither","Fever","New pain"],"why":null,"whySource":null,"meaning":"A fever or new pain suggests a medical precipitant — infection or an acute problem — is driving the functional decline, which would make this a medical admission in disguise rather than a purely social one.","meaningSource":"ai-draft"},{"id":"history-10","system":"psychiatric","question":"Have you been feeling down, hopeless, or had any thoughts of harming yourself?","listenFor":["No low mood or suicidal ideation","Low mood without suicidal ideation","Suicidal ideation present"],"why":null,"whySource":null,"meaning":"Depression can present as functional decline and withdrawal from self-care; any suicidal ideation is an emergency that takes priority over placement planning and requires immediate psychiatric safety evaluation.","meaningSource":"ai-draft"},{"id":"history-11","system":"functional","question":"Do you use a walker, cane, or wheelchair at home, and is your home set up safely for how you get around now?","listenFor":["Home is safe for current mobility level","Home is not set up safely for current mobility level"],"why":null,"whySource":null,"meaning":"A walker or wheelchair only prevents falls if the home accommodates it — narrow doorways, stairs without rails, or a bathroom the device cannot enter leave the patient unsafe despite the equipment, signaling a need for home modification or relocation.","meaningSource":"ai-draft"},{"id":"history-12","system":"functional","question":"Who is the person who would make medical decisions for you if you couldn't, and are they involved in your care?","listenFor":["Identified and involved decision maker","No identified or involved decision maker"],"why":null,"whySource":null,"meaning":"An identified, involved decision-maker is essential for consent and discharge planning; without one, decisions stall and the team may need to involve ethics, social work, or legal guardianship processes.","meaningSource":"ai-draft"}],"exam":[{"id":"exam-01","system":"neurologic","maneuver":"Assess orientation, attention, and ability to follow commands.","findings":["Alert and fully oriented","Disoriented or inattentive"],"how":null,"why":"Inattention with fluctuating alertness is the hallmark of delirium.","whySource":"curated","meaning":"Inattention with fluctuating alertness is the hallmark of delirium.","meaningSource":"curated"},{"id":"exam-02","system":"general","maneuver":"Assess hydration status and body habitus for signs of neglect.","findings":["Euvolemic, normal body habitus","Signs of dehydration","Cachectic appearance"],"how":null,"why":"Documenting volume status (hypovolemic, euvolemic, or hypervolemic) guides fluid management and helps distinguish prerenal, intrinsic, and volume-overload causes of kidney injury and electrolyte disturbances.","whySource":"curated","meaning":"Documenting volume status (hypovolemic, euvolemic, or hypervolemic) guides fluid management and helps distinguish prerenal, intrinsic, and volume-overload causes of kidney injury and electrolyte disturbances.","meaningSource":"curated"},{"id":"exam-03","system":"skin","maneuver":"Inspect skin and hygiene for evidence of neglect or pressure injury.","findings":["Skin intact, hygiene appropriate","Poor hygiene","Pressure ulcers or bruising in varying stages of healing"],"how":null,"why":"Pressure ulcers or bruises in varying stages of healing raise concern for neglect or abuse.","whySource":"curated","meaning":"Pressure ulcers or bruises in varying stages of healing raise concern for neglect or abuse.","meaningSource":"curated"},{"id":"exam-04","system":"ent","maneuver":"Inspect the oral cavity and dentition.","findings":["Good dentition, moist mucous membranes","Poor dentition or oral lesions"],"how":null,"why":null,"whySource":null,"meaning":"Poor dentition, oral lesions, or dry mucous membranes suggest neglect, malnutrition, or dehydration — bedside markers of inadequate care or intake at home that corroborate the social concern.","meaningSource":"ai-draft"},{"id":"exam-05","system":"musculoskeletal","maneuver":"Assess gait, balance, and safety of ambulation with any usual assistive device, when safe.","findings":["Normal gait and balance","Unsteady gait","Unable to ambulate safely"],"how":null,"why":null,"whySource":null,"meaning":"Watching the patient walk with their usual device shows their real-world mobility and fall risk; inability to ambulate safely means discharge home is unsafe without major new supports.","meaningSource":"ai-draft"},{"id":"exam-06","system":"musculoskeletal","maneuver":"Assess ability to transfer from bed to chair independently, when safe.","findings":["Independent transfers","Requires assistance with transfers","Unable to transfer"],"how":null,"why":null,"whySource":null,"meaning":"Transfer ability is a practical dividing line in placement: independent transfers can be managed with home help, while inability to transfer usually requires facility-level care or a full-time caregiver.","meaningSource":"ai-draft"},{"id":"exam-07","system":"general","maneuver":"Assess vital signs for fever or hemodynamic instability.","findings":["Normal vital signs","Febrile","Hemodynamically abnormal"],"how":null,"why":null,"whySource":null,"meaning":"Fever or hemodynamic instability behind a 'social' presentation flags an acute medical problem — infection, sepsis, dehydration — that must be worked up and treated before any placement discussion.","meaningSource":"ai-draft"},{"id":"exam-08","system":"musculoskeletal","maneuver":"Assess proximal muscle strength.","findings":["Normal strength","Proximal muscle weakness"],"how":null,"why":"Proximal muscle weakness suggests myopathy.","whySource":"curated","meaning":"Proximal muscle weakness suggests myopathy.","meaningSource":"curated"},{"id":"exam-09","system":"psychiatric","maneuver":"Assess mood and affect.","findings":["Euthymic mood and affect","Depressed mood or flat affect"],"how":null,"why":null,"whySource":null,"meaning":"Depressed mood or flat affect corroborates depression as a driver of the decline and poor self-care; observed affect adds objective weight to the history when planning psychiatric follow-up.","meaningSource":"ai-draft"},{"id":"exam-10","system":"gastrointestinal","maneuver":"Perform a rectal examination when indicated.","findings":["Normal, guaiac negative, or deferred as not indicated","Melena or fecal impaction on rectal examination"],"how":null,"why":"Melena (black, tarry stools) indicates upper gastrointestinal bleeding.","whySource":"curated","meaning":"Melena (black, tarry stools) indicates upper gastrointestinal bleeding.","meaningSource":"curated"}],"reviewNeeded":{"whyMissing":16,"howMissing":10}},{"id":"fever-of-unknown-origin","title":"Fever of unknown origin","aliases":["FUO","persistent fever","unexplained fever"],"history":[{"id":"history-01","system":"infectious","question":"How long have you had this fever, how high does it go, and does it come and go in a specific pattern?","listenFor":["Short-duration fever less than 2 weeks","Persistent fever of 2 to 3 weeks","Chronic fever lasting more than 3 weeks"],"why":null,"whySource":null,"meaning":"Fever of unknown origin is defined by duration — classically fever above 38.3°C on multiple occasions over at least 3 weeks without a diagnosis — so establishing the timeline confirms the patient meets criteria, while the pattern and height help separate infectious, malignant, and rheumatologic causes.","meaningSource":"ai-draft"},{"id":"history-02","system":"constitutional","question":"Have you had shaking chills, drenching night sweats, or significant unexplained weight loss?","listenFor":["No night sweats, chills, or weight loss","Chills or night sweats without weight loss","Unintentional weight loss with drenching night sweats"],"why":"Fever with shaking chills (rigors) suggests bacteremia.","whySource":"curated","meaning":"Fever with shaking chills (rigors) suggests bacteremia.","meaningSource":"curated"},{"id":"history-03","system":"respiratory","question":"Have you had a persistent cough, shortness of breath, chest pain, or sinus congestion?","listenFor":["No respiratory symptoms","Cough or sinus congestion without dyspnea","Shortness of breath or pleuritic chest pain"],"why":"Pleuritic chest pain with sudden dyspnea suggests pulmonary embolism.","whySource":"curated","meaning":"Pleuritic chest pain with sudden dyspnea suggests pulmonary embolism.","meaningSource":"curated"},{"id":"history-04","system":"gastrointestinal","question":"Have you had abdominal pain, nausea, vomiting, diarrhea, or yellowing of your skin or eyes?","listenFor":["No gastrointestinal symptoms","Nausea or mild diarrhea","Severe abdominal pain, vomiting, or jaundice"],"why":null,"whySource":null,"meaning":"Abdominal pain, vomiting, or jaundice point to an intra-abdominal source — cholangitis, liver abscess, or cholecystitis — one of the major localizable categories in the FUO workup, directing imaging to the abdomen.","meaningSource":"ai-draft"},{"id":"history-05","system":"genitourinary","question":"Have you had burning or pain when you urinate, frequent urination, or flank/back pain?","listenFor":["No urinary symptoms","Dysuria or urinary frequency","Flank pain or gross hematuria"],"why":null,"whySource":null,"meaning":"Dysuria or frequency suggests a urinary source; flank pain points higher — to pyelonephritis or a perinephric abscess — both common, treatable causes of prolonged fever.","meaningSource":"ai-draft"},{"id":"history-06","system":"musculoskeletal","question":"Have you had new joint pain, joint swelling, muscle aches, or severe headache?","listenFor":["No joint or muscle pain","Diffuse muscle aches or mild joint pain","Joint swelling, severe headache, or neck stiffness"],"why":"Neck stiffness with fever and headache suggests meningitis.","whySource":"curated","meaning":"Neck stiffness with fever and headache suggests meningitis.","meaningSource":"curated"},{"id":"history-07","system":"skin","question":"Have you noticed any new rashes, skin lumps, color changes, or sores?","listenFor":["No rashes or skin changes","Localized rash or hives","Petechiae, purpura, or nodular skin lesions"],"why":"Petechiae or purpura with fever suggests meningococcemia, vasculitis, or thrombocytopenia.","whySource":"curated","meaning":"Petechiae or purpura with fever suggests meningococcemia, vasculitis, or thrombocytopenia.","meaningSource":"curated"},{"id":"history-08","system":"infectious","question":"Have you traveled outside the country recently, spent time in wooded areas, or had contact with sick individuals?","listenFor":["No recent travel, outdoor, or sick exposures","Domestic travel or sick contact","International travel to endemic area or tick/insect bite"],"why":"International travel or tick exposure broadens the differential to imported and vector-borne infections.","whySource":"curated","meaning":"International travel or tick exposure broadens the differential to imported and vector-borne infections.","meaningSource":"curated"},{"id":"history-09","system":"infectious","question":"Have you had close contact with animals, drank unpasteurized milk, or eaten undercooked meat?","listenFor":["No animal or high-risk dietary exposures","Contact with domestic pets","Exposure to farm animals, wild animals, or unpasteurized dairy"],"why":"Farm animal or unpasteurized dairy exposure raises concern for zoonotic infections such as brucellosis or Q fever.","whySource":"curated","meaning":"Farm animal or unpasteurized dairy exposure raises concern for zoonotic infections such as brucellosis or Q fever.","meaningSource":"curated"},{"id":"history-10","system":"medication","question":"Have you started any new medications or supplements recently, or do you have any implanted medical devices?","listenFor":["No new medications or implanted devices","New medication without known drug fever risk","New drug fever risk medication or implanted device/line"],"why":"Many drugs can cause drug fever, which resolves after the drug is stopped.","whySource":"curated","meaning":"Many drugs can cause drug fever, which resolves after the drug is stopped.","meaningSource":"curated"},{"id":"history-11","system":"hematologic","question":"Do you have a history of cancer, autoimmune disease, or any condition that suppresses your immune system?","listenFor":["No history of immunosuppression or malignancy","Autoimmune disease or solid tumor","Active hematologic malignancy, chemotherapy, or severe immunosuppression"],"why":null,"whySource":null,"meaning":"Malignancy (especially lymphoma) and autoimmune disease are leading non-infectious causes of FUO; immunosuppression additionally broadens the differential to opportunistic infections that require specific testing.","meaningSource":"ai-draft"}],"exam":[{"id":"exam-01","system":"general","maneuver":"Assess body temperature, heart rate, blood pressure, and overall clinical appearance.","findings":["Normal vitals and appearing well","Tachycardic or febrile at assessment","Hypotensive or in septic shock"],"how":null,"why":null,"whySource":null,"meaning":"Documented fever and tachycardia confirm the febrile state, while hypotension would reclassify the presentation as sepsis rather than FUO and shift to emergent management; a well-appearing patient supports the deliberate FUO workup pace.","meaningSource":"ai-draft"},{"id":"exam-02","system":"skin","maneuver":"Inspect skin, mucosal surfaces, and conjunctivae for rashes, petechiae, splinter hemorrhages, or jaundice.","findings":["Skin intact, no rash or lesions","Maculopapular or localized rash","Petechiae, purpura, splinter hemorrhages, or jaundice"],"how":null,"why":"Petechiae or purpura with fever suggests meningococcemia, vasculitis, or thrombocytopenia.","whySource":"curated","meaning":"Petechiae or purpura with fever suggests meningococcemia, vasculitis, or thrombocytopenia.","meaningSource":"curated"},{"id":"exam-03","system":"hematologic","maneuver":"Palpate cervical, supraclavicular, axillary, and inguinal lymph nodes.","findings":["No lymphadenopathy","Localized mobile lymphadenopathy","Diffuse, fixed, or tender lymphadenopathy"],"how":null,"why":"Lymphadenopathy suggests infection, malignancy, or systemic inflammatory disease.","whySource":"curated","meaning":"Lymphadenopathy suggests infection, malignancy, or systemic inflammatory disease.","meaningSource":"curated"},{"id":"exam-04","system":"cardiovascular","maneuver":"Auscultate the heart for murmurs, rubs, or gallops.","findings":["Normal heart sounds, no murmur","Systolic murmur, stable or known","New diastolic or changing murmur, or pericardial rub"],"how":null,"why":"A pericardial friction rub suggests acute pericarditis.","whySource":"curated","meaning":"A pericardial friction rub suggests acute pericarditis.","meaningSource":"curated"},{"id":"exam-05","system":"respiratory","maneuver":"Auscultate lungs for crackles, wheezing, or decreased breath sounds.","findings":["Clear breath sounds bilaterally","Focal crackles or wheezing","Diffuse crackles, rub, or absent breath sounds"],"how":null,"why":null,"whySource":null,"meaning":"Focal crackles or wheezing suggest pneumonia; diffuse crackles, a rub, or absent breath sounds raise other pulmonary sources (tuberculosis, fungal infection, effusion) — chest imaging is a core step in every FUO evaluation.","meaningSource":"ai-draft"},{"id":"exam-06","system":"gastrointestinal","maneuver":"Palpate the abdomen for tenderness, masses, or organomegaly (hepatosplenomegaly).","findings":["Soft, nontender, no organomegaly","Mild diffuse tenderness","Focal tenderness, guarding, palpable mass, or hepatosplenomegaly"],"how":null,"why":"Guarding, rebound, or rigidity on palpation suggests peritonitis.","whySource":"curated","meaning":"Guarding, rebound, or rigidity on palpation suggests peritonitis.","meaningSource":"curated"},{"id":"exam-07","system":"genitourinary","maneuver":"Percuss the costovertebral angles for tenderness.","findings":["No costovertebral angle tenderness","Unilateral costovertebral angle tenderness","Bilateral costovertebral angle tenderness"],"how":null,"why":null,"whySource":null,"meaning":"Costovertebral angle tenderness localizes the fever to the kidney — pyelonephritis or perinephric infection — giving the FUO workup a concrete target for urine studies and renal imaging.","meaningSource":"ai-draft"},{"id":"exam-08","system":"musculoskeletal","maneuver":"Examine joints for swelling, erythema, warmth, or tenderness, and inspect temporal arteries.","findings":["No joint swelling or temporal artery tenderness","Mild joint tenderness without swelling","Active synovitis, joint effusion, or tender/thickened temporal arteries"],"how":null,"why":"A tender or thickened temporal artery in an older adult suggests giant cell arteritis.","whySource":"curated","meaning":"A tender or thickened temporal artery in an older adult suggests giant cell arteritis.","meaningSource":"curated"},{"id":"exam-09","system":"neurologic","maneuver":"Assess neck mobility for rigidity or signs of meningismus.","findings":["Supple neck, full range of motion","Neck discomfort with terminal flexion","Nuchal rigidity, positive Brudzinski or Kernig signs"],"how":null,"why":"Nuchal rigidity suggests meningeal irritation, as in meningitis or subarachnoid hemorrhage.","whySource":"curated","meaning":"Nuchal rigidity suggests meningeal irritation, as in meningitis or subarachnoid hemorrhage.","meaningSource":"curated"},{"id":"exam-10","system":"ent","maneuver":"Inspect the dentition, pharynx, and sinuses.","findings":["Normal dentition, no pharyngeal erythema","Sinus tenderness or pharyngeal injection","Dental abscess, dental caries, or tonsillar exudates"],"how":null,"why":"A dental abscess can seed bacteremia and endocarditis.","whySource":"curated","meaning":"A dental abscess can seed bacteremia and endocarditis.","meaningSource":"curated"}],"reviewNeeded":{"whyMissing":7,"howMissing":10}},{"id":"subacute-bacterial-endocarditis","title":"Subacute bacterial endocarditis","aliases":["infective endocarditis","SBE"],"history":[{"id":"history-01","system":"infectious","question":"Have you had persistent fevers, night sweats, fatigue, or unexplained weight loss?","listenFor":["No fevers or systemic symptoms","Low-grade fevers or fatigue","High fevers, night sweats, and weight loss"],"why":null,"whySource":null,"meaning":"Persistent low-grade fevers, night sweats, fatigue, and weight loss are the classic subacute prodrome of endocarditis, often smoldering for weeks before diagnosis; this constellation should prompt blood cultures and echocardiography, especially with a murmur or known valvular disease.","meaningSource":"ai-draft"},{"id":"history-02","system":"cardiovascular","question":"Do you have a history of valve disease, a heart murmur, a prosthetic valve, or a cardiac device?","listenFor":["No history of valve disease or cardiac device","Known heart murmur or valve disease","Prosthetic heart valve or implanted cardiac device"],"why":"Prosthetic valves and cardiac devices are major risk factors for endocarditis.","whySource":"curated","meaning":"Prosthetic valves and cardiac devices are major risk factors for endocarditis.","meaningSource":"curated"},{"id":"history-03","system":"medication","question":"Have you used intravenous drugs, or have you had recent dental work or surgeries?","listenFor":["No IV drug use or recent invasive procedures","Recent minor surgery or dental cleaning","Active intravenous drug use or major dental surgery/extraction"],"why":"Intravenous drug use raises risk for bacteremia, endocarditis, and soft tissue infection.","whySource":"curated","meaning":"Intravenous drug use raises risk for bacteremia, endocarditis, and soft tissue infection.","meaningSource":"curated"},{"id":"history-04","system":"cardiovascular","question":"Have you had new shortness of breath, chest pain, or swelling in your legs?","listenFor":["No cardiopulmonary symptoms","Mild exertional dyspnea or trace leg edema","Orthopnea, chest pain, or severe peripheral edema"],"why":"Orthopnea suggests elevated left-sided filling pressures, as seen in left heart failure.","whySource":"curated","meaning":"Orthopnea suggests elevated left-sided filling pressures, as seen in left heart failure.","meaningSource":"curated"},{"id":"history-05","system":"skin","question":"Have you noticed any new painful or painless spots, bumps, or lines on your skin, fingers, or toes?","listenFor":["No skin or nail lesions","Nonspecific rash","Splinter hemorrhages, painful nodules on fingers, or painless red spots on palms/soles"],"why":"Janeway lesions, Osler nodes, splinter hemorrhages, and Roth spots are embolic or immunologic stigmata of infective endocarditis.","whySource":"curated","meaning":"Janeway lesions, Osler nodes, splinter hemorrhages, and Roth spots are embolic or immunologic stigmata of infective endocarditis.","meaningSource":"curated"},{"id":"history-06","system":"neurologic","question":"Have you had a sudden weakness, numbness, vision changes, or severe headache?","listenFor":["No neurologic symptoms","Transient dizziness or headache","Acute focal weakness, sensory loss, vision changes, or meningeal headache"],"why":"Acute focal deficits in endocarditis suggest septic emboli to the brain.","whySource":"curated","meaning":"Acute focal deficits in endocarditis suggest septic emboli to the brain.","meaningSource":"curated"},{"id":"history-07","system":"genitourinary","question":"Have you noticed blood in your urine or flank pain?","listenFor":["No hematuria or flank pain","Microscopic hematuria only","Gross hematuria or acute flank pain"],"why":"Gross hematuria or flank pain in endocarditis suggests renal emboli or immune-complex glomerulonephritis.","whySource":"curated","meaning":"Gross hematuria or flank pain in endocarditis suggests renal emboli or immune-complex glomerulonephritis.","meaningSource":"curated"},{"id":"history-08","system":"musculoskeletal","question":"Have you had new joint pain or back pain?","listenFor":["No joint or back pain","Mild joint aches","Severe localized back pain or acute joint swelling"],"why":"Severe localized back pain suggests vertebral osteomyelitis, discitis, or epidural abscess.","whySource":"curated","meaning":"Severe localized back pain suggests vertebral osteomyelitis, discitis, or epidural abscess.","meaningSource":"curated"},{"id":"history-09","system":"medication","question":"Have you taken antibiotics recently before your blood cultures were drawn?","listenFor":["No recent antibiotic use","Completed antibiotic course over 2 weeks ago","Recent or active antibiotic use within past 2 weeks"],"why":"Recent antibiotics before blood cultures are drawn can sterilize cultures and obscure the diagnosis of endocarditis.","whySource":"curated","meaning":"Recent antibiotics before blood cultures are drawn can sterilize cultures and obscure the diagnosis of endocarditis.","meaningSource":"curated"},{"id":"history-10","system":"infectious","question":"Do you have an indwelling venous line, hemodialysis catheter, or a history of recurrent bloodstream infections?","listenFor":["No indwelling catheters or recurrent infections","Prior indwelling catheter, currently removed","Active central line, hemodialysis catheter, or prior bacteremia"],"why":null,"whySource":null,"meaning":"Indwelling venous lines, hemodialysis catheters, and prior bloodstream infections are major risk factors for bacteremia seeding heart valves; an active line with systemic symptoms makes line infection with secondary endocarditis a leading concern and may require line removal as well as prolonged antibiotics.","meaningSource":"ai-draft"}],"exam":[{"id":"exam-01","system":"cardiovascular","maneuver":"Auscultate the heart for a new murmur or changes to an existing murmur.","findings":["No murmur or stable chronic murmur","New systolic murmur","New diastolic murmur or changing murmur severity"],"how":null,"why":"A new or changing murmur is a major criterion for infective endocarditis.","whySource":"curated","meaning":"A new or changing murmur is a major criterion for infective endocarditis.","meaningSource":"curated"},{"id":"exam-02","system":"general","maneuver":"Assess body temperature, heart rate, blood pressure, and perfusion status.","findings":["Afebrile, stable hemodynamics","Febrile or tachycardic","Hypotensive or in decompensated shock"],"how":null,"why":null,"whySource":null,"meaning":"Fever with tachycardia supports ongoing bacteremia and systemic infection, while hypotension or shock suggests severe sepsis, acute valvular destruction, or heart failure from endocarditis — a decompensated state requiring ICU care and urgent echocardiography; stable afebrile vitals do not exclude subacute disease.","meaningSource":"ai-draft"},{"id":"exam-03","system":"skin","maneuver":"Inspect palms and soles for painless, erythematous macular lesions (Janeway lesions).","findings":["No Janeway lesions","Janeway lesions present"],"how":null,"why":"Janeway lesions, Osler nodes, splinter hemorrhages, and Roth spots are embolic or immunologic stigmata of infective endocarditis.","whySource":"curated","meaning":"Janeway lesions, Osler nodes, splinter hemorrhages, and Roth spots are embolic or immunologic stigmata of infective endocarditis.","meaningSource":"curated"},{"id":"exam-04","system":"skin","maneuver":"Inspect pads of fingers and toes for painful, erythematous nodules (Osler nodes).","findings":["No Osler nodes","Osler nodes present"],"how":null,"why":"Janeway lesions, Osler nodes, splinter hemorrhages, and Roth spots are embolic or immunologic stigmata of infective endocarditis.","whySource":"curated","meaning":"Janeway lesions, Osler nodes, splinter hemorrhages, and Roth spots are embolic or immunologic stigmata of infective endocarditis.","meaningSource":"curated"},{"id":"exam-05","system":"skin","maneuver":"Inspect fingernails and toenails for linear dark red streaks (splinter hemorrhages).","findings":["No splinter hemorrhages","Splinter hemorrhages present"],"how":null,"why":"Janeway lesions, Osler nodes, splinter hemorrhages, and Roth spots are embolic or immunologic stigmata of infective endocarditis.","whySource":"curated","meaning":"Janeway lesions, Osler nodes, splinter hemorrhages, and Roth spots are embolic or immunologic stigmata of infective endocarditis.","meaningSource":"curated"},{"id":"exam-06","system":"eyes","maneuver":"Examine the conjunctivae for petechiae and perform fundoscopy to assess for retinal hemorrhages (Roth spots) if trained.","findings":["Normal conjunctival and retinal exam","Conjunctival petechiae present","Roth spots present on fundoscopic exam"],"how":null,"why":"Retinal hemorrhages can reflect hypertensive end-organ damage, or Roth spots from septic emboli in endocarditis.","whySource":"curated","meaning":"Retinal hemorrhages can reflect hypertensive end-organ damage, or Roth spots from septic emboli in endocarditis.","meaningSource":"curated"},{"id":"exam-07","system":"respiratory","maneuver":"Auscultate lungs for crackles, wheezing, or evidence of pulmonary congestion.","findings":["Clear lung fields bilaterally","Focal crackles","Diffuse bilateral crackles indicating heart failure"],"how":null,"why":"Diffuse bilateral crackles suggest pulmonary edema from left heart failure.","whySource":"curated","meaning":"Diffuse bilateral crackles suggest pulmonary edema from left heart failure.","meaningSource":"curated"},{"id":"exam-08","system":"gastrointestinal","maneuver":"Palpate the abdomen for splenomegaly or left upper quadrant tenderness.","findings":["No splenomegaly or left upper quadrant tenderness","Left upper quadrant tenderness without splenomegaly","Palpable splenomegaly or severe tender splenic infarct findings"],"how":null,"why":"Splenomegaly suggests portal hypertension, hematologic disease, or systemic infection.","whySource":"curated","meaning":"Splenomegaly suggests portal hypertension, hematologic disease, or systemic infection.","meaningSource":"curated"},{"id":"exam-09","system":"neurologic","maneuver":"Perform a focused neurologic exam assessing strength, sensation, cranial nerves, and signs of embolic stroke.","findings":["No focal neurologic deficits","Mild or old neurologic deficit","New focal neurologic deficit (hemiparesis, aphasia) suggesting embolic event"],"how":null,"why":"A new focal deficit in endocarditis suggests cerebral septic embolism.","whySource":"curated","meaning":"A new focal deficit in endocarditis suggests cerebral septic embolism.","meaningSource":"curated"},{"id":"exam-10","system":"skin","maneuver":"Inspect any indwelling catheter or line site for erythema, warmth, tenderness, or purulent drainage.","findings":["No indwelling lines, or line site is clean and quiet","Mild erythema without drainage at line site","Erythema, purulent drainage, or tenderness at line site"],"how":null,"why":null,"whySource":null,"meaning":"An erythematous, tender, or draining line site identifies the likely source of bacteremia that could seed the valves; purulent drainage warrants cultures of the site, blood cultures, and consideration of line removal, since a retained infected line will perpetuate endocarditis despite antibiotics.","meaningSource":"ai-draft"}],"reviewNeeded":{"whyMissing":4,"howMissing":10}},{"id":"ob-labor-triage","title":"Labor triage & current pregnancy","aliases":["labor","triage","pregnancy","labor check","contractions","vaginal bleeding in pregnancy"],"history":[{"id":"history-01","system":"obstetric","question":"What brought you in today? What is most important to address?","listenFor":["Chief concern in patient's own words","Most important issue identified"],"why":null,"whySource":null,"meaning":"Starting with the patient's own chief concern sets triage priorities and ensures the evaluation addresses what matters most to her, not just what the chart suggests.","meaningSource":"ai-draft"},{"id":"history-02","system":"obstetric","question":"Could you be pregnant? Are you trying to conceive?","listenFor":["Could be pregnant","Trying to conceive","Not pregnant / not trying"],"why":null,"whySource":null,"meaning":"Pregnancy status changes the entire differential — ectopic pregnancy, miscarriage, and preeclampsia enter the picture — so establishing it early determines which emergencies must be ruled out first.","meaningSource":"ai-draft"},{"id":"history-03","system":"obstetric","question":"When was the first day of your last normal period (LMP)?","listenFor":["LMP date given","Unsure of LMP"],"why":null,"whySource":null,"meaning":"The last menstrual period anchors gestational dating and the evaluation of abnormal bleeding; an unreliable or unknown LMP means dating must come from early ultrasound instead.","meaningSource":"ai-draft"},{"id":"history-04","system":"obstetric","question":"Have you had a home or clinic pregnancy test?","listenFor":["Positive test","Negative test","Not tested"],"why":null,"whySource":null,"meaning":"A pregnancy test confirms pregnancy before any imaging, medications, or procedures, and a positive test with pain or bleeding triggers the ectopic pregnancy workup.","meaningSource":"ai-draft"},{"id":"history-05","system":"obstetric","question":"What is your gestational age and estimated due date (EDD), and how was the pregnancy dated?","listenFor":["GA and EDD known","Dated by LMP","Dated by ultrasound"],"why":null,"whySource":null,"meaning":"Gestational age determines viability thresholds and management — preterm labor, post-term, and dating accuracy all hinge on it — and knowing how the pregnancy was dated tells you how much to trust the number.","meaningSource":"ai-draft"},{"id":"history-06","system":"obstetric","question":"Have you had prenatal care this pregnancy?","listenFor":["Receiving prenatal care","No or limited prenatal care"],"why":null,"whySource":null,"meaning":"Lack of prenatal care marks a higher-risk pregnancy with unknown complications, undated gestation, and unscreened infections; it lowers the threshold for a comprehensive evaluation.","meaningSource":"ai-draft"},{"id":"history-07","system":"obstetric","question":"Is this one baby or more than one (fetal number)?","listenFor":["Singleton","Multifetal gestation"],"why":null,"whySource":null,"meaning":"Multiple gestation carries higher risks of preterm labor, preeclampsia, and malpresentation, so knowing fetal number changes surveillance and delivery planning.","meaningSource":"ai-draft"},{"id":"history-08","system":"obstetric","question":"Any complications or medications in this pregnancy?","listenFor":["None reported","Complications or medications listed"],"why":null,"whySource":null,"meaning":"Complications such as hypertension or diabetes and current medications inform immediate risk — some drugs are teratogenic or affect labor management — and shape the triage plan.","meaningSource":"ai-draft"},{"id":"history-09","system":"obstetric","question":"Are you having any vaginal bleeding?","listenFor":["No vaginal bleeding","Vaginal bleeding present"],"why":null,"whySource":null,"meaning":"Vaginal bleeding in pregnancy is never normal; the differential includes labor, abruption, and placenta previa — heavy bleeding or bleeding with pain is an emergency, and a digital exam must wait until previa is excluded.","meaningSource":"ai-draft"},{"id":"history-10","system":"obstetric","question":"Are you having contractions?","listenFor":["No contractions","Contractions — onset, frequency, duration described"],"why":null,"whySource":null,"meaning":"Contraction timing, frequency, and regularity distinguish true labor from Braxton Hicks; regular painful contractions with cervical change define labor and determine admission versus discharge.","meaningSource":"ai-draft"},{"id":"history-11","system":"obstetric","question":"Any leakage of fluid?","listenFor":["No leakage","Possible fluid leakage / rupture of membranes"],"why":null,"whySource":null,"meaning":"Leakage of fluid suggests ruptured membranes, which should be confirmed on exam; confirmed ROM starts the clock on infection risk such as chorioamnionitis, especially if prolonged or preterm.","meaningSource":"ai-draft"},{"id":"history-12","system":"obstetric","question":"How has the baby's movement been?","listenFor":["Normal fetal movement","Decreased fetal movement"],"why":null,"whySource":null,"meaning":"Decreased fetal movement is a red flag for fetal compromise and warrants prompt antenatal testing and monitoring — it should never be dismissed without evaluation.","meaningSource":"ai-draft"},{"id":"history-13","system":"obstetric","question":"Any severe headache, vision change, right-upper-quadrant or epigastric pain, marked swelling, fever, burning with urination, or trauma?","listenFor":["None reported","Concerning symptom reported"],"why":null,"whySource":null,"meaning":"Severe headache, vision changes, right-upper-quadrant pain, marked swelling, fever, dysuria, or trauma are red flags for preeclampsia with severe features, infection, or abruption — each demands urgent targeted evaluation.","meaningSource":"ai-draft"}],"exam":[],"reviewNeeded":{"whyMissing":13,"howMissing":0}},{"id":"ob-menstrual-menopause","title":"Menstrual history & menopause","aliases":["periods","menstruation","LMP","menopause","abnormal uterine bleeding","intermenstrual bleeding"],"history":[{"id":"history-01","system":"gynecologic","question":"How old were you when your periods started (menarche)?","listenFor":["Menarche age given"],"why":null,"whySource":null,"meaning":"Age at menarche frames the reproductive timeline: very early or late menarche points to underlying endocrine causes such as precocious puberty or primary ovarian insufficiency that shape the current workup.","meaningSource":"ai-draft"},{"id":"history-02","system":"gynecologic","question":"Are your periods regular — every how many days, bleeding for how many days?","listenFor":["Regular pattern described","Irregular pattern"],"why":null,"whySource":null,"meaning":"Cycle regularity distinguishes ovulatory from anovulatory bleeding — regular cycles suggest ovulation with a structural or bleeding-disorder cause, while irregular cycles point to anovulation from PCOS, thyroid disease, or perimenopause.","meaningSource":"ai-draft"},{"id":"history-03","system":"gynecologic","question":"Has there been a recent change in your periods?","listenFor":["No recent change","Recent change described"],"why":null,"whySource":null,"meaning":"A recent change in a previously stable pattern is a red flag for new pathology such as fibroids, polyps, pregnancy, or malignancy, and warrants targeted evaluation rather than reassurance.","meaningSource":"ai-draft"},{"id":"history-04","system":"gynecologic","question":"How heavy is your flow — pads, tampons, or cup per day? Do you fully soak them?","listenFor":["Pads / tampons / cup per day, not soaked","Fully soaked","Flooding or overnight changes","Clots"],"why":null,"whySource":null,"meaning":"Quantifying flow — pads or tampons per day and whether they are fully soaked — defines heavy menstrual bleeding objectively, guides anemia screening, and sets a baseline for judging treatment response.","meaningSource":"ai-draft"},{"id":"history-05","system":"gynecologic","question":"How do your periods affect your life?","listenFor":["Minimal impact","Limits daily activities"],"why":null,"whySource":null,"meaning":"How periods affect daily life measures severity from the patient's perspective and determines whether treatment is warranted — bleeding that disrupts work or school deserves intervention even when labs are normal.","meaningSource":"ai-draft"},{"id":"history-06","system":"gynecologic","question":"Do you have cramping or pelvic pain with your periods? Headache, mood changes, or other symptoms around your period?","listenFor":["No perimenstrual symptoms","Cramping or pelvic pain","Headache, mood, or other perimenstrual symptoms"],"why":null,"whySource":null,"meaning":"Cramping and pelvic pain with periods raise concern for endometriosis or adenomyosis, while cyclical headache and mood changes point toward premenstrual disorders — each leads to different treatment options.","meaningSource":"ai-draft"},{"id":"history-07","system":"gynecologic","question":"Any bleeding between periods? Any bleeding after sex?","listenFor":["No intermenstrual or postcoital bleeding","Bleeding between periods","Bleeding after sex"],"why":null,"whySource":null,"meaning":"Bleeding between periods or after sex points to cervical or endometrial pathology such as polyps; postcoital bleeding in particular requires cervical evaluation including up-to-date screening.","meaningSource":"ai-draft"},{"id":"history-08","system":"gynecologic","question":"When did your periods stop? Any menopause symptoms? Any hormone therapy? Any bleeding or spotting since your periods stopped?","listenFor":["Menopause details given","Postmenopausal bleeding or spotting"],"why":null,"whySource":null,"meaning":"Any bleeding after menopause is endometrial cancer until proven otherwise and needs prompt evaluation; menopause timing and symptoms also frame discussions about hormone therapy risks and benefits.","meaningSource":"ai-draft"},{"id":"history-09","system":"gynecologic","question":"Record: menarche age | LMP | cycle every __ days x __ days | flow | intermenstrual or postcoital bleeding Y/N.","listenFor":["Chart completed"],"why":null,"whySource":null,"meaning":"Recording the full menstrual summary in one structured line ensures nothing is missed on handoff and makes changes over time easy to track across visits.","meaningSource":"ai-draft"}],"exam":[],"reviewNeeded":{"whyMissing":9,"howMissing":0}},{"id":"ob-obstetric-history","title":"Obstetric history (GTPAL)","aliases":["GTPAL","gravida para","obstetric history","pregnancy history","postpartum","postpartum hemorrhage"],"history":[{"id":"history-01","system":"obstetric","question":"What is your GTPAL — gravida, term births, preterm births, abortions / losses / ectopics, living children?","listenFor":["G___ P___-___-___-___ stated"],"why":null,"whySource":null,"meaning":"GTPAL is the universal shorthand for obstetric history — gravida, term births, preterm births, abortions and losses including ectopics, living children. Getting it right at the start frames every risk assessment that follows, from preterm-birth risk to Rh management.","meaningSource":"ai-draft"},{"id":"history-02","system":"obstetric","question":"For each pregnancy: what year, what gestational age, and what was the outcome?","listenFor":["Each pregnancy detailed"],"why":null,"whySource":null,"meaning":"Detailing each pregnancy by year, gestational age, and outcome reveals patterns — recurrent preterm birth, repeated losses, short interpregnancy intervals — that a bare GTPAL number would hide and that directly change the surveillance plan.","meaningSource":"ai-draft"},{"id":"history-03","system":"obstetric","question":"Was labor spontaneous or induced? Was the delivery vaginal, operative vaginal, or cesarean?","listenFor":["Spontaneous labor","Induced labor","Vaginal delivery","Operative vaginal delivery","Cesarean delivery"],"why":null,"whySource":null,"meaning":"How each labor started and how each delivery ended predicts this pregnancy's risks: a prior cesarean raises the question of trial of labor versus repeat cesarean, while prior inductions or operative vaginal deliveries hint at underlying issues like dystocia or fetal intolerance of labor.","meaningSource":"ai-draft"},{"id":"history-04","system":"obstetric","question":"What was the baby's sex and birth weight? Any maternal or newborn complications?","listenFor":["Infant details and complications given","No complications"],"why":null,"whySource":null,"meaning":"Birth weights and newborn complications flag recurrent risks: a prior macrosomic infant predicts gestational diabetes and shoulder dystocia, while a prior growth-restricted or NICU infant prompts closer fetal surveillance this time.","meaningSource":"ai-draft"},{"id":"history-05","system":"obstetric","question":"Any pregnancy losses, ectopic pregnancies, or molar pregnancies — what type or cause, and was treatment medical or surgical? Any complications?","listenFor":["Loss / ectopic / molar history detailed","None"],"why":null,"whySource":null,"meaning":"The type and management of each loss matters: recurrent early losses suggest a workup for anatomic, genetic, or clotting causes; a prior ectopic raises recurrence risk; a prior molar pregnancy mandates hCG surveillance and changes counseling. Note whether treatment was medical or surgical and whether complications followed.","meaningSource":"ai-draft"},{"id":"history-06","system":"obstetric","question":"Any of these complications in a prior pregnancy: preeclampsia or hypertension, gestational diabetes, preterm birth, fetal growth restriction, shoulder dystocia, postpartum hemorrhage, stillbirth or anomaly, blood clots, ICU stay, postpartum depression or psychosis?","listenFor":["None reported","Prior complication identified"],"why":null,"whySource":null,"meaning":"Each prior complication tends to recur — preeclampsia, gestational diabetes, preterm birth, growth restriction, shoulder dystocia, and postpartum hemorrhage all raise the risk of the same event again. This list directly generates the surveillance and prevention plan for the current pregnancy.","meaningSource":"ai-draft"},{"id":"history-07","system":"obstetric","question":"How do you count a twin pregnancy in GTPAL?","listenFor":["One pregnancy in G/TPA","Each living child counted in L"],"why":"A multifetal gestation counts as 1 pregnancy in G/TPA; count each living child in L. Use your institution's gestational-age threshold.","whySource":"curated","meaning":"A multifetal gestation counts as 1 pregnancy in G/TPA; count each living child in L. Use your institution's gestational-age threshold.","meaningSource":"curated"}],"exam":[],"reviewNeeded":{"whyMissing":6,"howMissing":0}},{"id":"ob-gyn-history-screening","title":"GYN history, screening & pelvic floor","aliases":["gyn","gynecology","pap smear","cervical screening","pelvic floor","incontinence","prolapse","mammogram"],"history":[{"id":"history-01","system":"gynecologic","question":"Any pelvic or abdominal pain, vaginal discharge — its color, odor, consistency — itching or burning, vulvar lesions, or abnormal bleeding?","listenFor":["None reported","Symptom described"],"why":null,"whySource":null,"meaning":"These symptoms localize to infection, structural disease, or malignancy: discharge with odor or itching suggests bacterial vaginosis, trichomoniasis, or candidiasis; vulvar lesions raise concern for herpes or HPV. Abnormal bleeding — especially postmenopausal — is endometrial cancer until proven otherwise and needs timely evaluation.","meaningSource":"ai-draft"},{"id":"history-02","system":"gynecologic","question":"Any history of fibroids, endometriosis, ovarian cysts, PCOS, infertility, PID or STIs, or prolapse — how were they diagnosed and treated?","listenFor":["No GYN conditions","Condition with diagnosis and treatment given"],"why":null,"whySource":null,"meaning":"Prior GYN diagnoses shape the current differential — fibroids and endometriosis explain bleeding and pain patterns, PCOS explains irregular menses and metabolic risk, and PID history raises ectopic and infertility risk. Knowing how each was diagnosed and treated prevents repeating workups and flags recurrence.","meaningSource":"ai-draft"},{"id":"history-03","system":"gynecologic","question":"Any GYN procedures — biopsy, hysteroscopy or laparoscopy, ablation, myomectomy, hysterectomy, oophorectomy? What was the indication and date, and were there complications?","listenFor":["No prior procedures","Procedure with indication, date, complications"],"why":null,"whySource":null,"meaning":"Prior procedures change anatomy and risk: hysteroscopy or ablation affects bleeding evaluation, myomectomy affects labor management, and hysterectomy or oophorectomy changes screening needs and hormone considerations. The indication and date anchor whether current symptoms represent recurrence or a new problem.","meaningSource":"ai-draft"},{"id":"history-04","system":"gynecologic","question":"What are your pregnancy goals? How long have you been trying? Any prior fertility evaluation for you or your partner, or relevant disease or surgery?","listenFor":["Fertility history given"],"why":null,"whySource":null,"meaning":"Duration of trying defines infertility (12 months, or 6 months if over 35) and triggers the evaluation pathway; knowing the prior fertility workup for both partners avoids duplication and identifies known barriers. This history directly determines referral timing and testing.","meaningSource":"ai-draft"},{"id":"history-05","system":"gynecologic","question":"When was your last cervical cancer screening and what was the result? Any prior abnormal result or HPV, colposcopy, LEEP, or other treatment? Have you had HPV vaccination?","listenFor":["Screening history and result given","Prior abnormal result or treatment","HPV vaccinated"],"why":null,"whySource":null,"meaning":"Screening history determines what is due: prior abnormal results or LEEP change surveillance intervals and raise current risk, while HPV vaccination modifies but does not eliminate screening need. An overdue screen in a symptomatic patient should be expedited.","meaningSource":"ai-draft"},{"id":"history-06","system":"gynecologic","question":"When was your last mammogram or breast imaging and what was the result? Any current lump, pain, skin or nipple change, or discharge? Any prior breast biopsy, surgery, or cancer?","listenFor":["Breast screening history given","Current breast symptom","Prior breast biopsy, surgery, or cancer"],"why":null,"whySource":null,"meaning":"Breast screening history establishes risk and what imaging is due; a current lump, skin or nipple change, or discharge needs prompt diagnostic — not screening — imaging. Prior biopsy or cancer markedly raises risk and changes the surveillance plan.","meaningSource":"ai-draft"},{"id":"history-07","system":"gynecologic","question":"Any burning with urination or urinating more often? Any urine leakage with coughing, sneezing, or exercise (stress) versus a sudden urge you cannot hold (urge)?","listenFor":["No urinary symptoms","Dysuria or frequency","Stress leakage","Urge leakage"],"why":null,"whySource":null,"meaning":"Distinguishing stress leakage (with cough, sneeze, exercise) from urge leakage (sudden urge, cannot hold) determines treatment — stress incontinence is anatomic and may need pelvic floor therapy or surgery, while urge incontinence is detrusor overactivity treated behaviorally or pharmacologically. Dysuria or frequency suggests UTI or overactive bladder and needs urinalysis.","meaningSource":"ai-draft"},{"id":"history-08","system":"gynecologic","question":"Any stool or gas leakage, constipation, pelvic pressure, or a vaginal bulge?","listenFor":["No bowel or prolapse symptoms","Symptom described"],"why":null,"whySource":null,"meaning":"Fecal or gas leakage, pelvic pressure, and a vaginal bulge suggest pelvic organ prolapse or pelvic floor dysfunction, which is graded on exam and managed from pessary to surgery. Constipation may be both a symptom and a contributor — addressing it is part of prolapse management.","meaningSource":"ai-draft"}],"exam":[],"reviewNeeded":{"whyMissing":8,"howMissing":0}},{"id":"ob-sexual-history","title":"Sexual history: 5 Ps + PLUS","aliases":["sexual history","5 Ps","STI","sexually transmitted infection","partners"],"history":[{"id":"history-01","system":"gynecologic","question":"I ask everyone these questions because sexual health is part of overall health. Is it okay if we discuss this?","listenFor":["Patient agrees to discuss","Patient declines or defers"],"why":null,"whySource":null,"meaning":"Explicitly normalizing the topic and asking permission builds trust and increases honest disclosure — patients answer sensitive questions more completely when the clinician frames them as routine; if the patient declines, respect it and revisit later rather than pressing.","meaningSource":"ai-draft"},{"id":"history-02","system":"gynecologic","question":"Are you having sex of any kind now or in the past? How many partners in recent months? What genders? Any new or concurrent partners?","listenFor":["Partner history given"],"why":null,"whySource":null,"meaning":"Partner number, genders, and concurrency define STI and HIV risk far better than assumptions about orientation or relationship status; new or concurrent partners are the strongest behavioral predictors of incident STI and guide who needs testing and counseling.","meaningSource":"ai-draft"},{"id":"history-03","system":"gynecologic","question":"What kinds of sex — oral, vaginal/frontal, anal — and which body parts are involved?","listenFor":["Practices described"],"why":"This guides site-specific testing.","whySource":"curated","meaning":"This guides site-specific testing.","meaningSource":"curated"},{"id":"history-04","system":"gynecologic","question":"Do you use condoms or barriers — for which acts and how often? Any STI testing? Have you had HPV or hepatitis vaccines? Is PrEP relevant?","listenFor":["Protection practices described"],"why":null,"whySource":null,"meaning":"Detailing barrier use by act, testing history, and vaccination status reveals the actual protection gaps — condoms used inconsistently or only for vaginal sex leave substantial risk; it also identifies who is due for HPV or hepatitis vaccination and whether PrEP counseling is appropriate.","meaningSource":"ai-draft"},{"id":"history-05","system":"gynecologic","question":"Any past STIs — testing and prior diagnoses, dates, treatment, recurrence, partner history? Ask specifically as needed: gonorrhea, chlamydia, trich, HSV, HPV/warts, syphilis, HIV, hepatitis, PID.","listenFor":["No prior STIs","Prior STI history detailed"],"why":null,"whySource":null,"meaning":"A prior STI is the strongest predictor of a current or future one and signals the need for retesting, partner evaluation, and counseling on recurrence; a history of PID additionally raises concern for tubal damage and future ectopic pregnancy or infertility.","meaningSource":"ai-draft"},{"id":"history-06","system":"gynecologic","question":"Would you like pregnancy now, later, or not at all? How important is preventing pregnancy? What contraception do you use now or used before — adherence, satisfaction, side effects?","listenFor":["Pregnancy intention and contraception history given"],"why":null,"whySource":null,"meaning":"Clarifying pregnancy intention first ensures contraception counseling matches the patient's actual goals — preventing an unwanted pregnancy versus planning one; asking about adherence, satisfaction, and side effects uncovers why a method is failing and guides switching rather than simply repeating the same prescription.","meaningSource":"ai-draft"},{"id":"history-07","system":"gynecologic","question":"Any pain with sex? Any concerns about desire, arousal, orgasm, pleasure, or satisfaction? Any unwanted or coerced sexual activity?","listenFor":["No concerns reported","Concern disclosed"],"why":null,"whySource":null,"meaning":"Asking directly about pain with sex, sexual function concerns, and coerced activity uncovers problems patients rarely volunteer — dyspareunia may signal endometriosis or infection, and any disclosure of coercion requires a private, supportive response with safety planning and referral resources.","meaningSource":"ai-draft"}],"exam":[],"reviewNeeded":{"whyMissing":6,"howMissing":0}},{"id":"ob-safety-close","title":"OB/GYN do-not-miss, safety & close","aliases":["IPV","intimate partner violence","safety","do not miss","one-liner","family history"],"history":[{"id":"history-01","system":"general","question":"When appropriate, interview alone. Do you feel safe at home and in your relationships? Has anyone hurt, threatened, controlled you, or forced you into sexual activity?","listenFor":["Feels safe","Safety concern disclosed"],"why":null,"whySource":null,"meaning":"Asking about safety alone — away from partners or family — is the only way disclosure happens, since abuse often hides behind a present partner. A disclosed concern should prompt safety planning, social work involvement, and resource referrals; it directly affects pregnancy and health outcomes.","meaningSource":"ai-draft"},{"id":"history-02","system":"general","question":"Any family history of breast, ovarian, endometrial/uterine, cervical, or colon cancer — which relative and at what age? Any blood clots or osteoporosis?","listenFor":["No relevant family history","Family history detailed"],"why":null,"whySource":null,"meaning":"A family history of breast, ovarian, endometrial, or colon cancer at young ages suggests hereditary syndromes like BRCA or Lynch that change screening and referral; clot history affects whether estrogen contraception is safe. Detailing which relative and at what age determines whether genetic counseling is indicated.","meaningSource":"ai-draft"},{"id":"history-03","system":"general","question":"If pregnancy-relevant: any known inherited disorders, developmental delay, trisomy, neural tube defects, or congenital heart defects in the family?","listenFor":["None reported","Relevant family history"],"why":null,"whySource":null,"meaning":"A family history of chromosomal conditions, neural tube defects, or congenital heart disease changes prenatal care — from higher-dose folic acid to carrier screening, genetic counseling, and targeted fetal imaging. Eliciting it before or early in pregnancy is when it can still change management.","meaningSource":"ai-draft"},{"id":"history-04","system":"general","question":"What hormones or contraceptives, blood thinners, fertility medications, over-the-counter drugs, herbs, or vitamins do you take?","listenFor":["Medication list given","None"],"why":null,"whySource":null,"meaning":"A complete medication list — including hormones, blood thinners, fertility drugs, and over-the-counter or herbal products patients often don't volunteer — identifies teratogens, bleeding risks for procedures and delivery, and drug interactions. Reviewing it is essential before prescribing anything in pregnancy.","meaningSource":"ai-draft"},{"id":"history-05","system":"general","question":"Do you use tobacco, alcohol, cannabis, or other drugs?","listenFor":["No substance use","Use described"],"why":null,"whySource":null,"meaning":"Substance use directly affects pregnancy outcomes — alcohol, tobacco, and drugs raise risks of miscarriage, preterm birth, and abruption — and shapes contraceptive and counseling plans. Asking nonjudgmentally opens the door to cessation resources rather than shutting it.","meaningSource":"ai-draft"},{"id":"history-06","system":"general","question":"Any allergies, including latex — and what was the reaction?","listenFor":["No allergies","Allergy with reaction described"],"why":null,"whySource":null,"meaning":"Latex allergy is especially relevant in obstetrics and gynecology — gloves, condoms, and catheters are everywhere — and the specific reaction separates true allergy from intolerance. Documenting it protects the patient across every future procedure and delivery.","meaningSource":"ai-draft"},{"id":"history-07","system":"general","question":"What else about your menstrual, reproductive, or sexual health should we discuss today?","listenFor":["Nothing further","Additional concern raised"],"why":null,"whySource":null,"meaning":"An open-ended close catches what the structured questions missed — sexual pain, incontinence, fertility worries, or anything the patient was embarrassed to raise. Patients often save their real concern for last, so this question frequently surfaces the actual reason for the visit.","meaningSource":"ai-draft"},{"id":"history-08","system":"general","question":"One-liner: ___-year-old G__P____ at __w__d (if pregnant), LMP ___, presenting with ___. Key menstrual, OB, GYN, and sexual history: ___.","listenFor":["One-liner completed"],"why":null,"whySource":null,"meaning":"The one-liner distills the encounter into the standard handoff currency — age, gravidity and parity, gestational age, and key history — so anyone picking up the chart grasps the essentials in seconds. Building it forces you to decide what actually matters about this patient.","meaningSource":"ai-draft"}],"exam":[],"reviewNeeded":{"whyMissing":8,"howMissing":0}}]};
